    // -----------------------------------------------------------------------
    // Generic type argument count checking (TS2314)
    // -----------------------------------------------------------------------

    /**
     * Type parameter info: (minRequired, maxTotal, displayName).
     * minRequired = count of type params without defaults.
     * maxTotal = total type params count.
     */
    private data class TypeParamInfo(val minRequired: Int, val maxTotal: Int, val displayName: String)

    /**
     * Get type parameter info for a named type. Returns null if the type is not generic.
     */
    private fun getTypeParamInfo(name: String): TypeParamInfo? {
        // Check binder symbols first (user-declared types)
        for (result in binderResults) {
            val symbol = result.locals[name] ?: continue
            val info = getTypeParamInfoFromSymbol(symbol)
            if (info != null) return info
        }
        val globalSymbol = globals[name]
        if (globalSymbol != null) {
            val info = getTypeParamInfoFromSymbol(globalSymbol)
            if (info != null) return info
        }
        // Check known built-in generics (all required, no defaults)
        val builtin = KNOWN_GENERIC_BUILTINS[name] ?: return null
        return TypeParamInfo(builtin.first, builtin.first, builtin.second)
    }

    /**
     * Extract type parameter info from a symbol's declarations.
     */
    private fun getTypeParamInfoFromSymbol(symbol: Symbol): TypeParamInfo? {
        var foundClassLike = false
        for (decl in symbol.declarations) {
            when (decl) {
                is ClassDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size,
                            "${symbol.name}<${typeParams.joinToString(", ") { it.name.text }}>")
                    }
                }
                is InterfaceDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size,
                            "${symbol.name}<${typeParams.joinToString(", ") { it.name.text }}>")
                    }
                }
                is TypeAliasDeclaration -> {
                    foundClassLike = true
                    val typeParams = decl.typeParameters
                    if (!typeParams.isNullOrEmpty()) {
                        val minRequired = typeParams.count { it.default == null }
                        return TypeParamInfo(minRequired, typeParams.size, symbol.name)
                    }
                }
                else -> {}
            }
        }
        // If the symbol has a class/interface/type-alias declaration with 0 type params,
        // it shadows any global builtin with the same name — return (0, 0) to suppress TS2314.
        if (foundClassLike) return TypeParamInfo(0, 0, symbol.name)
        return null
    }

    /**
     * Check if a type annotation is a bare generic type reference that would trigger TS2314.
     * Used to suppress false-positive TS2564 on error types.
     */
    private fun isUnresolvedGenericType(type: TypeNode?): Boolean {
        if (type !is TypeReference) return false
        val typeName = type.typeName
        val name = when (typeName) {
            is Identifier -> typeName.text
            else -> return false
        }
        val info = getTypeParamInfo(name) ?: return false
        if (info.maxTotal == 0) return false // non-generic local type → TS2315, not TS2314
        if (info.minRequired != info.maxTotal) return false
        val providedCount = type.typeArguments?.size ?: 0
        return providedCount != info.maxTotal
    }

    /**
     * Check type argument count for a TypeReference node.
     * Emits TS2314: "Generic type 'X' requires N type argument(s)."
     * Only fires when all type params are required (no defaults).
     * Types with default type params need TS2707 (different code) — skipped.
     */
    private fun checkTypeArgCount(
        typeRef: TypeReference,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val typeName = typeRef.typeName
        val name = when (typeName) {
            is Identifier -> typeName.text
            else -> return // QualifiedName — skip
        }

        // Only check if the name actually resolves (skip if it would be TS2304)
        if (name.isEmpty()) return
        if (name[0] !in 'A'..'Z' && name[0] !in 'a'..'z' && name[0] != '_' && name[0] != '$') return
        if (name in KEYWORD_IDENTIFIERS) return
        if (!scope.has(name)) return
        // Type parameters cannot trigger TS2314 — they are not generic type constructors
        if (scope.isTypeParam(name)) return

        // Look up type parameter info
        val info = getTypeParamInfo(name) ?: return

        // Non-generic local types (0 type params) used with type args → TS2315, not TS2314
        if (info.maxTotal == 0) return

        // Skip types with default type params — they need TS2707 not TS2314
        if (info.minRequired != info.maxTotal) return

        val providedCount = typeRef.typeArguments?.size ?: 0
        if (providedCount == info.maxTotal) return // correct count

        // Compute squiggle position
        val start: Int
        val length: Int
        if (providedCount == 0 && typeRef.typeArguments == null) {
            // No type args at all — squiggle on just the name
            start = typeName.pos
            length = name.length
        } else if (providedCount == 0 && typeRef.typeArguments != null) {
            // Empty type arg list `<>` — squiggle covers `Name<>`
            start = typeName.pos
            val ltIdx = source.indexOf("<>", start)
            length = if (ltIdx >= 0) ltIdx + 2 - start else name.length
        } else {
            // Wrong count — squiggle on the entire type reference including <args>
            start = typeName.pos
            val lastArgEnd = typeRef.typeArguments!!.last().end
            val gtIdx = source.indexOf('>', lastArgEnd - 1)
            length = if (gtIdx >= 0) gtIdx + 1 - start else name.length
        }

        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Generic type '${info.displayName}' requires ${info.maxTotal} type argument(s).",
            category = DiagnosticCategory.Error,
            code = 2314,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check type argument count for an ExpressionWithTypeArguments in heritage clauses.
     * Emits TS2314 when extends/implements clause uses wrong number of type args.
     * Only fires when all type params are required (no defaults).
     */
    private fun checkHeritageTypeArgCount(
        exprWithArgs: ExpressionWithTypeArguments,
        scope: NameScope,
        source: String,
        fileName: String,
    ) {
        val expression = exprWithArgs.expression
        val name = when (expression) {
            is Identifier -> expression.text
            else -> return // PropertyAccessExpression — skip
        }

        // Only check if the name resolves
        if (name.isEmpty()) return
        if (!scope.has(name)) return

        val info = getTypeParamInfo(name) ?: return

        // Non-generic local types (0 type params) used with type args → TS2315, not TS2314
        if (info.maxTotal == 0) return

        // Skip types with default type params — they need TS2707 not TS2314
        if (info.minRequired != info.maxTotal) return

        val providedCount = exprWithArgs.typeArguments?.size ?: 0
        if (providedCount == info.maxTotal) return

        val start = expression.pos
        val length: Int
        if (providedCount == 0) {
            length = name.length
        } else {
            // Squiggle covers name + <args>
            val lastArgEnd = exprWithArgs.typeArguments!!.last().end
            val gtIdx = source.indexOf('>', lastArgEnd - 1)
            length = if (gtIdx >= 0) gtIdx + 1 - start else name.length
        }

        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // In JS files, use TS8026 instead of TS2314 for heritage clauses without type args
        val isJsFile = fileName.endsWith(".js") || fileName.endsWith(".jsx")
        if (isJsFile && providedCount == 0) {
            diagnostics.add(Diagnostic(
                message = "Expected ${info.displayName} type arguments; provide these with an '@extends' tag.",
                category = DiagnosticCategory.Error,
                code = 8026,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } else {
            diagnostics.add(Diagnostic(
                message = "Generic type '${info.displayName}' requires ${info.maxTotal} type argument(s).",
                category = DiagnosticCategory.Error,
                code = 2314,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // Type used as value checking (TS2693)
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // Always-truthy expression checking (TS2872)
    // -----------------------------------------------------------------------

    /**
     * Check for expressions that are always truthy in logical OR and if conditions.
     * Emits TS2872 "This kind of expression is always truthy."
     */
    private fun checkAlwaysTruthy() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkAlwaysTruthyInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkAlwaysTruthyInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkAlwaysTruthyInStatement(stmt, source, fileName)
    }

    private fun checkAlwaysTruthyInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkAlwaysTruthyInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
            }
            is IfStatement -> {
                // Check for always-falsy conditions (e.g. `void x`) → TS2873
                if (isAlwaysFalsyExpr(stmt.expression)) {
                    emitTS2873(stmt.expression, source, fileName)
                }
                // Walk the if-else chain: only flag always-truthy conditions that are
                // UNREACHABLE because a preceding branch was always-truthy
                var prevTruthy = isAlwaysTruthyExpr(stmt.expression)
                checkAlwaysTruthyInStatement(stmt.thenStatement, source, fileName)
                var elseStmt = stmt.elseStatement
                while (elseStmt is IfStatement) {
                    if (prevTruthy) {
                        checkAlwaysTruthyCondition(elseStmt.expression, source, fileName)
                    }
                    if (isAlwaysTruthyExpr(elseStmt.expression)) prevTruthy = true
                    checkAlwaysTruthyInStatement(elseStmt.thenStatement, source, fileName)
                    elseStmt = elseStmt.elseStatement
                }
                elseStmt?.let { checkAlwaysTruthyInStatement(it, source, fileName) }
            }
            is Block -> checkAlwaysTruthyInStatements(stmt.statements, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
                    else -> {}
                }
            }
            is ForStatement -> {
                stmt.condition?.let { checkAlwaysTruthyInExpr(it, source, fileName) }
                checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkAlwaysTruthyInStatement(stmt.statement, source, fileName)
            is SwitchStatement -> for (c in stmt.caseBlock) {
                val clauseStmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                checkAlwaysTruthyInStatements(clauseStmts, source, fileName)
            }
            is TryStatement -> {
                checkAlwaysTruthyInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkAlwaysTruthyInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkAlwaysTruthyInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.BarBar) {
                    if (isAlwaysTruthyForOrExpr(expr.left)) {
                        emitTS2872(expr.left, source, fileName)
                    }
                }
                // Iterative left spine to avoid StackOverflow
                var current: Expression = expr
                while (current is BinaryExpression) {
                    if (current.operator == SyntaxKind.BarBar && current !== expr) {
                        if (isAlwaysTruthyForOrExpr(current.left)) {
                            emitTS2872(current.left, source, fileName)
                        }
                    }
                    checkAlwaysTruthyInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkAlwaysTruthyInExpr(current, source, fileName)
            }
            is ParenthesizedExpression -> checkAlwaysTruthyInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkAlwaysTruthyInExpr(expr.whenTrue, source, fileName)
                checkAlwaysTruthyInExpr(expr.whenFalse, source, fileName)
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkAlwaysTruthyInStatements(body.statements, source, fileName)
                is Expression -> checkAlwaysTruthyInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkAlwaysTruthyInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkAlwaysTruthyCondition(expr: Expression, source: String, fileName: String) {
        if (expr is NumericLiteralNode) {
            val value = expr.text.toDoubleOrNull() ?: return
            if (value != 0.0 && !value.isNaN()) {
                emitTS2872(expr, source, fileName)
            }
        }
        if (expr is ParenthesizedExpression) {
            checkAlwaysTruthyCondition(expr.expression, source, fileName)
        }
    }

    /** Only flag simple literal expressions and function expressions to avoid false positives. */
    private fun isAlwaysTruthyExpr(expr: Expression): Boolean {
        return when (expr) {
            is StringLiteralNode -> expr.text.isNotEmpty()
            is NumericLiteralNode -> {
                val value = expr.text.toDoubleOrNull() ?: return false
                value != 0.0 && !value.isNaN()
            }
            is ParenthesizedExpression -> isAlwaysTruthyExpr(expr.expression)
            is ArrowFunction -> true
            is FunctionExpression -> true
            is ObjectLiteralExpression -> true
            is ArrayLiteralExpression -> true
            is ClassExpression -> true
            is RegularExpressionLiteralNode -> true
            is NewExpression -> true
            else -> false
        }
    }

    /**
     * TypeScript only flags these expression kinds in `||` contexts (LHS of ||).
     * Numeric/string literals and `new` expressions are NOT flagged in `||`.
     */
    private fun isAlwaysTruthyForOrExpr(expr: Expression): Boolean {
        return when (expr) {
            is ParenthesizedExpression -> isAlwaysTruthyForOrExpr(expr.expression)
            is ArrowFunction -> true
            is FunctionExpression -> true
            is ObjectLiteralExpression -> true
            is ArrayLiteralExpression -> true
            is ClassExpression -> true
            is RegularExpressionLiteralNode -> true
            else -> false
        }
    }

    /**
     * Check if an expression is always falsy (e.g. `void x`).
     * TypeScript emits TS2873 for such expressions in `if` conditions.
     */
    private fun isAlwaysFalsyExpr(expr: Expression): Boolean {
        return when (expr) {
            is VoidExpression -> true
            is ParenthesizedExpression -> isAlwaysFalsyExpr(expr.expression)
            else -> false
        }
    }

    private fun emitTS2873(expr: Expression, source: String, fileName: String) {
        val start = expr.pos
        // For VoidExpression, compute length from operand's true end to get correct span
        val length = when (expr) {
            is VoidExpression -> expressionTrueEnd(expr.expression) - start
            else -> expressionTrueEnd(expr) - start
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This kind of expression is always falsy.",
            category = DiagnosticCategory.Error,
            code = 2873,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2872(expr: Expression, source: String, fileName: String) {
        val start = expr.pos
        // Use text length for literals to get accurate squiggle
        val length = when (expr) {
            is StringLiteralNode -> (expr.rawText?.length ?: expr.text.length) + 2 // +2 for quotes
            is NumericLiteralNode -> expr.text.length
            else -> expressionTrueEnd(expr) - start
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "This kind of expression is always truthy.",
            category = DiagnosticCategory.Error,
            code = 2872,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Comma operator left side unused (TS2695)
    // -----------------------------------------------------------------------

    private fun checkCommaOperatorUnused() {
        // TypeScript suppresses TS2695 when allowUnreachableCode is explicitly true
        if (options.allowUnreachableCode == true) return
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCommaInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkCommaInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkCommaInStatement(stmt, source, fileName)
    }

    private fun checkCommaInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkCommaInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkCommaInExpr(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { checkCommaInExpr(it, source, fileName) }
            is IfStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkCommaInStatement(it, source, fileName) }
            }
            is Block -> checkCommaInStatements(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { checkCommaInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkCommaInExpr(it, source, fileName) }
                    is GetAccessor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkCommaInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is ForStatement -> {
                stmt.initializer?.let { init ->
                    when (init) {
                        is VariableDeclarationList -> for (d in init.declarations) {
                            d.initializer?.let { checkCommaInExpr(it, source, fileName) }
                        }
                        is Expression -> checkCommaInExpr(init, source, fileName)
                        else -> {}
                    }
                }
                stmt.condition?.let { checkCommaInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkCommaInExpr(it, source, fileName) }
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                checkCommaInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkCommaInStatement(stmt.statement, source, fileName)
                checkCommaInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkCommaInExpr(stmt.expression, source, fileName)
                for (c in stmt.caseBlock) {
                    when (c) {
                        is CaseClause -> {
                            checkCommaInExpr(c.expression, source, fileName)
                            checkCommaInStatements(c.statements, source, fileName)
                        }
                        is DefaultClause -> checkCommaInStatements(c.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkCommaInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkCommaInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkCommaInStatements(it.statements, source, fileName) }
            }
            is ThrowStatement -> stmt.expression?.let { checkCommaInExpr(it, source, fileName) }
            is LabeledStatement -> checkCommaInStatement(stmt.statement, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkCommaInStatements(it.statements, source, fileName) }
            is EnumDeclaration -> for (m in stmt.members) {
                m.initializer?.let { checkCommaInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    /** Check if this comma expression is an indirect call pattern: (0, obj.prop)() */
    private fun isIndirectCallComma(expr: BinaryExpression): Boolean {
        val right = expr.right
        // (0, obj.method)() — indirect call pattern with property/element access
        if (right is PropertyAccessExpression || right is ElementAccessExpression) return true
        // (0, eval)("code") — indirect eval pattern
        if (right is Identifier && right.text == "eval") return true
        return false
    }

    private fun checkCommaInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                if (expr.operator == SyntaxKind.Comma) {
                    if (!hasSideEffects(expr.left) && !isIndirectCallComma(expr)) {
                        val start = expr.left.pos
                        val length = commaLeftSpanLength(expr.left, start)
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Left side of comma operator is unused and has no side effects.",
                            category = DiagnosticCategory.Error,
                            code = 2695,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
                checkCommaInExpr(expr.left, source, fileName)
                checkCommaInExpr(expr.right, source, fileName)
            }
            is ParenthesizedExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkCommaInExpr(expr.condition, source, fileName)
                checkCommaInExpr(expr.whenTrue, source, fileName)
                checkCommaInExpr(expr.whenFalse, source, fileName)
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkCommaInStatements(body.statements, source, fileName)
                is Expression -> checkCommaInExpr(body, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkCommaInStatements(it.statements, source, fileName) }
            is CallExpression -> {
                checkCommaInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkCommaInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkCommaInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkCommaInExpr(it, source, fileName) }
            }
            is PropertyAccessExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkCommaInExpr(expr.expression, source, fileName)
                checkCommaInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkCommaInExpr(el, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkCommaInExpr(prop.initializer, source, fileName)
                    is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let { checkCommaInExpr(it, source, fileName) }
                    is SpreadAssignment -> checkCommaInExpr(prop.expression, source, fileName)
                    else -> {}
                }
            }
            is PrefixUnaryExpression -> checkCommaInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkCommaInExpr(expr.operand, source, fileName)
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkCommaInExpr(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> {
                checkCommaInExpr(expr.tag, source, fileName)
                val template = expr.template
                if (template is TemplateExpression) {
                    for (span in template.templateSpans) {
                        checkCommaInExpr(span.expression, source, fileName)
                    }
                }
            }
            is TypeAssertionExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is AsExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is SpreadElement -> checkCommaInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkCommaInExpr(it, source, fileName) }
            is VoidExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is DeleteExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkCommaInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkCommaInExpr(expr.expression, source, fileName)
            else -> {}
        }
    }

    /** Compute squiggle length for the left operand of a comma expression. */
    private fun commaLeftSpanLength(expr: Expression, start: Int): Int {
        return when (expr) {
            // Function expressions: squiggle only covers 'function' keyword (8 chars)
            is FunctionExpression -> 8
            // Arrow functions: squiggle covers the whole expression
            is ArrowFunction -> (expr.end - 1 - start).coerceAtLeast(1)
            // Parenthesized: squiggle covers the whole parenthesized expression
            is ParenthesizedExpression -> (expr.end - 1 - start).coerceAtLeast(1)
            // String literals: text.length + 2 for quotes
            is StringLiteralNode -> (expr.rawText?.length ?: expr.text.length) + 2
            // Template strings: use node span
            is NoSubstitutionTemplateLiteralNode -> (expr.end - 1 - start).coerceAtLeast(1)
            // Regex literals: use node span
            is RegularExpressionLiteralNode -> (expr.end - 1 - start).coerceAtLeast(1)
            // Default: use node span
            else -> (expr.end - 1 - start).coerceAtLeast(1)
        }
    }

    /** Check if an expression has side effects (assignments, calls, increments, etc.) */
    private fun hasSideEffects(expr: Expression): Boolean {
        return when (expr) {
            // Assignments always have side effects
            is BinaryExpression -> when (expr.operator) {
                SyntaxKind.Equals, SyntaxKind.PlusEquals, SyntaxKind.MinusEquals,
                SyntaxKind.AsteriskEquals, SyntaxKind.SlashEquals, SyntaxKind.PercentEquals,
                SyntaxKind.AmpersandEquals, SyntaxKind.BarEquals, SyntaxKind.CaretEquals,
                SyntaxKind.LessThanLessThanEquals, SyntaxKind.GreaterThanGreaterThanEquals,
                SyntaxKind.GreaterThanGreaterThanGreaterThanEquals,
                SyntaxKind.AsteriskAsteriskEquals,
                SyntaxKind.BarBarEquals, SyntaxKind.AmpersandAmpersandEquals,
                SyntaxKind.QuestionQuestionEquals -> true
                // Comma: if left has side effects, whole thing does
                SyntaxKind.Comma -> hasSideEffects(expr.left) || hasSideEffects(expr.right)
                // Other binary ops: check both sides
                else -> hasSideEffects(expr.left) || hasSideEffects(expr.right)
            }
            // Increment/decrement have side effects
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.PlusPlus, SyntaxKind.MinusMinus -> true
                else -> hasSideEffects(expr.operand)
            }
            is PostfixUnaryExpression -> true // ++ and -- always have side effects
            // Function/method calls have side effects
            is CallExpression -> true
            is NewExpression -> true
            is TaggedTemplateExpression -> true
            // Delete has side effects
            is DeleteExpression -> true
            // Yield/await have side effects
            is YieldExpression -> true
            is AwaitExpression -> true
            // Void expression: TypeScript treats as OK (no TS2695)
            is VoidExpression -> true
            // Type assertions: TypeScript treats as OK (no TS2695)
            is TypeAssertionExpression -> true
            is AsExpression -> true
            is SatisfiesExpression -> true
            // Parenthesized: check inner
            is ParenthesizedExpression -> hasSideEffects(expr.expression)
            // Non-null assertion (x!): no side effect
            is NonNullExpression -> hasSideEffects(expr.expression)
            // Conditional: has side effects if any branch does
            is ConditionalExpression -> hasSideEffects(expr.whenTrue) || hasSideEffects(expr.whenFalse)
            // Everything else (literals, identifiers, typeof, array/object literals,
            // arrow functions, function expressions, etc.) — no side effects
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // Null/undefined usage checking (TS18050)
    // -----------------------------------------------------------------------

    /**
     * Check for null/undefined used in invalid positions:
     * property access base, binary operator operands, etc.
     * Emits TS18050: "The value 'null'/'undefined' cannot be used here."
     */
    private fun checkNullUndefinedUsage() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkNullUndefinedInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkNullUndefinedInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkNullUndefinedInStatement(stmt, source, fileName)
    }

    private fun checkNullUndefinedInStatement(stmt: Statement, source: String, fileName: String) {
        if (checkDepth > maxCheckDepth) return
        checkDepth++
        try {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        decl.initializer?.let { checkNullUndefinedInExpr(it, source, fileName) }
                    }
                }
                is ExpressionStatement -> checkNullUndefinedInExpr(stmt.expression, source, fileName)
                is ReturnStatement -> stmt.expression?.let { checkNullUndefinedInExpr(it, source, fileName) }
                is IfStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    checkNullUndefinedInStatement(stmt.thenStatement, source, fileName)
                    stmt.elseStatement?.let { checkNullUndefinedInStatement(it, source, fileName) }
                }
                is Block -> checkNullUndefinedInStatements(stmt.statements, source, fileName)
                is ForStatement -> {
                    stmt.initializer?.let { if (it is Expression) checkNullUndefinedInExpr(it, source, fileName) }
                    stmt.condition?.let { checkNullUndefinedInExpr(it, source, fileName) }
                    stmt.incrementor?.let { checkNullUndefinedInExpr(it, source, fileName) }
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                }
                is WhileStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                }
                is DoStatement -> {
                    checkNullUndefinedInStatement(stmt.statement, source, fileName)
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                }
                is SwitchStatement -> {
                    checkNullUndefinedInExpr(stmt.expression, source, fileName)
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> {
                                checkNullUndefinedInExpr(clause.expression, source, fileName)
                                checkNullUndefinedInStatements(clause.statements, source, fileName)
                            }
                            is DefaultClause -> {
                                checkNullUndefinedInStatements(clause.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> {
                    stmt.body?.let { checkNullUndefinedInStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let {
                                checkNullUndefinedInStatements(it.statements, source, fileName)
                            }
                            is PropertyDeclaration -> member.initializer?.let {
                                checkNullUndefinedInExpr(it, source, fileName)
                            }
                            is Constructor -> member.body?.let {
                                checkNullUndefinedInStatements(it.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> {
                    when (val body = stmt.body) {
                        is ModuleBlock -> checkNullUndefinedInStatements(body.statements, source, fileName)
                        else -> {}
                    }
                }
                is ThrowStatement -> stmt.expression?.let { checkNullUndefinedInExpr(it, source, fileName) }
                else -> {}
            }
        } finally { checkDepth-- }
    }

    private fun checkNullUndefinedInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is BinaryExpression -> {
                // Check if null/undefined is used as operand of arithmetic/bitwise operators
                val op = expr.operator
                val isArithmeticOrBitwise = op in setOf(
                    SyntaxKind.Plus, SyntaxKind.Minus,
                    SyntaxKind.Asterisk, SyntaxKind.Slash, SyntaxKind.Percent,
                    SyntaxKind.AsteriskAsterisk,
                    SyntaxKind.Ampersand, SyntaxKind.Bar, SyntaxKind.Caret,
                    SyntaxKind.LessThanLessThan, SyntaxKind.GreaterThanGreaterThan,
                    SyntaxKind.GreaterThanGreaterThanGreaterThan,
                    SyntaxKind.PlusEquals, SyntaxKind.MinusEquals,
                    SyntaxKind.AsteriskEquals, SyntaxKind.SlashEquals,
                    SyntaxKind.PercentEquals, SyntaxKind.AsteriskAsteriskEquals,
                    SyntaxKind.AmpersandEquals, SyntaxKind.BarEquals,
                    SyntaxKind.CaretEquals, SyntaxKind.LessThanLessThanEquals,
                    SyntaxKind.GreaterThanGreaterThanEquals,
                    SyntaxKind.GreaterThanGreaterThanGreaterThanEquals,
                )
                if (isArithmeticOrBitwise) {
                    // For '+' operator, null/undefined is valid when other side is a string
                    val isPlus = op == SyntaxKind.Plus || op == SyntaxKind.PlusEquals
                    val leftIsString = expr.left is StringLiteralNode || expr.left is TemplateExpression ||
                            (expr.left is Identifier && (expr.left as Identifier).text.let { it != "null" && it != "undefined" } && false) // only literals
                    val rightIsString = expr.right is StringLiteralNode || expr.right is TemplateExpression
                    if (!(isPlus && rightIsString)) {
                        checkNullUndefinedLiteral(expr.left, source, fileName)
                    }
                    if (!(isPlus && leftIsString)) {
                        checkNullUndefinedLiteral(expr.right, source, fileName)
                    }
                }
                // Iteratively walk left spine to avoid StackOverflow on deep binary chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkNullUndefinedInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkNullUndefinedInExpr(current, source, fileName)
            }
            is PropertyAccessExpression -> {
                // null.foo or undefined.foo
                checkNullUndefinedLiteral(expr.expression, source, fileName)
                checkNullUndefinedInExpr(expr.expression, source, fileName)
            }
            is ElementAccessExpression -> {
                // null[x] or undefined[x]
                checkNullUndefinedLiteral(expr.expression, source, fileName)
                checkNullUndefinedInExpr(expr.expression, source, fileName)
                checkNullUndefinedInExpr(expr.argumentExpression, source, fileName)
            }
            is CallExpression -> {
                checkNullUndefinedInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkNullUndefinedInExpr(arg, source, fileName)
            }
            is ParenthesizedExpression -> checkNullUndefinedInExpr(expr.expression, source, fileName)
            is ConditionalExpression -> {
                checkNullUndefinedInExpr(expr.condition, source, fileName)
                checkNullUndefinedInExpr(expr.whenTrue, source, fileName)
                checkNullUndefinedInExpr(expr.whenFalse, source, fileName)
            }
            is PrefixUnaryExpression -> checkNullUndefinedInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkNullUndefinedInExpr(expr.operand, source, fileName)
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkNullUndefinedInExpr(span.expression, source, fileName)
                }
            }
            is ArrayLiteralExpression -> {
                for (elem in expr.elements) checkNullUndefinedInExpr(elem, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkNullUndefinedInExpr(prop.initializer, source, fileName)
                        is SpreadAssignment -> checkNullUndefinedInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkNullUndefinedInStatements(body.statements, source, fileName)
                    is Expression -> checkNullUndefinedInExpr(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                expr.body?.let { checkNullUndefinedInStatements(it.statements, source, fileName) }
            }
            else -> {}
        }
    }

    private fun checkNullUndefinedLiteral(expr: Expression, source: String, fileName: String) {
        // In our AST, null and undefined are parsed as Identifiers
        val keyword = when {
            expr is Identifier && expr.text == "null" -> "null"
            expr is Identifier && expr.text == "undefined" -> "undefined"
            else -> return
        }
        val start = expr.pos
        val length = keyword.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "The value '$keyword' cannot be used here.",
            category = DiagnosticCategory.Error,
            code = 18050,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /**
     * Check for type-only names used in value positions.
     * Emits TS2693 "'X' only refers to a type, but is being used as a value here."
     */
    private fun checkTypeUsedAsValue() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Collect interface/type alias names at file level (type-only declarations)
            // Skip names that also have a class/function/variable declaration (merged)
            val typeOnlyNames = mutableSetOf<String>()
            val valueNames = mutableSetOf<String>()
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ClassDeclaration -> stmt.name?.text?.let { valueNames.add(it) }
                    is FunctionDeclaration -> stmt.name?.text?.let { valueNames.add(it) }
                    is VariableStatement -> for (decl in stmt.declarationList.declarations) {
                        (decl.name as? Identifier)?.text?.let { valueNames.add(it) }
                    }
                    is EnumDeclaration -> valueNames.add(stmt.name.text)
                    // Import declarations create value bindings (aliases), not type-only names
                    is ImportDeclaration -> {
                        val clause = stmt.importClause ?: continue
                        clause.name?.text?.let { valueNames.add(it) }
                        when (val nb = clause.namedBindings) {
                            is NamespaceImport -> valueNames.add(nb.name.text)
                            is NamedImports -> nb.elements.forEach { spec -> valueNames.add(spec.name.text) }
                            else -> {}
                        }
                    }
                    is ImportEqualsDeclaration -> valueNames.add(stmt.name.text)
                    else -> {}
                }
            }
            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is InterfaceDeclaration -> {
                        val n = stmt.name.text
                        if (n !in valueNames && n !in KNOWN_GLOBALS) typeOnlyNames.add(n)
                    }
                    is TypeAliasDeclaration -> {
                        val n = stmt.name.text
                        if (n !in valueNames && n !in KNOWN_GLOBALS) typeOnlyNames.add(n)
                    }
                    else -> {}
                }
            }
            checkTypeAsValueInStatements(result.sourceFile.statements, source, fileName, typeOnlyNames, valueNames)
        }
    }

    private fun checkTypeAsValueInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        typeOnlyNames: Set<String>,
        valueNames: Set<String> = emptySet(),
    ) {
        for (stmt in statements) {
            checkTypeAsValueInStatement(stmt, source, fileName, typeOnlyNames, valueNames)
        }
    }

    private fun checkTypeAsValueInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        typeOnlyNames: Set<String>,
        valueNames: Set<String> = emptySet(),
    ) {
        when (stmt) {
            is ExpressionStatement -> checkTypeAsValueInExpr(stmt.expression, source, fileName, typeOnlyNames, valueNames)
            is LabeledStatement -> checkTypeAsValueInStatement(stmt.statement, source, fileName, typeOnlyNames, valueNames)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames) }
            is Block -> checkTypeAsValueInStatements(stmt.statements, source, fileName, typeOnlyNames, valueNames)
            is IfStatement -> {
                checkTypeAsValueInExpr(stmt.expression, source, fileName, typeOnlyNames, valueNames)
                checkTypeAsValueInStatement(stmt.thenStatement, source, fileName, typeOnlyNames, valueNames)
                stmt.elseStatement?.let { checkTypeAsValueInStatement(it, source, fileName, typeOnlyNames, valueNames) }
            }
            is FunctionDeclaration -> {
                // Collect type parameters as type-only within this function
                // But exclude names that are also parameter names (parameter shadows type param)
                val innerTypeOnly = typeOnlyNames.toMutableSet()
                stmt.typeParameters?.forEach { innerTypeOnly.add(it.name.text) }
                // Remove parameter names — they are values, not types
                val innerValues = valueNames.toMutableSet()
                for (p in stmt.parameters) {
                    val pName = p.name
                    if (pName is Identifier) {
                        innerTypeOnly.remove(pName.text)
                        innerValues.add(pName.text)
                    }
                }
                stmt.body?.let { checkTypeAsValueInStatements(it.statements, source, fileName, innerTypeOnly, innerValues) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            val innerTypeOnly = typeOnlyNames.toMutableSet()
                            member.typeParameters?.forEach { innerTypeOnly.add(it.name.text) }
                            member.body?.let { checkTypeAsValueInStatements(it.statements, source, fileName, innerTypeOnly, valueNames) }
                        }
                        is Constructor -> member.body?.let {
                            checkTypeAsValueInStatements(it.statements, source, fileName, typeOnlyNames, valueNames)
                        }
                        is PropertyDeclaration -> member.initializer?.let {
                            checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames)
                        }
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    private fun checkTypeAsValueInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        typeOnlyNames: Set<String>,
        valueNames: Set<String> = emptySet(),
    ) {
        when (expr) {
            is Identifier -> {
                val name = expr.text
                // Skip if the name is declared as a value (variable/parameter shadows type keyword)
                if (name !in valueNames && (name in TYPE_ONLY_KEYWORDS || name in typeOnlyNames)) {
                    emitTS2693(name, expr, source, fileName)
                }
            }
            is NewExpression -> {
                // Check the constructor expression
                val ctorExpr = expr.expression
                if (ctorExpr is Identifier) {
                    val name = ctorExpr.text
                    if (name !in valueNames && (name in TYPE_ONLY_KEYWORDS || name in typeOnlyNames)) {
                        emitTS2693(name, ctorExpr, source, fileName)
                    }
                }
                // Recurse into arguments
                expr.arguments?.forEach { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames) }
            }
            is CallExpression -> {
                checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames)
                expr.arguments.forEach { checkTypeAsValueInExpr(it, source, fileName, typeOnlyNames, valueNames) }
            }
            is BinaryExpression -> {
                // Iteratively walk binary chains to avoid StackOverflow on deep trees
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkTypeAsValueInExpr(current.right, source, fileName, typeOnlyNames, valueNames)
                    current = current.left
                }
                checkTypeAsValueInExpr(current, source, fileName, typeOnlyNames, valueNames)
            }
            is TypeOfExpression -> {
                // typeof T where T is a type param → TS2693
                val operand = expr.expression
                if (operand is Identifier) {
                    val name = operand.text
                    if (name !in valueNames && name in typeOnlyNames) {
                        emitTS2693(name, operand, source, fileName)
                    }
                }
            }
            is ParenthesizedExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames)
            is ConditionalExpression -> {
                checkTypeAsValueInExpr(expr.condition, source, fileName, typeOnlyNames, valueNames)
                checkTypeAsValueInExpr(expr.whenTrue, source, fileName, typeOnlyNames, valueNames)
                checkTypeAsValueInExpr(expr.whenFalse, source, fileName, typeOnlyNames, valueNames)
            }
            is PropertyAccessExpression -> checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames)
            is ElementAccessExpression -> {
                checkTypeAsValueInExpr(expr.expression, source, fileName, typeOnlyNames, valueNames)
                checkTypeAsValueInExpr(expr.argumentExpression, source, fileName, typeOnlyNames, valueNames)
            }
            else -> {}
        }
    }

    private fun emitTS2693(name: String, node: Node, source: String, fileName: String) {
        val start = node.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'$name' only refers to a type, but is being used as a value here.",
            category = DiagnosticCategory.Error,
            code = 2693,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Unreachable code checking (TS7027)
    // -----------------------------------------------------------------------

    /**
     * Check for unreachable code after return, throw, break, continue,
     * and infinite loops.
     */
    private fun checkUnreachableCode() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkUnreachableInStatements(result.sourceFile.statements, source, fileName, result)
        }
    }

    private fun checkUnreachableInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        binderResult: BinderResult,
    ) {
        var termIdx = -1
        var currentRun = mutableListOf<Statement>()

        for (i in statements.indices) {
            val stmt = statements[i]
            if (termIdx >= 0) {
                // After a terminating statement: collect unreachable runs separated by hoisted decls.
                // Hoisted = doesn't generate runtime code:
                //   - FunctionDeclaration: truly hoisted (JS var hoisting)
                //   - InterfaceDeclaration, TypeAliasDeclaration: type-only, erased
                //   - ImportDeclaration, ImportEqualsDeclaration, ExportDeclaration: module-level
                //   - VariableStatement with var flags: var declarations are function-hoisted
                //   - ModuleDeclaration that is non-instantiated (only type-only contents)
                val isHoisted = stmt is FunctionDeclaration ||
                    stmt is InterfaceDeclaration ||
                    stmt is TypeAliasDeclaration ||
                    stmt is ImportDeclaration ||
                    stmt is ImportEqualsDeclaration ||
                    stmt is ExportDeclaration ||
                    isVarDeclaration(stmt) ||
                    isNonPreservedConstEnum(stmt) ||
                    isNonInstantiatedNamespace(stmt, binderResult)
                if (isHoisted) {
                    // Emit current run if non-empty
                    if (currentRun.isNotEmpty()) {
                        emitTS7027(currentRun, source, fileName)
                        currentRun = mutableListOf()
                    }
                    // Recurse into hoisted declaration (it IS reachable for inner checks)
                    checkUnreachableInNestedStatement(stmt, source, fileName, binderResult)
                } else {
                    // Add to current unreachable run (do NOT recurse — it's unreachable)
                    currentRun.add(stmt)
                }
            } else {
                // Before the terminating statement: check normally
                if (isDefinitelyTerminating(stmt)) {
                    termIdx = i
                }
                // Recurse into nested blocks
                checkUnreachableInNestedStatement(stmt, source, fileName, binderResult)
            }
        }

        // Emit final run if any unreachable statements remain
        if (currentRun.isNotEmpty()) {
            emitTS7027(currentRun, source, fileName)
        }
    }

    /**
     * Returns true for `var` variable statements with NO initializer (pure declarations).
     * TypeScript does not report TS7027 for bare `var x;` after unreachable code because
     * `var` declarations without initializers are hoisted and have no runtime side effects.
     * `var x = 1;` (with initializer) IS reported since the initializer is unreachable code.
     */
    private fun isVarDeclaration(stmt: Statement): Boolean {
        if (stmt !is VariableStatement) return false
        if (stmt.declarationList.flags != SyntaxKind.VarKeyword) return false
        // Only treat as hoisted if ALL declarations have no initializer
        return stmt.declarationList.declarations.all { it.initializer == null }
    }

    /**
     * Returns true if a ModuleDeclaration is non-instantiated or const-enum-only (produces no runtime code).
     * Non-instantiated/ConstEnumOnly namespaces contain only type-only declarations (interfaces, type aliases,
     * non-preserved const enums) and are treated like hoisted declarations for TS7027 purposes.
     */
    private fun isNonInstantiatedNamespace(stmt: Statement, binderResult: BinderResult): Boolean {
        if (stmt !is ModuleDeclaration) return false
        val state = binderResult.moduleInstanceStates[nodeKey(stmt)]
        return state == ModuleInstanceState.NonInstantiated || state == ModuleInstanceState.ConstEnumOnly
    }

    /**
     * Returns true if this is a non-preserved `const enum` declaration.
     * Without `preserveConstEnums`, const enums are type-only (inlined at use sites)
     * and should not be reported as unreachable code.
     */
    private fun isNonPreservedConstEnum(stmt: Statement): Boolean {
        if (stmt !is EnumDeclaration) return false
        if (ModifierFlag.Const !in stmt.modifiers) return false
        return !options.preserveConstEnums
    }

    private fun isDefinitelyTerminating(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> true
            is ThrowStatement -> true
            is BreakStatement -> true
            is ContinueStatement -> true
            is WhileStatement -> {
                // while(true) with no break is an infinite loop
                isAlwaysTrue(stmt.expression) && !containsBreak(stmt.statement)
            }
            is DoStatement -> {
                // do {} while(true) with no break is an infinite loop
                isAlwaysTrue(stmt.expression) && !containsBreak(stmt.statement)
            }
            is ForStatement -> {
                // for(;;) with no break is infinite
                stmt.condition == null && !containsBreak(stmt.statement)
            }
            is IfStatement -> {
                val thenTerm = isBlockTerminating(stmt.thenStatement)
                val elseTerm = stmt.elseStatement?.let { isBlockTerminating(it) } ?: false
                // if (cond) { ... } else { ... } — both branches terminate
                // if (true) { ... } — always-true with terminating then branch (no else needed)
                (thenTerm && elseTerm) || (thenTerm && stmt.elseStatement == null && isAlwaysTrue(stmt.expression))
            }
            is SwitchStatement -> {
                // All cases + default terminate → switch is terminating
                val clauses = stmt.caseBlock
                val hasDefault = clauses.any { it is DefaultClause }
                if (!hasDefault) return false
                clauses.all { clause ->
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    // Empty case clauses fall through to the next
                    clauseStmts.isEmpty() || clauseStmts.any { isDefinitelyTerminating(it) }
                }
            }
            is TryStatement -> {
                // Try block terminates and there's no catch that doesn't terminate
                isBlockTerminating(stmt.tryBlock) &&
                    (stmt.catchClause == null || isBlockTerminating(stmt.catchClause!!.block))
            }
            else -> false
        }
    }

    private fun isBlockTerminating(stmt: Statement): Boolean {
        return when (stmt) {
            is Block -> stmt.statements.any { isDefinitelyTerminating(it) }
            else -> isDefinitelyTerminating(stmt)
        }
    }

    private fun isAlwaysTrue(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> expr.text == "true"
            is ParenthesizedExpression -> isAlwaysTrue(expr.expression)
            else -> false
        }
    }

    private fun isAlwaysFalse(expr: Expression): Boolean {
        return when (expr) {
            is Identifier -> expr.text == "false"
            is ParenthesizedExpression -> isAlwaysFalse(expr.expression)
            else -> false
        }
    }

    /**
     * Returns true if a call expression is an IIFE that always throws.
     * Pattern: `(function() { throw X; })()` or `(() => { throw X; })()`
     */
    private fun exprAlwaysThrows(expr: Expression): Boolean {
        if (expr !is CallExpression) return false
        val func = expr.expression
        val funcBody: List<Statement> = when {
            func is FunctionExpression -> func.body?.statements ?: return false
            func is ParenthesizedExpression && func.expression is FunctionExpression ->
                (func.expression as FunctionExpression).body?.statements ?: return false
            func is ArrowFunction -> {
                val body = func.body
                when (body) {
                    is Block -> body.statements
                    is ThrowStatement -> listOf(body)
                    else -> return false
                }
            }
            func is ParenthesizedExpression && func.expression is ArrowFunction -> {
                val body = (func.expression as ArrowFunction).body
                when (body) {
                    is Block -> body.statements
                    else -> return false
                }
            }
            else -> return false
        }
        return funcBody.any { it is ThrowStatement }
    }

    /**
     * Report unreachable code inside an IIFE's body statements.
     * Used for for-loop condition/incrementor that's unreachable.
     */
    private fun reportUnreachableIIFEBody(expr: Expression?, source: String, fileName: String) {
        if (expr == null) return
        val callExpr = expr as? CallExpression ?: return
        val func = callExpr.expression
        val funcBody: List<Statement>? = when {
            func is FunctionExpression -> func.body?.statements
            func is ParenthesizedExpression && func.expression is FunctionExpression ->
                (func.expression as FunctionExpression).body?.statements
            else -> null
        }
        if (!funcBody.isNullOrEmpty()) {
            emitTS7027(funcBody, source, fileName)
        }
    }

    private fun containsBreak(stmt: Statement): Boolean {
        return when (stmt) {
            is BreakStatement -> true
            is Block -> stmt.statements.any { containsBreak(it) }
            is IfStatement -> containsBreak(stmt.thenStatement) ||
                (stmt.elseStatement?.let { containsBreak(it) } ?: false)
            is LabeledStatement -> containsBreak(stmt.statement)
            // Don't recurse into nested loops/switches — break applies to them, not the outer
            else -> false
        }
    }

    private fun checkUnreachableInNestedStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        binderResult: BinderResult,
    ) {
        when (stmt) {
            is Block -> checkUnreachableInStatements(stmt.statements, source, fileName, binderResult)
            is IfStatement -> {
                if (isAlwaysTrue(stmt.expression)) {
                    // if(true) { ... } else { ... } — else branch is unreachable
                    checkUnreachableInNestedStatement(stmt.thenStatement, source, fileName, binderResult)
                    val elseStmt = stmt.elseStatement
                    if (elseStmt != null) {
                        // Mark else branch as unreachable
                        val elseStmts = if (elseStmt is Block) elseStmt.statements
                                        else listOf(elseStmt)
                        emitTS7027(elseStmts, source, fileName)
                        // Also recurse into else for inner unreachable checks (but mark outer as unreachable)
                    }
                } else {
                    checkUnreachableInNestedStatement(stmt.thenStatement, source, fileName, binderResult)
                    stmt.elseStatement?.let { checkUnreachableInNestedStatement(it, source, fileName, binderResult) }
                }
            }
            is ForStatement -> {
                // If the for-loop's initializer always throws, the condition and incrementor
                // are unreachable. TypeScript reports TS7027 on the IIFE body statements
                // inside the condition and incrementor expressions.
                val initTerminates = stmt.initializer?.let { init ->
                    when (init) {
                        is VariableDeclarationList -> false
                        is Expression -> exprAlwaysThrows(init)
                        else -> false
                    }
                } ?: false
                if (initTerminates) {
                    // Report unreachable code inside IIFE bodies of condition and incrementor
                    reportUnreachableIIFEBody(stmt.condition, source, fileName)
                    reportUnreachableIIFEBody(stmt.incrementor, source, fileName)
                } else {
                    checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
                }
            }
            is ForInStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is ForOfStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is WhileStatement -> {
                if (isAlwaysFalse(stmt.expression)) {
                    // while(false) { ... } — body is unreachable
                    val bodyStmts = if (stmt.statement is Block) (stmt.statement as Block).statements
                                    else listOf(stmt.statement)
                    emitTS7027(bodyStmts, source, fileName)
                } else {
                    checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
                }
            }
            is DoStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkUnreachableInStatements(clauseStmts, source, fileName, binderResult)
                }
            }
            is TryStatement -> {
                checkUnreachableInStatements(stmt.tryBlock.statements, source, fileName, binderResult)
                stmt.catchClause?.let {
                    checkUnreachableInStatements(it.block.statements, source, fileName, binderResult)
                }
                stmt.finallyBlock?.let {
                    checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let { checkUnreachableInStatements(it.statements, source, fileName, binderResult) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is Constructor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is GetAccessor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        is SetAccessor -> member.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        else -> {}
                    }
                }
            }
            is LabeledStatement -> checkUnreachableInNestedStatement(stmt.statement, source, fileName, binderResult)
            is ExpressionStatement -> {
                // Check arrow/function expressions
                when (val expr = stmt.expression) {
                    is ArrowFunction -> when (val body = expr.body) {
                        is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                        else -> {}
                    }
                    is FunctionExpression -> expr.body?.let {
                        checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                    }
                    else -> {}
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    when (val init = decl.initializer) {
                        is ArrowFunction -> when (val body = init.body) {
                            is Block -> checkUnreachableInStatements(body.statements, source, fileName, binderResult)
                            else -> {}
                        }
                        is FunctionExpression -> init.body?.let {
                            checkUnreachableInStatements(it.statements, source, fileName, binderResult)
                        }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body as? ModuleBlock ?: return
                checkUnreachableInStatements(body.statements, source, fileName, binderResult)
            }
            else -> {}
        }
    }

    private fun emitTS7027(stmts: List<Statement>, source: String, fileName: String) {
        if (stmts.isEmpty()) return
        val first = stmts.first()
        // Skip leading whitespace on first statement
        var actualStart = first.pos
        while (actualStart < source.length && source[actualStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            actualStart++
        }
        // For `const enum` declarations, the parser sets pos to the `enum` keyword
        // (since the caller consumes `const` via nextToken() before calling parseEnumDeclaration).
        // Look backwards to include the `const` keyword in the span start.
        actualStart = findConstEnumStart(source, first, actualStart)
        // Compute real span end for the last statement.
        // stmt.end includes one extra "next token" due to how our parser captures end positions.
        // Use a forward scan to find the natural end of the last statement.
        val spanEnd = computeUnreachableSpanEnd(source, stmts.last(), actualStart)
        val length = spanEnd - actualStart
        val (line, character) = getLineAndCharacterOfPosition(source, actualStart)
        diagnostics.add(Diagnostic(
            message = "Unreachable code detected.",
            category = DiagnosticCategory.Error,
            code = 7027,
            fileName = fileName,
            line = line,
            character = character,
            start = actualStart,
            length = length.coerceAtLeast(1),
        ))
    }

    /**
     * For `const enum` declarations, the parser sets `pos` to the `enum` keyword because the
     * caller consumed `const` via `nextToken()` before invoking `parseEnumDeclaration`.
     * This function looks backwards from the node pos to include `const` in the span start.
     */
    private fun findConstEnumStart(source: String, stmt: Statement, currentStart: Int): Int {
        if (stmt !is EnumDeclaration || ModifierFlag.Const !in stmt.modifiers) return currentStart
        // Look backwards from currentStart for "const" keyword
        var pos = currentStart - 1
        // Skip any whitespace/space between const and enum
        while (pos >= 0 && source[pos].let { it == ' ' || it == '\t' }) pos--
        // Check if source[pos-4..pos] == "const"
        if (pos >= 4 && source.substring(pos - 4, pos + 1) == "const") {
            return pos - 4
        }
        return currentStart
    }

    /**
     * Compute the real end of the last unreachable statement, excluding the
     * contaminating "next outer token" that stmt.end includes due to the scanner
     * advancing one token ahead during parsing.
     */
    private fun computeUnreachableSpanEnd(source: String, stmt: Statement, minStart: Int): Int {
        // Find the start of the statement text (after leading trivia)
        var start = stmt.pos
        while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            start++
        }
        start = start.coerceAtLeast(minStart)

        // Forward scan to find natural statement end (avoids the "next token" contamination)
        val naturalEnd = findStatementNaturalEnd(source, start, stmt.end)

        if (naturalEnd < stmt.end) {
            // Found a natural end before stmt.end — the scan terminated cleanly
            return naturalEnd
        }

        // Reached stmt.end without a natural terminator (e.g., ASI case at top level).
        // Trim trailing whitespace from stmt.end.
        var spanEnd = stmt.end
        while (spanEnd > start && spanEnd <= source.length && source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
            spanEnd--
        }

        // If the last char is '}', it may be the contaminating outer closing token.
        // Apply backward trimming to remove it and its preceding whitespace.
        if (spanEnd > start && spanEnd <= source.length && source[spanEnd - 1] == '}') {
            while (spanEnd > start && source[spanEnd - 1].let { it != ' ' && it != '\t' && it != '\n' && it != '\r' }) {
                spanEnd--
            }
            while (spanEnd > start && source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) {
                spanEnd--
            }
        }

        return spanEnd.coerceAtLeast(start + 1)
    }

    /**
     * Scan forward from [start] to find where the statement's content naturally ends,
     * not exceeding [upTo]. Tracks bracket depth to correctly handle nested blocks.
     *
     * Returns position AFTER the closing ';' or '}' that terminates the statement at depth 0.
     * Returns [upTo] if no natural end is found within the range.
     */
    private fun findStatementNaturalEnd(source: String, start: Int, upTo: Int): Int {
        var i = start
        var depth = 0
        var inString = false
        var stringChar = ' '

        while (i < upTo && i < source.length) {
            val ch = source[i]
            if (inString) {
                when {
                    ch == '\\' -> { i += 2; continue }
                    ch == stringChar -> { inString = false; i++ }
                    else -> i++
                }
                continue
            }
            when (ch) {
                '"', '\'' -> { inString = true; stringChar = ch; i++ }
                '`' -> { inString = true; stringChar = ch; i++ }
                '{', '(' , '[' -> { depth++; i++ }
                '}' -> {
                    depth--
                    i++
                    when {
                        depth < 0 -> return i - 1   // outer closing brace — stop BEFORE it
                        depth == 0 -> {
                            // Block closed at top level. Check if a ';' immediately follows
                            // (e.g. `x = function() { ... };` — need to include the ';').
                            var k = i
                            while (k < source.length && source[k].let { it == ' ' || it == '\t' }) k++
                            return if (k < upTo && k < source.length && source[k] == ';') k + 1 else i
                        }
                    }
                }
                ')', ']' -> { depth--; i++ }
                ';' -> { if (depth == 0) return i + 1; else i++ }
                else -> i++
            }
        }
        return i  // reached upTo (e.g., EOF or stmt.end)
    }

    // -----------------------------------------------------------------------
    // Missing function implementation checking (TS2391)
    // -----------------------------------------------------------------------

    /**
     * Check for function/method overload declarations that are missing their
     * implementation. Emits TS2391 "Function implementation is missing or
     * not immediately following the declaration."
     */
    private fun checkMissingImplementations() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files — TS8017 handles bodiless functions in JS
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            checkMissingImplInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkMissingImplInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
    ) {
        // Check file-level function declarations
        for (i in statements.indices) {
            val stmt = statements[i]
            when (stmt) {
                is FunctionDeclaration -> {
                    if (stmt.body == null && ModifierFlag.Declare !in stmt.modifiers) {
                        val name = stmt.name?.text ?: continue
                        // Check what follows this overload signature
                        val implResult = findImplementation(statements, i, name)
                        when (implResult) {
                            is ImplResult.Found -> {} // Same name follows
                            is ImplResult.WrongName -> {
                                // Next function has body but different name → TS2389
                                emitTS2389(implResult.nameNode, source, fileName, name)
                            }
                            is ImplResult.Missing -> {
                                emitTS2391(stmt.name!!, source, fileName)
                            }
                        }
                    }
                }
                is ClassDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        checkMissingImplInClass(stmt.members, source, fileName)
                    }
                }
                is ModuleDeclaration -> {
                    if (ModifierFlag.Declare !in stmt.modifiers) {
                        val body = stmt.body as? ModuleBlock ?: continue
                        checkMissingImplInStatements(body.statements, source, fileName)
                    }
                }
                is Block -> checkMissingImplInStatements(stmt.statements, source, fileName)
                is IfStatement -> {
                    checkMissingImplInStatements(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let {
                        checkMissingImplInStatements(listOf(it), source, fileName)
                    }
                }
                else -> {}
            }
        }
    }

    private sealed class ImplResult {
        data object Found : ImplResult()
        data class WrongName(val nameNode: Node) : ImplResult()
        data object Missing : ImplResult()
    }

    private fun findImplementation(
        statements: List<Statement>,
        fromIdx: Int,
        name: String,
    ): ImplResult {
        // Look at subsequent statements for a same-name function.
        for (j in fromIdx + 1 until statements.size) {
            val next = statements[j]
            if (next is FunctionDeclaration) {
                if (next.name?.text == name) {
                    return ImplResult.Found // Same name follows
                }
                // Different name with body → TS2389
                if (next.body != null && next.name != null) {
                    return ImplResult.WrongName(next.name!!)
                }
            }
            break // Different statement breaks the chain
        }
        return ImplResult.Missing
    }

    private fun checkMissingImplInClass(
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Track methods with bodies for TS2393 duplicate implementation detection
        val methodsWithBody = mutableMapOf<String, MethodDeclaration>()

        for (i in members.indices) {
            val member = members[i]
            if (member is Constructor && member.body == null) {
                // Constructor overload without body — check if a constructor WITH body follows
                val hasImpl = members.subList(i + 1, members.size).any { it is Constructor && it.body != null }
                if (!hasImpl) {
                    // Emit TS2390 on the "constructor" keyword span
                    emitTS2390(member, source, fileName)
                }
            } else if (member is MethodDeclaration) {
                val name = when (val n = member.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    is NumericLiteralNode -> n.text
                    else -> continue
                }
                // Include static qualifier in the key to distinguish instance vs static
                val isStatic = ModifierFlag.Static in member.modifiers
                val key = if (isStatic) "static:$name" else name

                if (member.body != null) {
                    val prev = methodsWithBody[key]
                    if (prev != null) {
                        // Duplicate implementation — TS2393 on both
                        emitTS2393(prev.name, source, fileName)
                        emitTS2393(member.name, source, fileName)
                    } else {
                        methodsWithBody[key] = member
                    }
                } else if (ModifierFlag.Abstract !in member.modifiers) {
                    // Overload without body — check for missing implementation
                    val displayName = when (member.name) {
                        is StringLiteralNode -> "\"$name\""
                        else -> name
                    }
                    val implResult = findMethodImplementation(members, i, name)
                    when (implResult) {
                        is ImplResult.Found -> {} // Same name follows
                        is ImplResult.WrongName -> {
                            emitTS2389(implResult.nameNode, source, fileName, displayName)
                        }
                        is ImplResult.Missing -> {
                            emitTS2391(member.name, source, fileName)
                        }
                    }
                }
            }
            // Recurse into nested class declarations
            if (member is PropertyDeclaration) {
                val init = member.initializer
                if (init is ClassExpression) {
                    checkMissingImplInClass(init.members, source, fileName)
                }
            }
        }
    }

    private fun emitTS2393(nameNode: Node, source: String, fileName: String) {
        val start = nameNode.pos
        val name = when (nameNode) {
            is Identifier -> nameNode.text
            is StringLiteralNode -> nameNode.text
            is NumericLiteralNode -> nameNode.text
            else -> return
        }
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Duplicate function implementation.",
            category = DiagnosticCategory.Error,
            code = 2393,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun findMethodImplementation(
        members: List<ClassElement>,
        fromIdx: Int,
        name: String,
    ): ImplResult {
        for (j in fromIdx + 1 until members.size) {
            val next = members[j]
            if (next is MethodDeclaration) {
                val nextName = when (val n = next.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    is NumericLiteralNode -> n.text
                    else -> null
                }
                if (nextName == name) {
                    return ImplResult.Found
                }
                // Different name with body → TS2389
                if (next.body != null && nextName != null) {
                    return ImplResult.WrongName(next.name)
                }
            }
            break // Non-matching member breaks the chain
        }
        return ImplResult.Missing
    }

    // -----------------------------------------------------------------------
    // Bodyless function return type checking (TS7010)
    // -----------------------------------------------------------------------

    /**
     * Check for function/method declarations without a body that lack a return
     * type annotation. Emits TS7010 when:
     * - The declaration is ambient (declare function) without return type, OR
     * - The declaration is a non-ambient overload with no matching implementation
     *   (same name with body) anywhere in the same scope.
     * This check is suppressed when @strict: false is explicitly set (like TS2454/TS2564).
     */
    private fun checkBodylessFunctionReturnTypesMissing() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files — TS8017 handles bodiless functions
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            checkTS7010InStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkTS7010InStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        isAmbientClass: Boolean = false,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    if (stmt.body == null && stmt.name != null && stmt.type == null) {
                        val name = stmt.name!!.text
                        // Emit TS7010 for all bodyless function declarations (both declare and overloads)
                        // that lack a return type annotation, regardless of whether an implementation exists.
                        emitTS7010(stmt.name!!, name, source, fileName)
                    }
                    stmt.body?.let { checkTS7010InStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    val isAmbient = ModifierFlag.Declare in stmt.modifiers
                    // Check methods in class body (recurse with ambient context)
                    for (member in stmt.members) {
                        if (member is MethodDeclaration && member.body == null && member.type == null) {
                            val name = (member.name as? Identifier)?.text
                                ?: (member.name as? StringLiteralNode)?.text
                            if (name != null && isAmbient) {
                                // In ambient classes, only PUBLIC methods get TS7010
                                val isPrivate = ModifierFlag.Private in member.modifiers
                                if (!isPrivate) {
                                    emitTS7010(member.name!!, name, source, fileName)
                                }
                            }
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    // Interface method signatures without return type annotation get TS7010/TS7020/TS7021.
                    // The squiggle covers the full method signature (from name through `;`).
                    for (member in stmt.members) {
                        if (member is MethodDeclaration && member.type == null) {
                            val rawName = (member.name as? Identifier)?.text
                                ?: (member.name as? StringLiteralNode)?.text
                            if (rawName != null) {
                                when {
                                    rawName.isEmpty() -> {
                                        // Call signature `()` — emit TS7020
                                        emitTS7020WithSpan(member.pos, member.end - member.pos, source, fileName)
                                    }
                                    rawName == "new" -> {
                                        // Construct signature `new()` — emit TS7013
                                        emitTS7013WithSpan(member.pos, member.end - member.pos, source, fileName)
                                    }
                                    else -> {
                                        // Named method signature — emit TS7010
                                        emitTS7010WithSpan(member.pos, member.end - member.pos, rawName, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkTS7010InStatements(body.statements, source, fileName)
                    } else if (body is ModuleDeclaration) {
                        checkTS7010InStatements(listOf(body), source, fileName)
                    }
                }
                is Block -> checkTS7010InStatements(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    /** Check if any function declaration with [name] and a body exists in [statements]. */
    private fun hasImplementationInScope(statements: List<Statement>, name: String): Boolean {
        return statements.any { it is FunctionDeclaration && it.name?.text == name && it.body != null }
    }

    private fun emitTS7010(nameNode: Node, nameText: String, source: String, fileName: String) {
        val start = nameNode.pos
        val length = when (nameNode) {
            is Identifier -> nameNode.text.length
            is StringLiteralNode -> nameNode.text.length + 2 // include quotes
            else -> return
        }
        emitTS7010WithSpan(start, length, nameText, source, fileName)
    }

    private fun emitTS7010WithSpan(start: Int, length: Int, nameText: String, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'$nameText', which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7010,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** TS7020: Call signature, which lacks return-type annotation, implicitly has an 'any' return type. */
    private fun emitTS7020WithSpan(start: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Call signature, which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7020,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** TS7013: Construct signature, which lacks return-type annotation, implicitly has an 'any' return type. */
    private fun emitTS7013WithSpan(start: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Construct signature, which lacks return-type annotation, implicitly has an 'any' return type.",
            category = DiagnosticCategory.Error,
            code = 7013,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2390(constructor: Constructor, source: String, fileName: String) {
        // TS2390: "Constructor implementation is missing." — squiggle covers "constructor" keyword
        val pos = constructor.pos
        val length = "constructor".length
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "Constructor implementation is missing.",
            category = DiagnosticCategory.Error,
            code = 2390,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = length,
        ))
    }

    private fun emitTS2391(nameNode: Node, source: String, fileName: String) {
        val start = nameNode.pos
        val name = when (nameNode) {
            is Identifier -> nameNode.text
            is StringLiteralNode -> nameNode.text
            else -> return
        }
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Function implementation is missing or not immediately following the declaration.",
            category = DiagnosticCategory.Error,
            code = 2391,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2389(nameNode: Node, source: String, fileName: String, expectedName: String) {
        val start = nameNode.pos
        val name = when (nameNode) {
            is Identifier -> nameNode.text
            is StringLiteralNode -> "\"${nameNode.text}\""
            is NumericLiteralNode -> nameNode.text
            else -> return
        }
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Function implementation name must be '$expectedName'.",
            category = DiagnosticCategory.Error,
            code = 2389,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Argument count checking (TS2554)
    // -----------------------------------------------------------------------

    /**
     * Check call and new expressions for wrong argument counts.
     * Only handles simple, direct function calls and class constructors
     * in the same file. Skips overloaded functions and rest parameters.
     */
    private fun checkArgumentCounts() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // In JS files (allowJs/checkJs), all parameters are implicitly optional (min=0)
            val isJsFile = fileName.endsWith(".js") || fileName.endsWith(".jsx") || fileName.endsWith(".mjs") || fileName.endsWith(".cjs")

            // Build function/class declaration maps for this file
            val funcParams = mutableMapOf<String, FuncParamInfo>()
            val classCtorParams = mutableMapOf<String, FuncParamInfo>()
            collectFuncDecls(result.sourceFile.statements, funcParams, classCtorParams, isJsFile)

            // Walk statements checking call expressions
            checkArgCountInStatements(result.sourceFile.statements, funcParams, classCtorParams, source, fileName)
        }
    }

    private data class FuncParamInfo(
        val minParams: Int,     // required params
        val maxParams: Int,     // total params (required + optional)
        val hasRest: Boolean,   // has ...rest param
        val isOverloaded: Boolean, // has multiple declarations (skip checking)
        val parameters: List<Parameter> = emptyList(), // actual parameter nodes (for related info)
    )

    private fun collectFuncDecls(
        statements: List<Statement>,
        funcParams: MutableMap<String, FuncParamInfo>,
        classCtorParams: MutableMap<String, FuncParamInfo>,
        isJsFile: Boolean = false,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    if (stmt.body == null) {
                        // Overload signature — mark as overloaded
                        funcParams[name] = FuncParamInfo(0, Int.MAX_VALUE, hasRest = true, isOverloaded = true)
                        continue
                    }
                    if (funcParams[name]?.isOverloaded == true) continue // already marked as overloaded
                    val info = paramInfo(stmt.parameters, isJsFile)
                    funcParams[name] = info
                }
                is ClassDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    val ctor = stmt.members.filterIsInstance<Constructor>().firstOrNull()
                    if (ctor != null) {
                        val info = paramInfo(ctor.parameters, isJsFile)
                        classCtorParams[name] = info
                    } else if (stmt.heritageClauses.isNullOrEmpty()) {
                        // No explicit constructor and no base class → 0 params
                        classCtorParams[name] = FuncParamInfo(0, 0, hasRest = false, isOverloaded = false)
                    }
                    // Skip classes with base class but no explicit constructor —
                    // they inherit the base constructor's param count which we can't resolve
                }
                is ModuleDeclaration -> {
                    val body = stmt.body as? ModuleBlock ?: continue
                    collectFuncDecls(body.statements, funcParams, classCtorParams, isJsFile)
                }
                else -> {}
            }
        }
    }

    private fun paramInfo(parameters: List<Parameter>, isJsFile: Boolean = false): FuncParamInfo {
        var total = 0
        var hasRest = false
        var lastRequiredPos = -1  // 0-based index of last non-optional param
        for (p in parameters) {
            // Skip `this` pseudo-parameter
            if (p.name is Identifier && (p.name as Identifier).text == "this") continue
            if (p.dotDotDotToken) {
                hasRest = true
                continue
            }
            // In JS files (checkJs), all parameters are implicitly optional (min=0, max=N)
            if (!isJsFile && !p.questionToken && p.initializer == null) {
                lastRequiredPos = total
            }
            total++
        }
        // Required = position of last required param + 1.
        // E.g., f(a, b = 0, c) → lastRequiredPos = 2 → required = 3.
        // This ensures optional params before a required one are effectively required.
        val required = lastRequiredPos + 1
        return FuncParamInfo(required, total, hasRest, isOverloaded = false, parameters = parameters)
    }

    private fun checkArgCountInStatements(
        statements: List<Statement>,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        for (stmt in statements) {
            checkArgCountInStatement(stmt, funcParams, classCtorParams, source, fileName)
        }
    }

    private fun checkArgCountInStatement(
        stmt: Statement,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            is IfStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInStatement(stmt.thenStatement, funcParams, classCtorParams, source, fileName)
                stmt.elseStatement?.let { checkArgCountInStatement(it, funcParams, classCtorParams, source, fileName) }
            }
            is Block -> checkArgCountInStatements(stmt.statements, funcParams, classCtorParams, source, fileName)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                        }
                    }
                    is Expression -> checkArgCountInExpr(init, funcParams, classCtorParams, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                stmt.incrementor?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            }
            is ForInStatement -> checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            is ForOfStatement -> checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            is WhileStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
            }
            is DoStatement -> {
                checkArgCountInStatement(stmt.statement, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
            }
            is SwitchStatement -> {
                checkArgCountInExpr(stmt.expression, funcParams, classCtorParams, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkArgCountInStatements(clauseStmts, funcParams, classCtorParams, source, fileName)
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let {
                    checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        is Constructor -> member.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        is GetAccessor -> member.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        is SetAccessor -> member.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        is PropertyDeclaration -> member.initializer?.let {
                            checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkArgCountInStatements(stmt.tryBlock.statements, funcParams, classCtorParams, source, fileName)
                stmt.catchClause?.let {
                    checkArgCountInStatements(it.block.statements, funcParams, classCtorParams, source, fileName)
                }
                stmt.finallyBlock?.let {
                    checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                }
            }
            else -> {}
        }
    }

    private fun checkArgCountInExpr(
        expr: Expression,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        if (++argCountDepth > 200) { argCountDepth--; return }
        try { checkArgCountInExprCore(expr, funcParams, classCtorParams, source, fileName) }
        finally { argCountDepth-- }
    }

    private fun checkArgCountInExprCore(
        expr: Expression,
        funcParams: Map<String, FuncParamInfo>,
        classCtorParams: Map<String, FuncParamInfo>,
        source: String,
        fileName: String,
    ) {
        when (expr) {
            is CallExpression -> {
                // Check the callee
                val calleeName = when (val e = expr.expression) {
                    is Identifier -> e.text
                    else -> null
                }
                if (calleeName != null) {
                    val info = funcParams[calleeName]
                    if (info != null && !info.isOverloaded) {
                        val argCount = expr.arguments.size
                        if (!info.hasRest && argCount > info.maxParams) {
                            emitTS2554TooMany(info.minParams, info.maxParams, argCount, expr.arguments, info.maxParams, source, fileName)
                        } else if (argCount < info.minParams) {
                            if (info.hasRest) {
                                emitTS2555TooFew(info.minParams, argCount, expr.expression, source, fileName, info.parameters)
                            } else {
                                emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr.expression, source, fileName, info.parameters)
                            }
                        }
                    }
                }
                // Recurse into arguments
                for (arg in expr.arguments) {
                    checkArgCountInExpr(arg, funcParams, classCtorParams, source, fileName)
                }
                checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            }
            is NewExpression -> {
                val className = when (val e = expr.expression) {
                    is Identifier -> e.text
                    else -> null
                }
                if (className != null) {
                    val info = classCtorParams[className]
                    if (info != null && !info.isOverloaded) {
                        val argCount = expr.arguments?.size ?: 0
                        if (!info.hasRest && argCount > info.maxParams) {
                            val args = expr.arguments ?: emptyList()
                            emitTS2554TooMany(info.minParams, info.maxParams, argCount, args, info.maxParams, source, fileName)
                        } else if (argCount < info.minParams) {
                            if (info.hasRest) {
                                emitTS2555TooFew(info.minParams, argCount, expr.expression, source, fileName)
                            } else {
                                emitTS2554TooFew(info.minParams, info.maxParams, argCount, expr.expression, source, fileName)
                            }
                        }
                    }
                }
                // Recurse
                expr.arguments?.forEach { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            }
            is BinaryExpression -> {
                // Iterative right-spine walk to prevent StackOverflow on deep chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkArgCountInExpr(current.left, funcParams, classCtorParams, source, fileName)
                    current = current.right
                }
                checkArgCountInExpr(current, funcParams, classCtorParams, source, fileName)
            }
            is ParenthesizedExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is ConditionalExpression -> {
                checkArgCountInExpr(expr.condition, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(expr.whenTrue, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(expr.whenFalse, funcParams, classCtorParams, source, fileName)
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkArgCountInStatements(body.statements, funcParams, classCtorParams, source, fileName)
                    is Expression -> checkArgCountInExpr(body, funcParams, classCtorParams, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                expr.body?.let {
                    checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                }
            }
            is ArrayLiteralExpression -> {
                for (el in expr.elements) {
                    checkArgCountInExpr(el, funcParams, classCtorParams, source, fileName)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkArgCountInExpr(prop.initializer, funcParams, classCtorParams, source, fileName)
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> checkArgCountInExpr(prop.expression, funcParams, classCtorParams, source, fileName)
                        is MethodDeclaration -> prop.body?.let {
                            checkArgCountInStatements(it.statements, funcParams, classCtorParams, source, fileName)
                        }
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkArgCountInExpr(span.expression, funcParams, classCtorParams, source, fileName)
                }
            }
            is PropertyAccessExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is ElementAccessExpression -> {
                checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
                checkArgCountInExpr(expr.argumentExpression, funcParams, classCtorParams, source, fileName)
            }
            is PrefixUnaryExpression -> checkArgCountInExpr(expr.operand, funcParams, classCtorParams, source, fileName)
            is PostfixUnaryExpression -> checkArgCountInExpr(expr.operand, funcParams, classCtorParams, source, fileName)
            is TypeAssertionExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is AsExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is NonNullExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is SpreadElement -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is AwaitExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is YieldExpression -> expr.expression?.let { checkArgCountInExpr(it, funcParams, classCtorParams, source, fileName) }
            is VoidExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is TypeOfExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is DeleteExpression -> checkArgCountInExpr(expr.expression, funcParams, classCtorParams, source, fileName)
            is TaggedTemplateExpression -> {
                checkArgCountInExpr(expr.tag, funcParams, classCtorParams, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Emit TS2554 for too many arguments.
     * Squiggle covers args[expectedCount] through args.last().
     */
    private fun formatExpectedArgs(minParams: Int, maxParams: Int): String =
        if (minParams != maxParams) "$minParams-$maxParams" else "$maxParams"

    private fun emitTS2554TooMany(
        minParams: Int,
        maxParams: Int,
        actual: Int,
        args: List<Expression>,
        firstExcessIdx: Int,
        source: String,
        fileName: String,
    ) {
        if (firstExcessIdx >= args.size) return
        val firstExcess = args[firstExcessIdx]
        val lastArg = args.last()
        val start = firstExcess.pos
        // Node.end includes the next token's scan position (always 1 char: ',' or ')'),
        // so subtract 1 to get the actual end of the argument text.
        val length = lastArg.end - 1 - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    private fun emitTS2554TooFew(
        minParams: Int,
        maxParams: Int,
        actual: Int,
        calleeExpr: Expression,
        source: String,
        fileName: String,
        parameters: List<Parameter> = emptyList(),
    ) {
        val start = calleeExpr.pos
        val length = expressionTrueEnd(calleeExpr) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Check if the first missing parameter is a binding pattern → emit TS6211 related info
        val relatedInfo = mutableListOf<Diagnostic>()
        if (parameters.isNotEmpty()) {
            // Find the first missing parameter (at index `actual`, skipping `this` params)
            val nonThisParams = parameters.filter {
                !(it.name is Identifier && (it.name as Identifier).text == "this")
            }
            if (actual < nonThisParams.size) {
                val missingParam = nonThisParams[actual]
                when (val paramName = missingParam.name) {
                    is ObjectBindingPattern, is ArrayBindingPattern -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.end - paramStart
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument matching this binding pattern was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6211,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    is Identifier -> {
                        // TS6210: "An argument for 'x' was not provided."
                        val paramStart = paramName.pos
                        val paramLen = paramName.text.length
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument for '${paramName.text}' was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6210,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    else -> {}
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected ${formatExpectedArgs(minParams, maxParams)} arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2554,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    /**
     * Emit TS2555 for too few arguments when function has rest parameters.
     * "Expected at least N arguments, but got M."
     */
    private fun emitTS2555TooFew(
        minParams: Int,
        actual: Int,
        calleeExpr: Expression,
        source: String,
        fileName: String,
        parameters: List<Parameter> = emptyList(),
    ) {
        val start = calleeExpr.pos
        val length = expressionTrueEnd(calleeExpr) - start
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val relatedInfo = mutableListOf<Diagnostic>()
        if (parameters.isNotEmpty()) {
            val nonThisParams = parameters.filter {
                !(it.name is Identifier && (it.name as Identifier).text == "this")
            }
            if (actual < nonThisParams.size) {
                val missingParam = nonThisParams[actual]
                when (val paramName = missingParam.name) {
                    is Identifier -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.text.length
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument for '${paramName.text}' was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6210,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    is ObjectBindingPattern, is ArrayBindingPattern -> {
                        val paramStart = paramName.pos
                        val paramLen = paramName.end - paramStart
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, paramStart)
                        relatedInfo.add(Diagnostic(
                            message = "An argument matching this binding pattern was not provided.",
                            category = DiagnosticCategory.Message,
                            code = 6211,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = paramStart,
                            length = paramLen,
                        ))
                    }
                    else -> {}
                }
            }
        }
        diagnostics.add(Diagnostic(
            message = "Expected at least $minParams arguments, but got $actual.",
            category = DiagnosticCategory.Error,
            code = 2555,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = relatedInfo.ifEmpty { emptyList() },
        ))
    }

    // -----------------------------------------------------------------------
    // Implicit this checking (TS2683)
    // -----------------------------------------------------------------------

    /**
     * Check for `this` expressions in functions without a `this:` parameter annotation
     * when noImplicitThis is enabled. Emits TS2683.
     *
     * The "this context" tracks whether `this` is typed (in a class member) or untyped
     * (in a regular function without `this:` param). Arrow functions are transparent —
     * they inherit the outer `this` context.
     *
     * @param shadowFunctionPos when non-null, the position of the function that shadows
     *   an outer typed `this` (for the related TS2738 diagnostic)
     */
    private fun checkImplicitThis() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkThisInStatements(
                result.sourceFile.statements, source, fileName,
                thisIsTyped = false, // file level — this is 'any' but we don't error at file level
                insideFunction = false, // not inside any function yet
                shadowFunctionPos = -1
            )
        }
    }

    private fun checkThisInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        thisIsTyped: Boolean,
        insideFunction: Boolean,
        shadowFunctionPos: Int,
    ) {
        for (stmt in statements) {
            checkThisInStatement(stmt, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
        }
    }

    private fun checkThisInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        thisIsTyped: Boolean,
        insideFunction: Boolean,
        shadowFunctionPos: Int,
    ) {
        when (stmt) {
            is FunctionDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val hasThisParam = hasThisParameter(stmt.parameters)
                val newThisIsTyped = hasThisParam
                val newShadowPos = if (!hasThisParam && thisIsTyped) {
                    // This function shadows a typed this context
                    stmt.name?.pos ?: stmt.pos
                } else if (!hasThisParam && !thisIsTyped) {
                    shadowFunctionPos // keep existing shadow info
                } else -1
                stmt.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = newThisIsTyped,
                        insideFunction = true,
                        shadowFunctionPos = newShadowPos
                    )
                }
            }
            is ClassDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                for (member in stmt.members) {
                    checkThisInClassElement(member, source, fileName)
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let {
                        checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                    }
                }
            }
            is ExpressionStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ReturnStatement -> {
                stmt.expression?.let {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is IfStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInStatement(stmt.thenStatement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                stmt.elseStatement?.let {
                    checkThisInStatement(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is Block -> {
                checkThisInStatements(stmt.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ForStatement -> {
                stmt.initializer?.let {
                    when (it) {
                        is Expression -> checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                        is VariableDeclarationList -> {
                            for (decl in it.declarations) {
                                decl.initializer?.let { init ->
                                    checkThisInExpr(init, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                                }
                            }
                        }
                        else -> {}
                    }
                }
                stmt.condition?.let { checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos) }
                stmt.incrementor?.let { checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos) }
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ForInStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ForOfStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is WhileStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is DoStatement -> {
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is SwitchStatement -> {
                checkThisInExpr(stmt.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkThisInExpr(clause.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                            checkThisInStatements(clause.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                        }
                        is DefaultClause -> {
                            checkThisInStatements(clause.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                        }
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> {
                stmt.expression?.let {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is TryStatement -> {
                checkThisInStatements(stmt.tryBlock.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                stmt.catchClause?.let {
                    checkThisInStatements(it.block.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
                stmt.finallyBlock?.let {
                    checkThisInStatements(it.statements, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is LabeledStatement -> {
                checkThisInStatement(stmt.statement, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ModuleDeclaration -> {
                when (val body = stmt.body) {
                    is ModuleBlock -> checkThisInStatements(
                        body.statements, source, fileName,
                        thisIsTyped = false, insideFunction = false, shadowFunctionPos = -1
                    )
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun checkThisInClassElement(
        element: ClassElement,
        source: String,
        fileName: String,
    ) {
        // Inside class members, `this` is typed — no error
        when (element) {
            is MethodDeclaration -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is Constructor -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is GetAccessor -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is SetAccessor -> {
                element.body?.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                    )
                }
            }
            is PropertyDeclaration -> {
                // Property initializers: `this` is typed (class context)
                // but function expressions in property initializers create new `this` scope
                element.initializer?.let {
                    checkThisInExpr(
                        it, source, fileName,
                        thisIsTyped = true, insideFunction = false, shadowFunctionPos = -1
                    )
                }
            }
            else -> {}
        }
    }

    private fun checkThisInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        thisIsTyped: Boolean,
        insideFunction: Boolean,
        shadowFunctionPos: Int,
    ) {
        when (expr) {
            is Identifier -> {
                if (expr.text == "this" && !thisIsTyped && insideFunction) {
                    emitTS2683(expr, source, fileName, shadowFunctionPos)
                }
            }
            is FunctionExpression -> {
                val hasThisParam = hasThisParameter(expr.parameters)
                val newThisIsTyped = hasThisParam
                val newShadowPos = if (!hasThisParam && thisIsTyped) {
                    // This function expression shadows a typed this context
                    expr.name?.pos ?: expr.pos
                } else if (!hasThisParam && !thisIsTyped) {
                    shadowFunctionPos
                } else -1
                expr.body.let {
                    checkThisInStatements(
                        it.statements, source, fileName,
                        thisIsTyped = newThisIsTyped,
                        insideFunction = true,
                        shadowFunctionPos = newShadowPos
                    )
                }
            }
            is ArrowFunction -> {
                // Arrow functions are transparent — inherit outer this context
                // insideFunction stays as-is: arrows don't create their own this
                when (val body = expr.body) {
                    is Block -> checkThisInStatements(
                        body.statements, source, fileName,
                        thisIsTyped, insideFunction,
                        shadowFunctionPos
                    )
                    is Expression -> checkThisInExpr(
                        body, source, fileName,
                        thisIsTyped, insideFunction,
                        shadowFunctionPos
                    )
                    else -> {}
                }
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    checkThisInClassElement(member, source, fileName)
                }
            }
            is CallExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                expr.arguments.forEach {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is NewExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                expr.arguments?.forEach {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkThisInExpr(current.right, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                    current = current.left
                }
                checkThisInExpr(current, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ParenthesizedExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is PropertyAccessExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ElementAccessExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInExpr(expr.argumentExpression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ConditionalExpression -> {
                checkThisInExpr(expr.condition, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInExpr(expr.whenTrue, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                checkThisInExpr(expr.whenFalse, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> {
                            val init = prop.initializer
                            if (init is FunctionExpression) {
                                // Function expressions as object literal property values have
                                // typed this (TypeScript infers the object type)
                                init.body.let {
                                    checkThisInStatements(
                                        it.statements, source, fileName,
                                        thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                                    )
                                }
                            } else {
                                checkThisInExpr(init, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                            }
                        }
                        is MethodDeclaration -> {
                            // Object literal methods have typed this (the object type)
                            prop.body?.let {
                                checkThisInStatements(
                                    it.statements, source, fileName,
                                    thisIsTyped = true, insideFunction = true, shadowFunctionPos = -1
                                )
                            }
                        }
                        is SpreadAssignment -> {
                            checkThisInExpr(prop.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                        }
                        is ShorthandPropertyAssignment -> {
                            prop.objectAssignmentInitializer?.let {
                                checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                            }
                        }
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) {
                    checkThisInExpr(span.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is TaggedTemplateExpression -> {
                checkThisInExpr(expr.tag, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                when (val template = expr.template) {
                    is TemplateExpression -> {
                        for (span in template.templateSpans) {
                            checkThisInExpr(span.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                        }
                    }
                    else -> {}
                }
            }
            is PrefixUnaryExpression -> {
                checkThisInExpr(expr.operand, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is PostfixUnaryExpression -> {
                checkThisInExpr(expr.operand, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is TypeOfExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is VoidExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is DeleteExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is AwaitExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is SpreadElement -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is YieldExpression -> {
                expr.expression?.let {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            is AsExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is NonNullExpression -> {
                checkThisInExpr(expr.expression, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
            }
            is CommaListExpression -> {
                expr.elements.forEach {
                    checkThisInExpr(it, source, fileName, thisIsTyped, insideFunction, shadowFunctionPos)
                }
            }
            else -> {}
        }
    }

    private fun hasThisParameter(parameters: List<Parameter>): Boolean {
        val first = parameters.firstOrNull() ?: return false
        val name = first.name
        return name is Identifier && name.text == "this"
    }

    private fun emitTS2683(
        thisExpr: Identifier,
        source: String,
        fileName: String,
        shadowFunctionPos: Int,
    ) {
        val start = thisExpr.pos
        val length = 4 // "this".length
        val (line, character) = getLineAndCharacterOfPosition(source, start)

        val related = if (shadowFunctionPos >= 0) {
            val (shadowLine, shadowCol) = getLineAndCharacterOfPosition(source, shadowFunctionPos)
            listOf(Diagnostic(
                message = "An outer value of 'this' is shadowed by this container.",
                category = DiagnosticCategory.Error,
                code = 2738,
                fileName = fileName,
                line = shadowLine,
                character = shadowCol,
            ))
        } else emptyList()

        diagnostics.add(Diagnostic(
            message = "'this' implicitly has type 'any' because it does not have a type annotation.",
            category = DiagnosticCategory.Error,
            code = 2683,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = related,
        ))
    }

    // -----------------------------------------------------------------------
    // Duplicate object literal property checking (TS1117)
    // -----------------------------------------------------------------------

    private fun checkDuplicateObjectLiteralProperties() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForObjectLiterals(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForObjectLiterals(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            walkNodeForObjectLiterals(stmt, source, fileName)
        }
    }

    private fun walkNodeForObjectLiterals(node: Node, source: String, fileName: String, depth: Int = 0) {
        if (depth > 100) return
        when (node) {
            is ObjectLiteralExpression -> {
                checkObjectLiteralDuplicates(node, source, fileName)
                // Also recurse into property values
                for (prop in node.properties) {
                    when (prop) {
                        is PropertyAssignment -> walkNodeForObjectLiterals(prop.initializer, source, fileName, depth + 1)
                        is SpreadAssignment -> walkNodeForObjectLiterals(prop.expression, source, fileName, depth + 1)
                        else -> {}
                    }
                }
            }
            // Skip the left side of assignment expressions (destructuring patterns)
            // but do check the right side
            is VariableStatement -> {
                for (decl in node.declarationList.declarations) {
                    decl.initializer?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
                }
            }
            is ExpressionStatement -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is ReturnStatement -> node.expression?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            is FunctionDeclaration -> node.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
            is ClassDeclaration -> {
                for (member in node.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is Constructor -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is GetAccessor -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is SetAccessor -> member.body?.let { walkForObjectLiterals(it.statements, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
                        else -> {}
                    }
                }
            }
            is Block -> walkForObjectLiterals(node.statements, source, fileName)
            is IfStatement -> {
                walkNodeForObjectLiterals(node.thenStatement, source, fileName, depth + 1)
                node.elseStatement?.let { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is ForStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is ForInStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is ForOfStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is WhileStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is DoStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is SwitchStatement -> {
                for (clause in node.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForObjectLiterals(clause.statements, source, fileName)
                        is DefaultClause -> walkForObjectLiterals(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForObjectLiterals(node.tryBlock.statements, source, fileName)
                node.catchClause?.block?.let { walkForObjectLiterals(it.statements, source, fileName) }
                node.finallyBlock?.let { walkForObjectLiterals(it.statements, source, fileName) }
            }
            is ArrowFunction -> {
                when (val body = node.body) {
                    is Block -> walkForObjectLiterals(body.statements, source, fileName)
                    else -> walkNodeForObjectLiterals(body, source, fileName, depth + 1)
                }
            }
            is FunctionExpression -> node.body.let { walkForObjectLiterals(it.statements, source, fileName) }
            is ParenthesizedExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is BinaryExpression -> {
                // Skip left side of assignment if it's a destructuring pattern
                if (node.operator == SyntaxKind.Equals && (node.left is ObjectLiteralExpression || node.left is ArrayLiteralExpression)) {
                    // Only recurse into the right side
                    walkNodeForObjectLiterals(node.right, source, fileName, depth + 1)
                } else {
                    walkNodeForObjectLiterals(node.left, source, fileName, depth + 1)
                    walkNodeForObjectLiterals(node.right, source, fileName, depth + 1)
                }
            }
            is ConditionalExpression -> {
                walkNodeForObjectLiterals(node.whenTrue, source, fileName, depth + 1)
                walkNodeForObjectLiterals(node.whenFalse, source, fileName, depth + 1)
            }
            is CallExpression -> {
                walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
                node.arguments.forEach { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is NewExpression -> {
                node.arguments?.forEach { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is ArrayLiteralExpression -> {
                node.elements.forEach { walkNodeForObjectLiterals(it, source, fileName, depth + 1) }
            }
            is PropertyAccessExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is TemplateExpression -> {
                node.templateSpans.forEach { walkNodeForObjectLiterals(it.expression, source, fileName, depth + 1) }
            }
            is LabeledStatement -> walkNodeForObjectLiterals(node.statement, source, fileName, depth + 1)
            is ModuleDeclaration -> {
                val body = node.body
                if (body is ModuleBlock) walkForObjectLiterals(body.statements, source, fileName)
            }
            is ExportAssignment -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is SpreadElement -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is AsExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            is TypeAssertionExpression -> walkNodeForObjectLiterals(node.expression, source, fileName, depth + 1)
            else -> {}
        }
    }

    private fun checkObjectLiteralDuplicates(obj: ObjectLiteralExpression, source: String, fileName: String) {
        // Track what kind of property has been seen: 'p' = property/method, 'g' = getter, 's' = setter
        val seen = mutableMapOf<String, Char>()
        for (prop in obj.properties) {
            val name = getPropertyName(prop) ?: continue
            val kind = when (prop) {
                is GetAccessor -> 'g'
                is SetAccessor -> 's'
                else -> 'p' // PropertyAssignment, ShorthandPropertyAssignment, MethodDeclaration
            }
            val prevKind = seen[name]
            val isDuplicate = when {
                prevKind == null -> false
                // getter + setter or setter + getter is OK
                prevKind == 'g' && kind == 's' -> false
                prevKind == 's' && kind == 'g' -> false
                else -> true
            }
            if (isDuplicate) {
                val nameNode = getPropertyNameNode(prop) ?: continue
                val start = nameNode.pos
                val length = getPropertyNameLength(nameNode, name)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "An object literal cannot have multiple properties with the same name.",
                    category = DiagnosticCategory.Error,
                    code = 1117,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            } else {
                seen[name] = kind
            }
        }
    }

    private fun getPropertyNameLength(nameNode: Node, name: String): Int {
        return when (nameNode) {
            is Identifier -> name.length
            is StringLiteralNode -> nameNode.rawText?.let { it.length + 2 } ?: (name.length + 2) // quotes
            is NumericLiteralNode -> nameNode.text.length // use original text length, not normalized name
            is ComputedPropertyName -> {
                // Span covers [expr] — find the closing ] in source
                // Can't use nameNode.end (overshoots by one token).
                // The expression text + brackets: count from pos to closing ']'
                val expr = nameNode.expression
                val exprLen = when (expr) {
                    is NumericLiteralNode -> expr.text.length
                    is StringLiteralNode -> expr.text.length + 2 // quotes
                    is PrefixUnaryExpression -> {
                        val operand = expr.operand
                        if (operand is NumericLiteralNode) 1 + operand.text.length else nameNode.end - nameNode.pos
                    }
                    is Identifier -> expr.text.length
                    is PropertyAccessExpression -> computedExpressionTextLength(expr)
                    else -> return nameNode.end - nameNode.pos
                }
                exprLen + 2 // [expr]
            }
            else -> nameNode.end - nameNode.pos
        }
    }

    private fun getPropertyName(prop: Node): String? {
        return when (prop) {
            is PropertyAssignment -> getPropertyKeyName(prop.name)
            is ShorthandPropertyAssignment -> prop.name.text
            is MethodDeclaration -> getPropertyKeyName(prop.name)
            is GetAccessor -> getPropertyKeyName(prop.name)
            is SetAccessor -> getPropertyKeyName(prop.name)
            else -> null
        }
    }

    /** Evaluate a property key to its string name, including computed property expressions. */
    private fun getPropertyKeyName(name: Node): String? {
        return when (name) {
            is Identifier -> name.text
            is StringLiteralNode -> name.text
            is NumericLiteralNode -> normalizeNumericLiteral(name.text)
            is ComputedPropertyName -> evaluateComputedPropertyName(name.expression)
            else -> null
        }
    }

    /** Normalize a numeric literal text to its canonical string form (e.g., "0b11" → "3"). */
    private fun normalizeNumericLiteral(text: String): String {
        val d = when {
            text.startsWith("0b", ignoreCase = true) -> text.substring(2).toLongOrNull(2)?.toDouble()
            text.startsWith("0o", ignoreCase = true) -> text.substring(2).toLongOrNull(8)?.toDouble()
            text.startsWith("0x", ignoreCase = true) -> text.substring(2).toLongOrNull(16)?.toDouble()
            else -> text.replace("_", "").toDoubleOrNull()
        }
        if (d == null) return text
        return if (d == d.toLong().toDouble() && d >= 0 && d < Long.MAX_VALUE.toDouble()) {
            d.toLong().toString()
        } else {
            d.toString()
        }
    }

    /** Evaluate simple constant computed property expressions to their string key value. */
    private fun evaluateComputedPropertyName(expr: Expression): String? {
        return when (expr) {
            is NumericLiteralNode -> normalizeNumericLiteral(expr.text)
            is StringLiteralNode -> expr.text  // ["+1"] → "+1"
            is PrefixUnaryExpression -> {
                val operand = expr.operand
                if (operand is NumericLiteralNode) {
                    val d = operand.text.toDoubleOrNull() ?: return null
                    val value = when (expr.operator) {
                        SyntaxKind.Plus -> d
                        SyntaxKind.Minus -> -d
                        else -> return null
                    }
                    if (value == value.toLong().toDouble()) value.toLong().toString() else value.toString()
                } else null
            }
            // Identifier and PropertyAccess references — compare syntactically
            // Prefix with __@computed: to avoid conflicts with regular property names
            is Identifier -> "__@computed:${expr.text}"
            is PropertyAccessExpression -> {
                val path = computedPropertyAccessPath(expr) ?: return null
                "__@computed:$path"
            }
            else -> null
        }
    }

    /** Build dotted path string from a property access chain (e.g., E1.A → "E1.A"). */
    private fun computedPropertyAccessPath(expr: Expression): String? {
        return when (expr) {
            is Identifier -> expr.text
            is PropertyAccessExpression -> {
                val base = computedPropertyAccessPath(expr.expression) ?: return null
                "$base.${expr.name.text}"
            }
            else -> null
        }
    }

    /** Compute the text length of a property access expression (e.g., E1.A → 4, keys.E1.A → 9). */
    private fun computedExpressionTextLength(expr: Expression): Int {
        return when (expr) {
            is Identifier -> expr.text.length
            is PropertyAccessExpression -> computedExpressionTextLength(expr.expression) + 1 + expr.name.text.length
            else -> 0
        }
    }

    private fun getPropertyNameNode(prop: Node): Node? {
        return when (prop) {
            is PropertyAssignment -> prop.name
            is ShorthandPropertyAssignment -> prop.name
            is MethodDeclaration -> prop.name
            is GetAccessor -> prop.name
            is SetAccessor -> prop.name
            else -> null
        }
    }

    // -----------------------------------------------------------------------
    // Super before this checking (TS17009)
    // -----------------------------------------------------------------------

    private fun checkSuperBeforeThis() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForDerivedConstructors(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForDerivedConstructors(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    // Check if class extends something (derived class)
                    if (stmt.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true) {
                        for (member in stmt.members) {
                            if (member is Constructor && member.body != null) {
                                checkConstructorThisBeforeSuper(member.body!!.statements, source, fileName)
                                // TS2376: when derived class has initialized properties/param properties,
                                // super() must be the first statement in the constructor
                                val hasInitializedProps = stmt.members.any { m ->
                                    m is PropertyDeclaration && m.initializer != null &&
                                        ModifierFlag.Static !in m.modifiers
                                }
                                val hasParamProps = member.parameters.any { p ->
                                    p.modifiers.any { it == ModifierFlag.Public || it == ModifierFlag.Private ||
                                        it == ModifierFlag.Protected || it == ModifierFlag.Readonly }
                                }
                                if (hasInitializedProps || hasParamProps) {
                                    // Check if super() exists somewhere in the constructor
                                    val hasSuperCall = member.body!!.statements.any { s ->
                                        s is ExpressionStatement && s.expression is CallExpression &&
                                            isSuperIdentifier((s.expression as CallExpression).expression)
                                    }
                                    // Skip prologue directives ("use strict", etc.)
                                    val firstNonPrologueStmt = member.body!!.statements.firstOrNull { s ->
                                        !(s is ExpressionStatement && s.expression is StringLiteralNode)
                                    }
                                    val isSuperFirst = firstNonPrologueStmt is ExpressionStatement &&
                                        firstNonPrologueStmt.expression is CallExpression &&
                                        isSuperIdentifier((firstNonPrologueStmt.expression as CallExpression).expression)
                                    // TS2376 only fires when super IS called, just not as first statement
                                    // (TS2377 handles missing super entirely)
                                    if (hasSuperCall && !isSuperFirst) {
                                        val start = member.pos
                                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                                        diagnostics.add(Diagnostic(
                                            message = "A 'super' call must be the first statement in the constructor to refer to 'super' or 'this' when a derived class contains initialized properties, parameter properties, or private identifiers.",
                                            category = DiagnosticCategory.Error,
                                            code = 2376,
                                            fileName = fileName,
                                            line = line,
                                            character = character,
                                            start = start,
                                            length = "constructor".length,
                                        ))
                                    }
                                }
                            }
                        }
                    }
                    // Recurse into class members for nested classes
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                            is PropertyDeclaration -> {
                                val init = member.initializer
                                if (init is ClassExpression && init.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true) {
                                    for (m in init.members) {
                                        if (m is Constructor && m.body != null) {
                                            checkConstructorThisBeforeSuper(m.body!!.statements, source, fileName)
                                        }
                                    }
                                }
                            }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForDerivedConstructors(it.statements, source, fileName) }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForDerivedConstructors(body.statements, source, fileName)
                }
                is Block -> walkForDerivedConstructors(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun isThisIdentifier(node: Node): Boolean =
        node is Identifier && node.text == "this"

    private fun isSuperIdentifier(node: Node): Boolean =
        node is Identifier && node.text == "super"

    private fun checkConstructorThisBeforeSuper(statements: List<Statement>, source: String, fileName: String) {
        // Walk statements until we find super() call; any this reference before that is TS17009
        for (stmt in statements) {
            // Check for super(this) — this in super call arguments is also an error
            val superCallThisRef = findThisInSuperCallArgs(stmt)
            if (superCallThisRef != null) {
                emitTS17009(superCallThisRef, source, fileName)
                return
            }
            // Check if this statement contains a super() call (and stop if so)
            if (containsSuperCall(stmt)) return
            // Check if this statement references 'this' before super
            val thisRef = findFirstThisReference(stmt)
            if (thisRef != null) {
                emitTS17009(thisRef, source, fileName)
                return // Only report first occurrence
            }
        }
    }

    private fun emitTS17009(thisRef: Identifier, source: String, fileName: String) {
        val start = thisRef.pos
        val length = 4 // "this" is 4 characters
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'super' must be called before accessing 'this' in the constructor of a derived class.",
            category = DiagnosticCategory.Error,
            code = 17009,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    /** Find 'this' used in super() call arguments. */
    private fun findThisInSuperCallArgs(node: Node): Identifier? {
        if (node !is ExpressionStatement) return null
        val expr = node.expression
        if (expr is CallExpression && isSuperIdentifier(expr.expression)) {
            for (arg in expr.arguments) {
                findFirstThisInExpr(arg)?.let { return it }
            }
        }
        return null
    }

    private fun containsSuperCall(node: Node): Boolean {
        return when (node) {
            is ExpressionStatement -> containsSuperCallInExpr(node.expression)
            else -> false
        }
    }

    private fun containsSuperCallInExpr(expr: Expression): Boolean {
        return when (expr) {
            is CallExpression -> isSuperIdentifier(expr.expression) || containsSuperCallInExpr(expr.expression)
            is BinaryExpression -> containsSuperCallInExpr(expr.left) || containsSuperCallInExpr(expr.right)
            is ParenthesizedExpression -> containsSuperCallInExpr(expr.expression)
            else -> false
        }
    }

    private fun findFirstThisReference(node: Node): Identifier? {
        return when (node) {
            is ExpressionStatement -> findFirstThisInExpr(node.expression)
            is VariableStatement -> {
                for (decl in node.declarationList.declarations) {
                    decl.initializer?.let { findFirstThisInExpr(it) }?.let { return it }
                }
                null
            }
            is ReturnStatement -> node.expression?.let { findFirstThisInExpr(it) }
            is IfStatement -> findFirstThisInExpr(node.expression)
            else -> null
        }
    }

    private fun findFirstThisInExpr(expr: Expression): Identifier? {
        return when {
            isThisIdentifier(expr) -> expr as Identifier
            expr is PropertyAccessExpression -> findFirstThisInExpr(expr.expression)
            expr is CallExpression -> {
                // Check for super(this) — this in arguments is also flagged
                if (isSuperIdentifier(expr.expression)) {
                    // Check arguments for 'this'
                    for (arg in expr.arguments) {
                        findFirstThisInExpr(arg)?.let { return it }
                    }
                    return null
                }
                findFirstThisInExpr(expr.expression)
                    ?: run { for (arg in expr.arguments) { findFirstThisInExpr(arg)?.let { return it } }; null }
            }
            expr is BinaryExpression -> findFirstThisInExpr(expr.left) ?: findFirstThisInExpr(expr.right)
            expr is ParenthesizedExpression -> findFirstThisInExpr(expr.expression)
            expr is ElementAccessExpression -> findFirstThisInExpr(expr.expression)
            expr is ConditionalExpression -> findFirstThisInExpr(expr.condition)
            expr is AsExpression -> findFirstThisInExpr(expr.expression)
            expr is TypeAssertionExpression -> findFirstThisInExpr(expr.expression)
            expr is SpreadElement -> findFirstThisInExpr(expr.expression)
            expr is ArrayLiteralExpression -> {
                for (elem in expr.elements) { findFirstThisInExpr(elem)?.let { return it } }
                null
            }
            expr is ObjectLiteralExpression -> null // Object literal creates new scope for 'this'
            expr is ArrowFunction -> null
            expr is FunctionExpression -> null
            else -> null
        }
    }

    // -----------------------------------------------------------------------
    // Const assignment checking (TS2540)
    // -----------------------------------------------------------------------

    // -----------------------------------------------------------------------
    // Delete operator checking (TS1102/TS2703)
    // -----------------------------------------------------------------------

    /**
     * TS2703: "The operand of a 'delete' operator must be a property reference."
     * Fires unconditionally when delete operand is not a PropertyAccessExpression
     * or ElementAccessExpression.
     *
     * TS1102: "'delete' cannot be called on an identifier in strict mode."
     * Additionally fires when the operand is an Identifier and the code is in strict mode.
     */
    private fun checkDeleteOperator() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val isModule = result.sourceFile.statements.any {
                it is ImportDeclaration || it is ExportDeclaration || it is ExportAssignment
            }
            val isStrict = options.target >= ScriptTarget.ES2015 ||
                options.strict == true ||
                options.alwaysStrict == true ||
                isModule ||
                result.sourceFile.statements.firstOrNull()?.let { stmt ->
                    stmt is ExpressionStatement && stmt.expression is StringLiteralNode &&
                        (stmt.expression as StringLiteralNode).text == "use strict"
                } == true
            walkForDeleteOperator(result.sourceFile.statements, source, fileName, isStrict)
        }
    }

    private fun walkForDeleteOperator(stmts: List<Statement>, source: String, fileName: String, isStrict: Boolean) {
        for (stmt in stmts) walkStmtForDelete(stmt, source, fileName, isStrict)
    }

    private fun walkStmtForDelete(stmt: Statement, source: String, fileName: String, isStrict: Boolean) {
        when (stmt) {
            is ExpressionStatement -> walkExprForDelete(stmt.expression, source, fileName, isStrict)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForDelete(it, source, fileName, isStrict) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForDelete(it, source, fileName, isStrict) }
            is IfStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                walkStmtForDelete(stmt.thenStatement, source, fileName, isStrict)
                stmt.elseStatement?.let { walkStmtForDelete(it, source, fileName, isStrict) }
            }
            is Block -> walkForDeleteOperator(stmt.statements, source, fileName, isStrict)
            is ForStatement -> {
                (stmt.initializer as? Expression)?.let { walkExprForDelete(it, source, fileName, isStrict) }
                stmt.condition?.let { walkExprForDelete(it, source, fileName, isStrict) }
                stmt.incrementor?.let { walkExprForDelete(it, source, fileName, isStrict) }
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            }
            is ForInStatement -> walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            is ForOfStatement -> walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            is WhileStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            }
            is DoStatement -> {
                walkStmtForDelete(stmt.statement, source, fileName, isStrict)
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
            }
            is SwitchStatement -> {
                walkExprForDelete(stmt.expression, source, fileName, isStrict)
                for (clause in stmt.caseBlock) {
                    val stmts2 = when (clause) { is CaseClause -> clause.statements; is DefaultClause -> clause.statements; else -> emptyList() }
                    walkForDeleteOperator(stmts2, source, fileName, isStrict)
                }
            }
            is TryStatement -> {
                walkForDeleteOperator(stmt.tryBlock.statements, source, fileName, isStrict)
                stmt.catchClause?.let { walkForDeleteOperator(it.block.statements, source, fileName, isStrict) }
                stmt.finallyBlock?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
            }
            is FunctionDeclaration -> stmt.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is Constructor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is GetAccessor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        is SetAccessor -> member.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForDeleteOperator(body.statements, source, fileName, isStrict)
            }
            is LabeledStatement -> walkStmtForDelete(stmt.statement, source, fileName, isStrict)
            else -> {}
        }
    }

    private fun walkExprForDelete(expr: Expression, source: String, fileName: String, isStrict: Boolean) {
        when (expr) {
            is DeleteExpression -> {
                val operand = expr.expression
                // Unwrap parentheses
                var inner = operand
                while (inner is ParenthesizedExpression) inner = inner.expression
                val isPropertyRef = inner is PropertyAccessExpression || inner is ElementAccessExpression
                if (!isPropertyRef) {
                    // TS2703: operand must be property reference
                    val start = inner.pos
                    val length = inner.end - inner.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    if (isStrict && inner is Identifier) {
                        // TS1102: delete on identifier in strict mode
                        diagnostics.add(Diagnostic(
                            message = "'delete' cannot be called on an identifier in strict mode.",
                            category = DiagnosticCategory.Error,
                            code = 1102,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = inner.text.length,
                        ))
                    }
                    diagnostics.add(Diagnostic(
                        message = "The operand of a 'delete' operator must be a property reference.",
                        category = DiagnosticCategory.Error,
                        code = 2703,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = if (inner is Identifier) inner.text.length else (inner.end - inner.pos).coerceAtLeast(1),
                    ))
                }
                // Also recurse into the operand for nested deletes
                walkExprForDelete(operand, source, fileName, isStrict)
            }
            is BinaryExpression -> {
                walkExprForDelete(expr.left, source, fileName, isStrict)
                walkExprForDelete(expr.right, source, fileName, isStrict)
            }
            is CallExpression -> {
                walkExprForDelete(expr.expression, source, fileName, isStrict)
                expr.arguments.forEach { walkExprForDelete(it, source, fileName, isStrict) }
            }
            is ParenthesizedExpression -> walkExprForDelete(expr.expression, source, fileName, isStrict)
            is ConditionalExpression -> {
                walkExprForDelete(expr.condition, source, fileName, isStrict)
                walkExprForDelete(expr.whenTrue, source, fileName, isStrict)
                walkExprForDelete(expr.whenFalse, source, fileName, isStrict)
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> walkForDeleteOperator(body.statements, source, fileName, isStrict)
                is Expression -> walkExprForDelete(body, source, fileName, isStrict)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { walkForDeleteOperator(it.statements, source, fileName, isStrict) }
            is ArrayLiteralExpression -> expr.elements.forEach { walkExprForDelete(it, source, fileName, isStrict) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> walkExprForDelete(prop.initializer, source, fileName, isStrict)
                        is SpreadAssignment -> walkExprForDelete(prop.expression, source, fileName, isStrict)
                        else -> {}
                    }
                }
            }
            is TemplateExpression -> {
                expr.templateSpans.forEach { walkExprForDelete(it.expression, source, fileName, isStrict) }
            }
            is CommaListExpression -> expr.elements.forEach { walkExprForDelete(it, source, fileName, isStrict) }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Const assignment checking (TS2588)
    // -----------------------------------------------------------------------

    private fun checkConstAssignment() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkConstAssignmentInStatements(result.sourceFile.statements, source, fileName, mutableSetOf())
        }
    }

    private fun checkConstAssignmentInStatements(
        statements: List<Statement>,
        source: String,
        fileName: String,
        constNames: MutableSet<String>,
    ) {
        for (stmt in statements) {
            // Collect const declarations
            if (stmt is VariableStatement) {
                if (stmt.declarationList.flags == SyntaxKind.ConstKeyword) {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier) {
                            constNames.add(name.text)
                        }
                    }
                }
            }
            // Collect class names — classes are also immutable bindings (TS2629)
            if (stmt is ClassDeclaration && stmt.name != null) {
                constNames.add(stmt.name!!.text)
            }
            // Check for assignments to const variables
            checkConstAssignmentInStatement(stmt, source, fileName, constNames)
        }
    }

    private fun checkConstAssignmentInStatement(
        stmt: Statement,
        source: String,
        fileName: String,
        constNames: Set<String>,
    ) {
        when (stmt) {
            is ExpressionStatement -> checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkConstAssignmentInExpr(it, source, fileName, constNames) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkConstAssignmentInExpr(it, source, fileName, constNames) }
            is IfStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                checkConstAssignmentInStatement(stmt.thenStatement, source, fileName, constNames)
                stmt.elseStatement?.let { checkConstAssignmentInStatement(it, source, fileName, constNames) }
            }
            is Block -> checkConstAssignmentInStatements(stmt.statements, source, fileName, constNames.toMutableSet())
            is ForStatement -> {
                // Collect const in for init
                val forConsts = constNames.toMutableSet()
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        if (init.flags == SyntaxKind.ConstKeyword) {
                            for (decl in init.declarations) {
                                val name = decl.name
                                if (name is Identifier) forConsts.add(name.text)
                            }
                        }
                    }
                    is Expression -> checkConstAssignmentInExpr(init, source, fileName, constNames)
                    else -> {}
                }
                stmt.condition?.let { checkConstAssignmentInExpr(it, source, fileName, forConsts) }
                stmt.incrementor?.let { checkConstAssignmentInExpr(it, source, fileName, forConsts) }
                checkConstAssignmentInStatement(stmt.statement, source, fileName, forConsts)
            }
            is ForInStatement -> checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            is ForOfStatement -> checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            is WhileStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            }
            is DoStatement -> {
                checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
            }
            is SwitchStatement -> {
                checkConstAssignmentInExpr(stmt.expression, source, fileName, constNames)
                for (clause in stmt.caseBlock) {
                    val stmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkConstAssignmentInStatements(stmts, source, fileName, constNames.toMutableSet())
                }
            }
            is TryStatement -> {
                checkConstAssignmentInStatements(stmt.tryBlock.statements, source, fileName, constNames.toMutableSet())
                stmt.catchClause?.block?.let {
                    checkConstAssignmentInStatements(it.statements, source, fileName, constNames.toMutableSet())
                }
                stmt.finallyBlock?.let {
                    checkConstAssignmentInStatements(it.statements, source, fileName, constNames.toMutableSet())
                }
            }
            is FunctionDeclaration -> {
                stmt.body?.let { checkConstAssignmentInStatements(it.statements, source, fileName, mutableSetOf()) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    // Pass outer constNames so class/enum assignments in methods are caught
                    body?.let { checkConstAssignmentInStatements(it.statements, source, fileName, constNames.toMutableSet()) }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    checkConstAssignmentInStatements(body.statements, source, fileName, constNames.toMutableSet())
                }
            }
            is LabeledStatement -> checkConstAssignmentInStatement(stmt.statement, source, fileName, constNames)
            else -> {}
        }
    }

    private fun checkConstAssignmentInExpr(
        expr: Expression,
        source: String,
        fileName: String,
        constNames: Set<String>,
    ) {
        when (expr) {
            is BinaryExpression -> {
                // Iteratively walk left spine to avoid StackOverflow on deep binary chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    val op = current.operator
                    if (op == SyntaxKind.Equals || op == SyntaxKind.PlusEquals || op == SyntaxKind.MinusEquals
                        || op == SyntaxKind.AsteriskEquals || op == SyntaxKind.SlashEquals
                        || op == SyntaxKind.PercentEquals || op == SyntaxKind.AmpersandEquals
                        || op == SyntaxKind.BarEquals || op == SyntaxKind.CaretEquals
                        || op == SyntaxKind.LessThanLessThanEquals || op == SyntaxKind.GreaterThanGreaterThanEquals
                        || op == SyntaxKind.GreaterThanGreaterThanGreaterThanEquals
                        || op == SyntaxKind.AsteriskAsteriskEquals
                        || op == SyntaxKind.BarBarEquals || op == SyntaxKind.AmpersandAmpersandEquals
                        || op == SyntaxKind.QuestionQuestionEquals) {
                        val left = current.left
                        if (left is Identifier && left.text in constNames) {
                            emitTS2588(left, source, fileName)
                        }
                        // Check assignment to readonly property (TS2540)
                        checkReadonlyAssignmentTarget(left, source, fileName)
                    }
                    checkConstAssignmentInExpr(current.right, source, fileName, constNames)
                    current = current.left
                }
                checkConstAssignmentInExpr(current, source, fileName, constNames)
            }
            is PrefixUnaryExpression -> {
                if (expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus) {
                    val operand = unwrapParens(expr.operand)
                    if (operand is Identifier && operand.text in constNames) {
                        emitTS2588(operand, source, fileName)
                    }
                    // Check readonly property (TS2540)
                    checkReadonlyAssignmentTarget(operand, source, fileName)
                }
                checkConstAssignmentInExpr(expr.operand, source, fileName, constNames)
            }
            is PostfixUnaryExpression -> {
                if (expr.operator == SyntaxKind.PlusPlus || expr.operator == SyntaxKind.MinusMinus) {
                    val operand = unwrapNonNull(expr.operand)
                    if (operand is Identifier && operand.text in constNames) {
                        emitTS2588(operand, source, fileName)
                    }
                    // Check readonly property (TS2540)
                    checkReadonlyAssignmentTarget(operand, source, fileName)
                }
                checkConstAssignmentInExpr(expr.operand, source, fileName, constNames)
            }
            is CallExpression -> {
                checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
                expr.arguments.forEach { checkConstAssignmentInExpr(it, source, fileName, constNames) }
            }
            is ParenthesizedExpression -> checkConstAssignmentInExpr(expr.expression, source, fileName, constNames)
            is ConditionalExpression -> {
                checkConstAssignmentInExpr(expr.condition, source, fileName, constNames)
                checkConstAssignmentInExpr(expr.whenTrue, source, fileName, constNames)
                checkConstAssignmentInExpr(expr.whenFalse, source, fileName, constNames)
            }
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> checkConstAssignmentInStatements(body.statements, source, fileName, mutableSetOf())
                    else -> {} // Arrow with expression body — const from outer scope may or may not apply
                }
            }
            is FunctionExpression -> {
                checkConstAssignmentInStatements(expr.body.statements, source, fileName, mutableSetOf())
            }
            else -> {}
        }
    }

    private fun unwrapNonNull(expr: Expression): Expression {
        var e = expr
        while (e is NonNullExpression) e = e.expression
        return e
    }

    private fun unwrapParens(expr: Expression): Expression {
        var e = expr
        while (e is ParenthesizedExpression) e = e.expression
        return e
    }

    /** Check if a property access targets a readonly property. */
    private fun isReadonlyPropertyAccess(expr: PropertyAccessExpression): Boolean {
        val objExpr = expr.expression
        val propName = expr.name.text
        // Check namespace/module exports for const variables
        if (objExpr is Identifier) {
            val objSymbol = globals[objExpr.text]
            if (objSymbol != null && objSymbol.flags.hasAny(SymbolFlags.Module)) {
                val exportSymbol = objSymbol.exports?.get(propName)
                if (exportSymbol != null && isConstExport(objSymbol, propName)) {
                    return true
                }
            }
        }
        // Check interface/class readonly property members via type system
        try {
            val objectType = getTypeOfExpression(objExpr)
            if (objectType === anyType || objectType === errorType) return false
            val prop = getPropertyOfType(objectType, propName) ?: return false
            return isReadonlySymbol(prop)
        } catch (_: StackOverflowError) {
            return false
        }
    }

    /** Check if a symbol is declared readonly. */
    private fun isReadonlySymbol(symbol: Symbol): Boolean {
        return symbol.declarations.any { decl ->
            when (decl) {
                is PropertyDeclaration -> ModifierFlag.Readonly in decl.modifiers
                else -> false
            }
        }
    }

    /** Check if a namespace/module exports a name as a const variable. */
    private fun isConstExport(namespaceSymbol: Symbol, exportName: String): Boolean {
        // Walk the namespace body to find if the export is a const declaration
        for (decl in namespaceSymbol.declarations) {
            val body = when (decl) {
                is ModuleDeclaration -> decl.body
                else -> continue
            }
            val stmts = when (body) {
                is ModuleBlock -> body.statements
                else -> continue
            }
            for (stmt in stmts) {
                if (stmt is VariableStatement && stmt.declarationList.flags == SyntaxKind.ConstKeyword) {
                    for (varDecl in stmt.declarationList.declarations) {
                        val name = varDecl.name
                        if (name is Identifier && name.text == exportName) return true
                    }
                }
            }
        }
        return false
    }

    /** Emit TS2540 for assignment to a readonly property. */
    private fun emitTS2540(propName: String, pos: Int, length: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, pos)
        diagnostics.add(Diagnostic(
            message = "Cannot assign to '$propName' because it is a read-only property.",
            category = DiagnosticCategory.Error,
            code = 2540,
            fileName = fileName,
            line = line,
            character = character,
            start = pos,
            length = length,
        ))
    }

    /** Check if an assignment target is a readonly property and emit TS2540. */
    private fun checkReadonlyAssignmentTarget(target: Expression, source: String, fileName: String) {
        val unwrapped = unwrapParens(target)
        when (unwrapped) {
            is PropertyAccessExpression -> {
                if (isReadonlyPropertyAccess(unwrapped)) {
                    emitTS2540(unwrapped.name.text, unwrapped.name.pos, unwrapped.name.text.length, source, fileName)
                }
            }
            is ElementAccessExpression -> {
                // m["x"] = value — check if it's a readonly property too
                val arg = unwrapped.argumentExpression
                if (arg is StringLiteralNode && unwrapped.expression is Identifier) {
                    val objName = (unwrapped.expression as Identifier).text
                    val objSymbol = globals[objName]
                    if (objSymbol != null && objSymbol.flags.hasAny(SymbolFlags.Module) &&
                        isConstExport(objSymbol, arg.text)) {
                        emitTS2540(arg.text, arg.pos, (arg.rawText ?: arg.text).length + 2, source, fileName)
                    }
                }
            }
            else -> {}
        }
    }

    private fun emitTS2588(id: Identifier, source: String, fileName: String) {
        val start = id.pos
        val length = id.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Check if the name is a class (TS2629) or enum (TS2628) rather than const (TS2588)
        // Search file locals, globals, and namespace exports recursively
        val binderResult = fileResults[fileName]
        var symbol = binderResult?.locals?.get(id.text) ?: globals[id.text]
        if (symbol == null && binderResult != null) {
            // Search inside namespace exports
            fun searchExports(table: SymbolTable): Symbol? {
                for ((_, sym) in table) {
                    if (sym.exports != null) {
                        val found = sym.exports!![id.text]
                        if (found != null) return found
                        val deeper = searchExports(sym.exports!!)
                        if (deeper != null) return deeper
                    }
                }
                return null
            }
            symbol = searchExports(binderResult.locals)
        }
        val (message, code) = when {
            symbol?.flags?.hasAny(SymbolFlags.Class) == true ->
                "Cannot assign to '${id.text}' because it is a class." to 2629
            symbol?.flags?.hasAny(SymbolFlags.Enum) == true ->
                "Cannot assign to '${id.text}' because it is an enum." to 2628
            else ->
                "Cannot assign to '${id.text}' because it is a constant." to 2588
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = code,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Parameter property checking (TS2369)
    // -----------------------------------------------------------------------

    private fun checkParameterProperties() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForParameterProperties(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForParameterProperties(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    // Function parameters with access modifiers → TS2369
                    checkParamPropsInParams(stmt.parameters, source, fileName)
                    checkInvalidParameterModifiers(stmt.parameters, source, fileName)
                    // Check for param props in type annotations (e.g., return type `(public B) => C`)
                    checkParamPropsInTypeAnnotation(stmt.type, source, fileName)
                    for (p in stmt.parameters) checkParamPropsInTypeAnnotation(p.type, source, fileName)
                    stmt.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                checkParamPropsInParams(member.parameters, source, fileName)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            is Constructor -> {
                                // Flag parameter properties on constructor declarations without body
                                if (member.body == null) {
                                    checkParamPropsInParams(member.parameters, source, fileName)
                                }
                                // TS1090: invalid modifiers checked on ALL constructors (with or without body)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                // Check for param props in parameter type annotations
                                for (p in member.parameters) checkParamPropsInTypeAnnotation(p.type, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            is GetAccessor -> {
                                checkParamPropsInParams(member.parameters, source, fileName)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            is SetAccessor -> {
                                checkParamPropsInParams(member.parameters, source, fileName)
                                checkInvalidParameterModifiers(member.parameters, source, fileName)
                                member.body?.let { walkForParameterProperties(it.statements, source, fileName) }
                            }
                            else -> {}
                        }
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        when (val init = decl.initializer) {
                            is ArrowFunction -> checkParamPropsInParams(init.parameters, source, fileName)
                            is FunctionExpression -> {
                                checkParamPropsInParams(init.parameters, source, fileName)
                                walkForParameterProperties(init.body.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ExpressionStatement -> walkForParamPropsInExpr(stmt.expression, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForParameterProperties(body.statements, source, fileName)
                }
                is InterfaceDeclaration -> {
                    // Interface construct signatures `new (public x)` → TS2369
                    for (member in stmt.members) {
                        if (member is MethodDeclaration) {
                            checkParamPropsInParams(member.parameters, source, fileName)
                        }
                    }
                }
                is Block -> walkForParameterProperties(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkParamPropsInTypeAnnotation(type: TypeNode?, source: String, fileName: String) {
        when (type) {
            is FunctionType -> checkParamPropsInParams(type.parameters, source, fileName)
            else -> {}
        }
    }

    private fun walkForParamPropsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> checkParamPropsInParams(expr.parameters, source, fileName)
            is FunctionExpression -> {
                checkParamPropsInParams(expr.parameters, source, fileName)
                walkForParameterProperties(expr.body.statements, source, fileName)
            }
            is ParenthesizedExpression -> walkForParamPropsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkForParamPropsInExpr(current.right, source, fileName)
                    current = current.left
                }
                walkForParamPropsInExpr(current, source, fileName)
            }
            is CallExpression -> {
                walkForParamPropsInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { walkForParamPropsInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    private fun isParameterPropertyModifier(flag: ModifierFlag): Boolean =
        flag == ModifierFlag.Public || flag == ModifierFlag.Private ||
        flag == ModifierFlag.Protected || flag == ModifierFlag.Readonly ||
        flag == ModifierFlag.Override

    private fun isInvalidParameterModifier(flag: ModifierFlag): Boolean =
        flag == ModifierFlag.Static || flag == ModifierFlag.Export ||
        flag == ModifierFlag.Async || flag == ModifierFlag.Declare

    private fun modifierFlagKeyword(flag: ModifierFlag): String = when (flag) {
        ModifierFlag.Static -> "static"
        ModifierFlag.Export -> "export"
        ModifierFlag.Async -> "async"
        ModifierFlag.Declare -> "declare"
        ModifierFlag.Public -> "public"
        ModifierFlag.Private -> "private"
        ModifierFlag.Protected -> "protected"
        ModifierFlag.Readonly -> "readonly"
        ModifierFlag.Override -> "override"
        ModifierFlag.Abstract -> "abstract"
        ModifierFlag.Default -> "default"
        ModifierFlag.Const -> "const"
        ModifierFlag.In -> "in"
        ModifierFlag.Out -> "out"
        ModifierFlag.Accessor -> "accessor"
    }

    private fun checkInvalidParameterModifiers(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            for (mod in param.modifiers) {
                if (!isInvalidParameterModifier(mod)) continue
                val keyword = modifierFlagKeyword(mod)
                // Find keyword position in source between param.pos and param.name.pos
                val searchStart = param.pos
                val searchEnd = param.name.pos
                val idx = source.indexOf(keyword, searchStart)
                if (idx < 0 || idx >= searchEnd) continue
                val (line, character) = getLineAndCharacterOfPosition(source, idx)
                diagnostics.add(Diagnostic(
                    message = "'$keyword' modifier cannot appear on a parameter.",
                    category = DiagnosticCategory.Error,
                    code = 1090,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = idx,
                    length = keyword.length,
                ))
            }
        }
    }

    private fun checkParamPropsInParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            if (param.modifiers.any { isParameterPropertyModifier(it) }) {
                // Parameter has access modifier outside constructor implementation → TS2369
                val start = param.pos
                // Skip leading whitespace
                var spanStart = start
                while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                // Calculate span: from modifier to end of type or name
                // Use the type pos + type text length if present, otherwise name
                val contentEnd = param.type?.let { typeNode ->
                    // For keyword types (string, number, etc.), use the type pos + keyword length
                    // For other types, use type.end - 1 to skip trailing trivia
                    var te = typeNode.end
                    while (te > typeNode.pos && te <= source.length && source[te - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ')' || it == ',' }) te--
                    te
                } ?: run {
                    var ne = param.name.end
                    while (ne > param.name.pos && ne <= source.length && source[ne - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ')' || it == ',' }) ne--
                    ne
                }
                val spanEnd = contentEnd
                val length = spanEnd - spanStart
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                diagnostics.add(Diagnostic(
                    message = "A parameter property is only allowed in a constructor implementation.",
                    category = DiagnosticCategory.Error,
                    code = 2369,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = spanStart,
                    length = length,
                ))
                // Also emit TS7006 when parameter has no type annotation.
                // Fires by default but suppressed when strict is explicitly false.
                val name = param.name
                if (param.type == null && name is Identifier && name.text != "this" &&
                    !options.strictExplicitlyFalse) {
                    diagnostics.add(Diagnostic(
                        message = "Parameter '${name.text}' implicitly has an 'any' type.",
                        category = DiagnosticCategory.Error,
                        code = 7006,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = length,
                    ))
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Super in non-derived class checking (TS2335)
    // -----------------------------------------------------------------------

    private fun checkSuperInNonDerived() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForSuperInNonDerived(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForSuperInNonDerived(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val isDerived = stmt.heritageClauses?.any { it.token == SyntaxKind.ExtendsKeyword } == true
                    if (!isDerived) {
                        // Check all methods/constructors for super references
                        for (member in stmt.members) {
                            val body = when (member) {
                                is MethodDeclaration -> member.body
                                is Constructor -> member.body
                                is GetAccessor -> member.body
                                is SetAccessor -> member.body
                                else -> null
                            }
                            body?.let {
                                findSuperRefsInStatements(it.statements, source, fileName)
                            }
                        }
                    }
                    // Recurse into nested classes (even in derived ones)
                    for (member in stmt.members) {
                        val body = when (member) {
                            is MethodDeclaration -> member.body
                            is Constructor -> member.body
                            is GetAccessor -> member.body
                            is SetAccessor -> member.body
                            else -> null
                        }
                        body?.let { walkForSuperInNonDerived(it.statements, source, fileName) }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForSuperInNonDerived(it.statements, source, fileName) }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForSuperInNonDerived(body.statements, source, fileName)
                }
                is Block -> walkForSuperInNonDerived(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun findSuperRefsInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            findSuperRefsInStatement(stmt, source, fileName)
        }
    }

    private fun findSuperRefsInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> findSuperRefsInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { findSuperRefsInExpr(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { findSuperRefsInExpr(it, source, fileName) }
            is IfStatement -> {
                findSuperRefsInExpr(stmt.expression, source, fileName)
                findSuperRefsInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { findSuperRefsInStatement(it, source, fileName) }
            }
            is Block -> findSuperRefsInStatements(stmt.statements, source, fileName)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is Expression -> findSuperRefsInExpr(init, source, fileName)
                    else -> {}
                }
                findSuperRefsInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                findSuperRefsInExpr(stmt.expression, source, fileName)
                findSuperRefsInStatement(stmt.statement, source, fileName)
            }
            else -> {}
        }
    }

    private fun findSuperRefsInExpr(expr: Expression, source: String, fileName: String) {
        when {
            isSuperIdentifier(expr) -> {
                emitTS2335(expr as Identifier, source, fileName)
            }
            expr is PropertyAccessExpression -> {
                if (isSuperIdentifier(expr.expression)) {
                    emitTS2335(expr.expression as Identifier, source, fileName)
                } else {
                    findSuperRefsInExpr(expr.expression, source, fileName)
                }
            }
            expr is CallExpression -> {
                if (isSuperIdentifier(expr.expression)) {
                    emitTS2335(expr.expression as Identifier, source, fileName)
                } else {
                    findSuperRefsInExpr(expr.expression, source, fileName)
                }
                expr.arguments.forEach { findSuperRefsInExpr(it, source, fileName) }
            }
            expr is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    findSuperRefsInExpr(current.right, source, fileName)
                    current = current.left
                }
                findSuperRefsInExpr(current, source, fileName)
            }
            expr is ParenthesizedExpression -> findSuperRefsInExpr(expr.expression, source, fileName)
            expr is ArrowFunction -> {} // Don't recurse into nested functions
            expr is FunctionExpression -> {} // Don't recurse into nested functions
            else -> {}
        }
    }

    private fun emitTS2335(superRef: Identifier, source: String, fileName: String) {
        val start = superRef.pos
        val length = 5 // "super" is 5 characters
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'super' can only be referenced in a derived class.",
            category = DiagnosticCategory.Error,
            code = 2335,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Const without initializer checking (TS1155)
    // -----------------------------------------------------------------------

    private fun checkConstWithoutInitializer() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForConstWithoutInit(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForConstWithoutInit(statements: List<Statement>, source: String, fileName: String, isAmbient: Boolean = false) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    if (stmt.declarationList.flags == SyntaxKind.ConstKeyword
                        && !isAmbient && ModifierFlag.Declare !in stmt.modifiers) {
                        for (decl in stmt.declarationList.declarations) {
                            if (decl.initializer == null) {
                                // const without initializer
                                val nameNode = decl.name
                                if (nameNode is Identifier) {
                                    val start = nameNode.pos
                                    val length = nameNode.text.length
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "'const' declarations must be initialized.",
                                        category = DiagnosticCategory.Error,
                                        code = 1155,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = length,
                                    ))
                                }
                            }
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        val body = when (member) {
                            is MethodDeclaration -> member.body
                            is Constructor -> member.body
                            is GetAccessor -> member.body
                            is SetAccessor -> member.body
                            else -> null
                        }
                        body?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                    }
                }
                is Block -> walkForConstWithoutInit(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    val childAmbient = isAmbient || ModifierFlag.Declare in stmt.modifiers
                    if (body is ModuleBlock) walkForConstWithoutInit(body.statements, source, fileName, childAmbient)
                }
                is IfStatement -> {
                    walkForConstWithoutInit(listOf(stmt.thenStatement), source, fileName)
                    stmt.elseStatement?.let { walkForConstWithoutInit(listOf(it), source, fileName) }
                }
                is ForStatement -> {
                    // Check initializer for const without init: for(const c9; ...)
                    val init = stmt.initializer
                    if (init is VariableDeclarationList && init.flags == SyntaxKind.ConstKeyword) {
                        for (decl in init.declarations) {
                            if (decl.initializer == null) {
                                val nameNode = decl.name
                                if (nameNode is Identifier) {
                                    val start = nameNode.pos
                                    val length = nameNode.text.length
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "'const' declarations must be initialized.",
                                        category = DiagnosticCategory.Error,
                                        code = 1155,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = length,
                                    ))
                                }
                            }
                        }
                    }
                    walkForConstWithoutInit(listOf(stmt.statement), source, fileName)
                }
                is WhileStatement -> walkForConstWithoutInit(listOf(stmt.statement), source, fileName)
                is DoStatement -> walkForConstWithoutInit(listOf(stmt.statement), source, fileName)
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        val stmts = when (clause) {
                            is CaseClause -> clause.statements
                            is DefaultClause -> clause.statements
                            else -> emptyList()
                        }
                        walkForConstWithoutInit(stmts, source, fileName)
                    }
                }
                is TryStatement -> {
                    walkForConstWithoutInit(stmt.tryBlock.statements, source, fileName)
                    stmt.catchClause?.block?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                    stmt.finallyBlock?.let { walkForConstWithoutInit(it.statements, source, fileName) }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // Reserved word identifier checking (TS1359)
    // -----------------------------------------------------------------------

    private val reservedWords = setOf("await", "yield", "void", "delete", "typeof",
        "instanceof", "in", "of", "new", "return", "throw", "case", "switch",
        "if", "else", "for", "while", "do", "try", "catch", "finally",
        "with", "debugger", "var", "let", "const", "class", "function",
        "import", "export", "default", "extends", "implements", "enum",
        "interface", "package", "private", "protected", "public", "static")

    private fun checkReservedWordIdentifiers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForReservedWords(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForReservedWords(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            when (stmt) {
                is FunctionDeclaration -> {
                    if (ModifierFlag.Async in stmt.modifiers) {
                        checkAwaitParams(stmt.parameters, source, fileName)
                    }
                    stmt.body?.let { walkForReservedWords(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                if (ModifierFlag.Async in member.modifiers) {
                                    checkAwaitParams(member.parameters, source, fileName)
                                }
                                member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            }
                            is Constructor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            is GetAccessor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            is SetAccessor -> member.body?.let { walkForReservedWords(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        when (val init = decl.initializer) {
                            is ArrowFunction -> {
                                if (ModifierFlag.Async in init.modifiers) {
                                    checkAwaitParams(init.parameters, source, fileName)
                                }
                            }
                            is FunctionExpression -> {
                                if (ModifierFlag.Async in init.modifiers) {
                                    checkAwaitParams(init.parameters, source, fileName)
                                }
                                walkForReservedWords(init.body.statements, source, fileName)
                            }
                            else -> {}
                        }
                    }
                }
                is ExpressionStatement -> walkForReservedWordsInExpr(stmt.expression, source, fileName)
                is Block -> walkForReservedWords(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) walkForReservedWords(body.statements, source, fileName)
                }
                // Check enum names that are reserved words
                is EnumDeclaration -> {
                    val name = stmt.name.text
                    if (name == "void" || name == "await" || name == "yield") {
                        emitTS1359(stmt.name, source, fileName, name)
                    }
                }
                else -> {}
            }
        }
    }

    private fun walkForReservedWordsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                if (ModifierFlag.Async in expr.modifiers) {
                    checkAwaitParams(expr.parameters, source, fileName)
                }
            }
            is FunctionExpression -> {
                if (ModifierFlag.Async in expr.modifiers) {
                    checkAwaitParams(expr.parameters, source, fileName)
                }
                walkForReservedWords(expr.body.statements, source, fileName)
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkForReservedWordsInExpr(current.right, source, fileName)
                    current = current.left
                }
                walkForReservedWordsInExpr(current, source, fileName)
            }
            is ParenthesizedExpression -> walkForReservedWordsInExpr(expr.expression, source, fileName)
            is CallExpression -> {
                walkForReservedWordsInExpr(expr.expression, source, fileName)
                expr.arguments.forEach { walkForReservedWordsInExpr(it, source, fileName) }
            }
            else -> {}
        }
    }

    private fun checkAwaitParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            val name = param.name
            if (name is Identifier && name.text == "await") {
                emitTS1359(name, source, fileName, "await")
            }
        }
    }

    private fun emitTS1359(nameNode: Identifier, source: String, fileName: String, word: String) {
        val start = nameNode.pos
        val length = word.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Identifier expected. '$word' is a reserved word that cannot be used here.",
            category = DiagnosticCategory.Error,
            code = 1359,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // TS6131: Cannot compile modules using option 'outFile' unless '--module' is 'amd' or 'system'
    // Only emitted when module kind is NOT explicitly set (defaulted from target).
    // When module is explicitly set, TS6082 handles the conflict at the configuration level.
    private fun checkOutFileModuleConflict() {
        if (options.outFile == null) return
        // When 'out' is set (removed option), TS5102 handles it — don't add TS6131
        if (options.out != null) return
        // When module is explicitly set, TS6082 handles it (from TypeScriptCompiler.kt)
        if (options.module != null) return
        val effectiveModule = options.effectiveModule
        if (effectiveModule == ModuleKind.AMD || effectiveModule == ModuleKind.System
            || effectiveModule == ModuleKind.UMD) return
        if (effectiveModule == ModuleKind.None) return

        // TypeScript emits TS6131 only once per compilation (first eligible file with exports)
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            // Find the first export module statement (not import-only)
            val firstExportStmt = findFirstExportStatement(result.sourceFile.statements)
                ?: continue

            // Determine diagnostic span based on statement type
            val (spanStart, spanLength) = getModuleStatementSpan(firstExportStmt, source)
            val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
            diagnostics.add(Diagnostic(
                message = "Cannot compile modules using option 'outFile' unless the '--module' flag is 'amd' or 'system'.",
                category = DiagnosticCategory.Error,
                code = 6131,
                fileName = fileName,
                line = line,
                character = character,
                start = spanStart,
                length = spanLength,
            ))
            break // Only emit once per compilation
        }
    }

    /** Find the first export statement (not import-only). Used for TS6131 which fires only on exports. */
    private fun findFirstExportStatement(statements: List<Statement>): Statement? {
        for (stmt in statements) {
            when (stmt) {
                is ExportDeclaration -> return stmt
                is ExportAssignment -> return stmt
                else -> {
                    val modifiers = when (stmt) {
                        is FunctionDeclaration -> stmt.modifiers
                        is ClassDeclaration -> stmt.modifiers
                        is VariableStatement -> stmt.modifiers
                        is EnumDeclaration -> stmt.modifiers
                        is InterfaceDeclaration -> stmt.modifiers
                        is TypeAliasDeclaration -> stmt.modifiers
                        is ModuleDeclaration -> stmt.modifiers
                        else -> emptySet()
                    }
                    if (ModifierFlag.Export in modifiers) return stmt
                }
            }
        }
        return null
    }

    private fun findFirstModuleStatement(statements: List<Statement>): Statement? {
        for (stmt in statements) {
            when (stmt) {
                is ImportDeclaration -> return stmt
                is ImportEqualsDeclaration -> return stmt
                is ExportDeclaration -> return stmt
                is ExportAssignment -> return stmt
                else -> {
                    val modifiers = when (stmt) {
                        is FunctionDeclaration -> stmt.modifiers
                        is ClassDeclaration -> stmt.modifiers
                        is VariableStatement -> stmt.modifiers
                        is EnumDeclaration -> stmt.modifiers
                        is InterfaceDeclaration -> stmt.modifiers
                        is TypeAliasDeclaration -> stmt.modifiers
                        is ModuleDeclaration -> stmt.modifiers
                        else -> emptySet()
                    }
                    if (ModifierFlag.Export in modifiers) return stmt
                }
            }
        }
        return null
    }

    /**
     * Get the diagnostic span for a module statement.
     * For class/function/enum/interface: span covers the name identifier.
     * For variable statements and imports: span covers the entire statement including export keyword.
     */
    /** Get text span for a statement, stopping at semicolon or end of text content (before comments). */
    private fun getStatementTextSpan(stmt: Statement, source: String): Pair<Int, Int> {
        var start = stmt.pos
        // Skip leading whitespace
        while (start < source.length && source[start] in " \t\r\n") start++
        // Find end: stop at semicolon or comment start
        val lineEnd = source.indexOf('\n', start).let { if (it < 0) source.length else it }
        var end = start
        var i = start
        while (i < lineEnd) {
            val ch = source[i]
            if (ch == ';') {
                end = i + 1
                break
            }
            if (ch == '/' && i + 1 < lineEnd && (source[i + 1] == '/' || source[i + 1] == '*')) {
                // Comment starts — end before it, trim trailing whitespace
                while (end > start && source[end - 1] in " \t") end--
                break
            }
            end = i + 1
            i++
        }
        return Pair(start, (end - start).coerceAtLeast(1))
    }

    private fun getModuleStatementSpan(stmt: Statement, source: String): Pair<Int, Int> {
        // For class/function declarations, use the name identifier position
        when (stmt) {
            is ClassDeclaration -> stmt.name?.let {
                return Pair(it.pos, it.text.length)
            }
            is FunctionDeclaration -> stmt.name?.let {
                return Pair(it.pos, it.text.length)
            }
            is EnumDeclaration -> {
                return Pair(stmt.name.pos, stmt.name.text.length)
            }
            is InterfaceDeclaration -> {
                return Pair(stmt.name.pos, stmt.name.text.length)
            }
            else -> {}
        }
        // For everything else (export var, import, export =, etc.), use the full statement span.
        // The statement pos may start after the 'export' keyword, so search backwards for it.
        var start = stmt.pos
        if (stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers) {
            // Find the 'export' keyword before the var/let/const keyword
            var p = start - 1
            while (p >= 0 && source[p] in " \t\r\n") p--
            // p should now be at the 't' of 'export'
            if (p >= 5 && source.substring(p - 5, p + 1) == "export") {
                start = p - 5
            }
        }
        // Find the end of actual content (before trailing whitespace/newline)
        var end = stmt.end
        while (end > start && end - 1 < source.length && source[end - 1] in " \t\r\n") end--
        return Pair(start, (end - start).coerceAtLeast(1))
    }

    // TS1185: Merge conflict marker encountered
    private fun checkConflictMarkers() {
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            // Scan for conflict markers at the start of lines
            var i = 0
            while (i < source.length) {
                // Check if we're at the start of a line (position 0 or preceded by newline)
                if (i == 0 || source[i - 1] == '\n') {
                    val ch = source[i]
                    val isMarker = when (ch) {
                        '<' -> i + 6 < source.length && source.substring(i, i + 7) == "<<<<<<<"
                        '=' -> i + 6 < source.length && source.substring(i, i + 7) == "======="
                        '>' -> i + 6 < source.length && source.substring(i, i + 7) == ">>>>>>>"
                        '|' -> i + 6 < source.length && source.substring(i, i + 7) == "|||||||"
                        else -> false
                    }
                    if (isMarker) {
                        val (line, character) = getLineAndCharacterOfPosition(source, i)
                        diagnostics.add(Diagnostic(
                            message = "Merge conflict marker encountered.",
                            category = DiagnosticCategory.Error,
                            code = 1185,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = i,
                            length = 7,
                        ))
                    }
                }
                i++
            }
        }
    }

    // TS1148: Cannot use imports, exports, or module augmentations when '--module' is 'none'
    // Only fires for pre-ES2015 targets — ES2015+ supports module syntax natively
    private fun checkModuleNoneConflict() {
        if (options.module != ModuleKind.None) return
        if (options.target >= ScriptTarget.ES2015) return

        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            val firstModuleStmt = findFirstModuleStatement(result.sourceFile.statements)
                ?: continue

            val (spanStart, spanLength) = getModuleStatementSpan(firstModuleStmt, source)
            val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
            diagnostics.add(Diagnostic(
                message = "Cannot use imports, exports, or module augmentations when '--module' is 'none'.",
                category = DiagnosticCategory.Error,
                code = 1148,
                fileName = fileName,
                line = line,
                character = character,
                start = spanStart,
                length = spanLength,
            ))
        }
    }

    // TS1218: Export assignment is not supported when '--module' flag is 'system'
    private fun checkExportAssignmentInSystem() {
        if (options.effectiveModule != ModuleKind.System) return

        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            for (stmt in result.sourceFile.statements) {
                if (stmt is ExportAssignment && stmt.isExportEquals) {
                    // Span covers just `export = expr;` (skip comments/trailing whitespace)
                    val (spanStart, spanLength) = getStatementTextSpan(stmt, source)
                    val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                    diagnostics.add(Diagnostic(
                        message = "Export assignment is not supported when '--module' flag is 'system'.",
                        category = DiagnosticCategory.Error,
                        code = 1218,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = spanLength,
                    ))
                }
            }
        }
    }

    // TS2441: Duplicate identifier 'exports'/'require'. Compiler reserves name in top level scope.
    // Applies to CJS/AMD/UMD/System module formats where exports/require are runtime variables.
    private fun checkReservedModuleNames() {
        // Skip when no emit (no runtime conflict possible)
        if (options.noEmit) return
        val module = options.effectiveModule
        // Only applies to module formats that use exports/require at runtime
        if (module != ModuleKind.CommonJS && module != ModuleKind.AMD
            && module != ModuleKind.UMD && module != ModuleKind.System) return

        val reservedNames = setOf("exports", "require")

        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            if (!isModuleFile(result.sourceFile.statements)) continue

            for (stmt in result.sourceFile.statements) {
                // Check top-level function/class/enum/variable declarations
                // Skip ambient (declare) declarations — they don't conflict at runtime
                val names = mutableListOf<Identifier>()
                when (stmt) {
                    is FunctionDeclaration -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) stmt.name?.let { names.add(it) }
                    }
                    is ClassDeclaration -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) stmt.name?.let { names.add(it) }
                    }
                    is EnumDeclaration -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) names.add(stmt.name)
                    }
                    is VariableStatement -> {
                        if (ModifierFlag.Declare !in stmt.modifiers) {
                            for (decl in stmt.declarationList.declarations) {
                                val n = decl.name
                                if (n is Identifier) names.add(n)
                            }
                        }
                    }
                    is ImportEqualsDeclaration -> {
                        // import exports = m.c; import require = m.c;
                        names.add(stmt.name)
                    }
                    is ModuleDeclaration -> {
                        // export namespace exports {} / export namespace require {}
                        // Skip uninstantiated namespaces (only types/interfaces) — no runtime conflict
                        if (ModifierFlag.Declare !in stmt.modifiers && stmt.name is Identifier
                            && isNamespaceInstantiated(stmt)) names.add(stmt.name as Identifier)
                    }
                    else -> {}
                }
                for (name in names) {
                    if (name.text in reservedNames) {
                        val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                        diagnostics.add(Diagnostic(
                            message = "Duplicate identifier '${name.text}'. Compiler reserves name '${name.text}' in top level scope of a module.",
                            category = DiagnosticCategory.Error,
                            code = 2441,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = name.pos,
                            length = name.text.length,
                        ))
                    }
                }
            }
        }
    }

    // TS1216: __esModule is reserved as an exported marker when transforming ECMAScript modules
    private fun checkEsModuleReservedExport() {
        if (options.noEmit) return
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            if (!isModuleFile(result.sourceFile.statements)) continue
            for (stmt in result.sourceFile.statements) {
                if (stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers) {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier && name.text == "__esModule") {
                            val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                            diagnostics.add(Diagnostic(
                                message = "Identifier expected. '__esModule' is reserved as an exported marker when transforming ECMAScript modules.",
                                category = DiagnosticCategory.Error,
                                code = 1216,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = name.pos,
                                length = name.text.length,
                            ))
                        }
                    }
                }
            }
        }
    }

    // TS1250: Function declarations not allowed inside blocks in strict mode targeting ES5
    // TypeScript fires this for target < ES2015 (raw target, not effective) regardless of
    // explicit strict mode — block-scoped functions are undefined behavior in ES5.
    private fun checkBlockScopedFunctionDeclarations() {
        if (options.target > ScriptTarget.ES5) return
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName

            checkBlockFuncDeclInStatements(result.sourceFile.statements, source, fileName, inBlock = false)
        }
    }

    private fun checkBlockFuncDeclInStatements(
        statements: List<Statement>, source: String, fileName: String, inBlock: Boolean
    ) {
        for (stmt in statements) {
            if (inBlock && stmt is FunctionDeclaration) {
                val name = stmt.name ?: continue
                val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                diagnostics.add(Diagnostic(
                    message = "Function declarations are not allowed inside blocks in strict mode when targeting 'ES5'.",
                    category = DiagnosticCategory.Error,
                    code = 1250,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = name.pos,
                    length = name.text.length,
                ))
            }
            // Recurse into blocks (but NOT function bodies — those create new scopes)
            checkBlockFuncDeclInStatement(stmt, source, fileName)
        }
    }

    private fun checkBlockFuncDeclInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is IfStatement -> {
                val thenStmt = stmt.thenStatement
                if (thenStmt is Block) {
                    checkBlockFuncDeclInStatements(thenStmt.statements, source, fileName, inBlock = true)
                }
                val elseStmt = stmt.elseStatement
                if (elseStmt is Block) {
                    checkBlockFuncDeclInStatements(elseStmt.statements, source, fileName, inBlock = true)
                } else if (elseStmt != null) {
                    checkBlockFuncDeclInStatement(elseStmt, source, fileName)
                }
            }
            is ForStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true)
                }
            }
            is ForInStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true)
                }
            }
            is ForOfStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true)
                }
            }
            is WhileStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true)
                }
            }
            is DoStatement -> {
                val body = stmt.statement
                if (body is Block) {
                    checkBlockFuncDeclInStatements(body.statements, source, fileName, inBlock = true)
                }
            }
            is Block -> {
                // Standalone block
                checkBlockFuncDeclInStatements(stmt.statements, source, fileName, inBlock = true)
            }
            is TryStatement -> {
                checkBlockFuncDeclInStatements(stmt.tryBlock.statements, source, fileName, inBlock = true)
                stmt.catchClause?.let { catch ->
                    checkBlockFuncDeclInStatements(catch.block.statements, source, fileName, inBlock = true)
                }
                stmt.finallyBlock?.let { finally_ ->
                    checkBlockFuncDeclInStatements(finally_.statements, source, fileName, inBlock = true)
                }
            }
            is LabeledStatement -> {
                checkBlockFuncDeclInStatement(stmt.statement, source, fileName)
            }
            // Don't recurse into functions/classes/modules — they create new scopes
            else -> {}
        }
    }

    // TS1191: An import declaration cannot have modifiers
    private fun checkImportModifiers() {
        for (result in binderResults) {
            if (isDtsFile(result.sourceFile.fileName)) continue
            val source = result.sourceFile.text
            val fileName = result.sourceFile.fileName
            for (stmt in result.sourceFile.statements) {
                if (stmt is ImportDeclaration && ModifierFlag.Export in stmt.modifiers) {
                    // Squiggle covers the 'export' keyword which precedes 'import'
                    // Search backwards from stmt.pos to find 'export'
                    var exportPos = stmt.pos
                    val searchStart = maxOf(0, stmt.pos - 20)
                    val prefix = source.substring(searchStart, stmt.pos)
                    val idx = prefix.lastIndexOf("export")
                    if (idx >= 0) exportPos = searchStart + idx
                    val (line, character) = getLineAndCharacterOfPosition(source, exportPos)
                    diagnostics.add(Diagnostic(
                        message = "An import declaration cannot have modifiers.",
                        category = DiagnosticCategory.Error,
                        code = 1191,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = exportPos,
                        length = 6, // "export"
                    ))
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Block-scoped variable use before declaration (TS2448/TS2450)
    // -----------------------------------------------------------------------

    private fun checkUseBeforeDeclaration() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkUBDInStatements(result.sourceFile.statements, source, fileName)
        }
        // Cross-file: check if top-level identifiers reference block-scoped decls in later files
        if (binderResults.size > 1) {
            checkCrossFileUseBeforeDeclaration()
        }
    }

    /**
     * Cross-file TS2448: when file1 uses identifier `x` at top level,
     * and `x` is declared with let/const in a later file2, emit TS2448.
     */
    private fun checkCrossFileUseBeforeDeclaration() {
        for ((fileIdx, result) in binderResults.withIndex()) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val localNames = result.locals.keys
            for (stmt in result.sourceFile.statements) {
                if (stmt is ExpressionStatement && stmt.expression is Identifier) {
                    val ident = stmt.expression as Identifier
                    val name = ident.text
                    // Skip if locally declared in this file (same-file checks handle it)
                    if (name in localNames) continue
                    // Check if declared as block-scoped in a later file
                    for (i in fileIdx + 1 until binderResults.size) {
                        val laterResult = binderResults[i]
                        val laterFileName = laterResult.sourceFile.fileName
                        if (isDtsFile(laterFileName)) continue
                        val laterSource = laterResult.sourceFile.text
                        for (laterStmt in laterResult.sourceFile.statements) {
                            if (laterStmt is VariableStatement &&
                                ModifierFlag.Declare !in laterStmt.modifiers) {
                                val kind = laterStmt.declarationList.flags
                                if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                                    for (d in laterStmt.declarationList.declarations) {
                                        val nameNode = d.name
                                        if (nameNode is Identifier && nameNode.text == name) {
                                            emitCrossFileTS2448(ident, name, source, fileName,
                                                nameNode.pos, nameNode.text, laterSource, laterFileName)
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private fun emitCrossFileTS2448(
        useNode: Identifier, name: String, useSource: String, useFileName: String,
        declPos: Int, declName: String, declSource: String, declFileName: String,
    ) {
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(useSource, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(declSource, declPos)
        diagnostics.add(Diagnostic(
            message = "Block-scoped variable '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2448,
            fileName = useFileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$declName' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = declFileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = declName.length,
            )),
        ))
    }

    private fun checkUBDInStatements(stmts: List<Statement>, source: String, fileName: String) {
        // Collect all let/const/enum declaration names in this block with their positions
        val blockScopedDecls = collectBlockScopedDeclsEx(stmts, source)
        // Remove names that also have hoisted declarations (function/var) in the same scope
        // because hoisted declarations make the name available before its let/const decl
        val hoistedNames = mutableSetOf<String>()
        for (stmt in stmts) {
            if (stmt is FunctionDeclaration && stmt.name != null) {
                hoistedNames.add(stmt.name!!.text)
            }
            if (stmt is VariableStatement && stmt.declarationList.flags == SyntaxKind.VarKeyword) {
                for (d in stmt.declarationList.declarations) {
                    if (d.name is Identifier) hoistedNames.add((d.name as Identifier).text)
                }
            }
        }
        for (name in hoistedNames) blockScopedDecls.remove(name)

        for (stmt in stmts) {
            checkUBDForwardRefs(stmt, blockScopedDecls, source, fileName)
            checkUBDInStatement(stmt, source, fileName, blockScopedDecls)
        }
    }

    /** Check all identifier usages in this statement for forward references to block-scoped declarations */
    private fun checkUBDForwardRefs(stmt: Statement, blockDecls: Map<String, BlockScopedDecl>, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
            is VariableStatement -> {
                val kind = stmt.declarationList.flags
                if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                    for (d in stmt.declarationList.declarations) {
                        // Self-referencing initializers (let x = x)
                        val selfNames = mutableMapOf<String, Int>()
                        collectSelfRefNames(d.name, selfNames)
                        d.initializer?.let { checkUBDInInitializer(it, selfNames, source, fileName) }
                        checkUBDInBindingDefaults(d.name, selfNames, source, fileName)
                        // Forward refs to OTHER block-scoped decls (let a = x; let x;)
                        d.initializer?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
                    }
                } else {
                    // var declarations: check for forward refs to block-scoped decls
                    for (d in stmt.declarationList.declarations) {
                        d.initializer?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
                    }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
            is ThrowStatement -> stmt.expression?.let { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
            is IfStatement -> {
                checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
                checkUBDForwardRefs(stmt.thenStatement, blockDecls, source, fileName)
                stmt.elseStatement?.let { checkUBDForwardRefs(it, blockDecls, source, fileName) }
            }
            is WhileStatement -> {
                checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
                // Don't check body — it runs after condition, which may include the decl
            }
            is ClassDeclaration -> {
                // Check heritage (extends) clause for forward references
                stmt.heritageClauses?.forEach { clause ->
                    if (clause.token == SyntaxKind.ExtendsKeyword) {
                        for (typeExpr in clause.types) {
                            checkUBDForwardInExpr(typeExpr.expression, blockDecls, source, fileName)
                        }
                    }
                }
            }
            is SwitchStatement -> checkUBDForwardInExpr(stmt.expression, blockDecls, source, fileName)
            is LabeledStatement -> checkUBDForwardRefs(stmt.statement, blockDecls, source, fileName)
            else -> {}
        }
    }

    /** Check expression for forward references to block-scoped declarations */
    private fun checkUBDForwardInExpr(expr: Expression, blockDecls: Map<String, BlockScopedDecl>, source: String, fileName: String) {
        when (expr) {
            is Identifier -> {
                val decl = blockDecls[expr.text]
                if (decl != null && expr.pos < decl.pos) {
                    when {
                        decl.isEnum -> emitTS2450(expr, decl.pos, expr.text, source, fileName)
                        decl.isClass -> emitTS2449(expr, decl.pos, expr.text, source, fileName)
                        else -> emitTS2448(expr, decl.pos, expr.text, source, fileName)
                    }
                }
            }
            is BinaryExpression -> {
                // Iteratively walk left spine to avoid StackOverflow on deep binary chains
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkUBDForwardInExpr(current.right, blockDecls, source, fileName)
                    current = current.left
                }
                checkUBDForwardInExpr(current, blockDecls, source, fileName)
            }
            is PrefixUnaryExpression -> checkUBDForwardInExpr(expr.operand, blockDecls, source, fileName)
            is PostfixUnaryExpression -> checkUBDForwardInExpr(expr.operand, blockDecls, source, fileName)
            is ParenthesizedExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is ConditionalExpression -> {
                checkUBDForwardInExpr(expr.condition, blockDecls, source, fileName)
                checkUBDForwardInExpr(expr.whenTrue, blockDecls, source, fileName)
                checkUBDForwardInExpr(expr.whenFalse, blockDecls, source, fileName)
            }
            is CallExpression -> {
                checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
                for (arg in expr.arguments) checkUBDForwardInExpr(arg, blockDecls, source, fileName)
            }
            is PropertyAccessExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is ElementAccessExpression -> {
                checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
                checkUBDForwardInExpr(expr.argumentExpression, blockDecls, source, fileName)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkUBDForwardInExpr(el, blockDecls, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkUBDForwardInExpr(prop.initializer, blockDecls, source, fileName)
                    is SpreadAssignment -> checkUBDForwardInExpr(prop.expression, blockDecls, source, fileName)
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkUBDForwardInExpr(span.expression, blockDecls, source, fileName)
            }
            is TypeOfExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is NonNullExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is SpreadElement -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is NewExpression -> {
                checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
                expr.arguments?.forEach { checkUBDForwardInExpr(it, blockDecls, source, fileName) }
            }
            is AsExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is TypeAssertionExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is VoidExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is DeleteExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            is AwaitExpression -> checkUBDForwardInExpr(expr.expression, blockDecls, source, fileName)
            // Don't recurse into functions/arrows (they capture lazily)
            is ArrowFunction, is FunctionExpression -> {}
            else -> {}
        }
    }

    private data class BlockScopedDecl(val pos: Int, val isEnum: Boolean = false, val isClass: Boolean = false)

    private fun collectBlockScopedDeclsEx(stmts: List<Statement>, source: String): MutableMap<String, BlockScopedDecl> {
        val decls = mutableMapOf<String, BlockScopedDecl>()
        for (stmt in stmts) collectBlockScopedDeclEx(stmt, decls, source)
        return decls
    }

    private fun collectBlockScopedDeclEx(stmt: Statement, decls: MutableMap<String, BlockScopedDecl>, source: String) {
        when (stmt) {
            is VariableStatement -> {
                // declare const/let have no temporal dead zone (they're ambient)
                if (ModifierFlag.Declare in stmt.modifiers) return
                val kind = stmt.declarationList.flags
                if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                    for (d in stmt.declarationList.declarations) {
                        collectBindingNamesEx(d.name, decls)
                    }
                }
            }
            is EnumDeclaration -> {
                // declare enum has no temporal dead zone
                if (ModifierFlag.Declare in stmt.modifiers) return
                // const enum values are inlined at compile time — no temporal dead zone
                // EXCEPT with isolatedModules/verbatimModuleSyntax, where inlining is suppressed
                val isConst = ModifierFlag.Const in stmt.modifiers
                if (!isConst || options.isolatedModules || options.verbatimModuleSyntax) {
                    decls[stmt.name.text] = BlockScopedDecl(stmt.name.pos, isEnum = true)
                }
            }
            is ClassDeclaration -> {
                // declare class has no temporal dead zone
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    val name = stmt.name
                    if (name != null) {
                        decls[name.text] = BlockScopedDecl(name.pos, isClass = true)
                    }
                }
            }
            else -> {}
        }
    }

    /** Collect binding names into a simple name -> pos map for self-reference checks */
    private fun collectSelfRefNames(name: Node, decls: MutableMap<String, Int>) {
        when (name) {
            is Identifier -> decls[name.text] = name.pos
            is ObjectBindingPattern -> for (el in name.elements) {
                collectSelfRefNames(el.name, decls)
            }
            is ArrayBindingPattern -> for (el in name.elements) {
                if (el is BindingElement) collectSelfRefNames(el.name, decls)
            }
            else -> {}
        }
    }

    private fun collectBindingNamesEx(name: Node, decls: MutableMap<String, BlockScopedDecl>) {
        when (name) {
            is Identifier -> decls[name.text] = BlockScopedDecl(name.pos)
            is ObjectBindingPattern -> for (el in name.elements) {
                collectBindingNamesEx(el.name, decls)
            }
            is ArrayBindingPattern -> for (el in name.elements) {
                if (el is BindingElement) collectBindingNamesEx(el.name, decls)
            }
            else -> {}
        }
    }

    /** Recurse into nested block scopes (functions, classes, blocks) */
    private fun checkUBDInStatement(stmt: Statement, source: String, fileName: String, blockDecls: Map<String, BlockScopedDecl>) {
        when (stmt) {
            is VariableStatement -> {
                // Recurse into nested scopes in initializers
                for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { checkUBDInExprForNested(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkUBDInExprForNested(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkUBDInExprForNested(it, source, fileName) }
            is IfStatement -> {
                checkUBDInStatement(stmt.thenStatement, source, fileName, blockDecls)
                stmt.elseStatement?.let { checkUBDInStatement(it, source, fileName, blockDecls) }
            }
            is Block -> checkUBDInStatements(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { checkUBDInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { checkUBDInExprForNested(it, source, fileName) }
                    is GetAccessor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is SetAccessor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is ForStatement -> {
                // Self-references in for-loop let/const initializers
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) {
                            val selfNames = mutableMapOf<String, Int>()
                            collectSelfRefNames(d.name, selfNames)
                            d.initializer?.let { checkUBDInInitializer(it, selfNames, source, fileName) }
                        }
                    }
                }
                checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            }
            is ForInStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) {
                            val selfNames = mutableMapOf<String, Int>()
                            collectSelfRefNames(d.name, selfNames)
                            checkUBDInInitializer(stmt.expression, selfNames, source, fileName)
                        }
                    }
                }
                checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            }
            is ForOfStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val kind = init.flags
                    if (kind == SyntaxKind.LetKeyword || kind == SyntaxKind.ConstKeyword) {
                        for (d in init.declarations) {
                            val selfNames = mutableMapOf<String, Int>()
                            collectSelfRefNames(d.name, selfNames)
                            checkUBDInInitializer(stmt.expression, selfNames, source, fileName)
                        }
                    }
                }
                checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            }
            is WhileStatement -> checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            is DoStatement -> checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            is SwitchStatement -> for (c in stmt.caseBlock) {
                val clauseStmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                checkUBDInStatements(clauseStmts, source, fileName)
            }
            is TryStatement -> {
                checkUBDInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkUBDInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkUBDInStatements(it.statements, source, fileName) }
            }
            is LabeledStatement -> checkUBDInStatement(stmt.statement, source, fileName, blockDecls)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkUBDInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    /** Check defaults in destructuring binding patterns for self-references */
    private fun checkUBDInBindingDefaults(name: Node, selfNames: Map<String, Int>, source: String, fileName: String) {
        // For binding patterns, earlier elements are available in later element defaults.
        // Only check each element's initializer against names that are NOT yet initialized
        // (i.e. the current element's own name and later elements, but not earlier ones).
        when (name) {
            is ObjectBindingPattern -> {
                val remaining = selfNames.toMutableMap()
                for (el in name.elements) {
                    el.initializer?.let { checkUBDInInitializer(it, remaining, source, fileName) }
                    checkUBDInBindingDefaults(el.name, remaining, source, fileName)
                    val elNames = mutableMapOf<String, Int>()
                    collectSelfRefNames(el.name, elNames)
                    for (n in elNames.keys) remaining.remove(n)
                }
            }
            is ArrayBindingPattern -> {
                val remaining = selfNames.toMutableMap()
                for (el in name.elements) {
                    if (el is BindingElement) {
                        el.initializer?.let { checkUBDInInitializer(it, remaining, source, fileName) }
                        checkUBDInBindingDefaults(el.name, remaining, source, fileName)
                        val elNames = mutableMapOf<String, Int>()
                        collectSelfRefNames(el.name, elNames)
                        for (n in elNames.keys) remaining.remove(n)
                    }
                }
            }
            else -> {}
        }
    }

    /** Check an initializer expression for references to the variable being declared */
    private fun checkUBDInInitializer(expr: Expression, selfNames: Map<String, Int>, source: String, fileName: String) {
        when (expr) {
            is Identifier -> {
                val declPos = selfNames[expr.text]
                if (declPos != null) {
                    emitTS2448(expr, declPos, expr.text, source, fileName)
                }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkUBDInInitializer(current.right, selfNames, source, fileName)
                    current = current.left
                }
                checkUBDInInitializer(current, selfNames, source, fileName)
            }
            is PrefixUnaryExpression -> checkUBDInInitializer(expr.operand, selfNames, source, fileName)
            is PostfixUnaryExpression -> checkUBDInInitializer(expr.operand, selfNames, source, fileName)
            is ParenthesizedExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is ConditionalExpression -> {
                checkUBDInInitializer(expr.condition, selfNames, source, fileName)
                checkUBDInInitializer(expr.whenTrue, selfNames, source, fileName)
                checkUBDInInitializer(expr.whenFalse, selfNames, source, fileName)
            }
            is CallExpression -> {
                checkUBDInInitializer(expr.expression, selfNames, source, fileName)
                for (arg in expr.arguments) checkUBDInInitializer(arg, selfNames, source, fileName)
            }
            is NewExpression -> {
                checkUBDInInitializer(expr.expression, selfNames, source, fileName)
                expr.arguments?.forEach { checkUBDInInitializer(it, selfNames, source, fileName) }
            }
            is PropertyAccessExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is ElementAccessExpression -> {
                checkUBDInInitializer(expr.expression, selfNames, source, fileName)
                checkUBDInInitializer(expr.argumentExpression, selfNames, source, fileName)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkUBDInInitializer(el, selfNames, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkUBDInInitializer(prop.initializer, selfNames, source, fileName)
                    is ShorthandPropertyAssignment -> {
                        // Shorthand { x } where x is a self-ref
                        val declPos = selfNames[prop.name.text]
                        if (declPos != null) {
                            emitTS2448(prop.name, declPos, prop.name.text, source, fileName)
                        }
                        prop.objectAssignmentInitializer?.let { checkUBDInInitializer(it, selfNames, source, fileName) }
                    }
                    is SpreadAssignment -> checkUBDInInitializer(prop.expression, selfNames, source, fileName)
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkUBDInInitializer(span.expression, selfNames, source, fileName)
            }
            is TypeOfExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is NonNullExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is SpreadElement -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is VoidExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is DeleteExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is AsExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is TypeAssertionExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            is SatisfiesExpression -> checkUBDInInitializer(expr.expression, selfNames, source, fileName)
            // Arrow functions, function expressions — DON'T recurse into bodies (lazy evaluation)
            is ArrowFunction, is FunctionExpression -> {}
            else -> {}
        }
    }

    /** Recurse into nested scopes (functions, classes) to find new block-scoped declarations */
    private fun checkUBDInExprForNested(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkUBDInStatements(body.statements, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkUBDInStatements(it.statements, source, fileName) }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkUBDInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun emitTS2448(useNode: Identifier, declPos: Int, name: String, source: String, fileName: String) {
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(source, declPos)
        diagnostics.add(Diagnostic(
            message = "Block-scoped variable '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2448,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = fileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = name.length,
            )),
        ))
    }

    private fun emitTS2450(useNode: Identifier, declPos: Int, name: String, source: String, fileName: String) {
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(source, declPos)
        diagnostics.add(Diagnostic(
            message = "Enum '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2450,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = fileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = name.length,
            )),
        ))
    }

    private fun emitTS2449(useNode: Identifier, declPos: Int, name: String, source: String, fileName: String) {
        val start = useNode.pos
        val length = name.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        val (declLine, declChar) = getLineAndCharacterOfPosition(source, declPos)
        diagnostics.add(Diagnostic(
            message = "Class '$name' used before its declaration.",
            category = DiagnosticCategory.Error,
            code = 2449,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            relatedInformation = listOf(Diagnostic(
                message = "'$name' is declared here.",
                category = DiagnosticCategory.Message,
                code = 2728,
                fileName = fileName,
                line = declLine,
                character = declChar,
                start = declPos,
                length = name.length,
            )),
        ))
    }

    // -----------------------------------------------------------------------
    // Setter parameter count (TS1049)
    // -----------------------------------------------------------------------

    private fun checkSetterParameterCount() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkSetterInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkSetterInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkSetterInStatement(stmt, source, fileName)
    }

    private fun checkSetterInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    if (m is SetAccessor) {
                        checkSetterParams(m.name, m.parameters, source, fileName)
                    }
                    if (m is GetAccessor && m.parameters.isNotEmpty()) {
                        // TS1054: get accessor cannot have parameters
                        val nameNode = m.name
                        val start = if (nameNode is Identifier) nameNode.pos else m.pos
                        val length = if (nameNode is Identifier) nameNode.text.length else 3
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "A 'get' accessor cannot have parameters.",
                            category = DiagnosticCategory.Error,
                            code = 1054,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    // Recurse into methods/constructors
                    when (m) {
                        is MethodDeclaration -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { checkSetterInStatements(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> checkSetterInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkSetterInExpr(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { checkSetterInExpr(it, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { checkSetterInStatements(it.statements, source, fileName) }
            is Block -> checkSetterInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkSetterInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkSetterInStatement(it, source, fileName) }
            }
            is ForStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is ForInStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is ForOfStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is TryStatement -> {
                checkSetterInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkSetterInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkSetterInStatements(it.statements, source, fileName) }
            }
            is SwitchStatement -> for (c in stmt.caseBlock) {
                when (c) {
                    is CaseClause -> checkSetterInStatements(c.statements, source, fileName)
                    is DefaultClause -> checkSetterInStatements(c.statements, source, fileName)
                    else -> {}
                }
            }
            is LabeledStatement -> checkSetterInStatement(stmt.statement, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkSetterInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkSetterInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                if (prop is SetAccessor) {
                    checkSetterParams(prop.name, prop.parameters, source, fileName)
                }
                if (prop is GetAccessor && prop.parameters.isNotEmpty()) {
                    val nameNode = prop.name
                    val start = if (nameNode is Identifier) nameNode.pos else prop.pos
                    val length = if (nameNode is Identifier) nameNode.text.length else 3
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "A 'get' accessor cannot have parameters.",
                        category = DiagnosticCategory.Error,
                        code = 1054,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkSetterInStatements(body.statements, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkSetterInStatements(it.statements, source, fileName) }
            is ClassExpression -> {
                for (m in expr.members) {
                    if (m is SetAccessor) {
                        checkSetterParams(m.name, m.parameters, source, fileName)
                    }
                }
            }
            is ParenthesizedExpression -> checkSetterInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkSetterInExpr(current.right, source, fileName)
                    current = current.left
                }
                checkSetterInExpr(current, source, fileName)
            }
            is ConditionalExpression -> {
                checkSetterInExpr(expr.whenTrue, source, fileName)
                checkSetterInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                checkSetterInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkSetterInExpr(arg, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkSetterParams(name: Node, params: List<Parameter>, source: String, fileName: String) {
        // Count non-comment-placeholder params
        val realParams = params.count { !it.isCommentPlaceholder }
        if (realParams != 1) {
            val nameId = when (name) {
                is Identifier -> name
                is ComputedPropertyName -> null // skip computed names
                else -> null
            }
            val start = nameId?.pos ?: name.pos
            val length = if (nameId != null) nameId.text.length else (name.end - 1 - start).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, start)
            diagnostics.add(Diagnostic(
                message = "A 'set' accessor must have exactly one parameter.",
                category = DiagnosticCategory.Error,
                code = 1049,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // Duplicate modifiers (TS1030)
    // -----------------------------------------------------------------------

    private fun checkDuplicateModifiers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkDupModInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkDupModInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkDupModInStatement(stmt, source, fileName)
    }

    private fun checkDupModInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                for (m in stmt.members) {
                    when (m) {
                        is PropertyDeclaration -> checkModifiers(m.modifiers, source, fileName, m.pos)
                        is MethodDeclaration -> {
                            checkModifiers(m.modifiers, source, fileName, m.pos)
                            m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        }
                        is Constructor -> m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        is GetAccessor -> {
                            checkModifiers(m.modifiers, source, fileName, m.pos)
                            m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        }
                        is SetAccessor -> {
                            checkModifiers(m.modifiers, source, fileName, m.pos)
                            m.body?.let { checkDupModInStatements(it.statements, source, fileName) }
                        }
                        else -> {}
                    }
                }
            }
            is FunctionDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                stmt.body?.let { checkDupModInStatements(it.statements, source, fileName) }
            }
            is VariableStatement -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is InterfaceDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                for (m in stmt.members) {
                    when (m) {
                        is PropertyDeclaration -> checkModifiers(m.modifiers, source, fileName, m.pos)
                        is MethodDeclaration -> checkModifiers(m.modifiers, source, fileName, m.pos)
                        else -> {}
                    }
                }
            }
            is EnumDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is TypeAliasDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is ModuleDeclaration -> {
                checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
                (stmt.body as? ModuleBlock)?.let { checkDupModInStatements(it.statements, source, fileName) }
            }
            is Block -> checkDupModInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkDupModInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkDupModInStatement(it, source, fileName) }
            }
            is ExportDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            is ImportDeclaration -> checkModifiers(stmt.modifiers, source, fileName, stmt.pos)
            else -> {}
        }
    }

    private fun checkModifiers(modifiers: Set<ModifierFlag>, source: String, fileName: String, stmtPos: Int) {
        if (modifiers.size <= 1) {
            // Only 1 modifier in the set — could still be a duplicate if parser deduped
            // (e.g. `declare declare var x` → modifiers = {Declare}).
            // Only 'declare' and 'export' can appear as duplicates via parseDeclareDeclaration
            // (other keywords like 'protected' can be property names, so skip)
            if (modifiers.isEmpty() || (ModifierFlag.Declare !in modifiers && ModifierFlag.Export !in modifiers)) return
        }
        // Check for duplicate modifiers by scanning the source text around the statement
        // Find the modifier keyword positions
        val modifierKeywords = listOf("export", "default", "declare", "abstract", "async",
            "static", "readonly", "public", "private", "protected", "override", "const", "accessor")
        // Scan backwards from stmtPos to find modifier keywords that precede the declaration keyword
        // (needed because parseDeclareDeclaration consumes 'declare' before creating the statement)
        var pos = stmtPos
        while (pos > 0) {
            // Skip whitespace backwards
            var p = pos - 1
            while (p >= 0 && source[p].isWhitespace()) p--
            if (p < 0) break
            // Try to match a modifier keyword ending at p+1
            var found = false
            for (kw in modifierKeywords) {
                val kwStart = p + 1 - kw.length
                if (kwStart >= 0 &&
                    source.substring(kwStart, kwStart + kw.length) == kw &&
                    (kwStart == 0 || !source[kwStart - 1].isLetterOrDigit())) {
                    pos = kwStart
                    found = true
                    break
                }
            }
            if (!found) break
        }
        val seen = mutableSetOf<String>()
        val end = (stmtPos + 200).coerceAtMost(source.length) // scan up to 200 chars
        while (pos < end) {
            // Skip whitespace
            while (pos < end && source[pos].isWhitespace()) pos++
            if (pos >= end) break
            // Try to match a modifier keyword
            var matched = false
            for (kw in modifierKeywords) {
                if (pos + kw.length <= source.length &&
                    source.substring(pos, pos + kw.length) == kw &&
                    (pos + kw.length >= source.length || !source[pos + kw.length].isLetterOrDigit())) {
                    if (kw in seen) {
                        // Duplicate modifier
                        val (line, character) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'$kw' modifier already seen.",
                            category = DiagnosticCategory.Error,
                            code = 1030,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    // Check ordering: visibility modifiers must precede static
                    if ((kw == "public" || kw == "private" || kw == "protected") && "static" in seen) {
                        val (line2, character2) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'$kw' modifier must precede 'static' modifier.",
                            category = DiagnosticCategory.Error,
                            code = 1029,
                            fileName = fileName,
                            line = line2,
                            character = character2,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    // export must precede default
                    if (kw == "export" && "default" in seen) {
                        val (line2, character2) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'export' modifier must precede 'default' modifier.",
                            category = DiagnosticCategory.Error,
                            code = 1029,
                            fileName = fileName,
                            line = line2,
                            character = character2,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    // export must precede declare
                    if (kw == "export" && "declare" in seen) {
                        val (line2, character2) = getLineAndCharacterOfPosition(source, pos)
                        diagnostics.add(Diagnostic(
                            message = "'export' modifier must precede 'declare' modifier.",
                            category = DiagnosticCategory.Error,
                            code = 1029,
                            fileName = fileName,
                            line = line2,
                            character = character2,
                            start = pos,
                            length = kw.length,
                        ))
                    }
                    seen.add(kw)
                    pos += kw.length
                    matched = true
                    break
                }
            }
            if (!matched) break // Hit a non-modifier token → done
        }
    }

    // -----------------------------------------------------------------------
    // Rest parameter must be last (TS1014)
    // -----------------------------------------------------------------------

    private fun checkRestParameterLast() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkRestLastInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkRestLastInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkRestLastInStatement(stmt, source, fileName)
    }

    private fun checkRestLastInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> {
                checkRestLastInParams(stmt.parameters, source, fileName)
                stmt.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
            }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is Constructor -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is GetAccessor -> m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    is SetAccessor -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    else -> {}
                }
            }
            is ExpressionStatement -> checkRestLastInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkRestLastInExpr(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { checkRestLastInExpr(it, source, fileName) }
            is Block -> checkRestLastInStatements(stmt.statements, source, fileName)
            is IfStatement -> {
                checkRestLastInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkRestLastInStatement(it, source, fileName) }
            }
            is ForStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkRestLastInStatement(stmt.statement, source, fileName)
            is TryStatement -> {
                checkRestLastInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkRestLastInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkRestLastInStatements(it.statements, source, fileName) }
            }
            is InterfaceDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> checkRestLastInParams(m.parameters, source, fileName)
                    else -> {}
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkRestLastInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkRestLastInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> {
                checkRestLastInParams(expr.parameters, source, fileName)
                when (val body = expr.body) {
                    is Block -> checkRestLastInStatements(body.statements, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkRestLastInParams(expr.parameters, source, fileName)
                expr.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
            }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is Constructor -> {
                        checkRestLastInParams(m.parameters, source, fileName)
                        m.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    else -> {}
                }
            }
            is ParenthesizedExpression -> checkRestLastInExpr(expr.expression, source, fileName)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is MethodDeclaration -> {
                        checkRestLastInParams(prop.parameters, source, fileName)
                        prop.body?.let { checkRestLastInStatements(it.statements, source, fileName) }
                    }
                    is SetAccessor -> checkRestLastInParams(prop.parameters, source, fileName)
                    else -> {}
                }
            }
            else -> {}
        }
    }

    private fun checkRestLastInParams(params: List<Parameter>, source: String, fileName: String) {
        val realParams = params.filter { !it.isCommentPlaceholder }
        for (i in 0 until realParams.size - 1) {
            val param = realParams[i]
            if (param.dotDotDotToken) {
                val name = param.name
                // Span covers `...name`
                val start = if (name is Identifier) name.pos - 3 else param.pos
                val length = if (name is Identifier) 3 + name.text.length else (param.end - 1 - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "A rest parameter must be last in a parameter list.",
                    category = DiagnosticCategory.Error,
                    code = 1014,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // Implementation in ambient context (TS1183)
    // -----------------------------------------------------------------------

    private fun checkAmbientImplementation() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkAmbientInStatements(result.sourceFile.statements, source, fileName, isAmbient = false)
        }
    }

    private fun checkAmbientInStatements(stmts: List<Statement>, source: String, fileName: String, isAmbient: Boolean) {
        for (stmt in stmts) checkAmbientInStatement(stmt, source, fileName, isAmbient)
    }

    private fun checkAmbientInStatement(stmt: Statement, source: String, fileName: String, isAmbient: Boolean) {
        val isDeclare = when (stmt) {
            is ClassDeclaration -> ModifierFlag.Declare in stmt.modifiers
            is FunctionDeclaration -> ModifierFlag.Declare in stmt.modifiers
            is ModuleDeclaration -> ModifierFlag.Declare in stmt.modifiers
            else -> false
        }
        val ambient = isAmbient || isDeclare

        when (stmt) {
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        is Constructor -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        is GetAccessor -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        is SetAccessor -> {
                            if (ambient && m.body != null) {
                                emitTS1183(m.body!!, source, fileName)
                            }
                            if (!ambient) m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        }
                        else -> {}
                    }
                }
            }
            is FunctionDeclaration -> {
                if (ambient && stmt.body != null) {
                    emitTS1183(stmt.body!!, source, fileName)
                }
                if (!ambient) stmt.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
            }
            is InterfaceDeclaration -> {
                // Interface members are always ambient
                for (m in stmt.members) {
                    when (m) {
                        is GetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                        is SetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                        is MethodDeclaration -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                        else -> {}
                    }
                }
            }
            is TypeAliasDeclaration -> {
                // Type literal members with bodies — walk the type
                checkAmbientInType(stmt.type, source, fileName)
            }
            is ModuleDeclaration -> {
                (stmt.body as? ModuleBlock)?.let { checkAmbientInStatements(it.statements, source, fileName, ambient) }
            }
            is Block -> checkAmbientInStatements(stmt.statements, source, fileName, isAmbient)
            is IfStatement -> {
                checkAmbientInStatement(stmt.thenStatement, source, fileName, isAmbient)
                stmt.elseStatement?.let { checkAmbientInStatement(it, source, fileName, isAmbient) }
            }
            is VariableStatement -> {
                for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { checkAmbientInExpr(it, source, fileName) }
                }
            }
            is ExpressionStatement -> checkAmbientInExpr(stmt.expression, source, fileName)
            is ReturnStatement -> stmt.expression?.let { checkAmbientInExpr(it, source, fileName) }
            else -> {}
        }
    }

    private fun checkAmbientInType(type: TypeNode, source: String, fileName: String) {
        if (type is TypeLiteral) {
            for (m in type.members) {
                when (m) {
                    is GetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                    is SetAccessor -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                    is MethodDeclaration -> if (m.body != null) emitTS1183(m.body!!, source, fileName)
                    else -> {}
                }
            }
        }
    }

    private fun checkAmbientInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ClassExpression -> {
                // Class expressions themselves are not ambient
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        is Constructor -> m.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkAmbientInStatements(body.statements, source, fileName, false)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkAmbientInStatements(it.statements, source, fileName, false) }
            else -> {}
        }
    }

    private fun emitTS1183(body: Block, source: String, fileName: String) {
        // Skip synthetic empty bodies created by parser error recovery (pos = -1)
        if (body.pos < 0) return
        // Squiggle on the opening `{` only (1 char)
        val start = body.pos
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "An implementation cannot be declared in ambient contexts.",
            category = DiagnosticCategory.Error,
            code = 1183,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = 1,
        ))
    }

    // -----------------------------------------------------------------------
    // Arguments collision with rest parameters (TS2396)
    // -----------------------------------------------------------------------

    private fun checkArgumentsCollision() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val isModule = isModuleFile(result.sourceFile.statements)
            checkArgsCollisionInStatements(result.sourceFile.statements, source, fileName, isModule)
        }
    }

    private fun checkArgsCollisionInStatements(stmts: List<Statement>, source: String, fileName: String, isModule: Boolean = false) {
        for (stmt in stmts) checkArgsCollisionInStatement(stmt, source, fileName, isModule)
    }

    private fun checkArgsCollisionInStatement(stmt: Statement, source: String, fileName: String, isModule: Boolean = false) {
        when (stmt) {
            is FunctionDeclaration -> {
                // Only check implementations (have body), skip overload signatures and declare
                if (stmt.body != null && ModifierFlag.Declare !in stmt.modifiers) {
                    checkArgsCollisionInParams(stmt.parameters, source, fileName, isModule)
                }
                stmt.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
            }
            is ClassDeclaration -> {
                val isDeclare = ModifierFlag.Declare in stmt.modifiers
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            if (!isDeclare && m.body != null) checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                            m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        }
                        is Constructor -> {
                            if (!isDeclare && m.body != null) checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                            m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        }
                        is GetAccessor -> m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        is SetAccessor -> m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> checkArgsCollisionInExpr(stmt.expression, source, fileName, isModule)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            }
            is ReturnStatement -> stmt.expression?.let { checkArgsCollisionInExpr(it, source, fileName, isModule) }
            is Block -> checkArgsCollisionInStatements(stmt.statements, source, fileName, isModule)
            is IfStatement -> {
                checkArgsCollisionInStatement(stmt.thenStatement, source, fileName, isModule)
                stmt.elseStatement?.let { checkArgsCollisionInStatement(it, source, fileName, isModule) }
            }
            is ForStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is WhileStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is DoStatement -> checkArgsCollisionInStatement(stmt.statement, source, fileName, isModule)
            is TryStatement -> {
                checkArgsCollisionInStatements(stmt.tryBlock.statements, source, fileName, isModule)
                stmt.catchClause?.let { checkArgsCollisionInStatements(it.block.statements, source, fileName, isModule) }
                stmt.finallyBlock?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
            }
            is ModuleDeclaration -> {
                if (ModifierFlag.Declare !in stmt.modifiers) {
                    (stmt.body as? ModuleBlock)?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                }
            }
            else -> {}
        }
    }

    private fun checkArgsCollisionInExpr(expr: Expression, source: String, fileName: String, isModule: Boolean = false) {
        when (expr) {
            is ArrowFunction -> {
                checkArgsCollisionInParams(expr.parameters, source, fileName, isModule)
                when (val body = expr.body) {
                    is Block -> checkArgsCollisionInStatements(body.statements, source, fileName, isModule)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                checkArgsCollisionInParams(expr.parameters, source, fileName, isModule)
                expr.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
            }
            is ClassExpression -> for (m in expr.members) {
                when (m) {
                    is MethodDeclaration -> {
                        checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                        m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    is Constructor -> {
                        checkArgsCollisionInParams(m.parameters, source, fileName, isModule)
                        m.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    else -> {}
                }
            }
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is MethodDeclaration -> {
                        checkArgsCollisionInParams(prop.parameters, source, fileName, isModule)
                        prop.body?.let { checkArgsCollisionInStatements(it.statements, source, fileName, isModule) }
                    }
                    else -> {}
                }
            }
            is ParenthesizedExpression -> checkArgsCollisionInExpr(expr.expression, source, fileName, isModule)
            else -> {}
        }
    }

    private fun checkArgsCollisionInParams(params: List<Parameter>, source: String, fileName: String, isModule: Boolean = false) {
        val hasRest = params.any { it.dotDotDotToken && !it.isCommentPlaceholder }
        // In module files (strict mode), "arguments" is always invalid as a parameter name (TS1215)
        // In non-module files, only check when rest params exist (TS2396)
        if (!hasRest && !isModule) return
        // Check each parameter for "arguments" name
        for (param in params) {
            if (param.isCommentPlaceholder) continue
            val name = param.name
            if (name is Identifier && name.text == "arguments") {
                // Span includes type annotation and modifier if present
                // For parameter properties (public/private/protected/readonly arguments),
                // start from the modifier position
                val hasParamModifier = param.modifiers.isNotEmpty()
                val start = if (param.dotDotDotToken) name.pos - 3
                    else if (hasParamModifier) param.pos
                    else name.pos
                val end = if (param.type != null) {
                    // end position is after the type text, minus trailing trivia
                    param.type!!.end - 1
                } else if (param.dotDotDotToken) {
                    name.pos + name.text.length
                } else {
                    name.pos + name.text.length
                }
                val length = (end - start).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                if (isModule) {
                    diagnostics.add(Diagnostic(
                        message = "Invalid use of 'arguments'. Modules are automatically in strict mode.",
                        category = DiagnosticCategory.Error,
                        code = 1215,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                } else {
                    diagnostics.add(Diagnostic(
                        message = "Duplicate identifier 'arguments'. Compiler uses 'arguments' to initialize rest parameters.",
                        category = DiagnosticCategory.Error,
                        code = 2396,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Initializers in ambient contexts (TS1039)
    // -----------------------------------------------------------------------

    private fun checkAmbientInitializers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkAmbientInitInStatements(result.sourceFile.statements, source, fileName, isAmbient = false)
        }
    }

    /**
     * Returns true if the expression qualifies as a constant for ambient enum member initializers.
     * TS1066 fires when this returns false inside a declare enum.
     */
    private fun isConstantEnumMemberExpr(expr: Expression): Boolean = when (expr) {
        is NumericLiteralNode -> true
        is StringLiteralNode -> true
        is PrefixUnaryExpression -> (expr.operator == SyntaxKind.Minus || expr.operator == SyntaxKind.Plus) &&
            expr.operand is NumericLiteralNode
        is BinaryExpression -> isConstantEnumMemberExpr(expr.left) && isConstantEnumMemberExpr(expr.right)
        is ParenthesizedExpression -> isConstantEnumMemberExpr(expr.expression)
        else -> false
    }

    /**
     * Computes the true end position of an expression in source text.
     *
     * In this AST, node.end includes the start of the NEXT scanned token
     * (because the parser calls getEnd() after nextToken()). This helper
     * recovers the actual end of the expression text by examining the
     * rightmost leaf of the expression tree.
     */
    private fun expressionTrueEnd(expr: Expression): Int = when (expr) {
        is NumericLiteralNode -> expr.pos + expr.text.length
        is StringLiteralNode -> {
            val quoteCount = if (expr.isUnterminated) 1 else 2
            val content = expr.rawText ?: expr.text
            expr.pos + content.length + quoteCount
        }
        is Identifier -> expr.pos + expr.text.length
        is PrefixUnaryExpression -> expressionTrueEnd(expr.operand)
        is BinaryExpression -> expressionTrueEnd(expr.right)
        is ParenthesizedExpression -> expressionTrueEnd(expr.expression) + 1 // +1 for closing )
        is PropertyAccessExpression -> expr.name.pos + expr.name.text.length
        is ElementAccessExpression -> expressionTrueEnd(expr.argumentExpression) + 1 // +1 for ]
        is NonNullExpression -> expressionTrueEnd(expr.expression) + 1 // +1 for !
        is CallExpression -> {
            // end of closing ) after arguments
            if (expr.arguments.isNotEmpty()) expressionTrueEnd(expr.arguments.last()) + 1
            else expr.end // fallback for empty arg lists
        }
        is NewExpression -> {
            // new Foo() — end of closing ) after arguments
            if (expr.arguments?.isNotEmpty() == true) expressionTrueEnd(expr.arguments!!.last()) + 1
            else if (expr.arguments != null) expressionTrueEnd(expr.expression) + 2 // +2 for ()
            else expressionTrueEnd(expr.expression)
        }
        is ObjectLiteralExpression -> {
            // closeBracePos is position of `}`, +1 for the char itself
            if (expr.closeBracePos >= 0) expr.closeBracePos + 1 else expr.end
        }
        is ArrayLiteralExpression -> {
            // Last element end + closing `]`
            if (expr.elements.isNotEmpty()) expressionTrueEnd(expr.elements.last()) + 1
            else expr.pos + 2 // empty `[]`
        }
        is ArrowFunction -> {
            // Arrow function body end
            val body = expr.body
            when (body) {
                is Block -> body.end - 1  // end includes next token; -1 for }
                is Expression -> expressionTrueEnd(body)
                else -> expr.end
            }
        }
        else -> expr.end // fallback — may overshoot by one token for complex expressions
    }

    /** Check if an expression is a simple literal (allowed in `declare const x = ...`). */
    private fun isLiteralExpression(expr: Expression): Boolean = when (expr) {
        is NumericLiteralNode -> true
        is StringLiteralNode -> true
        is BigIntLiteralNode -> true
        is PrefixUnaryExpression -> expr.operator == SyntaxKind.Minus && isLiteralExpression(expr.operand)
        else -> false
    }

    private fun checkAmbientInitInStatements(stmts: List<Statement>, source: String, fileName: String, isAmbient: Boolean) {
        for (stmt in stmts) {
            val isDeclare = when (stmt) {
                is VariableStatement -> ModifierFlag.Declare in stmt.modifiers
                is ClassDeclaration -> ModifierFlag.Declare in stmt.modifiers
                is ModuleDeclaration -> ModifierFlag.Declare in stmt.modifiers
                is EnumDeclaration -> ModifierFlag.Declare in stmt.modifiers
                else -> false
            }
            val ambient = isAmbient || isDeclare
            when (stmt) {
                is EnumDeclaration -> {
                    if (ambient) {
                        for (member in stmt.members) {
                            val init = member.initializer ?: continue
                            if (!isConstantEnumMemberExpr(init)) {
                                val start = init.pos
                                val length = (expressionTrueEnd(init) - start).coerceAtLeast(1)
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "In ambient enum declarations member initializer must be constant expression.",
                                    category = DiagnosticCategory.Error,
                                    code = 1066,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                ))
                            }
                        }
                    }
                }
                is VariableStatement -> {
                    if (ambient) {
                        // TypeScript allows `declare const x = 123` (without type annotation) —
                        // the literal initializer serves as the type annotation.
                        // With explicit type annotation, TS1039 still fires.
                        val isConst = stmt.declarationList.flags == SyntaxKind.ConstKeyword
                        for (d in stmt.declarationList.declarations) {
                            val init = d.initializer ?: continue
                            // Skip TS1039 for `declare const x = <literal>` without type annotation
                            if (isConst && d.type == null && isLiteralExpression(init)) continue
                            val start = init.pos
                            val length = (init.end - 1 - start).coerceAtLeast(1)
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            // TS1254 for `declare const x = <non-literal>` without type annotation
                            val useTs1254 = isConst && d.type == null && !isLiteralExpression(init)
                            diagnostics.add(Diagnostic(
                                message = if (useTs1254) "A 'const' initializer in an ambient context must be a string or numeric literal or literal enum reference."
                                    else "Initializers are not allowed in ambient contexts.",
                                category = DiagnosticCategory.Error,
                                code = if (useTs1254) 1254 else 1039,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                }
                is ClassDeclaration -> {
                    if (ambient) {
                        for (m in stmt.members) {
                            if (m is PropertyDeclaration && m.initializer != null) {
                                val init = m.initializer!!
                                val start = init.pos
                                val length = (init.end - 1 - start).coerceAtLeast(1)
                                val (line, character) = getLineAndCharacterOfPosition(source, start)
                                diagnostics.add(Diagnostic(
                                    message = "Initializers are not allowed in ambient contexts.",
                                    category = DiagnosticCategory.Error,
                                    code = 1039,
                                    fileName = fileName,
                                    line = line,
                                    character = character,
                                    start = start,
                                    length = length,
                                ))
                            }
                        }
                    }
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let {
                        checkAmbientInitInStatements(it.statements, source, fileName, ambient)
                    }
                }
                is Block -> checkAmbientInitInStatements(stmt.statements, source, fileName, isAmbient)
                is FunctionDeclaration -> stmt.body?.let { checkAmbientInitInStatements(it.statements, source, fileName, false) }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // Multiple defaults in switch (TS1113)
    // -----------------------------------------------------------------------

    private fun checkMultipleDefaults() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkMultiDefaultsInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkMultiDefaultsInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) checkMultiDefaultsInStatement(stmt, source, fileName)
    }

    private fun checkMultiDefaultsInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is SwitchStatement -> {
                var defaultSeen = false
                var errorEmitted = false
                for (c in stmt.caseBlock) {
                    if (c is DefaultClause) {
                        if (defaultSeen && !errorEmitted) {
                            val start = c.pos
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "A 'default' clause cannot appear more than once in a 'switch' statement.",
                                category = DiagnosticCategory.Error,
                                code = 1113,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = 8, // "default:"
                            ))
                            errorEmitted = true
                        }
                        defaultSeen = true
                        checkMultiDefaultsInStatements(c.statements, source, fileName)
                    } else if (c is CaseClause) {
                        checkMultiDefaultsInStatements(c.statements, source, fileName)
                    }
                }
            }
            is Block -> checkMultiDefaultsInStatements(stmt.statements, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
                    else -> {}
                }
            }
            is IfStatement -> {
                checkMultiDefaultsInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkMultiDefaultsInStatement(it, source, fileName) }
            }
            is ForStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is WhileStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is DoStatement -> checkMultiDefaultsInStatement(stmt.statement, source, fileName)
            is TryStatement -> {
                checkMultiDefaultsInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkMultiDefaultsInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            }
            is ExpressionStatement -> checkMultiDefaultsInExpr(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkMultiDefaultsInExpr(it, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun checkMultiDefaultsInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> when (val body = expr.body) {
                is Block -> checkMultiDefaultsInStatements(body.statements, source, fileName)
                else -> {}
            }
            is FunctionExpression -> expr.body?.let { checkMultiDefaultsInStatements(it.statements, source, fileName) }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // Interface property initializers (TS1246)
    // -----------------------------------------------------------------------

    private fun checkInterfacePropertyInitializers() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                checkInterfacePropInit(stmt, source, fileName)
            }
        }
    }

    // -----------------------------------------------------------------------
    // Await in non-async context (TS1308) / for await in non-async (TS1103)
    // -----------------------------------------------------------------------

    /**
     * Tracks the enclosing function for the "Did you mean to mark this function as 'async'?" related info.
     */
    private data class FuncRef(val pos: Int, val length: Int)

    private fun makeAsyncRelated(funcRef: FuncRef?, source: String, fileName: String): List<Diagnostic> {
        if (funcRef == null) return emptyList()
        val (relLine, relChar) = getLineAndCharacterOfPosition(source, funcRef.pos)
        return listOf(Diagnostic(
            message = "Did you mean to mark this function as 'async'?",
            category = DiagnosticCategory.Message,
            code = 1356,
            fileName = fileName,
            line = relLine,
            character = relChar,
            start = funcRef.pos,
            length = funcRef.length,
        ))
    }

    private fun checkAwaitContext() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Top level of modules is OK for await
            val isModule = result.sourceFile.statements.any { stmt ->
                stmt is ImportDeclaration || stmt is ExportDeclaration ||
                (stmt is ExportAssignment) ||
                (stmt is VariableStatement && ModifierFlag.Export in stmt.modifiers) ||
                (stmt is FunctionDeclaration && ModifierFlag.Export in stmt.modifiers) ||
                (stmt is ClassDeclaration && ModifierFlag.Export in stmt.modifiers)
            }
            checkAwaitInStatements(result.sourceFile.statements, source, fileName, isAsync = isModule)
        }
    }

    private fun checkAwaitInStatements(stmts: List<Statement>, source: String, fileName: String, isAsync: Boolean, enclosingFunc: FuncRef? = null) {
        for (stmt in stmts) checkAwaitInStatement(stmt, source, fileName, isAsync, enclosingFunc)
    }

    private fun checkAwaitInStatement(stmt: Statement, source: String, fileName: String, isAsync: Boolean, enclosingFunc: FuncRef? = null) {
        when (stmt) {
            is ExpressionStatement -> checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ReturnStatement -> stmt.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            is FunctionDeclaration -> {
                val async = ModifierFlag.Async in stmt.modifiers
                val funcRef = if (!async && stmt.name != null) FuncRef(stmt.name.pos, stmt.name.text.length) else null
                stmt.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, funcRef) }
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            val async = ModifierFlag.Async in m.modifiers
                            val mRef = if (!async) { val mid = m.name as? Identifier; if (mid != null) FuncRef(mid.pos, mid.text.length) else null } else null
                            m.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, mRef) }
                        }
                        is Constructor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        is PropertyDeclaration -> m.initializer?.let { checkAwaitInExpr(it, source, fileName, false, null) }
                        is GetAccessor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        is SetAccessor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        else -> {}
                    }
                }
            }
            is Block -> checkAwaitInStatements(stmt.statements, source, fileName, isAsync, enclosingFunc)
            is IfStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.thenStatement, source, fileName, isAsync, enclosingFunc)
                stmt.elseStatement?.let { checkAwaitInStatement(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ForStatement -> {
                stmt.condition?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
                stmt.incrementor?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is ForOfStatement -> {
                if (stmt.awaitModifier && !isAsync) {
                    // TS1103: 'for await' loops are only allowed within async functions and at the top levels of modules.
                    val forStart = stmt.pos
                    val awaitIdx = source.indexOf("await", forStart)
                    if (awaitIdx >= 0 && awaitIdx < forStart + 20) {
                        val (line, character) = getLineAndCharacterOfPosition(source, awaitIdx)
                        diagnostics.add(Diagnostic(
                            message = "'for await' loops are only allowed within async functions and at the top levels of modules.",
                            category = DiagnosticCategory.Error,
                            code = 1103,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = awaitIdx,
                            length = 5, // "await"
                            relatedInformation = makeAsyncRelated(enclosingFunc, source, fileName),
                        ))
                    }
                }
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is ForInStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is WhileStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            }
            is DoStatement -> {
                checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
            }
            is TryStatement -> {
                checkAwaitInStatements(stmt.tryBlock.statements, source, fileName, isAsync, enclosingFunc)
                stmt.catchClause?.let { checkAwaitInStatements(it.block.statements, source, fileName, isAsync, enclosingFunc) }
                stmt.finallyBlock?.let { checkAwaitInStatements(it.statements, source, fileName, isAsync, enclosingFunc) }
            }
            is SwitchStatement -> {
                checkAwaitInExpr(stmt.expression, source, fileName, isAsync, enclosingFunc)
                for (c in stmt.caseBlock) {
                    when (c) {
                        is CaseClause -> {
                            checkAwaitInExpr(c.expression, source, fileName, isAsync, enclosingFunc)
                            checkAwaitInStatements(c.statements, source, fileName, isAsync, enclosingFunc)
                        }
                        is DefaultClause -> checkAwaitInStatements(c.statements, source, fileName, isAsync, enclosingFunc)
                        else -> {}
                    }
                }
            }
            is ThrowStatement -> stmt.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            is LabeledStatement -> checkAwaitInStatement(stmt.statement, source, fileName, isAsync, enclosingFunc)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkAwaitInStatements(it.statements, source, fileName, isAsync, enclosingFunc) }
            else -> {}
        }
    }

    private fun checkAwaitInExpr(expr: Expression, source: String, fileName: String, isAsync: Boolean, enclosingFunc: FuncRef? = null) {
        when (expr) {
            is AwaitExpression -> {
                if (!isAsync) {
                    val start = expr.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val relatedInfo = makeAsyncRelated(enclosingFunc, source, fileName)
                    diagnostics.add(Diagnostic(
                        message = "'await' expressions are only allowed within async functions and at the top levels of modules.",
                        category = DiagnosticCategory.Error,
                        code = 1308,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = 5, // "await"
                        relatedInformation = relatedInfo,
                    ))
                }
                expr.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ArrowFunction -> {
                val async = ModifierFlag.Async in expr.modifiers
                // For the related info, point to the opening paren of the params
                val arrowRef = if (!async) {
                    val paramStart = if (expr.hasParenthesizedParameters) {
                        // Find the '(' — typically at expr.pos or just before parameters
                        val firstParam = expr.parameters.firstOrNull()
                        if (firstParam != null) {
                            // The '(' is right before the first parameter
                            val searchStart = expr.pos
                            val parenIdx = source.indexOf('(', searchStart)
                            if (parenIdx >= 0 && parenIdx < firstParam.pos) parenIdx else expr.pos
                        } else expr.pos
                    } else expr.pos
                    FuncRef(paramStart, 1) // just the '(' character
                } else null
                when (val body = expr.body) {
                    is Block -> checkAwaitInStatements(body.statements, source, fileName, async, arrowRef)
                    is Expression -> checkAwaitInExpr(body, source, fileName, async, arrowRef)
                    else -> {}
                }
            }
            is FunctionExpression -> {
                val async = ModifierFlag.Async in expr.modifiers
                val fRef = if (!async) {
                    if (expr.name != null) FuncRef(expr.name.pos, expr.name.text.length)
                    else FuncRef(expr.pos, 8) // "function" keyword length
                } else null
                expr.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, fRef) }
            }
            is ClassExpression -> {
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> {
                            val async = ModifierFlag.Async in m.modifiers
                            val mRef = if (!async) { val mid = m.name as? Identifier; if (mid != null) FuncRef(mid.pos, mid.text.length) else null } else null
                            m.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, mRef) }
                        }
                        is Constructor -> m.body?.let { checkAwaitInStatements(it.statements, source, fileName, false, null) }
                        is PropertyDeclaration -> m.initializer?.let { checkAwaitInExpr(it, source, fileName, false, null) }
                        else -> {}
                    }
                }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    checkAwaitInExpr(current.right, source, fileName, isAsync, enclosingFunc)
                    current = current.left
                }
                checkAwaitInExpr(current, source, fileName, isAsync, enclosingFunc)
            }
            is CallExpression -> {
                checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
                for (arg in expr.arguments) checkAwaitInExpr(arg, source, fileName, isAsync, enclosingFunc)
            }
            is NewExpression -> {
                checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
                expr.arguments?.forEach { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            }
            is ParenthesizedExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is ConditionalExpression -> {
                checkAwaitInExpr(expr.condition, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(expr.whenTrue, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(expr.whenFalse, source, fileName, isAsync, enclosingFunc)
            }
            is PropertyAccessExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is ElementAccessExpression -> {
                checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
                checkAwaitInExpr(expr.argumentExpression, source, fileName, isAsync, enclosingFunc)
            }
            is ArrayLiteralExpression -> for (el in expr.elements) checkAwaitInExpr(el, source, fileName, isAsync, enclosingFunc)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkAwaitInExpr(prop.initializer, source, fileName, isAsync, enclosingFunc)
                    is SpreadAssignment -> checkAwaitInExpr(prop.expression, source, fileName, isAsync, enclosingFunc)
                    is MethodDeclaration -> {
                        val async = ModifierFlag.Async in prop.modifiers
                        val pRef = if (!async) { val pid = prop.name as? Identifier; if (pid != null) FuncRef(pid.pos, pid.text.length) else null } else null
                        prop.body?.let { checkAwaitInStatements(it.statements, source, fileName, async, pRef) }
                    }
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkAwaitInExpr(span.expression, source, fileName, isAsync, enclosingFunc)
            }
            is PrefixUnaryExpression -> checkAwaitInExpr(expr.operand, source, fileName, isAsync, enclosingFunc)
            is PostfixUnaryExpression -> checkAwaitInExpr(expr.operand, source, fileName, isAsync, enclosingFunc)
            is SpreadElement -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is NonNullExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is AsExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is TypeAssertionExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is YieldExpression -> expr.expression?.let { checkAwaitInExpr(it, source, fileName, isAsync, enclosingFunc) }
            is TaggedTemplateExpression -> checkAwaitInExpr(expr.tag, source, fileName, isAsync, enclosingFunc)
            is VoidExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is DeleteExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            is TypeOfExpression -> checkAwaitInExpr(expr.expression, source, fileName, isAsync, enclosingFunc)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2397: Declaration name conflicts with built-in global identifier
    // -----------------------------------------------------------------------

    private fun checkBuiltinGlobalConflict() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // In module files, top-level declarations are module-scoped — they don't conflict
            // with built-in globals like `globalThis`. TS2397 only fires in script files.
            if (isModuleFile(result.sourceFile.statements)) continue
            val source = result.sourceFile.text
            checkBuiltinGlobalInStatements(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkBuiltinGlobalInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        val name = decl.name
                        if (name is Identifier && name.text in BUILTIN_GLOBAL_CONFLICT_NAMES) {
                            reportBuiltinGlobalConflict(name, source, fileName)
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val name = stmt.name
                    if (name is Identifier && name.text in BUILTIN_GLOBAL_CONFLICT_NAMES) {
                        reportBuiltinGlobalConflict(name, source, fileName)
                    }
                    (stmt.body as? ModuleBlock)?.let { checkBuiltinGlobalInStatements(it.statements, source, fileName) }
                }
                else -> {}
            }
        }
    }

    private fun reportBuiltinGlobalConflict(name: Identifier, source: String, fileName: String) {
        val start = name.pos
        val length = name.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Declaration name conflicts with built-in global identifier '${name.text}'.",
            category = DiagnosticCategory.Error,
            code = 2397,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Interface property initializer checking (TS1246)
    // -----------------------------------------------------------------------

    private fun checkInterfacePropInit(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> {
                for (m in stmt.members) {
                    if (m is PropertyDeclaration && m.initializer != null) {
                        val init = m.initializer!!
                        val start = init.pos
                        val length = (init.end - 1 - start).coerceAtLeast(1)
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "An interface property cannot have an initializer.",
                            category = DiagnosticCategory.Error,
                            code = 1246,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                for (s in it.statements) checkInterfacePropInit(s, source, fileName)
            }
            is Block -> for (s in stmt.statements) checkInterfacePropInit(s, source, fileName)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS1015: Parameter cannot have question mark and initializer
    // -----------------------------------------------------------------------

    private fun checkOptionalParamWithInitializer() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForOptionalParams(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForOptionalParams(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkForOptionalParamsInStmt(stmt, source, fileName)
    }

    private fun walkForOptionalParamsInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> {
                checkParamsForTS1015(stmt.parameters, source, fileName)
                stmt.body?.let { walkForOptionalParams(it.statements, source, fileName) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is Constructor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is GetAccessor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is SetAccessor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        else -> {}
                    }
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    walkForOptionalParamsInExpr(decl.initializer, source, fileName)
                }
            }
            is ExpressionStatement -> walkForOptionalParamsInExpr(stmt.expression, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForOptionalParams(it.statements, source, fileName) }
            is Block -> walkForOptionalParams(stmt.statements, source, fileName)
            is ReturnStatement -> walkForOptionalParamsInExpr(stmt.expression, source, fileName)
            is IfStatement -> {
                walkForOptionalParamsInExpr(stmt.expression, source, fileName)
                walkForOptionalParamsInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkForOptionalParamsInStmt(it, source, fileName) }
            }
            else -> {}
        }
    }

    private fun walkForOptionalParamsInExpr(expr: Expression?, source: String, fileName: String) {
        when (expr) {
            is ArrowFunction -> checkParamsForTS1015(expr.parameters, source, fileName, requireType = false)
            is FunctionExpression -> {
                checkParamsForTS1015(expr.parameters, source, fileName, requireType = false)
                walkForOptionalParams(expr.body.statements, source, fileName)
            }
            is ParenthesizedExpression -> walkForOptionalParamsInExpr(expr.expression, source, fileName)
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkForOptionalParamsInExpr(current.right, source, fileName)
                    current = current.left
                }
                walkForOptionalParamsInExpr(current, source, fileName)
            }
            is ConditionalExpression -> {
                walkForOptionalParamsInExpr(expr.condition, source, fileName)
                walkForOptionalParamsInExpr(expr.whenTrue, source, fileName)
                walkForOptionalParamsInExpr(expr.whenFalse, source, fileName)
            }
            is CallExpression -> {
                walkForOptionalParamsInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) walkForOptionalParamsInExpr(arg, source, fileName)
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is MethodDeclaration -> {
                            checkParamsForTS1015(prop.parameters, source, fileName)
                            prop.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is PropertyAssignment -> walkForOptionalParamsInExpr(prop.initializer, source, fileName)
                        else -> {}
                    }
                }
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        is Constructor -> {
                            checkParamsForTS1015(member.parameters, source, fileName)
                            member.body?.let { walkForOptionalParams(it.statements, source, fileName) }
                        }
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    private fun checkParamsForTS1015(params: List<Parameter>, source: String, fileName: String, requireType: Boolean = true) {
        for (param in params) {
            if (param.questionToken && param.initializer != null) {
                // In function/method/constructor declarations, TS1015 only fires when type annotation is present
                // or when the parameter has an access modifier (parameter property).
                // In arrow/function expressions, it fires regardless.
                val isParamProperty = param.modifiers.any { it == ModifierFlag.Public || it == ModifierFlag.Private || it == ModifierFlag.Protected || it == ModifierFlag.Readonly }
                if (requireType && param.type == null && !isParamProperty) continue
                val name = param.name
                val start = name.pos
                val length = when (name) {
                    is Identifier -> name.text.length
                    else -> (name.end - 1 - start).coerceAtLeast(1)
                }
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Parameter cannot have question mark and initializer.",
                    category = DiagnosticCategory.Error,
                    code = 1015,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1052: A 'set' accessor parameter cannot have an initializer
    // -----------------------------------------------------------------------

    private fun checkSetAccessorInitializer() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForSetAccessorInit(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForSetAccessorInit(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        if (member is SetAccessor && member.parameters.any { it.initializer != null }) {
                            val name = member.name
                            val start = name.pos
                            val length = when (name) {
                                is Identifier -> name.text.length
                                else -> (name.end - 1 - start).coerceAtLeast(1)
                            }
                            val (line, character) = getLineAndCharacterOfPosition(source, start)
                            diagnostics.add(Diagnostic(
                                message = "A 'set' accessor parameter cannot have an initializer.",
                                category = DiagnosticCategory.Error,
                                code = 1052,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = start,
                                length = length,
                            ))
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForSetAccessorInit(it.statements, source, fileName) }
                is Block -> walkForSetAccessorInit(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1053: A 'set' accessor cannot have rest parameter
    // -----------------------------------------------------------------------

    private fun checkSetAccessorRestParameter() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForSetAccessorRest(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForSetAccessorRest(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        if (member is SetAccessor) {
                            for (param in member.parameters) {
                                if (param.dotDotDotToken) {
                                    // Squiggle on `...` (3 chars), at name.pos - 3
                                    val namePos = when (val n = param.name) {
                                        is Identifier -> n.pos
                                        else -> param.pos
                                    }
                                    val start = namePos - 3
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "A 'set' accessor cannot have rest parameter.",
                                        category = DiagnosticCategory.Error,
                                        code = 1053,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = 3,
                                    ))
                                }
                            }
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForSetAccessorRest(it.statements, source, fileName) }
                is Block -> walkForSetAccessorRest(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2404: The left-hand side of a 'for...in' statement cannot use a type annotation
    // -----------------------------------------------------------------------

    private fun checkForInLhsTypeAnnotation() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForInLhsType(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForInLhsType(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ForInStatement -> {
                    val init = stmt.initializer
                    if (init is VariableDeclarationList) {
                        for (decl in init.declarations) {
                            if (decl.type == null) continue
                            // TypeScript squiggles the variable name, not the `:`.
                            val namePos = decl.name.pos
                            val nameLen = when (val n = decl.name) {
                                is Identifier -> n.text.length.coerceAtLeast(1)
                                else -> 1
                            }
                            val (line, character) = getLineAndCharacterOfPosition(source, namePos)
                            diagnostics.add(Diagnostic(
                                message = "The left-hand side of a 'for...in' statement cannot use a type annotation.",
                                category = DiagnosticCategory.Error,
                                code = 2404,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = namePos,
                                length = nameLen,
                            ))
                        }
                    }
                }
                is Block -> walkForInLhsType(stmt.statements, source, fileName)
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForInLhsType(it.statements, source, fileName) }
                is FunctionDeclaration -> stmt.body?.let { walkForInLhsType(it.statements, source, fileName) }
                is IfStatement -> {
                    val then = stmt.thenStatement
                    if (then is Block) walkForInLhsType(then.statements, source, fileName)
                    val els = stmt.elseStatement
                    if (els is Block) walkForInLhsType(els.statements, source, fileName)
                }
                is WhileStatement -> {
                    val body = stmt.statement
                    if (body is Block) walkForInLhsType(body.statements, source, fileName)
                }
                is ForStatement -> {
                    val body = stmt.statement
                    if (body is Block) walkForInLhsType(body.statements, source, fileName)
                }
                is ForOfStatement -> {
                    val body = stmt.statement
                    if (body is Block) walkForInLhsType(body.statements, source, fileName)
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> member.body?.let { walkForInLhsType(it.statements, source, fileName) }
                            is Constructor -> member.body?.let { walkForInLhsType(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1036: Statements are not allowed in ambient contexts
    // -----------------------------------------------------------------------

    private fun checkAmbientStatements() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            for (stmt in result.sourceFile.statements) {
                if (stmt is ModuleDeclaration && ModifierFlag.Declare in stmt.modifiers) {
                    val body = stmt.body
                    if (body is ModuleBlock) checkStatementsInAmbient(body.statements, source, fileName)
                }
            }
        }
    }

    private fun isValidAmbientStatement(stmt: Statement): Boolean = when (stmt) {
        is VariableStatement -> true
        is FunctionDeclaration -> true
        is ClassDeclaration -> true
        is InterfaceDeclaration -> true
        is TypeAliasDeclaration -> true
        is EnumDeclaration -> true
        is ModuleDeclaration -> true
        is ImportDeclaration -> true
        is ImportEqualsDeclaration -> true
        is ExportDeclaration -> true
        is ExportAssignment -> true
        else -> false
    }

    private fun checkStatementsInAmbient(stmts: List<Statement>, source: String, fileName: String) {
        var reported = false
        for (stmt in stmts) {
            if (!reported && !isValidAmbientStatement(stmt)) {
                reported = true
                // Report TS1036 — squiggle on the first token of the statement
                val start = stmt.pos
                val stmtEnd = stmt.end
                // Skip leading whitespace/trivia
                var spanStart = start
                while (spanStart < stmtEnd && spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                if (spanStart >= source.length) continue
                // Find the length of the first token (keyword or semicolon)
                var spanEnd = spanStart
                if (source[spanEnd] == ';') {
                    spanEnd++ // empty statement — just the semicolon
                } else {
                    while (spanEnd < source.length && source[spanEnd].isLetterOrDigit()) spanEnd++
                }
                val length = (spanEnd - spanStart).coerceAtLeast(1)
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                diagnostics.add(Diagnostic(
                    message = "Statements are not allowed in ambient contexts.",
                    category = DiagnosticCategory.Error,
                    code = 1036,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = spanStart,
                    length = length,
                ))
            }
            // Recurse into nested namespaces (including non-declare ones inside declare)
            if (stmt is ModuleDeclaration) {
                val body = stmt.body
                if (body is ModuleBlock) checkStatementsInAmbient(body.statements, source, fileName)
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2371: A parameter initializer is only allowed in a function or
    //         constructor implementation
    // -----------------------------------------------------------------------

    private fun checkParameterInitializerInNonImpl() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForParamInitNonImpl(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForParamInitNonImpl(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is FunctionDeclaration -> {
                    if (stmt.body == null) {
                        reportTS2371ForParams(stmt.parameters, source, fileName)
                    }
                    stmt.body?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                if (member.body == null) {
                                    reportTS2371ForParams(member.parameters, source, fileName)
                                }
                                member.body?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                            }
                            is Constructor -> {
                                if (member.body == null) {
                                    reportTS2371ForParams(member.parameters, source, fileName)
                                }
                                member.body?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                            }
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    for (member in stmt.members) {
                        if (member is MethodDeclaration) {
                            reportTS2371ForParams(member.parameters, source, fileName)
                        }
                    }
                }
                is VariableStatement -> {
                    // Check function type annotations in variable declarations
                    // e.g., var f: (a = 3) => number
                    for (decl in stmt.declarationList.declarations) {
                        checkFunctionTypeParams(decl.type, source, fileName)
                        // Also check initializers for type assertions with function types
                        checkExprForFunctionTypeParams(decl.initializer, source, fileName)
                    }
                }
                is TypeAliasDeclaration -> {
                    checkFunctionTypeParams(stmt.type, source, fileName)
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let { walkForParamInitNonImpl(it.statements, source, fileName) }
                }
                is Block -> walkForParamInitNonImpl(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkFunctionTypeParams(type: TypeNode?, source: String, fileName: String) {
        when (type) {
            is FunctionType -> reportTS2371ForParams(type.parameters, source, fileName)
            is ParenthesizedType -> checkFunctionTypeParams(type.type, source, fileName)
            is UnionType -> for (t in type.types) checkFunctionTypeParams(t, source, fileName)
            is IntersectionType -> for (t in type.types) checkFunctionTypeParams(t, source, fileName)
            else -> {}
        }
    }

    private fun checkExprForFunctionTypeParams(expr: Expression?, source: String, fileName: String) {
        when (expr) {
            is TypeAssertionExpression -> checkFunctionTypeParams(expr.type, source, fileName)
            is AsExpression -> checkFunctionTypeParams(expr.type, source, fileName)
            is ParenthesizedExpression -> checkExprForFunctionTypeParams(expr.expression, source, fileName)
            else -> {}
        }
    }

    private fun reportTS2371ForParams(params: List<Parameter>, source: String, fileName: String) {
        for (param in params) {
            val init = param.initializer ?: continue
            val nameStart = param.name.pos
            // Span from name start to initializer end, trimming trailing trivia
            var spanEnd = init.end
            while (spanEnd > nameStart && spanEnd <= source.length &&
                source[spanEnd - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' || it == ')' || it == ',' || it == ';' }) {
                spanEnd--
            }
            val length = (spanEnd - nameStart).coerceAtLeast(1)
            val (line, character) = getLineAndCharacterOfPosition(source, nameStart)
            diagnostics.add(Diagnostic(
                message = "A parameter initializer is only allowed in a function or constructor implementation.",
                category = DiagnosticCategory.Error,
                code = 2371,
                fileName = fileName,
                line = line,
                character = character,
                start = nameStart,
                length = length,
            ))
        }
    }

    // -----------------------------------------------------------------------
    // TS1212: Strict mode reserved word as identifier
    // -----------------------------------------------------------------------

    private fun checkStrictModeReservedWords() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Determine if file is in strict mode:
            // - target >= ES2015 (implicit strict)
            // - "use strict" prologue directive
            // - module file (ESM is strict)
            val isModule = result.sourceFile.statements.any { it is ImportDeclaration || it is ExportDeclaration || it is ExportAssignment }
            val isStrict = options.target >= ScriptTarget.ES2015 ||
                options.strict == true ||
                options.alwaysStrict == true ||
                isModule ||
                result.sourceFile.statements.firstOrNull()?.let { stmt ->
                    stmt is ExpressionStatement && stmt.expression is StringLiteralNode &&
                        (stmt.expression as StringLiteralNode).text == "use strict"
                } == true
            // TS2480 runs unconditionally; TS1212 runs in let/const contexts even without global strict
            walkForStrictReserved(result.sourceFile.statements, source, fileName, isStrict = isStrict)
        }
    }

    private fun walkForStrictReserved(stmts: List<Statement>, source: String, fileName: String, inClass: Boolean = false, isStrict: Boolean = true) {
        for (stmt in stmts) walkStmtForStrictReserved(stmt, source, fileName, inClass, isStrict)
    }

    private fun walkStmtForStrictReserved(stmt: Statement, source: String, fileName: String, inClass: Boolean = false, isStrict: Boolean = true) {
        when (stmt) {
            is VariableStatement -> {
                val isLetOrConst = stmt.declarationList.flags == SyntaxKind.LetKeyword || stmt.declarationList.flags == SyntaxKind.ConstKeyword
                for (decl in stmt.declarationList.declarations) {
                    // TS1212 fires in strict mode OR in let/const declarations (let/const implies strict for reserved words)
                    if (isStrict || isLetOrConst) checkNodeForStrictReserved(decl.name, source, fileName, inClass)
                    // TS2480 fires unconditionally for 'let' in let/const declarations
                    checkLetInLetOrConst(decl.name, stmt.declarationList.flags, source, fileName)
                }
            }
            is FunctionDeclaration -> if (isStrict) {
                val name = stmt.name
                if (name != null) checkIdentForStrictReserved(name, source, fileName, inClass)
                // Check parameters
                for (p in stmt.parameters) checkNodeForStrictReserved(p.name, source, fileName, inClass)
                stmt.body?.let { walkForStrictReserved(it.statements, source, fileName, inClass, isStrict) }
            }
            is ClassDeclaration -> if (isStrict) {
                val name = stmt.name
                if (name != null) checkIdentForStrictReserved(name, source, fileName, inClass)
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            for (p in member.parameters) checkNodeForStrictReserved(p.name, source, fileName, inClass = true)
                            member.body?.let { walkForStrictReserved(it.statements, source, fileName, inClass = true, isStrict = isStrict) }
                        }
                        is Constructor -> {
                            for (p in member.parameters) checkNodeForStrictReserved(p.name, source, fileName, inClass = true)
                            member.body?.let { walkForStrictReserved(it.statements, source, fileName, inClass = true, isStrict = isStrict) }
                        }
                        else -> {}
                    }
                }
            }
            is ModuleDeclaration -> if (isStrict) {
                val name = stmt.name
                checkExprForStrictReservedIdents(name, source, fileName, inClass)
                val body = stmt.body
                when (body) {
                    is ModuleBlock -> walkForStrictReserved(body.statements, source, fileName, inClass, isStrict)
                    is ModuleDeclaration -> walkStmtForStrictReserved(body, source, fileName, inClass, isStrict)
                    else -> {}
                }
            }
            is ForInStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val isLetOrConst = init.flags == SyntaxKind.LetKeyword || init.flags == SyntaxKind.ConstKeyword
                    for (d in init.declarations) {
                        if (isStrict || isLetOrConst) checkNodeForStrictReserved(d.name, source, fileName, inClass)
                        checkLetInLetOrConst(d.name, init.flags, source, fileName)
                    }
                }
                walkStmtForStrictReserved(stmt.statement, source, fileName, inClass, isStrict)
            }
            is ForOfStatement -> {
                val init = stmt.initializer
                if (init is VariableDeclarationList) {
                    val isLetOrConst = init.flags == SyntaxKind.LetKeyword || init.flags == SyntaxKind.ConstKeyword
                    for (d in init.declarations) {
                        if (isStrict || isLetOrConst) checkNodeForStrictReserved(d.name, source, fileName, inClass)
                        checkLetInLetOrConst(d.name, init.flags, source, fileName)
                    }
                }
                walkStmtForStrictReserved(stmt.statement, source, fileName, inClass, isStrict)
            }
            is Block -> walkForStrictReserved(stmt.statements, source, fileName, inClass, isStrict)
            is IfStatement -> {
                walkStmtForStrictReserved(stmt.thenStatement, source, fileName, inClass, isStrict)
                stmt.elseStatement?.let { walkStmtForStrictReserved(it, source, fileName, inClass, isStrict) }
            }
            is ExpressionStatement -> if (isStrict) {
                // Check for `let = 30;` style usage
                checkExprForStrictReserved(stmt.expression, source, fileName, inClass)
            }
            else -> {}
        }
    }

    private fun checkNodeForStrictReserved(node: Node, source: String, fileName: String, inClass: Boolean = false) {
        when (node) {
            is Identifier -> checkIdentForStrictReserved(node, source, fileName, inClass)
            is ObjectBindingPattern -> {
                for (el in node.elements) {
                    checkNodeForStrictReserved(el.name, source, fileName, inClass)
                }
            }
            is ArrayBindingPattern -> {
                for (el in node.elements) {
                    if (el is BindingElement) checkNodeForStrictReserved(el.name, source, fileName, inClass)
                }
            }
            else -> {}
        }
    }

    /** Check all identifiers in an expression tree for strict-mode reserved words */
    private fun checkExprForStrictReservedIdents(expr: Expression, source: String, fileName: String, inClass: Boolean = false) {
        when (expr) {
            is Identifier -> checkIdentForStrictReserved(expr, source, fileName, inClass)
            is PropertyAccessExpression -> {
                checkExprForStrictReservedIdents(expr.expression, source, fileName, inClass)
                checkIdentForStrictReserved(expr.name, source, fileName, inClass)
            }
            else -> {}
        }
    }

    private fun checkExprForStrictReserved(expr: Expression, source: String, fileName: String, inClass: Boolean = false) {
        when (expr) {
            is Identifier -> {
                if (expr.text in STRICT_MODE_RESERVED_WORDS) {
                    // Only in assignment context (let = 30)
                    // Actually, all uses of reserved words as identifiers in expressions count
                    reportTS1212(expr, source, fileName, inClass)
                }
            }
            is BinaryExpression -> {
                checkExprForStrictReserved(expr.left, source, fileName, inClass)
            }
            else -> {}
        }
    }

    private fun checkIdentForStrictReserved(id: Identifier, source: String, fileName: String, inClass: Boolean = false) {
        if (id.text in STRICT_MODE_RESERVED_WORDS) {
            reportTS1212(id, source, fileName, inClass)
        }
    }

    private fun reportTS1212(id: Identifier, source: String, fileName: String, inClass: Boolean = false) {
        val start = id.pos
        val length = id.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        if (inClass) {
            diagnostics.add(Diagnostic(
                message = "Identifier expected. '${id.text}' is a reserved word in strict mode. Class definitions are automatically in strict mode.",
                category = DiagnosticCategory.Error,
                code = 1213,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        } else {
            diagnostics.add(Diagnostic(
                message = "Identifier expected. '${id.text}' is a reserved word in strict mode.",
                category = DiagnosticCategory.Error,
                code = 1212,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /** TS2480: 'let' is not allowed to be used as a name in 'let' or 'const' declarations. */
    private fun checkLetInLetOrConst(name: Node, flags: SyntaxKind, source: String, fileName: String) {
        if (name !is Identifier || name.text != "let") return
        if (flags != SyntaxKind.LetKeyword && flags != SyntaxKind.ConstKeyword) return
        val start = name.pos
        val length = name.text.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'let' is not allowed to be used as a name in 'let' or 'const' declarations.",
            category = DiagnosticCategory.Error,
            code = 2480,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // TS2414/TS2427: Class/Interface name cannot be 'undefined'
    // -----------------------------------------------------------------------

    private fun checkUndefinedClassInterfaceName() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkUndefinedNamesInStmts(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkUndefinedNamesInStmts(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    val name = stmt.name
                    if (name != null && name.text in PREDEFINED_TYPE_NAMES) {
                        val start = name.pos
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Class name cannot be '${name.text}'.",
                            category = DiagnosticCategory.Error,
                            code = 2414,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = name.text.length,
                        ))
                    }
                }
                is InterfaceDeclaration -> {
                    if (stmt.name.text in PREDEFINED_TYPE_NAMES) {
                        val start = stmt.name.pos
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "Interface name cannot be '${stmt.name.text}'.",
                            category = DiagnosticCategory.Error,
                            code = 2427,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = stmt.name.text.length,
                        ))
                    }
                }
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let { checkUndefinedNamesInStmts(it.statements, source, fileName) }
                }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2528: A module cannot have multiple default exports
    // -----------------------------------------------------------------------

    private enum class DefaultDeclKind { DECL, REEXPORT, REF_TYPE, EXPR }

    private fun checkMultipleDefaultExports() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text

            // Classify default exports:
            // - DECL: ClassDeclaration, FunctionDeclaration, InterfaceDeclaration (all are "declaration forms")
            //         or ExportAssignment with Identifier pointing to a value symbol
            // - REF_TYPE: ExportAssignment with Identifier pointing to a type-only symbol
            // - EXPR: ExportAssignment with non-Identifier expression (literal, complex expr)
            // ts2528Start/Length: position for TS2528 diagnostic (identifier for ExportAssignment-id, else same as ts2323)
            // ts2323Start/Length: position for TS2323 diagnostic (whole statement for ExportAssignment, else same as ts2528)
            data class DefaultExportInfo(
                val stmt: Statement,
                val start: Int, val length: Int, // for TS2528
                val ts2323Start: Int, val ts2323Length: Int, // for TS2323 (may differ for ExportAssignment)
                val kind: DefaultDeclKind,
            )
            val defaults = mutableListOf<DefaultExportInfo>()

            fun isTypeOnlyIdentifier(name: String): Boolean {
                val sym = result.locals[name] ?: return false
                return !sym.flags.hasAny(SymbolFlags.Value)
            }

            fun exprStmtSpan(stmt: ExportAssignment): Pair<Int, Int> {
                // Whole-statement span for TS2323 on `export default <expr>`:
                // from start of "export" keyword to end of expression (+ optional semicolon).
                // Cannot use stmt.end because our parser's `end` includes lookahead position.
                var spanStart = stmt.pos
                while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                val expr = stmt.expression
                // Use expression text length to find expression end without lookahead artifacts
                val exprTextEnd = when (expr) {
                    is Identifier -> expr.pos + expr.text.length
                    else -> {
                        // For complex expressions, find the end by scanning the expression manually
                        var end = expr.pos
                        // Skip past non-newline, non-semicolon chars to find expression end
                        while (end < source.length && source[end] != '\n' && source[end] != '\r' && source[end] != ';') end++
                        end
                    }
                }
                var spanEnd = exprTextEnd
                while (spanEnd < source.length && source[spanEnd].let { it == ' ' || it == '\t' }) spanEnd++
                if (spanEnd < source.length && source[spanEnd] == ';') spanEnd++
                return spanStart to (spanEnd - spanStart).coerceAtLeast(1)
            }

            for (stmt in result.sourceFile.statements) {
                when (stmt) {
                    is ExportAssignment -> {
                        if (!stmt.isExportEquals) {
                            val expr = stmt.expression
                            if (expr is Identifier) {
                                // `export default identifier` — classify by whether identifier is value or type-only
                                // TS2528 reports at identifier, TS2323 reports at whole statement
                                val kind = if (isTypeOnlyIdentifier(expr.text)) DefaultDeclKind.REF_TYPE else DefaultDeclKind.DECL
                                val (ts2323Start, ts2323Len) = exprStmtSpan(stmt)
                                defaults.add(DefaultExportInfo(stmt, expr.pos, expr.text.length, ts2323Start, ts2323Len, kind))
                            } else {
                                // `export default <complex expr>` → report at start of whole statement
                                val (spanStart, spanLength) = exprStmtSpan(stmt)
                                defaults.add(DefaultExportInfo(stmt, spanStart, spanLength, spanStart, spanLength, DefaultDeclKind.EXPR))
                            }
                        }
                    }
                    is FunctionDeclaration -> {
                        if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default in stmt.modifiers) {
                            // TypeScript reports at function name. For anonymous functions, at "export" keyword.
                            val name = stmt.name
                            if (name != null) {
                                defaults.add(DefaultExportInfo(stmt, name.pos, name.text.length, name.pos, name.text.length, DefaultDeclKind.DECL))
                            } else {
                                // Anonymous function: FunctionDeclaration.pos = "function" keyword position.
                                // We need the "export" keyword which precedes "default function".
                                // Search backwards from stmt.pos for "export".
                                val exportStart = findExportKeywordBefore(source, stmt.pos)
                                defaults.add(DefaultExportInfo(stmt, exportStart, 6, exportStart, 6, DefaultDeclKind.DECL))
                            }
                        }
                    }
                    is ClassDeclaration -> {
                        if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default in stmt.modifiers) {
                            // TypeScript reports at class name. For anonymous classes, at "export" keyword.
                            val name = stmt.name
                            if (name != null) {
                                defaults.add(DefaultExportInfo(stmt, name.pos, name.text.length, name.pos, name.text.length, DefaultDeclKind.DECL))
                            } else {
                                // Anonymous class: ClassDeclaration.pos = "class" keyword position.
                                // We need the "export" keyword which precedes "default class".
                                val exportStart = findExportKeywordBefore(source, stmt.pos)
                                defaults.add(DefaultExportInfo(stmt, exportStart, 6, exportStart, 6, DefaultDeclKind.DECL))
                            }
                        }
                    }
                    is InterfaceDeclaration -> {
                        if (ModifierFlag.Export in stmt.modifiers && ModifierFlag.Default in stmt.modifiers) {
                            // `export default interface Foo {}` — declaration form, always DECL
                            defaults.add(DefaultExportInfo(stmt, stmt.name.pos, stmt.name.text.length, stmt.name.pos, stmt.name.text.length, DefaultDeclKind.DECL))
                        }
                    }
                    is ExportDeclaration -> {
                        // `export { default } from 'mod'` or `export { X as default } from 'mod'`
                        // These are re-exports of `default` — classified as REEXPORT.
                        val clause = stmt.exportClause
                        if (clause is NamedExports) {
                            for (spec in clause.elements) {
                                if (spec.name.text == "default") {
                                    // spec.name.pos includes leading trivia; skip whitespace to get token start
                                    var specStart = spec.name.pos
                                    while (specStart < source.length && source[specStart].let { it == ' ' || it == '\t' }) specStart++
                                    defaults.add(DefaultExportInfo(stmt, specStart, spec.name.text.length, specStart, spec.name.text.length, DefaultDeclKind.REEXPORT))
                                }
                            }
                        }
                    }
                    else -> {}
                }
            }

            if (defaults.size < 2) continue

            // Determine how to report: TS2323 vs TS2528
            // TS2323 fires when there are ≥2 DECL/REEXPORT forms.
            // TS2528 fires when any non-DECL form (REEXPORT, REF_TYPE, or EXPR) is present.
            // When ALL forms are DECL (no REEXPORT/REF_TYPE/EXPR): emit TS2323 only (no TS2528).
            // Function overloads with the same name count as 1 DECL for TS2323.
            val overloadNames = mutableSetOf<String>()
            var declCount = 0
            for (info in defaults) {
                if (info.kind == DefaultDeclKind.DECL || info.kind == DefaultDeclKind.REEXPORT) {
                    val stmt = info.stmt
                    if (stmt is FunctionDeclaration && stmt.name != null) {
                        val name = stmt.name!!.text
                        if (name in overloadNames) continue // don't count duplicate overloads
                        overloadNames.add(name)
                    }
                    declCount++
                }
            }
            val hasNonDeclInline = defaults.any { it.kind != DefaultDeclKind.DECL }
            val emitTs2323 = declCount >= 2
            val emitTs2528 = hasNonDeclInline || !emitTs2323

            // TS2393: Duplicate function implementation — fires for multiple anonymous
            // `export default function(){}` declarations (they all have a body but no name).
            val anonFuncDefaults = defaults.filter { d ->
                val fd = d.stmt as? FunctionDeclaration ?: return@filter false
                fd.name == null && fd.body != null
            }
            if (anonFuncDefaults.size >= 2) {
                for (anonD in anonFuncDefaults) {
                    val (ts2393Line, ts2393Char) = getLineAndCharacterOfPosition(source, anonD.start)
                    diagnostics.add(Diagnostic(
                        message = "Duplicate function implementation.",
                        category = DiagnosticCategory.Error,
                        code = 2393,
                        fileName = fileName,
                        line = ts2393Line,
                        character = ts2393Char,
                        start = anonD.start,
                        length = anonD.length,
                    ))
                }
            }

            val lastIdx = defaults.size - 1
            val lastStmt = defaults[lastIdx].stmt
            // When the last export is a FunctionDeclaration, it acts as the "canonical" binding:
            // all preceding exports point to it with TS2752 "The first export default is here.",
            // and the last export points back with TS2753 "Another export default is here."
            // In all other cases, preceding exports point to the last with TS2753/TS6204,
            // and the last export points to all preceding with TS2752.
            val lastIsFunctionDecl = lastStmt is FunctionDeclaration

            for (i in defaults.indices) {
                val d = defaults[i]
                val (line, character) = getLineAndCharacterOfPosition(source, d.start)
                val isLast = i == lastIdx

                // TS2323: fires for DECL/REEXPORT forms when declCount >= 2.
                // For DECL forms: all non-last get TS2323; last gets TS2323 only if it's a
                // "real declaration" (ClassDecl/FuncDecl/InterfaceDecl), not an ExportAssignment.
                // For REEXPORT forms: only non-last get TS2323 (last re-export gets only TS2528).
                // The span for TS2323 uses ts2323Start/ts2323Length (whole statement for ExportAssignment).
                if (emitTs2323 && (d.kind == DefaultDeclKind.DECL || d.kind == DefaultDeclKind.REEXPORT)) {
                    val isRealDecl = d.stmt !is ExportAssignment && d.kind != DefaultDeclKind.REEXPORT
                    if (!isLast || isRealDecl) {
                        val (ts2323Line, ts2323Char) = getLineAndCharacterOfPosition(source, d.ts2323Start)
                        diagnostics.add(Diagnostic(
                            message = "Cannot redeclare exported variable 'default'.",
                            category = DiagnosticCategory.Error,
                            code = 2323,
                            fileName = fileName,
                            line = ts2323Line,
                            character = ts2323Char,
                            start = d.ts2323Start,
                            length = d.ts2323Length,
                        ))
                    }
                }

                if (!emitTs2528) continue

                val relatedInfoList = mutableListOf<Diagnostic>()

                if (!isLast) {
                    // Non-last export: point to the last one
                    val relD = defaults[lastIdx]
                    val (relLine, relChar) = getLineAndCharacterOfPosition(source, relD.start)
                    val relCode: Int
                    val relMessage: String
                    if (lastIsFunctionDecl) {
                        // Last is FD: preceding exports use TS2752 "The first export default is here."
                        relCode = 2752
                        relMessage = "The first export default is here."
                    } else if (i == 0) {
                        // First export: TS2753 "Another export default is here."
                        relCode = 2753
                        relMessage = "Another export default is here."
                    } else {
                        // Non-first, non-last: TS6204 "and here."
                        relCode = 6204
                        relMessage = "and here."
                    }
                    relatedInfoList.add(Diagnostic(
                        message = relMessage,
                        category = DiagnosticCategory.Message,
                        code = relCode,
                        fileName = fileName,
                        line = relLine,
                        character = relChar,
                        start = relD.start,
                        length = relD.length,
                    ))
                } else {
                    // Last export: point to all previous ones
                    for (j in 0 until lastIdx) {
                        val relD = defaults[j]
                        val (relLine, relChar) = getLineAndCharacterOfPosition(source, relD.start)
                        val relCode: Int
                        val relMessage: String
                        if (lastIsFunctionDecl) {
                            // Last is FD: use TS2753 "Another export default is here."
                            relCode = 2753
                            relMessage = "Another export default is here."
                        } else {
                            // Normal case: use TS2752 "The first export default is here."
                            relCode = 2752
                            relMessage = "The first export default is here."
                        }
                        relatedInfoList.add(Diagnostic(
                            message = relMessage,
                            category = DiagnosticCategory.Message,
                            code = relCode,
                            fileName = fileName,
                            line = relLine,
                            character = relChar,
                            start = relD.start,
                            length = relD.length,
                        ))
                    }
                }

                diagnostics.add(Diagnostic(
                    message = "A module cannot have multiple default exports.",
                    category = DiagnosticCategory.Error,
                    code = 2528,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = d.start,
                    length = d.length,
                    relatedInformation = relatedInfoList,
                ))
            }
        }
    }

    /**
     * Find the position of the `export` keyword that appears before a given position.
     * Used when FunctionDeclaration/ClassDeclaration.pos is the keyword position (e.g. `function`)
     * but we need the `export` keyword position for anonymous declarations.
     */
    private fun findExportKeywordBefore(source: String, stmtPos: Int): Int {
        // Search backwards from stmtPos for "export" keyword.
        // The pattern is "export default function/class" where stmtPos = function/class position.
        val searchStart = (stmtPos - 30).coerceAtLeast(0)
        val idx = source.lastIndexOf("export", stmtPos)
        return if (idx in searchStart..stmtPos) idx else stmtPos
    }

    // -----------------------------------------------------------------------
    // TS2377: Constructors for derived classes must contain a 'super' call
    // -----------------------------------------------------------------------

    private fun checkDerivedConstructorSuper() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForDerivedSuper(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForDerivedSuper(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    checkClassDerivedSuper(stmt.heritageClauses, stmt.members, source, fileName)
                    // Recurse into class members for nested classes
                    for (m in stmt.members) {
                        when (m) {
                            is MethodDeclaration -> m.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                            is Constructor -> m.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                            else -> {}
                        }
                    }
                }
                is FunctionDeclaration -> stmt.body?.let { walkForDerivedSuper(it.statements, source, fileName) }
                is VariableStatement -> {
                    for (d in stmt.declarationList.declarations) {
                        when (val init = d.initializer) {
                            is ClassExpression -> {
                                checkClassDerivedSuper(init.heritageClauses, init.members, source, fileName)
                            }
                            is FunctionExpression -> walkForDerivedSuper(init.body.statements, source, fileName)
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForDerivedSuper(it.statements, source, fileName) }
                is Block -> walkForDerivedSuper(stmt.statements, source, fileName)
                else -> {}
            }
        }
    }

    private fun checkClassDerivedSuper(
        heritageClauses: List<HeritageClause>?,
        members: List<ClassElement>,
        source: String,
        fileName: String,
    ) {
        // Check if class extends something (skip null extends — `class X extends null` is special)
        val extendsClause = heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
        if (extendsClause == null) return
        val extendsExpr = extendsClause.types.firstOrNull()?.expression
        val extendsNull = extendsExpr is Identifier && extendsExpr.text == "null"

        if (extendsNull) {
            // For `class X extends null`, any super() call is TS17005.
            for (member in members) {
                if (member is Constructor && member.body != null) {
                    findSuperCallWithLength(member.body!!.statements)?.let { (superCallPos, len) ->
                        val (line, character) = getLineAndCharacterOfPosition(source, superCallPos)
                        diagnostics.add(Diagnostic(
                            message = "A constructor cannot contain a 'super' call when its class extends 'null'.",
                            category = DiagnosticCategory.Error,
                            code = 17005,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = superCallPos,
                            length = len,
                        ))
                    }
                }
            }
            return
        }

        // Find constructors with bodies that don't contain super()
        for (member in members) {
            if (member is Constructor && member.body != null) {
                val hasSuperCall = statementsContainSuperCall(member.body!!.statements)
                if (!hasSuperCall) {
                    // Find "constructor" keyword position
                    val ctorPos = member.pos
                    var spanStart = ctorPos
                    while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                    val idx = source.indexOf("constructor", spanStart)
                    if (idx < 0 || idx > spanStart + 20) continue
                    spanStart = idx
                    // Span covers just "constructor" keyword (11 chars)
                    val length = 11
                    val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                    diagnostics.add(Diagnostic(
                        message = "Constructors for derived classes must contain a 'super' call.",
                        category = DiagnosticCategory.Error,
                        code = 2377,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = length,
                    ))
                }
            }
        }
    }

    private fun statementsContainSuperCall(stmts: List<Statement>): Boolean {
        for (stmt in stmts) {
            if (stmtContainsSuperCall(stmt)) return true
        }
        return false
    }

    /** Returns the position of the first super() call in stmts, or null if none. */
    private fun findSuperCallInStatements(stmts: List<Statement>): Int? {
        for (stmt in stmts) {
            findSuperCallInStmt(stmt)?.let { return it }
        }
        return null
    }

    private fun findSuperCallInStmt(stmt: Statement): Int? = when (stmt) {
        is ExpressionStatement -> findSuperCallInExpr(stmt.expression)
        is Block -> findSuperCallInStatements(stmt.statements)
        is IfStatement -> findSuperCallInStmt(stmt.thenStatement) ?: stmt.elseStatement?.let { findSuperCallInStmt(it) }
        else -> null
    }

    private fun findSuperCallInExpr(expr: Expression): Int? = when (expr) {
        is CallExpression -> {
            val callee = expr.expression
            if (callee is Identifier && callee.text == "super") callee.pos.takeIf { it >= 0 }
            else findSuperCallInExpr(callee)
        }
        is ParenthesizedExpression -> findSuperCallInExpr(expr.expression)
        else -> null
    }

    /**
     * Returns a pair of (startPos, length) for a super() call expression,
     * where startPos is the start of 'super' and length covers 'super()'.
     */
    private fun findSuperCallWithLength(stmts: List<Statement>): Pair<Int, Int>? {
        for (stmt in stmts) {
            findSuperCallWithLengthInStmt(stmt)?.let { return it }
        }
        return null
    }

    private fun findSuperCallWithLengthInStmt(stmt: Statement): Pair<Int, Int>? = when (stmt) {
        is ExpressionStatement -> findSuperCallWithLengthInExpr(stmt.expression)
        is Block -> findSuperCallWithLength(stmt.statements)
        is IfStatement -> findSuperCallWithLengthInStmt(stmt.thenStatement) ?: stmt.elseStatement?.let { findSuperCallWithLengthInStmt(it) }
        else -> null
    }

    private fun findSuperCallWithLengthInExpr(expr: Expression): Pair<Int, Int>? = when (expr) {
        is CallExpression -> {
            val callee = expr.expression
            if (callee is Identifier && callee.text == "super" && callee.pos >= 0) {
                // expr.end is one past the token AFTER ')' (usually ';'). Subtract 1 to get just 'super(...)'.
                val rawLen = expr.end - callee.pos
                Pair(callee.pos, (rawLen - 1).coerceAtLeast(7))
            } else findSuperCallWithLengthInExpr(callee)
        }
        is ParenthesizedExpression -> findSuperCallWithLengthInExpr(expr.expression)
        else -> null
    }

    private fun stmtContainsSuperCall(stmt: Statement): Boolean = when (stmt) {
        is ExpressionStatement -> exprContainsSuperCall(stmt.expression)
        is IfStatement -> {
            exprContainsSuperCall(stmt.expression) ||
                stmtContainsSuperCall(stmt.thenStatement) ||
                (stmt.elseStatement?.let { stmtContainsSuperCall(it) } == true)
        }
        is Block -> stmt.statements.any { stmtContainsSuperCall(it) }
        is ForStatement -> stmtContainsSuperCall(stmt.statement)
        is WhileStatement -> stmtContainsSuperCall(stmt.statement)
        is SwitchStatement -> stmt.caseBlock.any { clause ->
            when (clause) {
                is CaseClause -> clause.statements.any { stmtContainsSuperCall(it) }
                is DefaultClause -> clause.statements.any { stmtContainsSuperCall(it) }
                else -> false
            }
        }
        is TryStatement -> {
            stmt.tryBlock.statements.any { stmtContainsSuperCall(it) } ||
                (stmt.catchClause?.block?.statements?.any { stmtContainsSuperCall(it) } == true) ||
                (stmt.finallyBlock?.statements?.any { stmtContainsSuperCall(it) } == true)
        }
        is ReturnStatement -> stmt.expression?.let { exprContainsSuperCall(it) } == true
        is VariableStatement -> stmt.declarationList.declarations.any { d ->
            d.initializer?.let { exprContainsSuperCall(it) } == true
        }
        else -> false
    }

    private fun exprContainsSuperCall(expr: Expression): Boolean = when (expr) {
        is CallExpression -> {
            val callee = expr.expression
            (callee is Identifier && callee.text == "super") || exprContainsSuperCall(callee)
        }
        is BinaryExpression -> exprContainsSuperCall(expr.left) || exprContainsSuperCall(expr.right)
        is ParenthesizedExpression -> exprContainsSuperCall(expr.expression)
        is ConditionalExpression -> exprContainsSuperCall(expr.whenTrue) || exprContainsSuperCall(expr.whenFalse)
        else -> false
    }

    // -----------------------------------------------------------------------
    // TS2303: Circular definition of import alias
    // -----------------------------------------------------------------------

    private fun checkCircularImportAlias() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkCircularAliasInStmts(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkCircularAliasInStmts(stmts: List<Statement>, source: String, fileName: String) {
        // Collect import= declarations with identifier references within this scope
        val importMap = mutableMapOf<String, ImportEqualsDeclaration>()
        for (stmt in stmts) {
            if (stmt is ImportEqualsDeclaration && stmt.moduleReference is Identifier) {
                importMap[stmt.name.text] = stmt
            }
        }

        // For each import, follow the chain to detect cycles
        val reported = mutableSetOf<String>()
        for ((name, decl) in importMap) {
            if (name in reported) continue
            val visited = mutableListOf(name)
            var current = (decl.moduleReference as Identifier).text
            while (current in importMap && current !in reported) {
                if (current in visited) {
                    // Cycle detected — report on the first import in the cycle
                    val cycleStart = visited.indexOf(current)
                    for (i in cycleStart until visited.size) {
                        val cycleName = visited[i]
                        val cycleDecl = importMap[cycleName] ?: continue
                        if (cycleName in reported) continue
                        reported.add(cycleName)
                        val start = cycleDecl.pos
                        var spanStart = start
                        while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                        // Find the semicolon at end of statement
                        val semiIdx = source.indexOf(';', spanStart)
                        val spanEnd = if (semiIdx in spanStart..cycleDecl.end) semiIdx + 1 else {
                            var e = cycleDecl.end
                            while (e > spanStart && e <= source.length && source[e - 1].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) e--
                            e
                        }
                        val length = (spanEnd - spanStart).coerceAtLeast(1)
                        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                        diagnostics.add(Diagnostic(
                            message = "Circular definition of import alias '$cycleName'.",
                            category = DiagnosticCategory.Error,
                            code = 2303,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = spanStart,
                            length = length,
                        ))
                        break // TypeScript only reports on the first import in the cycle
                    }
                    break
                }
                visited.add(current)
                val nextDecl = importMap[current] ?: break
                current = (nextDecl.moduleReference as Identifier).text
            }
        }

        // Recurse into namespaces
        for (stmt in stmts) {
            when (stmt) {
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkCircularAliasInStmts(it.statements, source, fileName) }
                else -> {}
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS1108: A 'return' statement can only be used within a function body
    // -----------------------------------------------------------------------

    private fun checkReturnOutsideFunction() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            checkReturnInTopLevel(result.sourceFile.statements, source, fileName)
        }
    }

    private fun checkReturnInTopLevel(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            when (stmt) {
                is ReturnStatement -> {
                    val start = stmt.pos
                    var spanStart = start
                    while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                    // Span covers just the 'return' keyword
                    val length = 6 // "return".length
                    val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                    diagnostics.add(Diagnostic(
                        message = "A 'return' statement can only be used within a function body.",
                        category = DiagnosticCategory.Error,
                        code = 1108,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = length,
                    ))
                }
                is IfStatement -> {
                    checkReturnInTopLevelStmt(stmt.thenStatement, source, fileName)
                    stmt.elseStatement?.let { checkReturnInTopLevelStmt(it, source, fileName) }
                }
                is Block -> checkReturnInTopLevel(stmt.statements, source, fileName)
                is ModuleDeclaration -> {
                    // Return inside namespace body is also invalid
                    val body = stmt.body
                    if (body is ModuleBlock) checkReturnInTopLevel(body.statements, source, fileName)
                }
                // Don't recurse into functions/classes — returns are valid there
                else -> {}
            }
        }
    }

    private fun checkReturnInTopLevelStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ReturnStatement -> {
                val start = stmt.pos
                var spanStart = start
                while (spanStart < source.length && source[spanStart].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) spanStart++
                // Span covers just the 'return' keyword (6 chars), not the expression
                val length = 6 // "return".length
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                diagnostics.add(Diagnostic(
                    message = "A 'return' statement can only be used within a function body.",
                    category = DiagnosticCategory.Error,
                    code = 1108,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = spanStart,
                    length = length,
                ))
            }
            is Block -> checkReturnInTopLevel(stmt.statements, source, fileName)
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS1101: 'with' statements are not allowed in strict mode
    // TS2410: The 'with' statement is not supported
    // -----------------------------------------------------------------------

    private fun checkWithStatements() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            // Strict mode: fires when alwaysStrict is not explicitly false
            val isStrict = options.alwaysStrict != false
            walkForWithStatements(result.sourceFile.statements, source, fileName, isStrict)
        }
    }

    private fun walkForWithStatements(stmts: List<Statement>, source: String, fileName: String, isStrict: Boolean) {
        for (stmt in stmts) {
            walkStmtForWithStatements(stmt, source, fileName, isStrict)
        }
    }

    private fun walkStmtForWithStatements(stmt: Statement, source: String, fileName: String, isStrict: Boolean) {
        when (stmt) {
            is WithStatement -> {
                var spanStart = stmt.pos
                while (spanStart < source.length && source[spanStart].isWhitespace()) spanStart++
                val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
                if (isStrict) {
                    // TS1101: span = just the 'with' keyword (4 chars)
                    diagnostics.add(Diagnostic(
                        message = "'with' statements are not allowed in strict mode.",
                        category = DiagnosticCategory.Error,
                        code = 1101,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = 4, // "with".length
                    ))
                }
                // TS2410: span = from 'with' to closing ')' of the condition.
                // Find the matching ')' by scanning forward from 'with ' and tracking depth.
                // Only emit TS2410 if the with statement is well-formed (balanced parens).
                var spanEnd2 = spanStart + 4 // skip 'with'
                while (spanEnd2 < source.length && source[spanEnd2] != '(') spanEnd2++
                var depth = 0
                var balanced = false
                while (spanEnd2 < source.length) {
                    when (source[spanEnd2]) {
                        '(' -> { depth++; spanEnd2++ }
                        ')' -> {
                            spanEnd2++ // include the ')'
                            if (--depth == 0) { balanced = true; break }
                        }
                        else -> spanEnd2++
                    }
                }
                if (balanced) {
                    val ts2410Length = spanEnd2 - spanStart
                    diagnostics.add(Diagnostic(
                        message = "The 'with' statement is not supported. All symbols in a 'with' block will have type 'any'.",
                        category = DiagnosticCategory.Error,
                        code = 2410,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = spanStart,
                        length = ts2410Length,
                    ))
                }
                // Recurse into the body statement
                walkStmtForWithStatements(stmt.statement, source, fileName, isStrict)
            }
            is Block -> walkForWithStatements(stmt.statements, source, fileName, isStrict)
            is IfStatement -> {
                walkStmtForWithStatements(stmt.thenStatement, source, fileName, isStrict)
                stmt.elseStatement?.let { walkStmtForWithStatements(it, source, fileName, isStrict) }
            }
            is ForStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict)
            is ForInStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict)
            is ForOfStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict)
            is WhileStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict)
            is DoStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val stmts2 = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    walkForWithStatements(stmts2, source, fileName, isStrict)
                }
            }
            is TryStatement -> {
                walkForWithStatements(stmt.tryBlock.statements, source, fileName, isStrict)
                stmt.catchClause?.block?.let { walkForWithStatements(it.statements, source, fileName, isStrict) }
                stmt.finallyBlock?.let { walkForWithStatements(it.statements, source, fileName, isStrict) }
            }
            is LabeledStatement -> walkStmtForWithStatements(stmt.statement, source, fileName, isStrict)
            // Function bodies: recurse (with becomes valid JS-wise inside them, but TS still checks)
            is FunctionDeclaration -> {
                stmt.body?.let { walkForWithStatements(it.statements, source, fileName, isStrict) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    body?.let { walkForWithStatements(it.statements, source, fileName, isStrict) }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForWithStatements(body.statements, source, fileName, isStrict)
            }
            is ExpressionStatement -> walkExprForWithStatements(stmt.expression, source, fileName, isStrict)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForWithStatements(it, source, fileName, isStrict) }
                }
            }
            else -> {}
        }
    }

    private fun walkExprForWithStatements(expr: Expression, source: String, fileName: String, isStrict: Boolean) {
        when (expr) {
            is FunctionExpression -> {
                walkForWithStatements(expr.body.statements, source, fileName, isStrict)
            }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) walkForWithStatements(body.statements, source, fileName, isStrict)
            }
            is ClassExpression -> {
                for (member in expr.members) {
                    val body = when (member) {
                        is MethodDeclaration -> member.body
                        is Constructor -> member.body
                        is GetAccessor -> member.body
                        is SetAccessor -> member.body
                        else -> null
                    }
                    body?.let { walkForWithStatements(it.statements, source, fileName, isStrict) }
                }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS1114: Duplicate label
    // -----------------------------------------------------------------------

    private fun checkDuplicateLabels() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForDuplicateLabels(result.sourceFile.statements, source, fileName, mutableSetOf())
        }
    }

    private fun walkForDuplicateLabels(stmts: List<Statement>, source: String, fileName: String, activeLabels: MutableSet<String>) {
        for (stmt in stmts) walkStmtForDupLabels(stmt, source, fileName, activeLabels)
    }

    private fun walkStmtForDupLabels(stmt: Statement, source: String, fileName: String, activeLabels: MutableSet<String>) {
        when (stmt) {
            is LabeledStatement -> {
                val label = stmt.label.text
                if (label in activeLabels) {
                    val start = stmt.label.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Duplicate label '$label'.",
                        category = DiagnosticCategory.Error,
                        code = 1114,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = label.length,
                    ))
                }
                activeLabels.add(label)
                walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
                activeLabels.remove(label)
            }
            is FunctionDeclaration -> {
                // New label scope inside functions
                stmt.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
                        is Constructor -> m.body?.let { walkForDuplicateLabels(it.statements, source, fileName, mutableSetOf()) }
                        else -> {}
                    }
                }
            }
            is Block -> walkForDuplicateLabels(stmt.statements, source, fileName, activeLabels)
            is IfStatement -> {
                walkStmtForDupLabels(stmt.thenStatement, source, fileName, activeLabels)
                stmt.elseStatement?.let { walkStmtForDupLabels(it, source, fileName, activeLabels) }
            }
            is ForStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is ForInStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is ForOfStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is WhileStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is DoStatement -> walkStmtForDupLabels(stmt.statement, source, fileName, activeLabels)
            is SwitchStatement -> {
                for (c in stmt.caseBlock) {
                    when (c) {
                        is CaseClause -> walkForDuplicateLabels(c.statements, source, fileName, activeLabels)
                        is DefaultClause -> walkForDuplicateLabels(c.statements, source, fileName, activeLabels)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForDuplicateLabels(stmt.tryBlock.statements, source, fileName, activeLabels)
                stmt.catchClause?.let { walkForDuplicateLabels(it.block.statements, source, fileName, activeLabels) }
                stmt.finallyBlock?.let { walkForDuplicateLabels(it.statements, source, fileName, activeLabels) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForDuplicateLabels(it.statements, source, fileName, activeLabels) }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS1099: Type argument list cannot be empty
    // -----------------------------------------------------------------------

    private fun checkEmptyTypeArguments() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForEmptyTypeArgs(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForEmptyTypeArgs(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForEmptyTypeArgs(stmt, source, fileName)
    }

    private fun walkStmtForEmptyTypeArgs(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ExpressionStatement -> walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
            is VariableStatement -> for (d in stmt.declarationList.declarations) {
                d.initializer?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
            is FunctionDeclaration -> stmt.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
                    is Constructor -> m.body?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
                    is PropertyDeclaration -> m.initializer?.let { walkExprForEmptyTypeArgs(it, source, fileName) }
                    else -> {}
                }
            }
            is Block -> walkForEmptyTypeArgs(stmt.statements, source, fileName)
            is IfStatement -> {
                walkExprForEmptyTypeArgs(stmt.expression, source, fileName)
                walkStmtForEmptyTypeArgs(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForEmptyTypeArgs(it, source, fileName) }
            }
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { walkForEmptyTypeArgs(it.statements, source, fileName) }
            else -> {}
        }
    }

    private fun walkExprForEmptyTypeArgs(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is CallExpression -> {
                if (expr.typeArguments != null && expr.typeArguments.isEmpty()) {
                    reportEmptyTypeArgs(expr, source, fileName)
                }
                walkExprForEmptyTypeArgs(expr.expression, source, fileName)
                for (arg in expr.arguments) walkExprForEmptyTypeArgs(arg, source, fileName)
            }
            is NewExpression -> {
                if (expr.typeArguments != null && expr.typeArguments.isEmpty()) {
                    reportEmptyTypeArgs(expr, source, fileName)
                }
                walkExprForEmptyTypeArgs(expr.expression, source, fileName)
                expr.arguments?.forEach { walkExprForEmptyTypeArgs(it, source, fileName) }
            }
            is BinaryExpression -> {
                var current: Expression = expr
                while (current is BinaryExpression) {
                    walkExprForEmptyTypeArgs(current.right, source, fileName)
                    current = current.left
                }
                walkExprForEmptyTypeArgs(current, source, fileName)
            }
            is ParenthesizedExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is ConditionalExpression -> {
                walkExprForEmptyTypeArgs(expr.condition, source, fileName)
                walkExprForEmptyTypeArgs(expr.whenTrue, source, fileName)
                walkExprForEmptyTypeArgs(expr.whenFalse, source, fileName)
            }
            is PropertyAccessExpression -> walkExprForEmptyTypeArgs(expr.expression, source, fileName)
            is ArrowFunction -> {
                when (val body = expr.body) {
                    is Block -> walkForEmptyTypeArgs(body.statements, source, fileName)
                    is Expression -> walkExprForEmptyTypeArgs(body, source, fileName)
                    else -> {}
                }
            }
            is FunctionExpression -> walkForEmptyTypeArgs(expr.body.statements, source, fileName)
            else -> {}
        }
    }

    private fun reportEmptyTypeArgs(expr: Node, source: String, fileName: String) {
        // Find the `<>` in source — search from the expression start (not end, which may
        // overshoot past `<` due to parser position semantics after nextToken())
        val searchStart = when (expr) {
            is CallExpression -> expr.expression.pos
            is NewExpression -> expr.expression.pos
            else -> expr.pos
        }
        val ltIdx = source.indexOf("<>", searchStart)
        if (ltIdx < 0) return
        emitTS1099(ltIdx, source, fileName)
    }

    private fun emitTS1099(start: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Type argument list cannot be empty.",
            category = DiagnosticCategory.Error,
            code = 1099,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = 2, // "<>"
        ))
    }

    // -----------------------------------------------------------------------
    // TS2354: importHelpers without tslib
    // -----------------------------------------------------------------------

    private fun checkImportHelpersWithoutTslib() {
        if (!options.importHelpers) return
        // Check if tslib is available in the compilation files
        val hasTslib = binderResults.any { it.sourceFile.fileName.contains("tslib") }
        if (hasTslib) return

        val em = options.effectiveModule
        // esModuleInterop helpers needed for CJS/AMD/UMD/NodeNext (not System/ES) modules
        val needsEsmHelpers = options.esModuleInterop && (em == ModuleKind.CommonJS || em == ModuleKind.AMD ||
                em == ModuleKind.UMD || em.isNodeNext)
        // Class extends helpers needed when target < ES2015 (raw target)
        val needsExtendsHelper = options.target <= ScriptTarget.ES5
        // Decorator helpers always needed when experimentalDecorators is set
        val needsDecoratorHelper = options.experimentalDecorators

        if (!needsEsmHelpers && !needsExtendsHelper && !needsDecoratorHelper) return

        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text

            val isModule = isModuleFile(result.sourceFile.statements)
            val ts2354StartCount = diagnostics.count { it.code == 2354 && it.fileName == fileName }

            for (stmt in result.sourceFile.statements) {
                if (diagnostics.count { it.code == 2354 && it.fileName == fileName } > ts2354StartCount) break
                when (stmt) {
                    is ExportDeclaration -> if (needsEsmHelpers) {
                        if (stmt.moduleSpecifier != null && !stmt.isTypeOnly) {
                            val clause = stmt.exportClause
                            if (clause is NamedExports) {
                                for (spec in clause.elements) {
                                    if (spec.isTypeOnly) continue
                                    val importedName = (spec.propertyName ?: spec.name).text
                                    if (importedName == "default") {
                                        val startNode = spec.propertyName ?: spec.name
                                        val endNode = if (spec.propertyName != null) spec.name else spec.name
                                        val spanStart = startNode.pos
                                        val spanLen = if (spec.propertyName != null) {
                                            endNode.pos + endNode.text.length - spanStart
                                        } else {
                                            startNode.text.length
                                        }
                                        emitTS2354(spanStart, spanLen, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                    is ImportDeclaration -> if (needsEsmHelpers) {
                        if (stmt.importClause?.isTypeOnly != true) {
                            val clause = stmt.importClause ?: continue
                            val bindings = clause.namedBindings
                            // import * as X from "..." needs __importStar
                            if (bindings is NamespaceImport) {
                                // Span covers whole import statement (from import keyword to semicolon)
                                val spanStart = stmt.pos
                                // Find end of statement line (up to and including semicolon)
                                val lineEnd = source.indexOf('\n', spanStart).let { if (it < 0) source.length else it }
                                val spanLen = source.substring(spanStart, lineEnd).trimEnd().length
                                emitTS2354(spanStart, spanLen, source, fileName)
                            }
                            // import { default as X } from "..." needs __importDefault
                            if (bindings is NamedImports) {
                                for (spec in bindings.elements) {
                                    if (spec.isTypeOnly) continue
                                    val importedName = (spec.propertyName ?: spec.name).text
                                    if (importedName == "default") {
                                        val startNode = spec.propertyName ?: spec.name
                                        val endNode = if (spec.propertyName != null) spec.name else spec.name
                                        val spanStart = startNode.pos
                                        val spanLen = if (spec.propertyName != null) {
                                            endNode.pos + endNode.text.length - spanStart
                                        } else {
                                            startNode.text.length
                                        }
                                        emitTS2354(spanStart, spanLen, source, fileName)
                                    }
                                }
                            }
                        }
                    }
                    is ClassDeclaration -> {
                        var emittedForClass = false
                        // Class extends with target < ES2015 needs __extends helper (module files only)
                        if (needsExtendsHelper && isModule) {
                            val heritageClauses = stmt.heritageClauses
                            if (heritageClauses != null) {
                                for (clause in heritageClauses) {
                                    if (clause.token == SyntaxKind.ExtendsKeyword && clause.types.isNotEmpty()) {
                                        val spanStart = clause.pos
                                        val firstType = clause.types.first()
                                        val typeEnd = expressionTrueEnd(firstType.expression)
                                        val spanLen = typeEnd - spanStart
                                        emitTS2354(spanStart, spanLen, source, fileName)
                                        emittedForClass = true
                                    }
                                }
                            }
                        }
                        // Decorators need __decorate helper (module files only) — skip if already emitted
                        if (!emittedForClass && needsDecoratorHelper && isModule) {
                            checkDecoratorHelperOnClass(stmt, source, fileName)
                        }
                    }
                    else -> {}
                }
            }
        }
    }

    private fun emitTS2354(spanStart: Int, spanLen: Int, source: String, fileName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, spanStart)
        diagnostics.add(Diagnostic(
            message = "This syntax requires an imported helper but module 'tslib' cannot be found.",
            category = DiagnosticCategory.Error,
            code = 2354,
            fileName = fileName,
            line = line,
            character = character,
            start = spanStart,
            length = spanLen,
        ))
    }

    private fun checkDecoratorHelperOnClass(stmt: ClassDeclaration, source: String, fileName: String) {
        // Check if the class or any of its members have decorators
        val firstDecorator = stmt.decorators?.firstOrNull()
        if (firstDecorator != null) {
            // Span covers the first decorator including @
            val spanStart = firstDecorator.pos
            val lineEnd = source.indexOf('\n', spanStart).let { if (it < 0) source.length else it }
            val spanLen = source.substring(spanStart, lineEnd).trimEnd().length
            emitTS2354(spanStart, spanLen, source, fileName)
            return
        }
        // Also check member decorators (methods, properties, parameters)
        for (member in stmt.members) {
            val memberDec = when (member) {
                is MethodDeclaration -> member.decorators?.firstOrNull()
                is PropertyDeclaration -> member.decorators?.firstOrNull()
                is GetAccessor -> member.decorators?.firstOrNull()
                is SetAccessor -> member.decorators?.firstOrNull()
                else -> null
            }
            if (memberDec != null) {
                val spanStart = memberDec.pos
                val lineEnd = source.indexOf('\n', spanStart).let { if (it < 0) source.length else it }
                val spanLen = source.substring(spanStart, lineEnd).trimEnd().length
                emitTS2354(spanStart, spanLen, source, fileName)
                return
            }
            // Check parameter decorators
            val params = when (member) {
                is MethodDeclaration -> member.parameters
                is Constructor -> member.parameters
                else -> emptyList()
            }
            for (param in params) {
                val paramDec = param.decorators?.firstOrNull()
                if (paramDec != null) {
                    val spanStart = paramDec.pos
                    val lineEnd = source.indexOf('\n', spanStart).let { if (it < 0) source.length else it }
                    val spanLen = source.substring(spanStart, lineEnd).trimEnd().length
                    emitTS2354(spanStart, spanLen, source, fileName)
                    return
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS7028: Unused label
    // -----------------------------------------------------------------------

    private fun checkUnusedLabels() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForUnusedLabels(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForUnusedLabels(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForUnusedLabels(stmt, source, fileName)
    }

    private fun walkStmtForUnusedLabels(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is LabeledStatement -> {
                val labelName = stmt.label.text
                // Check if this label is used by any break/continue within the labeled statement
                if (!isLabelUsed(labelName, stmt.statement)) {
                    val start = stmt.label.pos
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Unused label.",
                        category = DiagnosticCategory.Error,
                        code = 7028,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = labelName.length,
                    ))
                }
                // Recurse into the labeled statement
                walkStmtForUnusedLabels(stmt.statement, source, fileName)
            }
            is Block -> walkForUnusedLabels(stmt.statements, source, fileName)
            is IfStatement -> {
                walkStmtForUnusedLabels(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForUnusedLabels(it, source, fileName) }
            }
            is ForStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is ForInStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is ForOfStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is WhileStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is DoStatement -> walkStmtForUnusedLabels(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForUnusedLabels(clause.statements, source, fileName)
                        is DefaultClause -> walkForUnusedLabels(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForUnusedLabels(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForUnusedLabels(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForUnusedLabels(it.statements, source, fileName) }
            }
            is FunctionDeclaration -> {
                // New label scope inside function body
                stmt.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
            }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> walkExprForUnusedLabels(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForUnusedLabels(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { walkExprForUnusedLabels(it, source, fileName) }
            else -> {}
        }
    }

    private fun walkExprForUnusedLabels(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> expr.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) walkForUnusedLabels(body.statements, source, fileName)
            }
            is ClassExpression -> {
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkForUnusedLabels(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Returns true if a break or continue referencing [labelName] exists in [stmt].
     * Does NOT recurse into nested function boundaries (those create new label scopes).
     */
    private fun isLabelUsed(labelName: String, stmt: Statement): Boolean {
        return when (stmt) {
            is BreakStatement -> stmt.label?.text == labelName
            is ContinueStatement -> stmt.label?.text == labelName
            is Block -> stmt.statements.any { isLabelUsed(labelName, it) }
            is IfStatement -> isLabelUsed(labelName, stmt.thenStatement) ||
                (stmt.elseStatement?.let { isLabelUsed(labelName, it) } ?: false)
            is LabeledStatement -> isLabelUsed(labelName, stmt.statement)
            is ForStatement -> isLabelUsed(labelName, stmt.statement)
            is ForInStatement -> isLabelUsed(labelName, stmt.statement)
            is ForOfStatement -> isLabelUsed(labelName, stmt.statement)
            is WhileStatement -> isLabelUsed(labelName, stmt.statement)
            is DoStatement -> isLabelUsed(labelName, stmt.statement)
            is SwitchStatement -> stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> clause.statements.any { isLabelUsed(labelName, it) }
                    is DefaultClause -> clause.statements.any { isLabelUsed(labelName, it) }
                    else -> false
                }
            }
            is TryStatement -> stmt.tryBlock.statements.any { isLabelUsed(labelName, it) } ||
                (stmt.catchClause?.block?.statements?.any { isLabelUsed(labelName, it) } ?: false) ||
                (stmt.finallyBlock?.statements?.any { isLabelUsed(labelName, it) } ?: false)
            // Do NOT recurse into function declarations/expressions — new label scope
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // TS7029: Fallthrough case in switch
    // -----------------------------------------------------------------------

    private fun checkFallthroughCases() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForFallthroughCases(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForFallthroughCases(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForFallthroughCases(stmt, source, fileName)
    }

    private fun walkStmtForFallthroughCases(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is SwitchStatement -> {
                checkSwitchForFallthrough(stmt, source, fileName)
                // Recurse into case clause bodies too
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForFallthroughCases(clause.statements, source, fileName)
                        is DefaultClause -> walkForFallthroughCases(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is Block -> walkForFallthroughCases(stmt.statements, source, fileName)
            is IfStatement -> {
                walkStmtForFallthroughCases(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForFallthroughCases(it, source, fileName) }
            }
            is LabeledStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is ForStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is ForInStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is ForOfStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is WhileStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is DoStatement -> walkStmtForFallthroughCases(stmt.statement, source, fileName)
            is TryStatement -> {
                walkForFallthroughCases(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForFallthroughCases(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForFallthroughCases(it.statements, source, fileName) }
            }
            is FunctionDeclaration -> stmt.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        is Constructor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        is GetAccessor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        is SetAccessor -> m.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
                        else -> {}
                    }
                }
            }
            is ExpressionStatement -> walkExprForFallthroughCases(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForFallthroughCases(it, source, fileName) }
                }
            }
            else -> {}
        }
    }

    private fun walkExprForFallthroughCases(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> expr.body?.let { walkForFallthroughCases(it.statements, source, fileName) }
            is ArrowFunction -> {
                val body = expr.body
                if (body is Block) walkForFallthroughCases(body.statements, source, fileName)
            }
            else -> {}
        }
    }

    /**
     * Check a switch statement for fallthrough cases (TS7029).
     * A case clause falls through if it has statements but doesn't end with a terminating statement.
     * Empty case clauses (no statements) are allowed to fall through.
     * TypeScript reports TS7029 on the CURRENT case clause that falls through (not the next one).
     */
    private fun checkSwitchForFallthrough(stmt: SwitchStatement, source: String, fileName: String) {
        val clauses = stmt.caseBlock
        for (i in clauses.indices) {
            val clause = clauses[i]
            val clauseStmts = when (clause) {
                is CaseClause -> clause.statements
                is DefaultClause -> clause.statements
                else -> continue
            }
            // Only check non-last clauses — last clause doesn't fall through anywhere
            if (i == clauses.size - 1) continue
            // Empty clauses (no statements) are allowed to fall through
            if (clauseStmts.isEmpty()) continue
            // Check if the clause definitely terminates
            if (!clauseStmtsTerminate(clauseStmts)) {
                // Report on the CURRENT clause's case/default keyword
                val clauseStart = when (clause) {
                    is CaseClause -> clause.pos
                    is DefaultClause -> clause.pos
                    else -> continue
                }
                val (line, character) = getLineAndCharacterOfPosition(source, clauseStart)
                // Span covers "case X:" or "default:" header
                val colonIdx = source.indexOf(':', clauseStart)
                val spanEnd = if (colonIdx >= 0) colonIdx + 1 else clauseStart + 4
                val spanLen = spanEnd - clauseStart
                diagnostics.add(Diagnostic(
                    message = "Fallthrough case in switch.",
                    category = DiagnosticCategory.Error,
                    code = 7029,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = clauseStart,
                    length = spanLen,
                ))
            }
        }
    }

    /**
     * Returns true if a list of statements definitely terminates on ALL code paths.
     */
    private fun clauseStmtsTerminate(stmts: List<Statement>): Boolean {
        // A clause terminates if any statement in it definitely terminates on all paths
        return stmts.any { isDefinitelyTerminating(it) }
    }

    // -----------------------------------------------------------------------
    // TS7030: Not all code paths return a value / TS2355
    // -----------------------------------------------------------------------

    private fun checkImplicitReturns() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip JS files — return type checks (TS2355/TS7030/TS2366) don't apply
            if (!options.checkJs && (fileName.endsWith(".js") || fileName.endsWith(".jsx"))) continue
            val source = result.sourceFile.text
            walkForImplicitReturns(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForImplicitReturns(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) walkStmtForImplicitReturns(stmt, source, fileName)
    }

    private fun walkStmtForImplicitReturns(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is FunctionDeclaration -> checkFunctionForImplicitReturn(stmt, source, fileName)
            is ClassDeclaration -> {
                for (m in stmt.members) {
                    when (m) {
                        is MethodDeclaration -> checkMethodForImplicitReturn(m, source, fileName)
                        is Constructor -> {} // constructors don't need return value checks
                        is GetAccessor -> checkGetAccessorForImplicitReturn(m, source, fileName)
                        is SetAccessor -> {} // setters don't return
                        else -> {}
                    }
                }
            }
            is Block -> walkForImplicitReturns(stmt.statements, source, fileName)
            is IfStatement -> {
                walkStmtForImplicitReturns(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { walkStmtForImplicitReturns(it, source, fileName) }
            }
            is LabeledStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is ForStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is ForInStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is ForOfStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is WhileStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is DoStatement -> walkStmtForImplicitReturns(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> walkForImplicitReturns(clause.statements, source, fileName)
                        is DefaultClause -> walkForImplicitReturns(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                walkForImplicitReturns(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForImplicitReturns(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForImplicitReturns(it.statements, source, fileName) }
            }
            is ExpressionStatement -> walkExprForImplicitReturns(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { walkExprForImplicitReturns(it, source, fileName) }
                }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForImplicitReturns(body.statements, source, fileName)
            }
            else -> {}
        }
    }

    private fun walkExprForImplicitReturns(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is FunctionExpression -> {
                checkFuncExprForImplicitReturn(expr, source, fileName)
            }
            is ArrowFunction -> {
                checkArrowForImplicitReturn(expr, source, fileName)
            }
            is ClassExpression -> {
                for (m in expr.members) {
                    when (m) {
                        is MethodDeclaration -> checkMethodForImplicitReturn(m, source, fileName)
                        else -> {}
                    }
                }
            }
            else -> {}
        }
    }

    /**
     * Get the return type annotation node position/length for a function, for TS7030 diagnostic span.
     */
    private fun checkFunctionForImplicitReturn(decl: FunctionDeclaration, source: String, fileName: String) {
        val body = decl.body ?: return
        if (decl.asteriskToken) return // generators always return an iterator — no implicit-return check
        val retType = decl.type
        val isAsync = ModifierFlag.Async in decl.modifiers
        // Only check if there's an explicit return type annotation (for TS2355) or for TS7030
        checkBodyForImplicitReturn(body, retType, isAsync, decl.name?.let { FuncRef(it.pos, it.text.length) }, source, fileName)
        // Recurse into body for nested functions
        walkForImplicitReturns(body.statements, source, fileName)
    }

    private fun checkMethodForImplicitReturn(decl: MethodDeclaration, source: String, fileName: String) {
        val body = decl.body ?: return
        if (decl.asteriskToken) return // generators always return an iterator — no implicit-return check
        val retType = decl.type
        val isAsync = ModifierFlag.Async in decl.modifiers
        val nameNode = decl.name
        val nameRef = when (nameNode) {
            is Identifier -> FuncRef(nameNode.pos, nameNode.text.length)
            else -> null
        }
        checkBodyForImplicitReturn(body, retType, isAsync, nameRef, source, fileName)
        walkForImplicitReturns(body.statements, source, fileName)
    }

    private fun checkGetAccessorForImplicitReturn(decl: GetAccessor, source: String, fileName: String) {
        val body = decl.body ?: return
        val retType = decl.type
        val nameNode = decl.name
        val nameRef = when (nameNode) {
            is Identifier -> FuncRef(nameNode.pos, nameNode.text.length)
            else -> null
        }
        checkBodyForImplicitReturn(body, retType, false, nameRef, source, fileName)
        // Getters without type annotation: if body has value returns but doesn't always return,
        // emit TS2366 (TypeScript infers non-void return type from the body).
        if (retType == null && strictNullChecks) {
            val hasValueReturn = bodyHasReturnWithValue(body.statements, anyExpr = false)
            val alwaysReturns = bodyAlwaysReturns(body.statements)
            if (hasValueReturn && !alwaysReturns && nameNode is Identifier) {
                val start = nameNode.pos
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Function lacks ending return statement and return type does not include 'undefined'.",
                    category = DiagnosticCategory.Error,
                    code = 2366,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = nameNode.text.length,
                ))
            }
        }
        walkForImplicitReturns(body.statements, source, fileName)
    }

    private fun checkFuncExprForImplicitReturn(expr: FunctionExpression, source: String, fileName: String) {
        val body = expr.body ?: return
        if (expr.asteriskToken) return // generators always return an iterator
        val retType = expr.type
        val isAsync = ModifierFlag.Async in expr.modifiers
        val nameRef = expr.name?.let { FuncRef(it.pos, it.text.length) }
        checkBodyForImplicitReturn(body, retType, isAsync, nameRef, source, fileName)
        walkForImplicitReturns(body.statements, source, fileName)
    }

    private fun checkArrowForImplicitReturn(expr: ArrowFunction, source: String, fileName: String) {
        val bodyNode = expr.body
        if (bodyNode !is Block) return // expression body always returns
        val retType = expr.type
        val isAsync = ModifierFlag.Async in expr.modifiers
        checkBodyForImplicitReturn(bodyNode, retType, isAsync, null, source, fileName)
        walkForImplicitReturns(bodyNode.statements, source, fileName)
    }

    /**
     * Check a function body for TS7030 / TS2355 (not all code paths return a value).
     *
     * TypeScript's rules:
     * - With explicit non-void return type: report at the return type annotation.
     *   - TS2355 if the body has NO return-with-value statements anywhere.
     *   - TS7030 if the body has SOME return-with-value statements but not all paths return.
     * - Without return type (or void-like): report TS7030 at the function name.
     *   - Only when the body has SOME return-with-value statements but not all paths return.
     */
    private fun checkBodyForImplicitReturn(
        body: Block,
        retType: TypeNode?,
        isAsync: Boolean,
        funcNameRef: FuncRef?,
        source: String,
        fileName: String,
    ) {
        // Check if the return type annotation is present and classify it:
        // - "truly-void": void/any/never (and unions containing them) → suppress all checks
        // - "pure-undefined": exactly `undefined` keyword (not a union) → suppress all checks
        // - "nullable": union containing undefined but not void/any/never (e.g. `string | undefined`) → TS7030 if hasAnyReturn
        // - "non-void": all other types (number, string, unknown, non-nullable unions) → trigger TS2355/TS2366/TS7030
        // - null (no annotation): use function name position for TS7030
        val retTypeName = retType?.let { getTypeNodeName(it, isAsync) }
        val retTypeClass = when {
            retType == null -> null
            retTypeName == null -> "non-void"  // unknown type (complex type we can't parse) → treat as non-void
            isVoidLikeTypeName(retTypeName) && retTypeName != "undefined" -> "truly-void"  // void/any/never
            retTypeName == "undefined" -> if (retType is KeywordTypeNode) "pure-undefined" else "nullable"
            else -> "non-void"  // number, string, unknown, union, function-type, etc.
        }

        // truly-void and pure-undefined return types suppress all implicit-return checks
        if (retTypeClass == "truly-void" || retTypeClass == "pure-undefined") return

        // If the function always returns/throws on all paths, check for problematic empty returns
        val alwaysReturns = bodyAlwaysReturns(body.statements)
        if (alwaysReturns) {
            // Case 1: explicit non-void return type + body always returns via empty returns → TS7030 at each empty return
            if (retTypeClass == "non-void" && retType != null) {
                reportEmptyReturnsInBody(body.statements, source, fileName)
            }
            // Case 2: no explicit return type, but some paths return values and some do empty returns → TS7030 at empty returns
            // (detectable without type inference: hasAnyReturn strict-mode = true means there's a non-void return)
            if (retType == null) {
                val hasValueReturn = bodyHasReturnWithValue(body.statements, anyExpr = false)
                if (hasValueReturn) {
                    reportEmptyReturnsInBody(body.statements, source, fileName)
                }
            }
            return
        }

        // Determine if the body has any return-with-value statement.
        // When an explicit return type annotation is present, use liberal counting (any `return <expr>`,
        // including `return undefined`, `return callExpr()`). Without annotation, use strict counting
        // (only syntactically non-void expressions, excluding `return undefined` identifier).
        val hasAnyReturn = bodyHasReturnWithValue(body.statements, anyExpr = retType != null)

        // A type is "definitely non-nullable" for TS2366: it's non-void AND not unknown AND not nullable
        val isDefinitelyNonNullable = retTypeClass == "non-void" && retTypeName != "unknown"

        // For explicit return type annotations: report at the return type annotation
        if (retType != null) {
            // "nullable" (e.g. `string | undefined`) only triggers TS7030 if there are some return-with-value stmts
            if (retTypeClass == "nullable" && !hasAnyReturn) return

            val start = retType.pos
            val spanLen = getRetTypeSpanLength(source, start)
            val (line, character) = getLineAndCharacterOfPosition(source, start)

            when {
                // TS2366: non-nullable return type with some value returns under strictNullChecks,
                // or noImplicitReturns without value returns outside try blocks.
                // "Function lacks ending return statement and return type does not include 'undefined'."
                // Under strictNullChecks, undefined is NOT assignable to non-nullable types,
                // so implicit return (returning undefined) is a type error.
                isDefinitelyNonNullable && hasAnyReturn && (
                    strictNullChecks ||
                    (options.noImplicitReturns && !hasAnyReturnOutsideTry(body.statements))
                ) -> {
                    diagnostics.add(Diagnostic(
                        message = "Function lacks ending return statement and return type does not include 'undefined'.",
                        category = DiagnosticCategory.Error,
                        code = 2366,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = spanLen,
                    ))
                }
                hasAnyReturn && (strictNullChecks || options.noImplicitReturns) -> {
                    // TS7030: some paths return with a value, some don't (for nullable/unknown return types)
                    // Only fires when strictNullChecks is on (undefined not assignable) or noImplicitReturns is set.
                    // Without either, implicit return of undefined is always valid.
                    diagnostics.add(Diagnostic(
                        message = "Not all code paths return a value.",
                        category = DiagnosticCategory.Error,
                        code = 7030,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = spanLen,
                    ))
                }
                retTypeClass == "non-void" && !hasAnyReturn -> {
                    // TS2355: function has non-void return type but never returns (no return statements at all)
                    diagnostics.add(Diagnostic(
                        message = "A function whose declared type is neither 'undefined', 'void', nor 'any' must return a value.",
                        category = DiagnosticCategory.Error,
                        code = 2355,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = spanLen,
                    ))
                }
            }
            return
        }

        // No explicit return type: TS7030 at function name only when noImplicitReturns is set
        // Without noImplicitReturns, TypeScript does NOT report TS7030 for unannotated functions
        // even when they have mixed returns (some paths return, some don't).
        if (options.noImplicitReturns && hasAnyReturn && funcNameRef != null) {
            val (line, character) = getLineAndCharacterOfPosition(source, funcNameRef.pos)
            diagnostics.add(Diagnostic(
                message = "Not all code paths return a value.",
                category = DiagnosticCategory.Error,
                code = 7030,
                fileName = fileName,
                line = line,
                character = character,
                start = funcNameRef.pos,
                length = funcNameRef.length,
            ))
        }
    }

    /**
     * Report TS7030 at each empty `return;` statement in the body (and nested blocks).
     * Used when a function with non-void return type has all paths covered by return statements
     * but some returns are empty (returning undefined implicitly).
     * Does NOT recurse into nested function bodies.
     */
    private fun reportEmptyReturnsInBody(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            reportEmptyReturnsInStmt(stmt, source, fileName)
        }
    }

    private fun reportEmptyReturnsInStmt(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ReturnStatement -> {
                if (stmt.expression == null) {
                    // Empty return; in non-void function
                    val (line, character) = getLineAndCharacterOfPosition(source, stmt.pos)
                    diagnostics.add(Diagnostic(
                        message = "Not all code paths return a value.",
                        category = DiagnosticCategory.Error,
                        code = 7030,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = stmt.pos,
                        length = "return".length,
                    ))
                }
            }
            is Block -> reportEmptyReturnsInBody(stmt.statements, source, fileName)
            is IfStatement -> {
                reportEmptyReturnsInStmt(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { reportEmptyReturnsInStmt(it, source, fileName) }
            }
            is ForStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is ForInStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is ForOfStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is WhileStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is DoStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> reportEmptyReturnsInBody(clause.statements, source, fileName)
                        is DefaultClause -> reportEmptyReturnsInBody(clause.statements, source, fileName)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                reportEmptyReturnsInBody(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { reportEmptyReturnsInBody(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { reportEmptyReturnsInBody(it.statements, source, fileName) }
            }
            is LabeledStatement -> reportEmptyReturnsInStmt(stmt.statement, source, fileName)
            // Don't recurse into nested function declarations/expressions (they have their own checks)
            is FunctionDeclaration -> {}
            else -> {}
        }
    }

    /**
     * Returns true if the body contains any `return <expr>` statement.
     * When [anyExpr] is true: counts any non-null expression (even `return undefined`, `return callExpr()`).
     * When [anyExpr] is false (default): uses [isNonVoidExpression] filter (conservative).
     * Does NOT recurse into nested function bodies.
     */
    private fun bodyHasReturnWithValue(stmts: List<Statement>, anyExpr: Boolean = false): Boolean {
        return stmts.any { stmtHasReturnWithValue(it, anyExpr) }
    }

    /**
     * Returns true if an expression is syntactically non-void (definitely not void type).
     * Used to filter out `return voidFunc()` cases where we can't know if void without type info.
     * Conservative: call expressions return false (might be void), literals return true.
     */
    private fun isNonVoidExpression(expr: Expression): Boolean {
        return when (expr) {
            is NumericLiteralNode -> true
            is StringLiteralNode -> true
            is RegularExpressionLiteralNode -> true
            is Identifier -> expr.text != "undefined"
            is BinaryExpression -> true  // arithmetic/comparison/string concat
            is PrefixUnaryExpression -> true
            is PostfixUnaryExpression -> true
            is ArrayLiteralExpression -> true
            is ObjectLiteralExpression -> true
            is NewExpression -> true
            is ParenthesizedExpression -> isNonVoidExpression(expr.expression)
            is ConditionalExpression -> true  // ternary always has a value
            is TemplateExpression -> true
            is NoSubstitutionTemplateLiteralNode -> true
            // CallExpression might return void — skip counting these without type info
            is CallExpression -> false
            // TypeAssertionExpression (<T>expr): count unless cast type is any/void/undefined
            is TypeAssertionExpression -> {
                val typeName = getTypeNodeName(expr.type, false)
                typeName != null && !isVoidLikeTypeName(typeName)
            }
            // AsExpression (expr as T): count unless asserted type is any/void/undefined
            is AsExpression -> {
                val typeName = getTypeNodeName(expr.type, false)
                typeName != null && !isVoidLikeTypeName(typeName)
            }
            else -> false  // conservative
        }
    }

    private fun stmtHasReturnWithValue(stmt: Statement, anyExpr: Boolean = false): Boolean {
        return when (stmt) {
            is ReturnStatement -> {
                val expr = stmt.expression ?: return false
                if (anyExpr) true else isNonVoidExpression(expr)
            }
            is Block -> bodyHasReturnWithValue(stmt.statements, anyExpr)
            is IfStatement -> stmtHasReturnWithValue(stmt.thenStatement, anyExpr) ||
                (stmt.elseStatement?.let { stmtHasReturnWithValue(it, anyExpr) } ?: false)
            is WhileStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is ForStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is ForInStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is ForOfStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is DoStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is LabeledStatement -> stmtHasReturnWithValue(stmt.statement, anyExpr)
            is SwitchStatement -> stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> bodyHasReturnWithValue(clause.statements, anyExpr)
                    is DefaultClause -> bodyHasReturnWithValue(clause.statements, anyExpr)
                    else -> false
                }
            }
            is TryStatement -> bodyHasReturnWithValue(stmt.tryBlock.statements, anyExpr) ||
                (stmt.catchClause?.let { bodyHasReturnWithValue(it.block.statements, anyExpr) } ?: false) ||
                (stmt.finallyBlock?.let { bodyHasReturnWithValue(it.statements, anyExpr) } ?: false)
            // Do NOT recurse into nested function expressions
            else -> false
        }
    }

    /**
     * Returns true if the body has any return-with-value statement OUTSIDE of try blocks.
     * Used to distinguish TS2366 (no value returns outside try) from TS7030 (mixed returns).
     * Returns inside try blocks don't count — TypeScript handles these as "protected paths."
     */
    private fun hasAnyReturnOutsideTry(stmts: List<Statement>): Boolean {
        for (stmt in stmts) {
            if (stmtHasReturnWithValueOutsideTry(stmt)) return true
        }
        return false
    }

    private fun stmtHasReturnWithValueOutsideTry(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> {
                val expr = stmt.expression ?: return false
                // anyExpr=true: any return with expression counts (we only call with retType!=null)
                true
            }
            is Block -> hasAnyReturnOutsideTry(stmt.statements)
            is IfStatement -> stmtHasReturnWithValueOutsideTry(stmt.thenStatement) ||
                (stmt.elseStatement?.let { stmtHasReturnWithValueOutsideTry(it) } ?: false)
            is WhileStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is ForStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is ForInStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is ForOfStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is DoStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is LabeledStatement -> stmtHasReturnWithValueOutsideTry(stmt.statement)
            is SwitchStatement -> stmt.caseBlock.any { clause ->
                when (clause) {
                    is CaseClause -> hasAnyReturnOutsideTry(clause.statements)
                    is DefaultClause -> hasAnyReturnOutsideTry(clause.statements)
                    else -> false
                }
            }
            // TryStatement: returns inside try/catch/finally are "protected" — don't count
            is TryStatement -> false
            else -> false
        }
    }

    /**
     * Computes the actual span length of a return type annotation starting at [start] in [source].
     * TypeNode.end includes the next scanned token (the `{` of the body), so we must scan forward
     * to find the actual end of the type text.
     * Tracks nesting depth so spaces inside `()`, `<>`, `[]` do not break the scan.
     */
    private fun getRetTypeSpanLength(source: String, start: Int): Int {
        if (start >= source.length) return 0
        var i = start
        var depth = 0
        while (i < source.length) {
            val ch = source[i]
            when {
                ch == '<' || ch == '[' || ch == '(' -> { depth++; i++ }
                ch == '>' || ch == ']' || ch == ')' || ch == '}' -> {
                    if (depth > 0) { depth--; i++ }
                    else break // unmatched close = end of type
                }
                ch == '{' -> {
                    if (i == start) { depth++; i++ } // TypeLiteral `{}` — enter it
                    else break // start of body block
                }
                ch == '\n' || ch == '\r' -> break
                depth > 0 -> i++ // inside delimiters: consume everything
                ch == ',' || ch == ';' -> break
                ch == '=' -> {
                    // `=>` is the arrow in a function type like `(A) => B` — consume it
                    if (source.getOrNull(i + 1) == '>') { i += 2 }
                    else break // plain `=` ends the type
                }
                ch == '>' -> i++ // part of `=>` arrow (consumed after `=`)
                ch == '|' || ch == '&' || ch == '.' -> i++
                ch.isLetterOrDigit() || ch == '_' || ch == '$' -> i++
                ch == ' ' || ch == '\t' -> {
                    // At depth 0: space is valid inside union/intersection ("number | string")
                    // or before `=>` in a function type
                    val next = source.getOrNull(i + 1)
                    if (next != null && (next == '|' || next == '&' || next == '[' || next == '=' || next.isLetter())) {
                        i++ // part of multi-word type or function type arrow
                    } else {
                        break
                    }
                }
                ch == '?' -> i++ // optional types
                else -> break
            }
        }
        return (i - start).coerceAtLeast(1)
    }

    /**
     * Returns true if the type name represents void, undefined, or any.
     */
    private fun isVoidLikeTypeName(name: String): Boolean {
        return name == "void" || name == "undefined" || name == "any" || name == "never" || name == "unknown"
    }

    /**
     * Extracts the textual name of a type node for basic void/undefined/any check.
     */
    private fun getTypeNodeName(node: TypeNode, isAsync: Boolean): String? {
        return when (node) {
            is TypeReference -> {
                val typeName = node.typeName
                val baseName = when (typeName) {
                    is Identifier -> typeName.text
                    is QualifiedName -> typeName.right.text
                    else -> null
                }
                // For async functions, Promise<void> and Promise<any> are void-like
                if (isAsync && baseName == "Promise" && node.typeArguments?.size == 1) {
                    val argName = getTypeNodeName(node.typeArguments[0], false)
                    return if (argName != null && isVoidLikeTypeName(argName)) argName else baseName
                }
                baseName
            }
            is KeywordTypeNode -> when (node.kind) {
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.UndefinedKeyword -> "undefined"
                // number, string, boolean, bigint, symbol, object, unknown, null
                // are all non-void types — return a non-null name so we report
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is UnionType -> {
                // Union type classification for TS2355/TS7030/TS2366:
                // - Contains void/any/never → truly void-like, suppress all checks ("void")
                // - Contains undefined (but not void) → nullable union, suppress TS2355/TS2366
                //   but NOT TS7030 (e.g. `string | undefined`) → return "undefined"
                // - No void/any/never/undefined → non-nullable union, may trigger TS7030 → return "union"
                val memberNames = node.types.mapNotNull { getTypeNodeName(it, false) }
                when {
                    memberNames.any { it == "void" || it == "any" || it == "never" } -> "void"
                    memberNames.any { it == "undefined" } -> "undefined"
                    memberNames.isEmpty() -> null
                    else -> "union" // non-nullable union (e.g. `string | number`)
                }
            }
            is FunctionType -> "function-type"  // definitively non-void (a function type is always an object)
            else -> null
        }
    }

    /**
     * Returns true if a list of statements always returns/throws on all paths.
     * Used for TS7030 checking.
     */
    private fun bodyAlwaysReturns(stmts: List<Statement>): Boolean {
        // If no statements, doesn't always return
        if (stmts.isEmpty()) return false
        // Walk through statements — find if some statement definitely terminates
        for (stmt in stmts) {
            if (statementAlwaysReturns(stmt)) return true
        }
        return false
    }

    /**
     * Returns true if this statement always returns/throws on all code paths.
     */
    private fun statementAlwaysReturns(stmt: Statement): Boolean {
        return when (stmt) {
            is ReturnStatement -> true
            is ThrowStatement -> true
            is BreakStatement -> false  // break transfers control out of loop/switch, not "returns"
            is ContinueStatement -> false
            is Block -> bodyAlwaysReturns(stmt.statements)
            is IfStatement -> {
                val thenRet = statementAlwaysReturns(stmt.thenStatement)
                val elseBranch = stmt.elseStatement
                thenRet && elseBranch != null && statementAlwaysReturns(elseBranch)
            }
            is WhileStatement -> {
                // while(true) with no break always terminates (infinite loop or always throws/returns)
                isAlwaysTrue(stmt.expression) && !containsBreakOrReturn(stmt.statement)
            }
            is ForStatement -> {
                // for(;;) with no break always terminates
                stmt.condition == null && !containsBreakOrReturn(stmt.statement)
            }
            is DoStatement -> {
                // do {} while (false) - body must always return
                statementAlwaysReturns(stmt.statement) ||
                    (isAlwaysTrue(stmt.expression) && !containsBreakOrReturn(stmt.statement))
            }
            is SwitchStatement -> {
                // Switch always returns if it has a default clause and all clauses return
                val hasDefault = stmt.caseBlock.any { it is DefaultClause }
                if (!hasDefault) return false
                // Check that every clause either falls through to one that returns or returns itself
                switchAlwaysReturns(stmt.caseBlock)
            }
            is LabeledStatement -> statementAlwaysReturns(stmt.statement)
            is TryStatement -> {
                // try/catch: if both try and catch return, the whole statement returns
                val tryRet = bodyAlwaysReturns(stmt.tryBlock.statements)
                val catchRet = stmt.catchClause?.let { bodyAlwaysReturns(it.block.statements) } ?: true
                tryRet && catchRet
            }
            is ExpressionStatement -> {
                // IIFE or function call that always throws — check for iife pattern
                when (val expr = stmt.expression) {
                    is CallExpression -> {
                        val func = expr.expression
                        when (func) {
                            is FunctionExpression -> {
                                func.body?.let { bodyAlwaysReturns(it.statements) } ?: false
                            }
                            is ArrowFunction -> {
                                val body = func.body
                                when (body) {
                                    is Block -> bodyAlwaysReturns(body.statements)
                                    is ThrowStatement -> true
                                    else -> false
                                }
                            }
                            else -> false
                        }
                    }
                    else -> false
                }
            }
            else -> false
        }
    }

    private fun switchAlwaysReturns(clauses: List<Node>): Boolean {
        // Each clause either terminates or falls through to a clause that terminates
        // Simple: check that there's a path through all clauses that always returns
        val clauseTerminates = clauses.map { clause ->
            when (clause) {
                is CaseClause -> bodyAlwaysReturns(clause.statements)
                is DefaultClause -> bodyAlwaysReturns(clause.statements)
                else -> false
            }
        }
        // Find the last clause — it must terminate (or the one before that falls through to it)
        // Actually: switches always return if every "fall-through chain" ends in a return
        // Simple heuristic: if every non-empty clause terminates, it always returns
        return clauses.all { clause ->
            val stmts = when (clause) {
                is CaseClause -> clause.statements
                is DefaultClause -> clause.statements
                else -> emptyList()
            }
            stmts.isEmpty() || bodyAlwaysReturns(stmts)
        }
    }

    private fun containsBreakOrReturn(stmt: Statement): Boolean {
        return when (stmt) {
            is BreakStatement -> true
            is ReturnStatement -> true
            is Block -> stmt.statements.any { containsBreakOrReturn(it) }
            is IfStatement -> containsBreakOrReturn(stmt.thenStatement) ||
                (stmt.elseStatement?.let { containsBreakOrReturn(it) } ?: false)
            is LabeledStatement -> containsBreakOrReturn(stmt.statement)
            // Don't recurse into nested loops — breaks in them don't affect outer
            else -> false
        }
    }

    // -----------------------------------------------------------------------
    // TS1156 — block-scoped declarations outside blocks
    // -----------------------------------------------------------------------

    /**
     * TS1156: `const`/`let`/`type`/`interface` declarations can only be
     * declared inside a block. Fires when they appear as the single-statement
     * body of `if`/`else`/`while`/`do`/`for`/`for-in`/`for-of`.
     */
    private fun checkBlockScopedDeclarationsInSingleBody() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            walkForBlockScopeViolations(result.sourceFile.statements, source, fileName)
        }
    }

    private fun walkForBlockScopeViolations(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            walkBlockScopeInStatement(stmt, source, fileName)
        }
    }

    private fun walkBlockScopeInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is IfStatement -> {
                checkEmbeddedForBlockScope(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkEmbeddedForBlockScope(it, source, fileName) }
                // Also recurse into blocks
                if (stmt.thenStatement is Block) walkForBlockScopeViolations((stmt.thenStatement as Block).statements, source, fileName)
                stmt.elseStatement?.let { if (it is Block) walkForBlockScopeViolations((it as Block).statements, source, fileName) }
                // Recurse into non-block embedded (which may be labeled etc.)
                if (stmt.thenStatement !is Block) walkBlockScopeInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { if (it !is Block) walkBlockScopeInStatement(it, source, fileName) }
            }
            is WhileStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is ForStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkEmbeddedForBlockScope(stmt.statement, source, fileName)
                if (stmt.statement is Block) walkForBlockScopeViolations((stmt.statement as Block).statements, source, fileName)
                else walkBlockScopeInStatement(stmt.statement, source, fileName)
            }
            is Block -> walkForBlockScopeViolations(stmt.statements, source, fileName)
            is LabeledStatement -> walkBlockScopeInStatement(stmt.statement, source, fileName)
            is FunctionDeclaration -> stmt.body?.let { walkForBlockScopeViolations(it.statements, source, fileName) }
            is ClassDeclaration -> for (m in stmt.members) {
                val body = when (m) {
                    is MethodDeclaration -> m.body
                    is Constructor -> m.body
                    is GetAccessor -> m.body
                    is SetAccessor -> m.body
                    else -> null
                }
                body?.let { walkForBlockScopeViolations(it.statements, source, fileName) }
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) walkForBlockScopeViolations(body.statements, source, fileName)
            }
            is TryStatement -> {
                walkForBlockScopeViolations(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { walkForBlockScopeViolations(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { walkForBlockScopeViolations(it.statements, source, fileName) }
            }
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    val stmts2 = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    walkForBlockScopeViolations(stmts2, source, fileName)
                }
            }
            else -> {}
        }
    }

    /**
     * Check if [embedded] is a block-scoped declaration (const/let/type/interface)
     * that's the direct single-statement body of a control flow statement.
     */
    private fun checkEmbeddedForBlockScope(embedded: Statement, source: String, fileName: String) {
        if (embedded is Block) return  // Block is fine
        // Strip through LabeledStatement layers to find the actual declaration
        var stmt: Statement = embedded
        while (stmt is LabeledStatement) stmt = stmt.statement
        when (stmt) {
            is VariableStatement -> {
                val keyword = stmt.declarationList.flags
                val kwName = when (keyword) {
                    SyntaxKind.ConstKeyword -> "const"
                    SyntaxKind.LetKeyword -> "let"
                    else -> return  // var is allowed
                }
                reportBlockScopeViolation(stmt, stmt.pos, source, fileName, kwName, useFullStmtSpan = true)
            }
            is TypeAliasDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val nameStart = stmt.name.pos
                val nameLen = stmt.name.text.length
                reportBlockScopeViolationAt(nameStart, nameLen, source, fileName, "type")
            }
            is InterfaceDeclaration -> {
                if (ModifierFlag.Declare in stmt.modifiers) return
                val nameStart = stmt.name.pos
                val nameLen = stmt.name.text.length
                reportBlockScopeViolationAt(nameStart, nameLen, source, fileName, "interface")
            }
            else -> {}
        }
    }

    private fun reportBlockScopeViolation(
        stmt: Statement, stmtPos: Int, source: String, fileName: String,
        kwName: String, useFullStmtSpan: Boolean
    ) {
        // start = position of keyword (const/let)
        var start = stmtPos
        while (start < source.length && source[start].let { it == ' ' || it == '\t' || it == '\n' || it == '\r' }) start++
        val length = if (useFullStmtSpan) {
            // Span = entire statement text on the same line (up to `;`)
            // Find the `;` position
            var end = start
            while (end < source.length && source[end] != '\n' && source[end] != '\r') end++
            // Trim trailing whitespace
            while (end > start && source[end - 1].let { it == ' ' || it == '\t' || it == '\r' }) end--
            end - start
        } else {
            kwName.length
        }
        reportBlockScopeViolationAt(start, length, source, fileName, kwName)
    }

    private fun reportBlockScopeViolationAt(start: Int, length: Int, source: String, fileName: String, kwName: String) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "'$kwName' declarations can only be declared inside a block.",
            category = DiagnosticCategory.Error,
            code = 1156,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
        ))
    }

    // -----------------------------------------------------------------------
    // Type assignability checking (TS2322)
    // -----------------------------------------------------------------------

    /**
     * Determine if the Type engine can safely compare source and target types.
     * Returns true when both types are concrete (non-any, non-error) and the
     * comparison won't produce false positives from incomplete resolution.
     */
    private fun canUseTypeEngine(sourceType: Type, targetType: Type): Boolean {
        // Never compare when either side is unresolved
        if (sourceType === anyType || sourceType === errorType) return false
        if (targetType === anyType || targetType === errorType) return false
        val sourceIsIntrinsic = sourceType is Type.Intrinsic
        val targetIsIntrinsic = targetType is Type.Intrinsic
        // null/undefined → intrinsic target (strictNullChecks handles assignability)
        val sourceIsNullish = sourceType.flags.hasAny(TypeFlags.Null or TypeFlags.Undefined)
        if (sourceIsNullish && targetIsIntrinsic) return true
        // null/undefined → named type or function type
        if (sourceIsNullish && targetType is Type.Interface) return true
        if (sourceIsNullish && targetType is Type.Reference) return true
        // null/undefined → function/constructor type (Type.Object with signatures)
        if (sourceIsNullish && targetType is Type.Object &&
            (!targetType.callSignatures.isNullOrEmpty() || !targetType.constructSignatures.isNullOrEmpty())) return true
        // null/undefined → type literal / anonymous object with properties
        if (sourceIsNullish && targetType is Type.Object && !targetType.properties.isNullOrEmpty()) return true
        // null/undefined → union type (relation engine checks each constituent)
        if (sourceIsNullish && targetType is Type.Union) return true
        // intrinsic↔intrinsic (number→string, etc.)
        if (sourceIsIntrinsic && targetIsIntrinsic) return true
        // Object type → intrinsic target (object/interface/class/array is never assignable to primitive)
        if (sourceType is Type.Object && targetIsIntrinsic) return true
        // Function→function: both sides have call signatures — safe because anyType in
        // unresolved return/param types is handled by isSimpleTypeRelatedTo (any→anything)
        if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty() &&
            targetType is Type.Object && !targetType.callSignatures.isNullOrEmpty()) return true
        return false
    }

    private fun checkTypeAssignability() {
        val diagnosticsBefore = diagnostics.size
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            val varTypes = mutableMapOf<String, String>()
            currentLocalTypes = mutableMapOf()
            checkTypeAssignabilityInStatements(result.sourceFile.statements, source, fileName, varTypes, returnType = null, typeParams = emptySet())
        }
        // Post-filter: suppress TS2322 for null/undefined→NamedType when the named type
        // also has TS2304 (unresolved) or TS2314 (wrong type arg count) in the same file
        // Collect type names with errors per file: "$fileName" -> set of type names
        val errorTypeNames = mutableMapOf<String, MutableSet<String>>()
        for (d in diagnostics) {
            val fn = d.fileName ?: continue
            val msg = d.message ?: continue
            when (d.code) {
                2304 -> {
                    // "Cannot find name 'X'." → extract X
                    val match = Regex("Cannot find name '([^']+)'").find(msg)
                    match?.groupValues?.get(1)?.let { errorTypeNames.getOrPut(fn) { mutableSetOf() }.add(it) }
                }
                2314 -> {
                    // "Generic type 'X<T>' requires N type argument(s)." → extract X
                    val match = Regex("Generic type '([^<']+)").find(msg)
                    match?.groupValues?.get(1)?.let { errorTypeNames.getOrPut(fn) { mutableSetOf() }.add(it) }
                }
            }
        }
        if (errorTypeNames.isNotEmpty()) {
            val newDiags = diagnostics.filterIndexed { idx, d ->
                if (idx >= diagnosticsBefore && d.code == 2322) {
                    val fn = d.fileName
                    val msg = d.message ?: ""
                    // Extract target type name from "Type 'X' is not assignable to type 'Y'."
                    val targetMatch = Regex("not assignable to type '([^']+)'").find(msg)
                    val targetName = targetMatch?.groupValues?.get(1)
                    if (fn != null && targetName != null) {
                        val errorNames = errorTypeNames[fn]
                        // Also check base name (strip type args): "Two<number>" → "Two"
                        val baseName = targetName.substringBefore('<')
                        errorNames == null || (targetName !in errorNames && baseName !in errorNames)
                    } else true
                } else true
            }
            if (newDiags.size != diagnostics.size) {
                diagnostics.clear()
                diagnostics.addAll(newDiags)
            }
        }
        // Post-filter: suppress TS7030 at positions where TS2322 fires (bare return → undefined)
        val ts2322Positions = mutableSetOf<String>()
        for (d in diagnostics) {
            if (d.code == 2322) {
                ts2322Positions.add("${d.fileName}:${d.start}")
            }
        }
        if (ts2322Positions.isNotEmpty()) {
            val filtered = diagnostics.filter { d ->
                !(d.code == 7030 && "${d.fileName}:${d.start}" in ts2322Positions)
            }
            if (filtered.size != diagnostics.size) {
                diagnostics.clear()
                diagnostics.addAll(filtered)
            }
        }
    }

    private fun checkTypeAssignabilityInStatements(
        statements: List<Statement>, source: String, fileName: String,
        varTypes: MutableMap<String, String>, returnType: String?,
        typeParams: Set<String>,
        returnTypeNode: TypeNode? = null,
    ) {
        for (stmt in statements) {
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        checkVarDeclAssignability(decl, source, fileName, varTypes, typeParams)
                    }
                }
                is ExpressionStatement -> {
                    checkAssignmentExpression(stmt.expression, source, fileName, varTypes, typeParams)
                }
                is ReturnStatement -> {
                    if (returnType != null || returnTypeNode != null) {
                        checkReturnAssignability(stmt, returnType ?: "", source, fileName, varTypes, typeParams, returnTypeNode)
                    }
                }
                is FunctionDeclaration -> {
                    checkFunctionBody(stmt.body, stmt.type, stmt.parameters, stmt.typeParameters, source, fileName, varTypes)
                }
                is Block -> checkTypeAssignabilityInStatements(stmt.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams, returnTypeNode)
                is IfStatement -> {
                    checkTypeAssignabilityInStmt(stmt.thenStatement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                    stmt.elseStatement?.let { checkTypeAssignabilityInStmt(it, source, fileName, varTypes, returnType, typeParams, returnTypeNode) }
                }
                is ForStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is ForInStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is ForOfStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is WhileStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is DoStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                is ClassDeclaration -> {
                    val classTypeParams = collectTypeParamNames(stmt.typeParameters)
                    for (member in stmt.members) {
                        when (member) {
                            is MethodDeclaration -> {
                                checkFunctionBody(member.body, member.type, member.parameters, member.typeParameters, source, fileName, varTypes, classTypeParams)
                            }
                            is Constructor -> member.body?.let { body ->
                                val ctorTypes = varTypes.toMutableMap()
                                val savedLocalTypes = currentLocalTypes
                                currentLocalTypes = currentLocalTypes.toMutableMap()
                                // Populate this.prop types from class property declarations
                                for (m in stmt.members) {
                                    if (m is PropertyDeclaration) {
                                        val propType = m.type?.let { resolveSimpleTypeName(it) }
                                        val propName = (m.name as? Identifier)?.text
                                        if (propType != null && propName != null) {
                                            ctorTypes["this.$propName"] = propType
                                        }
                                        // Also populate Type engine local type map for this.prop
                                        if (propName != null && m.type != null) {
                                            try {
                                                val resolvedType = getTypeFromTypeNode(m.type!!)
                                                if (resolvedType !== anyType && resolvedType !== errorType) {
                                                    currentLocalTypes["this.$propName"] = resolvedType
                                                }
                                            } catch (_: StackOverflowError) {}
                                        }
                                    }
                                }
                                // Also add constructor parameter types
                                for (p in member.parameters) {
                                    val pName = (p.name as? Identifier)?.text
                                    val pType = p.type?.let { resolveSimpleTypeName(it) }
                                    if (pName != null && pType != null) ctorTypes[pName] = pType
                                    // Also populate Type engine local type map
                                    if (pName != null && p.type != null) {
                                        try {
                                            val resolvedType = getTypeFromTypeNode(p.type!!)
                                            if (resolvedType !== anyType && resolvedType !== errorType) {
                                                currentLocalTypes[pName] = resolvedType
                                            }
                                        } catch (_: StackOverflowError) {}
                                    }
                                }
                                checkTypeAssignabilityInStatements(body.statements, source, fileName, ctorTypes, returnType = null, classTypeParams)
                                currentLocalTypes = savedLocalTypes
                            }
                            is GetAccessor -> {
                                checkFunctionBody(member.body, member.type, emptyList(), null, source, fileName, varTypes, classTypeParams)
                            }
                            is PropertyDeclaration -> {
                                val init = member.initializer
                                val typeAnnotation = member.type
                                if (init != null && typeAnnotation != null) {
                                    val propName = member.name
                                    if (propName is Identifier) {
                                        checkPropertyInitAssignability(propName, typeAnnotation, init, source, fileName, classTypeParams)
                                    }
                                }
                            }
                            else -> {}
                        }
                    }
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) checkTypeAssignabilityInStatements(body.statements, source, fileName, varTypes.toMutableMap(), returnType = null, emptySet())
                }
                is TryStatement -> {
                    checkTypeAssignabilityInStatements(stmt.tryBlock.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                    stmt.catchClause?.block?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
                    stmt.finallyBlock?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
                }
                is SwitchStatement -> {
                    for (clause in stmt.caseBlock) {
                        when (clause) {
                            is CaseClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                            is DefaultClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                            else -> {}
                        }
                    }
                }
                is LabeledStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
                else -> {}
            }
        }
    }

    private fun collectTypeParamNames(typeParameters: List<TypeParameter>?): Set<String> {
        if (typeParameters == null || typeParameters.isEmpty()) return emptySet()
        return typeParameters.mapNotNull { it.name.text }.toSet()
    }

    private fun checkFunctionBody(
        body: Block?, returnTypeNode: TypeNode?, parameters: List<Parameter>,
        funcTypeParams: List<TypeParameter>?,
        source: String, fileName: String, varTypes: MutableMap<String, String>,
        outerTypeParams: Set<String> = emptySet()
    ) {
        body?.let {
            val innerTypes = varTypes.toMutableMap()
            // Save outer local types and create inner scope copy
            val savedLocalTypes = currentLocalTypes
            currentLocalTypes = currentLocalTypes.toMutableMap()
            for (param in parameters) {
                val paramType = param.type
                val paramName = param.name
                if (paramType != null && paramName is Identifier) {
                    val t = resolveSimpleTypeName(paramType)
                    if (t != null) innerTypes[paramName.text] = t
                    // Also populate Type engine local type map
                    try {
                        val resolvedType = getTypeFromTypeNode(paramType)
                        if (resolvedType !== anyType && resolvedType !== errorType) {
                            currentLocalTypes[paramName.text] = resolvedType
                        }
                    } catch (_: StackOverflowError) { /* circular type */ }
                }
            }
            val retType = if (returnTypeNode != null) resolveSimpleTypeName(returnTypeNode) else null
            val allTypeParams = outerTypeParams + collectTypeParamNames(funcTypeParams)
            checkTypeAssignabilityInStatements(it.statements, source, fileName, innerTypes, retType, allTypeParams, returnTypeNode)
            // Restore outer local types
            currentLocalTypes = savedLocalTypes
        }
    }

    private fun checkTypeAssignabilityInStmt(
        stmt: Statement, source: String, fileName: String,
        varTypes: MutableMap<String, String>, returnType: String?,
        typeParams: Set<String>,
        returnTypeNode: TypeNode? = null,
    ) {
        when (stmt) {
            is Block -> checkTypeAssignabilityInStatements(stmt.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams, returnTypeNode)
            is ExpressionStatement -> checkAssignmentExpression(stmt.expression, source, fileName, varTypes, typeParams)
            is ReturnStatement -> {
                if (returnType != null || returnTypeNode != null) checkReturnAssignability(stmt, returnType ?: "", source, fileName, varTypes, typeParams, returnTypeNode)
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    checkVarDeclAssignability(decl, source, fileName, varTypes, typeParams)
                }
            }
            is IfStatement -> {
                checkTypeAssignabilityInStmt(stmt.thenStatement, source, fileName, varTypes, returnType, typeParams)
                stmt.elseStatement?.let { checkTypeAssignabilityInStmt(it, source, fileName, varTypes, returnType, typeParams) }
            }
            is ForStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is ForInStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is ForOfStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is WhileStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is DoStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            is SwitchStatement -> {
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                        is DefaultClause -> checkTypeAssignabilityInStatements(clause.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkTypeAssignabilityInStatements(stmt.tryBlock.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams)
                stmt.catchClause?.block?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
                stmt.finallyBlock?.let { checkTypeAssignabilityInStatements(it.statements, source, fileName, varTypes.toMutableMap(), returnType, typeParams) }
            }
            is LabeledStatement -> checkTypeAssignabilityInStmt(stmt.statement, source, fileName, varTypes, returnType, typeParams, returnTypeNode)
            else -> {}
        }
    }

    private fun checkVarDeclAssignability(
        decl: VariableDeclaration, source: String, fileName: String,
        varTypes: MutableMap<String, String>, typeParams: Set<String>
    ) {
        val typeAnnotation = decl.type ?: return
        val name = decl.name
        if (name !is Identifier) return

        // Maintain old varTypes tracking for checkAssignmentExpression/checkReturnAssignability
        val declaredTypeStr = resolveSimpleTypeName(typeAnnotation)
        if (declaredTypeStr != null) varTypes[name.text] = declaredTypeStr

        // Populate local type map for Type engine identifier resolution
        try {
            val resolvedVarType = getTypeFromTypeNode(typeAnnotation)
            if (resolvedVarType !== anyType && resolvedVarType !== errorType) {
                currentLocalTypes[name.text] = resolvedVarType
            }
        } catch (_: StackOverflowError) { /* circular type */ }

        val init = decl.initializer ?: return

        // Use the Type-based engine (Phase 4) for clear-cut cases
        try {
            val targetType = getTypeFromTypeNode(typeAnnotation)
            val sourceType = getTypeOfExpression(init)
            if (canUseTypeEngine(sourceType, targetType) && !checkTypeRelatedTo(sourceType, targetType, assignableRelation)) {
                val displaySource = typeToString(sourceType)
                // Use annotation text for display (handles generics correctly)
                val displayTarget = formatTypeForDisplay(typeAnnotation) ?: typeToString(targetType)
                val (line, character) = getLineAndCharacterOfPosition(source, name.pos)
                val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                val chain = mutableListOf<String>()
                // Function→function: add specific elaboration (return/param mismatch)
                if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty() &&
                    targetType is Type.Object && !targetType.callSignatures.isNullOrEmpty()) {
                    chain.addAll(getFunctionMismatchElaboration(sourceType, targetType))
                } else {
                    // Add elaboration chain for non-trivial expressions (not literals, not calls)
                    val needsElaboration = !isSimpleLiteral(init) &&
                        init !is CallExpression && init !is NewExpression &&
                        init !is DeleteExpression && init !is AwaitExpression &&
                        init !is BinaryExpression && init !is ParenthesizedExpression
                    if (needsElaboration) chain.add("  $message")
                    if (targetType is Type.TypeParam) {
                        val targetName = targetType.symbol?.name ?: "T"
                        chain.add("  '$targetName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                    } else if (typeParams.isNotEmpty()) {
                        val targetBaseName = displayTarget.substringBefore('<')
                        if (targetBaseName in typeParams) {
                            chain.add("  '$targetBaseName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                        }
                    }
                }
                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error,
                    code = 2322,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = name.pos,
                    length = name.text.length,
                    messageChain = chain,
                ))
                return // Type engine handled it — skip old system
            }
        } catch (_: StackOverflowError) {
            // Circular type resolution — fall through to old system
        }

        // Fallback to old string-based system for remaining cases
        if (declaredTypeStr != null) {
            val exprType = inferSimpleExprType(init, varTypes)
            if (exprType != null && !isAssignableTo(exprType, declaredTypeStr)) {
                emitTS2322(name.pos, name.text.length, exprType, declaredTypeStr, source, fileName, hasElaboration = !isSimpleLiteral(init), typeParams = typeParams)
            }
        }
    }

    /** Check property initializer assignability (class member: `x: Type = value`). */
    private fun checkPropertyInitAssignability(
        propName: Identifier, typeAnnotation: TypeNode, init: Expression,
        source: String, fileName: String, typeParams: Set<String>
    ) {
        try {
            val targetType = getTypeFromTypeNode(typeAnnotation)
            val sourceType = getTypeOfExpression(init)
            if (canUseTypeEngine(sourceType, targetType) && !checkTypeRelatedTo(sourceType, targetType, assignableRelation)) {
                val displaySource = typeToString(sourceType)
                val displayTarget = formatTypeForDisplay(typeAnnotation) ?: typeToString(targetType)
                val (line, character) = getLineAndCharacterOfPosition(source, propName.pos)
                val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                val chain = mutableListOf<String>()
                if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty() &&
                    targetType is Type.Object && !targetType.callSignatures.isNullOrEmpty()) {
                    chain.addAll(getFunctionMismatchElaboration(sourceType, targetType))
                } else {
                    val needsElaboration = !isSimpleLiteral(init) &&
                        init !is CallExpression && init !is NewExpression &&
                        init !is DeleteExpression && init !is AwaitExpression &&
                        init !is BinaryExpression && init !is ParenthesizedExpression
                    if (needsElaboration) chain.add("  $message")
                }
                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error,
                    code = 2322,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = propName.pos,
                    length = propName.text.length,
                    messageChain = chain,
                ))
            }
        } catch (_: StackOverflowError) {
            // Circular type resolution — skip
        }
    }

    private fun checkReturnAssignability(
        stmt: ReturnStatement, returnType: String, source: String, fileName: String,
        varTypes: Map<String, String>, typeParams: Set<String>,
        returnTypeNode: TypeNode? = null,
    ) {
        val expr = stmt.expression

        // Try new Type-based engine when returnTypeNode is available
        if (returnTypeNode != null) {
            try {
                val targetType = getTypeFromTypeNode(returnTypeNode)
                val sourceType = if (expr != null) getTypeOfExpression(expr) else undefinedType
                if (canUseTypeEngine(sourceType, targetType) && !checkTypeRelatedTo(sourceType, targetType, assignableRelation)) {
                    val displaySource = typeToString(sourceType)
                    val displayTarget = formatTypeForDisplay(returnTypeNode) ?: typeToString(targetType)
                    val returnKeywordLength = 6
                    val (line, character) = getLineAndCharacterOfPosition(source, stmt.pos)
                    val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                    diagnostics.add(Diagnostic(
                        message = message,
                        category = DiagnosticCategory.Error,
                        code = 2322,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = stmt.pos,
                        length = returnKeywordLength,
                    ))
                    return
                }
            } catch (_: StackOverflowError) {
                // Fall through to old system
            }
        }

        // Fallback to old string-based system (skip when returnType is empty — means only returnTypeNode was available)
        if (returnType.isEmpty()) return
        val exprType = if (expr != null) {
            inferSimpleExprType(expr, varTypes)
                // For return statements: also check varTypes for identifier expressions
                // (safe here because return type is always a declared type, not a complex union)
                ?: (expr as? Identifier)?.let { varTypes[it.text] }
                ?: return
        } else {
            "undefined"
        }
        if (!isAssignableTo(exprType, returnType)) {
            val returnKeywordLength = 6
            val isLiteral = expr == null || isSimpleLiteral(expr)
            emitTS2322(stmt.pos, returnKeywordLength, exprType, returnType, source, fileName, hasElaboration = !isLiteral, typeParams = typeParams)
        }
    }

    private fun checkAssignmentExpression(expr: Expression, source: String, fileName: String, varTypes: MutableMap<String, String>, typeParams: Set<String>) {
        if (expr is BinaryExpression && expr.operator == SyntaxKind.Equals) {
            // Recurse into chained assignments first: a = b = c = null
            // Each assignment in the chain gets checked independently
            if (expr.right is BinaryExpression) {
                checkAssignmentExpression(expr.right, source, fileName, varTypes, typeParams)
            }
            val target = expr.left
            if (target is Identifier) {
                // Try new Type-based engine for file-level and local variables
                try {
                    var targetType: Type? = null
                    var typeAnnotation: TypeNode? = null
                    val symbol = globals[target.text]
                    if (symbol != null) {
                        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull()
                        typeAnnotation = (decl as? VariableDeclaration)?.type
                            ?: (decl as? Parameter)?.type
                            ?: (decl as? PropertyDeclaration)?.type
                        if (typeAnnotation != null) {
                            targetType = getTypeFromTypeNode(typeAnnotation)
                        }
                    }
                    // Also check local type scope for function-local variables
                    if (targetType == null || targetType === anyType || targetType === errorType) {
                        currentLocalTypes[target.text]?.let { localType ->
                            if (localType !== anyType && localType !== errorType) {
                                targetType = localType
                            }
                        }
                    }
                    if (targetType != null && targetType !== anyType && targetType !== errorType) {
                        val tt = targetType!!
                        val sourceType = getTypeOfExpression(expr.right)
                        if (canUseTypeEngine(sourceType, tt) && !checkTypeRelatedTo(sourceType, tt, assignableRelation)) {
                            val displaySource = typeToString(sourceType)
                            val displayTarget = if (typeAnnotation != null) formatTypeForDisplay(typeAnnotation!!) ?: typeToString(tt) else typeToString(tt)
                            val (line, character) = getLineAndCharacterOfPosition(source, target.pos)
                            val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
                            val chain = mutableListOf<String>()
                            // Function→function: add specific elaboration
                            if (sourceType is Type.Object && !sourceType.callSignatures.isNullOrEmpty() &&
                                tt is Type.Object && !tt.callSignatures.isNullOrEmpty()) {
                                chain.addAll(getFunctionMismatchElaboration(sourceType, tt))
                            } else {
                                val needsElaboration = !isSimpleLiteral(expr.right) &&
                                    expr.right !is CallExpression && expr.right !is NewExpression &&
                                    expr.right !is DeleteExpression && expr.right !is AwaitExpression &&
                                    expr.right !is BinaryExpression && expr.right !is ParenthesizedExpression
                                if (needsElaboration) chain.add("  $message")
                                if (tt is Type.TypeParam) {
                                    val targetName = tt.symbol?.name ?: "T"
                                    chain.add("  '$targetName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                                } else if (typeParams.isNotEmpty()) {
                                    val targetBaseName = displayTarget.substringBefore('<')
                                    if (targetBaseName in typeParams) {
                                        chain.add("  '$targetBaseName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
                                    }
                                }
                            }
                            diagnostics.add(Diagnostic(
                                message = message,
                                category = DiagnosticCategory.Error,
                                code = 2322,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = target.pos,
                                length = target.text.length,
                                messageChain = chain,
                            ))
                            return // Type engine handled it — skip old system
                        }
                    }
                } catch (_: StackOverflowError) {
                    // Circular type resolution — fall through to old system
                }

                // Fallback to old string-based system
                val declaredType = varTypes[target.text]
                if (declaredType != null) {
                    val exprType = inferSimpleExprType(expr.right, varTypes)
                    if (exprType != null && !isAssignableTo(exprType, declaredType)) {
                        emitTS2322(target.pos, target.text.length, exprType, declaredType, source, fileName, hasElaboration = !isSimpleLiteral(expr.right), typeParams = typeParams)
                    }
                }
            } else if (target is PropertyAccessExpression && (target.expression as? Identifier)?.text == "this") {
                // this.prop = value — look up class property type from varTypes
                val propName = target.name.text
                val declaredType = varTypes["this.$propName"]
                if (declaredType != null) {
                    val exprType = inferSimpleExprType(expr.right, varTypes)
                    if (exprType != null && !isAssignableTo(exprType, declaredType)) {
                        // Squiggle spans "this.prop" (the entire PropertyAccessExpression)
                        val squiggleStart = target.expression.pos
                        val squiggleLength = target.name.pos + target.name.text.length - squiggleStart
                        emitTS2322(squiggleStart, squiggleLength, exprType, declaredType, source, fileName, hasElaboration = !isSimpleLiteral(expr.right), typeParams = typeParams)
                    }
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Type resolution from TypeNodes (Phase 4 — semantic Type objects)
    // -----------------------------------------------------------------------

    /**
     * Convert an AST TypeNode into a semantic [Type] object.
     * Results are cached in [nodeTypes].
     */
    private fun getTypeFromTypeNode(node: TypeNode): Type {
        nodeTypes[node]?.let { return it }
        val type = getTypeFromTypeNodeWorker(node)
        nodeTypes[node] = type
        return type
    }

    private fun getTypeFromTypeNodeWorker(node: TypeNode): Type {
        return when (node) {
            is KeywordTypeNode -> getTypeFromKeyword(node.kind)
            is TypeReference -> getTypeFromTypeReference(node)
            is UnionType -> getUnionType(node.types.map { getTypeFromTypeNode(it) })
            is IntersectionType -> getIntersectionType(node.types.map { getTypeFromTypeNode(it) })
            is ArrayType -> getArrayType(getTypeFromTypeNode(node.elementType))
            is TupleType -> getTupleType(node)
            is LiteralType -> getTypeFromLiteralTypeNode(node)
            is FunctionType -> getFunctionTypeFromNode(node)
            is ConstructorType -> getFunctionTypeFromConstructorNode(node)
            is TypeQuery -> anyType // TODO: getTypeOfSymbol for typeof expressions
            is ParenthesizedType -> getTypeFromTypeNode(node.type)
            is ThisType -> anyType // TODO: proper this-type resolution
            is TypePredicate -> booleanType
            is TypeLiteral -> getTypeFromTypeLiteral(node)
            is TypeOperator -> getTypeFromTypeOperator(node)
            is IndexedAccessType -> anyType // TODO: indexed access types
            is ConditionalType -> anyType // TODO: conditional types
            is MappedType -> anyType // TODO: mapped types
            is TemplateLiteralType -> stringType // template literal types are string-like
            is InferType -> anyType // only valid inside conditional types
            is RestType -> getTypeFromTypeNode(node.type) // unwrap rest
            is NamedTupleMember -> getTypeFromTypeNode(node.type) // unwrap named tuple member
            is OptionalType -> getTypeFromTypeNode(node.type) // unwrap optional (adds undefined)
            is ImportType -> anyType // TODO: import types
            is TemplateLiteralTypeSpan -> anyType // shouldn't be visited directly
        }
    }

    /** Map keyword SyntaxKind to intrinsic type singleton. */
    private fun getTypeFromKeyword(kind: SyntaxKind): Type {
        return when (kind) {
            SyntaxKind.NumberKeyword -> numberType
            SyntaxKind.StringKeyword -> stringType
            SyntaxKind.BooleanKeyword -> booleanType
            SyntaxKind.VoidKeyword -> voidType
            SyntaxKind.AnyKeyword -> anyType
            SyntaxKind.UnknownKeyword -> unknownType
            SyntaxKind.NeverKeyword -> neverType
            SyntaxKind.ObjectKeyword -> nonPrimitiveType
            SyntaxKind.SymbolKeyword -> esSymbolType
            SyntaxKind.BigIntKeyword -> bigintType
            SyntaxKind.UndefinedKeyword -> undefinedType
            SyntaxKind.NullKeyword -> nullType
            SyntaxKind.TrueKeyword -> trueType
            SyntaxKind.FalseKeyword -> falseType
            else -> errorType
        }
    }

    /** Resolve a TypeReference node (e.g., `Foo`, `Array<string>`, `A.B`) to a Type. */
    private fun getTypeFromTypeReference(node: TypeReference): Type {
        val name = getTypeReferenceLastName(node.typeName) ?: return errorType
        // Check for built-in generic types
        when (name) {
            "Array", "ReadonlyArray" -> {
                val typeArgs = node.typeArguments
                if (typeArgs != null && typeArgs.size == 1) {
                    return getArrayType(getTypeFromTypeNode(typeArgs[0]))
                }
            }
            "Promise" -> {
                // Promise<T> is an object type — for now just return anyType for generics
                // TODO: proper generic type resolution
            }
        }
        // Look up the symbol in globals
        val symbol = globals[name]
        if (symbol != null) {
            return getDeclaredTypeOfSymbol(symbol)
        }
        // Not found — return errorType (TS2304 handles the diagnostic separately)
        return errorType
    }

    /** Get the declared type of a symbol (class, interface, enum, type alias, etc.). */
    private fun getDeclaredTypeOfSymbol(symbol: Symbol): Type {
        declaredTypes[symbol.id]?.let { return it }
        val type = getDeclaredTypeOfSymbolWorker(symbol)
        declaredTypes[symbol.id] = type
        return type
    }

    private fun getDeclaredTypeOfSymbolWorker(symbol: Symbol): Type {
        val flags = symbol.flags
        return when {
            flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface) -> {
                getDeclaredTypeOfClassOrInterface(symbol)
            }
            flags.hasAny(SymbolFlags.TypeAlias) -> {
                // Store sentinel in cache first to prevent circular type alias StackOverflow
                declaredTypes[symbol.id] = errorType
                val decl = symbol.declarations.firstOrNull { it is TypeAliasDeclaration } as? TypeAliasDeclaration
                val resolved = if (decl != null) getTypeFromTypeNode(decl.type) else errorType
                declaredTypes[symbol.id] = resolved
                resolved
            }
            flags.hasAny(SymbolFlags.Enum) -> {
                // Enums are both a type and a value — return an object type
                val enumType = Type.Object()
                enumType.symbol = symbol
                enumType
            }
            flags.hasAny(SymbolFlags.TypeParameter) -> {
                val typeParam = Type.TypeParam()
                typeParam.symbol = symbol
                typeParam
            }
            else -> anyType
        }
    }

    /**
     * Build an InterfaceType from class/interface declarations.
     * Collects type parameters and resolves base types (extends/implements).
     * Members are NOT resolved yet (lazy, done in resolveStructuredTypeMembers).
     */
    private fun getDeclaredTypeOfClassOrInterface(symbol: Symbol): Type.Interface {
        val interfaceType = Type.Interface()
        interfaceType.symbol = symbol
        // Store in cache BEFORE resolving base types to prevent circular reference StackOverflow
        declaredTypes[symbol.id] = interfaceType
        // Collect type parameters from the first class/interface declaration
        val decl = symbol.declarations.firstOrNull {
            it is ClassDeclaration || it is InterfaceDeclaration
        }
        if (decl != null) {
            val typeParams = when (decl) {
                is ClassDeclaration -> decl.typeParameters
                is InterfaceDeclaration -> decl.typeParameters
                else -> null
            }
            if (typeParams != null && typeParams.isNotEmpty()) {
                interfaceType.typeParameters = typeParams.map { tp ->
                    val param = Type.TypeParam()
                    param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                    tp.constraint?.let { param.constraint = getTypeFromTypeNode(it) }
                    tp.default?.let { param.default = getTypeFromTypeNode(it) }
                    param
                }
            }
            // Resolve base types from heritage clauses
            val heritageClauses = when (decl) {
                is ClassDeclaration -> decl.heritageClauses
                is InterfaceDeclaration -> decl.heritageClauses
                else -> null
            }
            if (heritageClauses != null) {
                val baseTypes = mutableListOf<Type>()
                for (clause in heritageClauses) {
                    // ExtendsKeyword = base class/interface; ImplementsKeyword = implemented interface
                    for (exprWithArgs in clause.types) {
                        val baseType = getTypeFromBaseTypeExpression(exprWithArgs)
                        if (baseType !== errorType) {
                            baseTypes.add(baseType)
                        }
                    }
                }
                if (baseTypes.isNotEmpty()) {
                    interfaceType.baseTypes = baseTypes
                }
            }
        }
        return interfaceType
    }

    /** Resolve a base type expression (e.g., `extends Foo<T>`) to a Type. */
    private fun getTypeFromBaseTypeExpression(expr: ExpressionWithTypeArguments): Type {
        val baseExpr = expr.expression
        val name = when (baseExpr) {
            is Identifier -> baseExpr.text
            is PropertyAccessExpression -> baseExpr.name.text
            else -> return errorType
        }
        val symbol = globals[name] ?: return errorType
        return getDeclaredTypeOfSymbol(symbol)
    }

    // -----------------------------------------------------------------------
    // Symbol type resolution (Phase 4 item 2a)
    // -----------------------------------------------------------------------

    /**
     * Get the type of a symbol (variable, parameter, function, class, etc.).
     * Cached in [symbolTypes].
     */
    private fun getTypeOfSymbol(symbol: Symbol): Type {
        symbolTypes[symbol.id]?.let { return it }
        val type = getTypeOfSymbolWorker(symbol)
        symbolTypes[symbol.id] = type
        return type
    }

    private fun getTypeOfSymbolWorker(symbol: Symbol): Type {
        val flags = symbol.flags
        return when {
            flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property) -> getTypeOfVariableOrProperty(symbol)
            flags.hasAny(SymbolFlags.Function) -> getTypeOfFunction(symbol)
            flags.hasAny(SymbolFlags.Class) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.Interface) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.Enum) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.TypeAlias) -> getDeclaredTypeOfSymbol(symbol)
            flags.hasAny(SymbolFlags.Alias) -> {
                // Import alias — resolve to target symbol's type
                val target = resolveAliasTarget(symbol)
                if (target != null && target !== symbol) getTypeOfSymbol(target) else anyType
            }
            flags.hasAny(SymbolFlags.TypeParameter) -> getDeclaredTypeOfSymbol(symbol)
            else -> anyType
        }
    }

    /** Get the type of a variable or property from its declaration. */
    private fun getTypeOfVariableOrProperty(symbol: Symbol): Type {
        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull() ?: return anyType
        return when (decl) {
            is VariableDeclaration -> {
                // Type annotation takes priority
                decl.type?.let { return getTypeFromTypeNode(it) }
                // No annotation — return anyType for now (expression type inference is item 3a)
                anyType
            }
            is Parameter -> {
                decl.type?.let { return getTypeFromTypeNode(it) }
                anyType
            }
            is PropertyDeclaration -> {
                decl.type?.let { return getTypeFromTypeNode(it) }
                anyType
            }
            else -> anyType
        }
    }

    /** Get the type of a function symbol — creates an ObjectType with call signatures.
     *  For overloaded functions, collects all visible overload signatures (body-less declarations).
     *  If no overloads, uses the single implementation declaration.
     */
    private fun getTypeOfFunction(symbol: Symbol): Type {
        val fnType = Type.Object()
        fnType.symbol = symbol
        // Collect all function declarations for this symbol
        val funcDecls = symbol.declarations.filterIsInstance<FunctionDeclaration>()
        if (funcDecls.isEmpty()) return anyType

        // Separate overload signatures (no body) from implementation (has body)
        val overloadDecls = funcDecls.filter { it.body == null }
        val implDecl = funcDecls.find { it.body != null }

        // Use overload signatures if present (they are the visible API),
        // otherwise use the implementation declaration
        val sigDecls = if (overloadDecls.isNotEmpty()) overloadDecls else listOfNotNull(implDecl)
        if (sigDecls.isEmpty()) return anyType

        val signatures = sigDecls.map { decl ->
            val returnType = decl.type?.let { getTypeFromTypeNode(it) } ?: anyType
            // Resolve type parameters
            val typeParams = decl.typeParameters?.map { tp ->
                val param = Type.TypeParam()
                param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                tp.constraint?.let { param.constraint = getTypeFromTypeNode(it) }
                tp.default?.let { param.default = getTypeFromTypeNode(it) }
                param
            }
            Signature(
                declaration = decl,
                typeParameters = typeParams,
                parameters = getParameterSymbols(decl.parameters),
                resolvedReturnType = returnType,
                minArgumentCount = decl.parameters.count {
                    !it.questionToken && !it.dotDotDotToken && it.initializer == null
                },
            )
        }
        fnType.callSignatures = signatures
        return fnType
    }

    /**
     * Create Symbol objects for function/method parameters.
     * Each Parameter AST node gets a corresponding Symbol with FunctionScopedVariable flag.
     * This is needed for type checking of call arguments (TS2345).
     */
    private fun getParameterSymbols(params: List<Parameter>): List<Symbol> {
        return params.mapNotNull { param ->
            // Skip `this` pseudo-parameter
            val name = when (val n = param.name) {
                is Identifier -> if (n.text == "this") return@mapNotNull null else n.text
                else -> return@mapNotNull null // binding patterns not yet supported
            }
            val sym = Symbol(SymbolFlags.FunctionScopedVariable, name)
            sym.declarations.add(param)
            sym.valueDeclaration = param
            sym
        }
    }

    /** Resolve an import alias to its target symbol, with cycle detection. */
    private fun resolveAliasTarget(symbol: Symbol): Symbol? {
        // Use the checker-local LinkStore target if available
        getSymbolTarget(symbol)?.let { return it }
        // Otherwise try resolveAlias logic from the checker's existing infrastructure
        val visited = mutableSetOf<Int>()
        var current = symbol
        while (current.flags.hasAny(SymbolFlags.Alias)) {
            if (!visited.add(current.id)) return null // cycle
            val target = getSymbolTarget(current) ?: return null
            current = target
        }
        return current
    }

    // -----------------------------------------------------------------------
    // Lazy member resolution (Phase 4 item 2c)
    // -----------------------------------------------------------------------

    /**
     * Lazily resolve an ObjectType's members, properties, and signatures.
     * After this call, type.members/properties/callSignatures are populated.
     */
    private fun resolveStructuredTypeMembers(type: Type.Object) {
        if (type.properties != null) return // already resolved
        when (type) {
            is Type.Interface -> resolveInterfaceMembers(type)
            is Type.Reference -> resolveReferenceMembers(type)
            else -> resolveAnonymousTypeMembers(type)
        }
    }

    /** Resolve members of an interface/class type from its declarations + base types. */
    private fun resolveInterfaceMembers(type: Type.Interface) {
        val symbol = type.symbol ?: run {
            type.properties = emptyList()
            return
        }
        val members = symbolTable()
        val callSignatures = mutableListOf<Signature>()
        val constructSignatures = mutableListOf<Signature>()
        var stringIndexInfo: IndexInfo? = null
        var numberIndexInfo: IndexInfo? = null

        // Inherit from base types
        type.baseTypes?.forEach { baseType ->
            if (baseType is Type.Object) {
                resolveStructuredTypeMembers(baseType)
                baseType.members?.forEach { (name, sym) ->
                    if (name !in members) members[name] = sym
                }
                baseType.callSignatures?.let { callSignatures.addAll(it) }
                baseType.constructSignatures?.let { constructSignatures.addAll(it) }
                if (stringIndexInfo == null) stringIndexInfo = baseType.stringIndexInfo
                if (numberIndexInfo == null) numberIndexInfo = baseType.numberIndexInfo
            }
        }

        // Collect members from all declarations of this symbol
        for (decl in symbol.declarations) {
            val classMembers = when (decl) {
                is ClassDeclaration -> decl.members
                is InterfaceDeclaration -> decl.members
                else -> continue
            }
            for (member in classMembers) {
                when (member) {
                    is PropertyDeclaration -> {
                        val name = getMemberName(member.name) ?: continue
                        val propSymbol = Symbol(SymbolFlags.Property, name)
                        propSymbol.declarations.add(member)
                        propSymbol.valueDeclaration = member
                        members[name] = propSymbol
                    }
                    is MethodDeclaration -> {
                        val name = getMemberName(member.name) ?: continue
                        val methodSymbol = Symbol(SymbolFlags.Property or SymbolFlags.Function, name)
                        methodSymbol.declarations.add(member)
                        methodSymbol.valueDeclaration = member
                        members[name] = methodSymbol
                    }
                    is Constructor -> {
                        val returnType = type as Type
                        val sig = Signature(
                            declaration = member,
                            parameters = getParameterSymbols(member.parameters),
                            resolvedReturnType = returnType,
                            minArgumentCount = member.parameters.count {
                                !it.questionToken && !it.dotDotDotToken && it.initializer == null
                            },
                        )
                        constructSignatures.add(sig)
                        // Also add parameter properties as members
                        for (param in member.parameters) {
                            if (param.modifiers.isNotEmpty() && param.name is Identifier) {
                                val paramName = (param.name as Identifier).text
                                val propSymbol = Symbol(SymbolFlags.Property, paramName)
                                propSymbol.declarations.add(param)
                                propSymbol.valueDeclaration = param
                                members[paramName] = propSymbol
                            }
                        }
                    }
                    is GetAccessor -> {
                        val name = getMemberName(member.name) ?: continue
                        members.getOrPut(name) {
                            Symbol(SymbolFlags.Property, name).also {
                                it.declarations.add(member)
                                it.valueDeclaration = member
                            }
                        }
                    }
                    is SetAccessor -> {
                        val name = getMemberName(member.name) ?: continue
                        members.getOrPut(name) {
                            Symbol(SymbolFlags.Property, name).also {
                                it.declarations.add(member)
                                it.valueDeclaration = member
                            }
                        }
                    }
                    is IndexSignature -> {
                        val keyParam = member.parameters.firstOrNull()
                        val keyType = keyParam?.type?.let { getTypeFromTypeNode(it) } ?: stringType
                        val valueType = member.type?.let { getTypeFromTypeNode(it) } ?: anyType
                        val info = IndexInfo(keyType, valueType, member.modifiers.contains(ModifierFlag.Readonly), member)
                        if (keyType === numberType) {
                            numberIndexInfo = info
                        } else {
                            stringIndexInfo = info
                        }
                    }
                    is SemicolonClassElement, is ClassStaticBlockDeclaration -> { /* skip */ }
                }
            }
        }

        // Also include exports from the symbol (for namespace merges, etc.)
        symbol.members?.forEach { (name, sym) ->
            if (name !in members) members[name] = sym
        }

        type.members = members
        type.properties = members.values.toList()
        type.callSignatures = callSignatures.ifEmpty { null }
        type.constructSignatures = constructSignatures.ifEmpty { null }
        type.stringIndexInfo = stringIndexInfo
        type.numberIndexInfo = numberIndexInfo
    }

    /** Resolve members of a generic type reference by instantiating target members. */
    private fun resolveReferenceMembers(type: Type.Reference) {
        // For now, just resolve the target's members directly
        // TODO: instantiate with type argument mapper when generic infra is ready
        resolveStructuredTypeMembers(type.target)
        type.members = type.target.members
        type.properties = type.target.properties
        type.callSignatures = type.target.callSignatures
        type.constructSignatures = type.target.constructSignatures
        type.stringIndexInfo = type.target.stringIndexInfo
        type.numberIndexInfo = type.target.numberIndexInfo
    }

    /** Resolve members of an anonymous object type (object literal type, function type, etc.). */
    private fun resolveAnonymousTypeMembers(type: Type.Object) {
        // For anonymous types created by getFunctionTypeFromNode etc., signatures are already set
        if (type.properties == null) {
            type.properties = type.members?.values?.toList() ?: emptyList()
        }
    }

    /** Extract the name string from a member name node (Identifier, StringLiteral, NumericLiteral). */
    private fun getMemberName(name: NameNode): String? {
        return when (name) {
            is Identifier -> name.text
            is StringLiteralNode -> name.text
            is NumericLiteralNode -> name.text
            is ComputedPropertyName -> null // dynamic — can't resolve statically
            else -> null
        }
    }

    /**
     * Get the properties of a type, triggering lazy resolution if needed.
     */
    private fun getPropertiesOfType(type: Type): List<Symbol> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.properties ?: emptyList()
        }
        if (type is Type.Union) {
            // TODO: intersection of constituent properties
            return emptyList()
        }
        return emptyList()
    }

    /**
     * Look up a property by name on a type.
     */
    private fun getPropertyOfType(type: Type, name: String): Symbol? {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.members?.get(name)
        }
        if (type is Type.Union) {
            // Property exists on a union if it exists on every constituent
            for (constituent in type.types) {
                val prop = getPropertyOfType(constituent, name) ?: return null
            }
            // TODO: return merged property symbol
            return type.types.firstNotNullOfOrNull { getPropertyOfType(it, name) }
        }
        return null
    }

    // -----------------------------------------------------------------------
    // Expression type inference (Phase 4 item 3a)
    // -----------------------------------------------------------------------

    /**
     * Get the type of an expression. This is the main entry point for
     * expression type inference, replacing the string-based inferSimpleExprType.
     */
    private fun getTypeOfExpression(expr: Expression): Type {
        return when (expr) {
            // Literals
            is NumericLiteralNode -> numberType
            is StringLiteralNode -> stringType
            is NoSubstitutionTemplateLiteralNode -> stringType
            is TemplateExpression -> stringType
            is RegularExpressionLiteralNode -> anyType // TODO: RegExp type
            is BigIntLiteralNode -> bigintType

            // Identifiers
            is Identifier -> getTypeOfIdentifier(expr)

            // Property access
            is PropertyAccessExpression -> getTypeOfPropertyAccess(expr)
            is ElementAccessExpression -> anyType // TODO: indexed access

            // Unary expressions
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.Exclamation -> booleanType
                SyntaxKind.Minus, SyntaxKind.Plus, SyntaxKind.Tilde -> numberType
                SyntaxKind.PlusPlus, SyntaxKind.MinusMinus -> numberType
                else -> anyType
            }
            is PostfixUnaryExpression -> numberType // x++, x--
            is TypeOfExpression -> stringType
            is VoidExpression -> undefinedType
            is DeleteExpression -> booleanType

            // Binary expressions
            is BinaryExpression -> getTypeOfBinaryExpression(expr)

            // Type assertions / casts
            is AsExpression -> getTypeFromTypeNode(expr.type)
            is TypeAssertionExpression -> getTypeFromTypeNode(expr.type)
            is SatisfiesExpression -> getTypeOfExpression(expr.expression)
            is NonNullExpression -> getTypeOfExpression(expr.expression) // strips null/undefined

            // Parenthesized
            is ParenthesizedExpression -> getTypeOfExpression(expr.expression)

            // Literals that create objects
            is ArrayLiteralExpression -> getTypeOfArrayLiteral(expr)
            is ObjectLiteralExpression -> getTypeOfObjectLiteral(expr)

            // Call expressions — resolve return type from signature
            is CallExpression -> getReturnTypeOfCallExpression(expr)
            is NewExpression -> getReturnTypeOfNewExpression(expr)

            // Arrow / function
            is ArrowFunction -> getTypeOfArrowFunction(expr)
            is FunctionExpression -> getTypeOfFunctionExpression(expr)

            // Conditional
            is ConditionalExpression -> {
                // Result is union of true/false branches
                val trueT = getTypeOfExpression(expr.whenTrue)
                val falseT = getTypeOfExpression(expr.whenFalse)
                if (trueT === falseT) trueT else getUnionType(listOf(trueT, falseT))
            }

            // Comma list expression — type of last element
            is CommaListExpression -> if (expr.elements.isNotEmpty()) getTypeOfExpression(expr.elements.last()) else anyType

            // Class expression
            is ClassExpression -> anyType // TODO: class type

            // Spread
            is SpreadElement -> getTypeOfExpression(expr.expression)

            // Await
            is AwaitExpression -> anyType // TODO: unwrap Promise

            // Yield
            is YieldExpression -> anyType // TODO: generator return type

            // Tagged template
            is TaggedTemplateExpression -> anyType // TODO: call signature return type

            else -> anyType
        }
    }

    /** Get the type of an identifier expression. */
    private fun getTypeOfIdentifier(id: Identifier): Type {
        return when (id.text) {
            "undefined" -> undefinedType
            "null" -> nullType
            "true" -> trueType
            "false" -> falseType
            "NaN", "Infinity" -> numberType
            else -> {
                // Check local scope first (populated during TS2322 checking)
                currentLocalTypes[id.text]?.let { return it }
                // Then look up symbol in globals
                val symbol = globals[id.text]
                if (symbol != null) getTypeOfSymbol(symbol) else anyType
            }
        }
    }

    /** Get the type of an object literal expression as an anonymous object type. */
    private fun getTypeOfObjectLiteral(expr: ObjectLiteralExpression): Type {
        val members = symbolTable()
        val properties = mutableListOf<Symbol>()
        for (prop in expr.properties) {
            when (prop) {
                is PropertyAssignment -> {
                    val name = when (val n = prop.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        is NumericLiteralNode -> n.text
                        else -> continue
                    }
                    val propType = getTypeOfExpression(prop.initializer)
                    val sym = Symbol(SymbolFlags.Property, name)
                    sym.declarations.add(prop)
                    sym.valueDeclaration = prop
                    members[name] = sym
                    properties.add(sym)
                    symbolTypes[sym.id] = propType
                }
                is ShorthandPropertyAssignment -> {
                    val name = prop.name.text
                    val propType = getTypeOfExpression(prop.name)
                    val sym = Symbol(SymbolFlags.Property, name)
                    sym.declarations.add(prop)
                    sym.valueDeclaration = prop
                    members[name] = sym
                    properties.add(sym)
                    symbolTypes[sym.id] = propType
                }
                is MethodDeclaration -> {
                    val name = when (val n = prop.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> continue
                    }
                    val sym = Symbol(SymbolFlags.Property or SymbolFlags.Function, name)
                    sym.declarations.add(prop)
                    sym.valueDeclaration = prop
                    members[name] = sym
                    properties.add(sym)
                    // Method type — create function type with call signature
                    val returnType = prop.type?.let { getTypeFromTypeNode(it) } ?: anyType
                    val params = getParameterSymbols(prop.parameters)
                    val sig = Signature(
                        declaration = prop,
                        parameters = params,
                        resolvedReturnType = returnType,
                        minArgumentCount = prop.parameters.count {
                            !it.questionToken && !it.dotDotDotToken && it.initializer == null
                        },
                    )
                    val methodType = Type.Object()
                    methodType.callSignatures = listOf(sig)
                    methodType.properties = emptyList()
                    symbolTypes[sym.id] = methodType
                }
                is SpreadAssignment -> continue // spread not yet supported
                is GetAccessor, is SetAccessor -> continue // accessors not yet supported
                else -> continue
            }
        }
        val objType = Type.Object()
        objType.members = members
        objType.properties = properties
        return objType
    }

    /** Get the type of an array literal expression. */
    private fun getTypeOfArrayLiteral(expr: ArrayLiteralExpression): Type {
        if (expr.elements.isEmpty()) return anyType // empty array — can't infer element type
        // Infer element type as union of all element types
        val elementTypes = mutableListOf<Type>()
        for (el in expr.elements) {
            if (el is SpreadElement) return anyType // spread not yet supported
            val t = getTypeOfExpression(el)
            if (t === anyType || t === errorType) return anyType // can't determine
            if (t !in elementTypes) elementTypes.add(t)
        }
        // For a homogeneous array, element type is the single type
        // For heterogeneous, it's a union
        val elementType = when (elementTypes.size) {
            0 -> anyType
            1 -> elementTypes[0]
            else -> getUnionType(elementTypes)
        }
        return getArrayType(elementType)
    }

    /** Get the type of an arrow function expression. */
    private fun getTypeOfArrowFunction(expr: ArrowFunction): Type {
        val returnType = expr.type?.let { getTypeFromTypeNode(it) } ?: run {
            val body = expr.body
            when {
                body is Block && !hasReturnWithExpression(body) -> voidType
                body is Block -> anyType // has return with expression, can't infer without analysis
                body != null -> getTypeOfExpression(body as Expression) // concise body: () => expr
                else -> anyType
            }
        }
        val params = getParameterSymbols(expr.parameters)
        val sig = Signature(
            declaration = expr,
            parameters = params,
            resolvedReturnType = returnType,
            minArgumentCount = expr.parameters.count {
                !it.questionToken && !it.dotDotDotToken && it.initializer == null
            },
        )
        val fnType = Type.Object()
        fnType.callSignatures = listOf(sig)
        fnType.properties = emptyList()
        return fnType
    }

    /** Get the type of a function expression. */
    private fun getTypeOfFunctionExpression(expr: FunctionExpression): Type {
        val returnType = expr.type?.let { getTypeFromTypeNode(it) }
            ?: if (expr.body != null && !hasReturnWithExpression(expr.body!!)) voidType else anyType
        val params = getParameterSymbols(expr.parameters)
        val sig = Signature(
            declaration = expr,
            parameters = params,
            resolvedReturnType = returnType,
            minArgumentCount = expr.parameters.count {
                !it.questionToken && !it.dotDotDotToken && it.initializer == null
            },
        )
        val fnType = Type.Object()
        fnType.callSignatures = listOf(sig)
        fnType.properties = emptyList()
        return fnType
    }

    /** Check if a block contains any return statement with an expression. */
    private fun hasReturnWithExpression(block: Block): Boolean {
        for (stmt in block.statements) {
            if (stmt is ReturnStatement && stmt.expression != null) return true
            // Don't recurse into nested functions — they have their own return scope
        }
        return false
    }

    /** Get the return type of a call expression by resolving the callee's call signature. */
    private fun getReturnTypeOfCallExpression(expr: CallExpression): Type {
        val calleeType = when (val callee = expr.expression) {
            is Identifier -> {
                val sym = globals[callee.text] ?: return anyType
                getTypeOfSymbol(sym)
            }
            is PropertyAccessExpression -> getTypeOfPropertyAccess(callee)
            else -> return anyType
        }
        if (calleeType === anyType || calleeType === errorType) return anyType
        if (calleeType !is Type.Object) return anyType
        resolveStructuredTypeMembers(calleeType)
        val sigs = calleeType.callSignatures
        if (sigs.isNullOrEmpty()) return anyType
        // Use the first signature's return type (simple resolution)
        return sigs[0].resolvedReturnType ?: anyType
    }

    /** Get the return type of a new expression by resolving the construct signature. */
    private fun getReturnTypeOfNewExpression(expr: NewExpression): Type {
        val calleeType = when (val callee = expr.expression) {
            is Identifier -> {
                val sym = globals[callee.text] ?: return anyType
                getTypeOfSymbol(sym)
            }
            else -> return anyType
        }
        if (calleeType === anyType || calleeType === errorType) return anyType
        // For new expressions, the return type is the class type itself
        if (calleeType is Type.Interface) return calleeType
        if (calleeType !is Type.Object) return anyType
        resolveStructuredTypeMembers(calleeType)
        val sigs = calleeType.constructSignatures
        if (sigs.isNullOrEmpty()) return anyType
        return sigs[0].resolvedReturnType ?: anyType
    }

    /** Get the type of a property access expression (e.g., `obj.prop`). */
    private fun getTypeOfPropertyAccess(expr: PropertyAccessExpression): Type {
        val objectType = getTypeOfExpression(expr.expression)
        val propName = expr.name.text
        val apparentType = getApparentType(objectType)
        val prop = getPropertyOfType(apparentType, propName)
        return if (prop != null) getTypeOfSymbol(prop) else anyType
    }

    /** Get the type of a binary expression. */
    private fun getTypeOfBinaryExpression(expr: BinaryExpression): Type {
        return when (expr.operator) {
            // Arithmetic → number
            SyntaxKind.Plus -> {
                // Plus is special: string + any = string, any + string = string
                val leftType = getTypeOfExpression(expr.left)
                val rightType = getTypeOfExpression(expr.right)
                if (leftType.flags.hasAny(TypeFlags.StringLike) || rightType.flags.hasAny(TypeFlags.StringLike)) {
                    stringType
                } else if (leftType.flags.hasAny(TypeFlags.NumberLike) && rightType.flags.hasAny(TypeFlags.NumberLike)) {
                    numberType
                } else if (leftType.flags.hasAny(TypeFlags.BigIntLike) && rightType.flags.hasAny(TypeFlags.BigIntLike)) {
                    bigintType
                } else {
                    anyType // could be string or number
                }
            }
            SyntaxKind.Minus, SyntaxKind.Asterisk, SyntaxKind.Slash,
            SyntaxKind.Percent, SyntaxKind.AsteriskAsterisk,
            SyntaxKind.Ampersand, SyntaxKind.Bar, SyntaxKind.Caret,
            SyntaxKind.LessThanLessThan, SyntaxKind.GreaterThanGreaterThan,
            SyntaxKind.GreaterThanGreaterThanGreaterThan -> numberType

            // Comparison → boolean
            SyntaxKind.LessThan, SyntaxKind.GreaterThan,
            SyntaxKind.LessThanEquals, SyntaxKind.GreaterThanEquals,
            SyntaxKind.EqualsEquals, SyntaxKind.ExclamationEquals,
            SyntaxKind.EqualsEqualsEquals, SyntaxKind.ExclamationEqualsEquals,
            SyntaxKind.InstanceOfKeyword, SyntaxKind.InKeyword -> booleanType

            // Assignment → type of left
            SyntaxKind.Equals -> getTypeOfExpression(expr.right)
            SyntaxKind.PlusEquals, SyntaxKind.MinusEquals,
            SyntaxKind.AsteriskEquals, SyntaxKind.SlashEquals -> getTypeOfExpression(expr.left)

            // Logical → union of operands
            SyntaxKind.AmpersandAmpersand -> getTypeOfExpression(expr.right)
            SyntaxKind.BarBar -> {
                val leftT = getTypeOfExpression(expr.left)
                val rightT = getTypeOfExpression(expr.right)
                if (leftT === rightT) leftT else getUnionType(listOf(leftT, rightT))
            }
            SyntaxKind.QuestionQuestion -> {
                val leftT = getTypeOfExpression(expr.left)
                val rightT = getTypeOfExpression(expr.right)
                if (leftT === rightT) leftT else getUnionType(listOf(leftT, rightT))
            }

            // Comma → type of right
            SyntaxKind.Comma -> getTypeOfExpression(expr.right)

            else -> anyType
        }
    }

    /**
     * Get the apparent type of a type — for type parameters, this is the constraint;
     * for primitives, this is the corresponding wrapper type.
     */
    private fun getApparentType(type: Type): Type {
        return when {
            type is Type.TypeParam -> type.constraint?.let { getApparentType(it) } ?: anyType
            type.flags.hasAny(TypeFlags.StringLike) -> anyType // TODO: String wrapper type
            type.flags.hasAny(TypeFlags.NumberLike) -> anyType // TODO: Number wrapper type
            type.flags.hasAny(TypeFlags.BooleanLike) -> anyType // TODO: Boolean wrapper type
            else -> type
        }
    }

    /**
     * Get a display-friendly string for a Type (used in diagnostic messages).
     */
    /** Format a signature as a string like `(x: number) => string` or `new (x: number) => Foo`. */
    private fun signatureToString(sig: Signature, isConstruct: Boolean): String {
        val prefix = if (isConstruct) "new " else ""
        val params = sig.parameters.joinToString(", ") { p ->
            val pType = getTypeOfSymbol(p).let { if (it === anyType) "any" else typeToString(it) }
            "${p.name}: $pType"
        }
        val retType = sig.resolvedReturnType?.let { typeToString(it) } ?: "any"
        return "$prefix($params) => $retType"
    }

    /** Format a signature using colon notation like `(x: number): string` for use in `{ }` blocks. */
    private fun signatureToStringColon(sig: Signature, isConstruct: Boolean): String {
        val prefix = if (isConstruct) "new " else ""
        val params = sig.parameters.joinToString(", ") { p ->
            val pType = getTypeOfSymbol(p).let { if (it === anyType) "any" else typeToString(it) }
            "${p.name}: $pType"
        }
        val retType = sig.resolvedReturnType?.let { typeToString(it) } ?: "any"
        return "$prefix($params): $retType"
    }

    private fun typeToString(type: Type): String {
        return when (type) {
            is Type.Intrinsic -> type.intrinsicName
            is Type.StringLiteral -> "\"${type.value}\""
            is Type.NumberLiteral -> type.toString()
            is Type.BigIntLiteral -> type.toString()
            // Interface and Reference must be checked BEFORE Object (they extend Object)
            is Type.Interface -> {
                val name = type.symbol?.name ?: "Interface"
                val tps = type.typeParameters
                if (tps != null && tps.isNotEmpty()) {
                    "$name<${tps.joinToString(", ") { it.symbol?.name ?: "T" }}>"
                } else name
            }
            is Type.Reference -> {
                val args = type.resolvedTypeArguments
                // Array types display as T[] (not Array<T>)
                if (type.target === globalArrayType && args != null && args.size == 1) {
                    "${typeToString(args[0])}[]"
                } else {
                    val target = type.target.symbol?.name ?: "Object"
                    if (args != null && args.isNotEmpty()) {
                        "$target<${args.joinToString(", ") { typeToString(it) }}>"
                    } else target
                }
            }
            is Type.Object -> {
                val callSigs = type.callSignatures
                val ctorSigs = type.constructSignatures
                // Function type: show signatures
                if (!callSigs.isNullOrEmpty() || !ctorSigs.isNullOrEmpty()) {
                    val totalSigs = (callSigs?.size ?: 0) + (ctorSigs?.size ?: 0)
                    if (totalSigs == 1) {
                        // Single signature: arrow format
                        if (!callSigs.isNullOrEmpty()) signatureToString(callSigs.first(), isConstruct = false)
                        else signatureToString(ctorSigs!!.first(), isConstruct = true)
                    } else {
                        // Multiple signatures: object format { (sig): ret; ... }
                        val parts = mutableListOf<String>()
                        callSigs?.forEach { parts.add(signatureToStringColon(it, isConstruct = false)) }
                        ctorSigs?.forEach { parts.add(signatureToStringColon(it, isConstruct = true)) }
                        "{ ${parts.joinToString("; ")}; }"
                    }
                } else {
                    val sym = type.symbol
                    if (sym != null) sym.name
                    else {
                        // Anonymous object type — format as { prop: type; ... }
                        val props = type.properties
                        if (props != null && props.isNotEmpty()) {
                            val entries = props.joinToString("; ") { p ->
                                val propType = symbolTypes[p.id]
                                "${p.name}: ${if (propType != null) typeToString(propType) else "any"}"
                            }
                            "{ $entries; }"
                        } else "{ ... }"
                    }
                }
            }
            is Type.Union -> type.types.joinToString(" | ") { typeToString(it) }
            is Type.Intersection -> type.types.joinToString(" & ") { typeToString(it) }
            is Type.TypeParam -> type.symbol?.name ?: "T"
        }
    }

    // -----------------------------------------------------------------------
    // TS2394: Overload signature not compatible with implementation
    // -----------------------------------------------------------------------

    private fun checkOverloadSignatureCompatibility() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                checkOverloadsInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkOverloadsInStatements(stmts: List<Statement>, source: String, fileName: String) {
        // Group function declarations by name
        val funcGroups = mutableMapOf<String, MutableList<FunctionDeclaration>>()
        for (stmt in stmts) {
            if (stmt is FunctionDeclaration && stmt.name != null) {
                funcGroups.getOrPut(stmt.name!!.text) { mutableListOf() }.add(stmt)
            }
        }

        for ((name, decls) in funcGroups) {
            val impl = decls.firstOrNull { it.body != null } ?: continue
            val overloads = decls.filter { it.body == null }
            if (overloads.isEmpty()) continue

            // Track reported overloads to skip duplicates
            val reported = mutableSetOf<Int>()
            for ((idx, overload) in overloads.withIndex()) {
                // Skip duplicate overloads (same param types as a previously-reported one)
                if (idx > 0 && isDuplicateOverload(overload, overloads[idx - 1])) continue
                if (!isOverloadCompatibleWithImpl(overload, impl)) {
                    val nameNode = overload.name ?: continue
                    val start = nameNode.pos
                    val length = nameNode.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val implNameNode = impl.name ?: continue
                    val implStart = implNameNode.pos
                    val (implLine, implChar) = getLineAndCharacterOfPosition(source, implStart)
                    diagnostics.add(Diagnostic(
                        message = "This overload signature is not compatible with its implementation signature.",
                        category = DiagnosticCategory.Error,
                        code = 2394,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        relatedInformation = listOf(Diagnostic(
                            message = "The implementation signature is declared here.",
                            category = DiagnosticCategory.Message,
                            code = 2750,
                            fileName = fileName,
                            line = implLine,
                            character = implChar,
                            start = implStart,
                            length = implNameNode.text.length,
                        )),
                    ))
                }
            }
        }

        // Recurse into nested blocks
        for (stmt in stmts) {
            when (stmt) {
                is ClassDeclaration -> {
                    // Check method overloads in classes
                    checkMethodOverloadsInClass(stmt.members, source, fileName)
                }
                is Block -> checkOverloadsInStatements(stmt.statements, source, fileName)
                is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                    checkOverloadsInStatements(it.statements, source, fileName)
                }
                else -> {}
            }
        }
    }

    private fun checkMethodOverloadsInClass(members: List<ClassElement>, source: String, fileName: String) {
        // Group methods by name
        val methodGroups = mutableMapOf<String, MutableList<MethodDeclaration>>()
        for (member in members) {
            if (member is MethodDeclaration) {
                val name = when (val n = member.name) {
                    is Identifier -> n.text
                    is StringLiteralNode -> n.text
                    else -> continue
                }
                methodGroups.getOrPut(name) { mutableListOf() }.add(member)
            }
        }

        for ((name, decls) in methodGroups) {
            val impl = decls.firstOrNull { it.body != null } ?: continue
            val overloads = decls.filter { it.body == null }
            if (overloads.isEmpty()) continue

            for (overload in overloads) {
                if (!isMethodOverloadCompatibleWithImpl(overload, impl)) {
                    val nameNode = overload.name
                    val nameText = when (nameNode) {
                        is Identifier -> nameNode.text
                        is StringLiteralNode -> nameNode.text
                        else -> continue
                    }
                    val start = nameNode.pos
                    val length = nameText.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    val implNameNode = impl.name
                    val implStart = implNameNode.pos
                    val implText = when (implNameNode) {
                        is Identifier -> implNameNode.text
                        is StringLiteralNode -> implNameNode.text
                        else -> continue
                    }
                    val (implLine, implChar) = getLineAndCharacterOfPosition(source, implStart)
                    diagnostics.add(Diagnostic(
                        message = "This overload signature is not compatible with its implementation signature.",
                        category = DiagnosticCategory.Error,
                        code = 2394,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        relatedInformation = listOf(Diagnostic(
                            message = "The implementation signature is declared here.",
                            category = DiagnosticCategory.Message,
                            code = 2750,
                            fileName = fileName,
                            line = implLine,
                            character = implChar,
                            start = implStart,
                            length = implText.length,
                        )),
                    ))
                }
            }
        }
    }

    /** Check if two consecutive overloads have identical parameter structure */
    private fun isDuplicateOverload(a: FunctionDeclaration, b: FunctionDeclaration): Boolean {
        if (a.parameters.size != b.parameters.size) return false
        for (i in a.parameters.indices) {
            val aType = a.parameters[i].type
            val bType = b.parameters[i].type
            if (aType == null && bType == null) continue
            if (aType == null || bType == null) return false
            // Compare keyword types
            if (aType is KeywordTypeNode && bType is KeywordTypeNode) {
                if (aType.kind != bType.kind) return false
            } else if (aType::class != bType::class) {
                return false
            }
        }
        return true
    }

    private fun isOverloadCompatibleWithImpl(overload: FunctionDeclaration, impl: FunctionDeclaration): Boolean {
        return isSignatureCompatible(overload.parameters, overload.type, impl.parameters, impl.type)
    }

    private fun isMethodOverloadCompatibleWithImpl(overload: MethodDeclaration, impl: MethodDeclaration): Boolean {
        return isSignatureCompatible(overload.parameters, overload.type, impl.parameters, impl.type)
    }

    /**
     * Conservative compatibility check between an overload signature and its implementation.
     * Returns true if compatible (or unknown), false only when clearly incompatible.
     */
    private fun isSignatureCompatible(
        overloadParams: List<Parameter>,
        overloadReturnType: TypeNode?,
        implParams: List<Parameter>,
        implReturnType: TypeNode?,
    ): Boolean {
        // Parameter count check: implementation must accept the number of args the overload promises
        val overloadTotalParams = overloadParams.size
        val implMinParams = implParams.count { !it.questionToken && it.initializer == null && !it.dotDotDotToken }
        if (implMinParams > overloadTotalParams) {
            return false
        }

        // Return type check: compare keyword types
        if (overloadReturnType != null && implReturnType != null) {
            if (!isTypeNodeCompatible(overloadReturnType, implReturnType)) {
                return false
            }
        }

        // Parameter type check: compare matching parameters by keyword type
        val commonCount = minOf(overloadParams.size, implParams.size)
        for (i in 0 until commonCount) {
            val overloadType = overloadParams[i].type ?: continue
            val implType = implParams[i].type ?: continue
            if (!isParamTypeCompatible(overloadType, implType)) {
                return false
            }
        }

        return true
    }

    /**
     * Check if overload return type is compatible with implementation return type.
     * Conservative: only flag clearly incompatible intrinsic types.
     */
    private fun isTypeNodeCompatible(overloadType: TypeNode, implType: TypeNode): Boolean {
        // Only compare keyword types (number, string, boolean, void, etc.)
        if (overloadType !is KeywordTypeNode || implType !is KeywordTypeNode) return true
        val overloadKind = overloadType.kind
        val implKind = implType.kind
        if (overloadKind == implKind) return true
        // 'any' implementation is compatible with everything
        if (implKind == SyntaxKind.AnyKeyword) return true
        // 'any' overload is compatible with any implementation
        if (overloadKind == SyntaxKind.AnyKeyword) return true
        // 'void' and 'undefined' are interchangeable
        if ((overloadKind == SyntaxKind.VoidKeyword && implKind == SyntaxKind.UndefinedKeyword) ||
            (overloadKind == SyntaxKind.UndefinedKeyword && implKind == SyntaxKind.VoidKeyword)) return true
        // Different intrinsic types are incompatible
        return false
    }

    /**
     * Check if overload parameter type is compatible with implementation parameter type.
     * Conservative: only flag clearly incompatible intrinsic types.
     */
    private fun isParamTypeCompatible(overloadType: TypeNode, implType: TypeNode): Boolean {
        // Same logic as return type compatibility for keyword types
        return isTypeNodeCompatible(overloadType, implType)
    }

    // -----------------------------------------------------------------------
    // TS2506: 'X' is referenced directly or indirectly in its own base expression
    // -----------------------------------------------------------------------

    private fun checkCircularBaseClasses() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                checkCircularBaseInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkCircularBaseInStatements(statements: List<Statement>, source: String, fileName: String) {
        // Collect all class names and their extends targets in this scope
        val classExtends = mutableMapOf<String, String>() // className → baseClassName
        val classDecls = mutableMapOf<String, ClassDeclaration>()
        for (stmt in statements) {
            when (stmt) {
                is ClassDeclaration -> {
                    val name = stmt.name?.text ?: continue
                    classDecls[name] = stmt
                    val extendsClause = stmt.heritageClauses?.firstOrNull {
                        it.token == SyntaxKind.ExtendsKeyword
                    } ?: continue
                    val baseExpr = extendsClause.types.firstOrNull()?.expression ?: continue
                    val baseName = when (baseExpr) {
                        is Identifier -> baseExpr.text
                        else -> continue
                    }
                    classExtends[name] = baseName
                }
                is ModuleDeclaration -> {
                    val body = stmt.body
                    if (body is ModuleBlock) {
                        checkCircularBaseInStatements(body.statements, source, fileName)
                    }
                }
                else -> {}
            }
        }
        // For each class, follow the extends chain to detect cycles
        for ((className, _) in classExtends) {
            val visited = mutableSetOf<String>()
            var current: String? = className
            while (current != null) {
                if (!visited.add(current)) {
                    // Cycle detected — emit TS2506 for all classes in the cycle
                    if (current == className) {
                        val decl = classDecls[className] ?: break
                        val nameNode = decl.name ?: break
                        val start = nameNode.pos
                        val length = nameNode.text.length
                        val (line, character) = getLineAndCharacterOfPosition(source, start)
                        diagnostics.add(Diagnostic(
                            message = "'$className' is referenced directly or indirectly in its own base expression.",
                            category = DiagnosticCategory.Error,
                            code = 2506,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = start,
                            length = length,
                        ))
                    }
                    break
                }
                current = classExtends[current]
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2320: Interface cannot simultaneously extend types with conflicting members
    // -----------------------------------------------------------------------

    private fun checkInterfaceMultiBaseConflicts() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkMultiBaseInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkMultiBaseInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> {
                val extendsClauses = stmt.heritageClauses?.filter { it.token == SyntaxKind.ExtendsKeyword } ?: return
                // Collect all base type names from extends clauses
                val baseTypeExprs = extendsClauses.flatMap { it.types }
                if (baseTypeExprs.size < 2) return // Need 2+ base types
                val ifaceName = stmt.name.text

                // Collect properties from each base type
                data class BaseProperty(val baseName: String, val isPrivate: Boolean, val propType: TypeNode?)
                val propSources = mutableMapOf<String, MutableList<BaseProperty>>()

                for (typeExpr in baseTypeExprs) {
                    val baseName = (typeExpr.expression as? Identifier)?.text ?: continue
                    val baseSymbol = globals[baseName] ?: continue
                    // Get members from all declarations (class or interface)
                    for (decl in baseSymbol.declarations) {
                        val members: List<Any> = when (decl) {
                            is ClassDeclaration -> decl.members
                            is InterfaceDeclaration -> decl.members.toList()
                            else -> continue
                        }
                        for (member in members) {
                            val propName: String
                            val isPrivate: Boolean
                            val propType: TypeNode?
                            when (member) {
                                is PropertyDeclaration -> {
                                    propName = (member.name as? Identifier)?.text ?: continue
                                    isPrivate = ModifierFlag.Private in member.modifiers
                                    propType = member.type
                                }
                                is MethodDeclaration -> {
                                    propName = (member.name as? Identifier)?.text ?: continue
                                    isPrivate = ModifierFlag.Private in member.modifiers
                                    propType = member.type
                                }
                                else -> continue
                            }
                            propSources.getOrPut(propName) { mutableListOf() }
                                .add(BaseProperty(baseName, isPrivate, propType))
                        }
                    }
                }

                // Check for conflicts: same property from different bases where at least one is private
                for ((propName, sources) in propSources) {
                    val distinctBases = sources.map { it.baseName }.distinct()
                    if (distinctBases.size < 2) continue // Same base — no conflict
                    val hasPrivate = sources.any { it.isPrivate }
                    if (!hasPrivate) continue // Both public — might still conflict on type, but that's TS2430

                    val base1 = distinctBases[0]
                    val base2 = distinctBases[1]
                    val nameNode = stmt.name
                    val start = nameNode.pos
                    val length = nameNode.text.length
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Interface '$ifaceName' cannot simultaneously extend types '$base1' and '$base2'.",
                        category = DiagnosticCategory.Error,
                        code = 2320,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                        messageChain = listOf("  Named property '$propName' of types '$base1' and '$base2' are not identical."),
                    ))
                    return // One TS2320 per interface
                }
            }
            is ModuleDeclaration -> {
                (stmt.body as? ModuleBlock)?.statements?.forEach { checkMultiBaseInStatement(it, source, fileName) }
            }
            else -> {}
        }
    }

    // -----------------------------------------------------------------------
    // TS2411: Property type not assignable to index type
    // -----------------------------------------------------------------------

    private fun checkIndexSignatureProperties() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkIndexSigInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkIndexSigInStatement(stmt: Statement, source: String, fileName: String) {
        val members: List<ClassElement> = when (stmt) {
            is ClassDeclaration -> stmt.members
            is InterfaceDeclaration -> stmt.members.filterIsInstance<ClassElement>()
            is ModuleDeclaration -> {
                (stmt.body as? ModuleBlock)?.statements?.forEach { checkIndexSigInStatement(it, source, fileName) }
                return
            }
            else -> return
        }
        // Find string index signature: [s: string]: T (also check base class)
        var stringIndexSig = members.filterIsInstance<IndexSignature>().firstOrNull { sig ->
            sig.parameters.firstOrNull()?.type?.let { it is KeywordTypeNode && it.kind == SyntaxKind.StringKeyword } == true
        }
        // If not found locally, check base class
        if (stringIndexSig == null && stmt is ClassDeclaration) {
            val baseName = stmt.heritageClauses?.firstOrNull { it.token == SyntaxKind.ExtendsKeyword }
                ?.types?.firstOrNull()?.expression
                ?.let { (it as? Identifier)?.text }
            if (baseName != null) {
                val baseSymbol = globals[baseName]
                val baseDecl = baseSymbol?.declarations?.filterIsInstance<ClassDeclaration>()?.firstOrNull()
                stringIndexSig = baseDecl?.members?.filterIsInstance<IndexSignature>()?.firstOrNull { sig ->
                    sig.parameters.firstOrNull()?.type?.let { it is KeywordTypeNode && it.kind == SyntaxKind.StringKeyword } == true
                }
            }
        }
        val stringIndexType = stringIndexSig?.type?.let { getTypeFromTypeNode(it) }
        if (stringIndexType == null || stringIndexType === anyType || stringIndexType === errorType) return

        // Check each named property against the string index type
        for (member in members) {
            val propName: String
            val propTypeNode: TypeNode?
            val nameNode: Node
            when (member) {
                is PropertyDeclaration -> {
                    // Skip private fields (#name) — they're not accessible via index operator
                    val propIdent = member.name
                    if (propIdent is Identifier && propIdent.text.startsWith("#")) continue
                    nameNode = member.name
                    propName = when (val n = member.name) {
                        is Identifier -> n.text
                        is StringLiteralNode -> n.text
                        else -> continue
                    }
                    propTypeNode = member.type
                }
                is MethodDeclaration -> {
                    nameNode = member.name ?: continue
                    propName = when (val n = member.name) {
                        is Identifier -> n.text
                        else -> continue
                    }
                    propTypeNode = null // methods have function type
                }
                else -> continue
            }
            if (propTypeNode == null) continue // skip methods without explicit type
            val propType = getTypeFromTypeNode(propTypeNode)
            if (propType === anyType || propType === errorType) continue

            if (!checkTypeRelatedTo(propType, stringIndexType, assignableRelation)) {
                val propTypeDisplay = formatTypeForDisplay(propTypeNode) ?: typeToString(propType)
                val indexTypeDisplay = typeToString(stringIndexType)
                val start: Int
                val length: Int
                when (nameNode) {
                    is Identifier -> { start = nameNode.pos; length = nameNode.text.length }
                    is StringLiteralNode -> { start = nameNode.pos; length = nameNode.text.length + 2 }
                    else -> continue
                }
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Property '$propName' of type '$propTypeDisplay' is not assignable to 'string' index type '$indexTypeDisplay'.",
                    category = DiagnosticCategory.Error,
                    code = 2411,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2511: Cannot create an instance of an abstract class
    // -----------------------------------------------------------------------

    private fun checkAbstractClassInstantiation() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                // Collect abstract class names visible at file level
                val abstractClasses = mutableSetOf<String>()
                collectAbstractClassNames(result.sourceFile.statements, abstractClasses)
                // Also check globals for abstract classes from other files
                for ((name, sym) in globals) {
                    if (isAbstractClass(sym)) abstractClasses.add(name)
                }
                checkAbstractInStmts(result.sourceFile.statements, source, fileName, abstractClasses)
            } catch (_: StackOverflowError) {}
        }
    }

    private fun collectAbstractClassNames(stmts: List<Statement>, names: MutableSet<String>) {
        for (stmt in stmts) {
            if (stmt is ClassDeclaration && stmt.name != null && ModifierFlag.Abstract in stmt.modifiers) {
                names.add(stmt.name!!.text)
            }
        }
    }

    private fun checkAbstractInStmts(stmts: List<Statement>, source: String, fileName: String, abstractClasses: MutableSet<String>) {
        // Collect abstract class names declared in this block
        val saved = abstractClasses.toSet()
        collectAbstractClassNames(stmts, abstractClasses)
        // Also remove names shadowed by non-abstract classes in this scope
        for (stmt in stmts) {
            if (stmt is ClassDeclaration && stmt.name != null && ModifierFlag.Abstract !in stmt.modifiers) {
                abstractClasses.remove(stmt.name!!.text)
            }
        }
        for (stmt in stmts) {
            checkAbstractInStmt(stmt, source, fileName, abstractClasses)
        }
        // Restore scope
        abstractClasses.clear()
        abstractClasses.addAll(saved)
    }

    private fun checkAbstractInStmt(stmt: Statement, source: String, fileName: String, abstractClasses: MutableSet<String>) {
        when (stmt) {
            is ExpressionStatement -> checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses)
            is VariableStatement -> {
                for (d in stmt.declarationList.declarations) {
                    d.initializer?.let { checkAbstractInExpr(it, source, fileName, abstractClasses) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkAbstractInExpr(it, source, fileName, abstractClasses) }
            is IfStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses)
                checkAbstractInStmt(stmt.thenStatement, source, fileName, abstractClasses)
                stmt.elseStatement?.let { checkAbstractInStmt(it, source, fileName, abstractClasses) }
            }
            is Block -> checkAbstractInStmts(stmt.statements, source, fileName, abstractClasses)
            is FunctionDeclaration -> stmt.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
            is ClassDeclaration -> for (m in stmt.members) {
                when (m) {
                    is MethodDeclaration -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
                    is Constructor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
                    is PropertyDeclaration -> m.initializer?.let { checkAbstractInExpr(it, source, fileName, abstractClasses) }
                    is GetAccessor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
                    is SetAccessor -> m.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
                    else -> {}
                }
            }
            is ForStatement -> {
                (stmt.initializer as? VariableDeclarationList)?.declarations?.forEach { d ->
                    d.initializer?.let { checkAbstractInExpr(it, source, fileName, abstractClasses) }
                }
                stmt.condition?.let { checkAbstractInExpr(it, source, fileName, abstractClasses) }
                stmt.incrementor?.let { checkAbstractInExpr(it, source, fileName, abstractClasses) }
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses)
            }
            is WhileStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses)
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses)
            }
            is DoStatement -> {
                checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses)
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses)
            }
            is SwitchStatement -> {
                checkAbstractInExpr(stmt.expression, source, fileName, abstractClasses)
                for (c in stmt.caseBlock) {
                    val clauseStmts = when (c) { is CaseClause -> c.statements; is DefaultClause -> c.statements; else -> emptyList() }
                    checkAbstractInStmts(clauseStmts, source, fileName, abstractClasses)
                }
            }
            is TryStatement -> {
                checkAbstractInStmts(stmt.tryBlock.statements, source, fileName, abstractClasses)
                stmt.catchClause?.let { checkAbstractInStmts(it.block.statements, source, fileName, abstractClasses) }
                stmt.finallyBlock?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
            }
            is ThrowStatement -> stmt.expression?.let { checkAbstractInExpr(it, source, fileName, abstractClasses) }
            is ForInStatement -> checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses)
            is ForOfStatement -> checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses)
            is LabeledStatement -> checkAbstractInStmt(stmt.statement, source, fileName, abstractClasses)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
            else -> {}
        }
    }

    private fun checkAbstractInExpr(expr: Expression, source: String, fileName: String, abstractClasses: MutableSet<String>) {
        when (expr) {
            is NewExpression -> {
                val callee = expr.expression
                if (callee is Identifier && callee.text in abstractClasses) {
                    val start = expr.pos
                    val exprEnd = expressionTrueEnd(expr)
                    val length = exprEnd - start
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Cannot create an instance of an abstract class.",
                        category = DiagnosticCategory.Error,
                        code = 2511,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
                for (arg in expr.arguments ?: emptyList()) {
                    checkAbstractInExpr(arg, source, fileName, abstractClasses)
                }
            }
            is BinaryExpression -> {
                checkAbstractInExpr(expr.left, source, fileName, abstractClasses)
                checkAbstractInExpr(expr.right, source, fileName, abstractClasses)
            }
            is CallExpression -> {
                checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
                for (arg in expr.arguments) checkAbstractInExpr(arg, source, fileName, abstractClasses)
            }
            is ParenthesizedExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is ConditionalExpression -> {
                checkAbstractInExpr(expr.condition, source, fileName, abstractClasses)
                checkAbstractInExpr(expr.whenTrue, source, fileName, abstractClasses)
                checkAbstractInExpr(expr.whenFalse, source, fileName, abstractClasses)
            }
            is ArrowFunction -> expr.body?.let {
                when (it) {
                    is Block -> checkAbstractInStmts(it.statements, source, fileName, abstractClasses)
                    is Expression -> checkAbstractInExpr(it, source, fileName, abstractClasses)
                    else -> {}
                }
            }
            is FunctionExpression -> expr.body?.let { checkAbstractInStmts(it.statements, source, fileName, abstractClasses) }
            is ArrayLiteralExpression -> for (el in expr.elements) checkAbstractInExpr(el, source, fileName, abstractClasses)
            is ObjectLiteralExpression -> for (prop in expr.properties) {
                when (prop) {
                    is PropertyAssignment -> checkAbstractInExpr(prop.initializer, source, fileName, abstractClasses)
                    is SpreadAssignment -> checkAbstractInExpr(prop.expression, source, fileName, abstractClasses)
                    else -> {}
                }
            }
            is TemplateExpression -> for (span in expr.templateSpans) {
                checkAbstractInExpr(span.expression, source, fileName, abstractClasses)
            }
            is AsExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is TypeAssertionExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is PrefixUnaryExpression -> checkAbstractInExpr(expr.operand, source, fileName, abstractClasses)
            is PostfixUnaryExpression -> checkAbstractInExpr(expr.operand, source, fileName, abstractClasses)
            is PropertyAccessExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is ElementAccessExpression -> {
                checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
                checkAbstractInExpr(expr.argumentExpression, source, fileName, abstractClasses)
            }
            is SpreadElement -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is AwaitExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is VoidExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is DeleteExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is NonNullExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            is TypeOfExpression -> checkAbstractInExpr(expr.expression, source, fileName, abstractClasses)
            else -> {}
        }
    }

    private fun isAbstractClass(symbol: Symbol): Boolean {
        for (decl in symbol.declarations) {
            if (decl is ClassDeclaration && ModifierFlag.Abstract in decl.modifiers) {
                return true
            }
        }
        return false
    }

    // -----------------------------------------------------------------------
    // TS2420: Class incorrectly implements interface
    // -----------------------------------------------------------------------

    private fun checkClassImplementsInterface() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkImplementsClausesInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {
                // Circular type resolution — skip
            }
        }
    }

    private fun checkImplementsClausesInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> {
                checkImplementsClauses(stmt, source, fileName)
                // Check nested classes in members (class expressions inside methods are unlikely, but be safe)
            }
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    for (s in body.statements) checkImplementsClausesInStatement(s, source, fileName)
                }
            }
            else -> {}
        }
    }

    private fun checkImplementsClauses(classDecl: ClassDeclaration, source: String, fileName: String) {
        val implementsClauses = classDecl.heritageClauses?.filter {
            it.token == SyntaxKind.ImplementsKeyword
        } ?: return
        if (implementsClauses.isEmpty()) return

        val className = classDecl.name?.text ?: return

        // Collect class's OWN declared member names (not inherited from interfaces)
        val classMemberNames = mutableSetOf<String>()
        for (member in classDecl.members) {
            val memberName = when (member) {
                is PropertyDeclaration -> (member.name as? Identifier)?.text
                is MethodDeclaration -> (member.name as? Identifier)?.text
                is GetAccessor -> (member.name as? Identifier)?.text
                is SetAccessor -> (member.name as? Identifier)?.text
                is Constructor -> {
                    // Parameter properties count as class members
                    for (param in member.parameters) {
                        if (param.modifiers.isNotEmpty() && param.name is Identifier) {
                            classMemberNames.add((param.name as Identifier).text)
                        }
                    }
                    null
                }
                is IndexSignature -> null // handled separately
                else -> null
            }
            if (memberName != null) classMemberNames.add(memberName)
        }

        // Check if class has index signatures
        val hasStringIndex = classDecl.members.any {
            it is IndexSignature && it.parameters.firstOrNull()?.type?.let { t ->
                t is KeywordTypeNode && t.kind == SyntaxKind.StringKeyword
            } == true
        }
        val hasNumberIndex = classDecl.members.any {
            it is IndexSignature && it.parameters.firstOrNull()?.type?.let { t ->
                t is KeywordTypeNode && t.kind == SyntaxKind.NumberKeyword
            } == true
        }

        for (clause in implementsClauses) {
            for (typeExpr in clause.types) {
                val ifaceName = when (val tn = typeExpr.expression) {
                    is Identifier -> tn.text
                    is PropertyAccessExpression -> (tn.name as? Identifier)?.text
                    else -> null
                } ?: continue
                val ifaceSymbol = globals[ifaceName] ?: continue
                // Only check actual interfaces, not classes (TS2720 handles class-implementing-class)
                if (!ifaceSymbol.flags.hasAny(SymbolFlags.Interface)) continue
                val ifaceType = getDeclaredTypeOfSymbol(ifaceSymbol)
                if (ifaceType !is Type.Object) continue
                resolveStructuredTypeMembers(ifaceType)

                // Check each required interface property exists in class
                val ifaceProps = ifaceType.properties ?: continue
                for (ifaceProp in ifaceProps) {
                    val propName = ifaceProp.name

                    if (propName !in classMemberNames) {
                        // Property missing — emit TS2420
                        val isOptional = isOptionalProperty(ifaceProp)
                        if (isOptional) continue

                        val classNameNode = classDecl.name ?: continue
                        val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                        val message = "Class '$className' incorrectly implements interface '$ifaceName'."
                        val chain = mutableListOf<String>()
                        chain.add("  Property '$propName' is missing in type '$className' but required in type '$ifaceName'.")
                        // TS2728 related info: point to interface property declaration
                        val relatedInfo = ifaceProp.valueDeclaration?.let { decl ->
                            val declPos = when (decl) {
                                is PropertyDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                is MethodDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                else -> decl.pos
                            }
                            val declLength = when (decl) {
                                is PropertyDeclaration -> (decl.name as? Identifier)?.text?.length ?: propName.length
                                is MethodDeclaration -> (decl.name as? Identifier)?.text?.length ?: propName.length
                                else -> propName.length
                            }
                            val (rl, rc) = getLineAndCharacterOfPosition(source, declPos)
                            listOf(Diagnostic(
                                message = "'$propName' is declared here.",
                                category = DiagnosticCategory.Message,
                                code = 2728,
                                fileName = fileName,
                                line = rl,
                                character = rc,
                                start = declPos,
                                length = declLength,
                            ))
                        } ?: emptyList()

                        diagnostics.add(Diagnostic(
                            message = message,
                            category = DiagnosticCategory.Error,
                            code = 2420,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = classNameNode.pos,
                            length = className.length,
                            messageChain = chain,
                            relatedInformation = relatedInfo,
                        ))
                        return // One TS2420 per class is enough (TypeScript only reports first mismatch)
                    } else {
                        // Property exists — check if it's private (interface members are always public)
                        val classMember = classDecl.members.firstOrNull { m ->
                            when (m) {
                                is PropertyDeclaration -> (m.name as? Identifier)?.text == propName
                                is MethodDeclaration -> (m.name as? Identifier)?.text == propName
                                else -> false
                            }
                        }
                        val isPrivate = when (classMember) {
                            is PropertyDeclaration -> ModifierFlag.Private in classMember.modifiers
                            is MethodDeclaration -> ModifierFlag.Private in classMember.modifiers
                            else -> false
                        }
                        if (isPrivate) {
                            val classNameNode = classDecl.name ?: continue
                            val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                            val message = "Class '$className' incorrectly implements interface '$ifaceName'."
                            val chain = mutableListOf(
                                "  Property '$propName' is private in type '$className' but not in type '$ifaceName'."
                            )
                            diagnostics.add(Diagnostic(
                                message = message,
                                category = DiagnosticCategory.Error,
                                code = 2420,
                                fileName = fileName,
                                line = line,
                                character = character,
                                start = classNameNode.pos,
                                length = className.length,
                                messageChain = chain,
                            ))
                            return
                        }
                    }
                }

                // Check index signatures
                val ifaceStringIdx = ifaceType.stringIndexInfo
                val ifaceNumberIdx = ifaceType.numberIndexInfo
                if (ifaceNumberIdx != null && !hasNumberIndex && !hasStringIndex) {
                    val classNameNode = classDecl.name ?: continue
                    val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                    val message = "Class '$className' incorrectly implements interface '$ifaceName'."
                    val chain = mutableListOf("  Index signature for type 'number' is missing in type '$className'.")
                    diagnostics.add(Diagnostic(
                        message = message,
                        category = DiagnosticCategory.Error,
                        code = 2420,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = classNameNode.pos,
                        length = className.length,
                        messageChain = chain,
                    ))
                    return
                }
                if (ifaceStringIdx != null && !hasStringIndex) {
                    val classNameNode = classDecl.name ?: continue
                    val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
                    val message = "Class '$className' incorrectly implements interface '$ifaceName'."
                    val chain = mutableListOf("  Index signature for type 'string' is missing in type '$className'.")
                    diagnostics.add(Diagnostic(
                        message = message,
                        category = DiagnosticCategory.Error,
                        code = 2420,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = classNameNode.pos,
                        length = className.length,
                        messageChain = chain,
                    ))
                    return
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // TS2430: Interface incorrectly extends interface
    // -----------------------------------------------------------------------

    private fun checkInterfaceExtendsInterface() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkInterfaceExtendsInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {}
        }
    }

    private fun checkInterfaceExtendsInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is InterfaceDeclaration -> checkInterfaceExtendsClauses(stmt, source, fileName)
            is ModuleDeclaration -> (stmt.body as? ModuleBlock)?.let {
                for (s in it.statements) checkInterfaceExtendsInStatement(s, source, fileName)
            }
            else -> {}
        }
    }

    private fun checkInterfaceExtendsClauses(ifaceDecl: InterfaceDeclaration, source: String, fileName: String) {
        val extendsClauses = ifaceDecl.heritageClauses?.filter {
            it.token == SyntaxKind.ExtendsKeyword
        } ?: return
        if (extendsClauses.isEmpty()) return

        val derivedName = ifaceDecl.name.text

        // Collect derived interface's property types from AST
        val derivedProps = mutableMapOf<String, TypeNode>()
        for (member in ifaceDecl.members) {
            val (name, type) = getMemberNameAndType(member) ?: continue
            if (type != null) derivedProps[name] = type
        }
        if (derivedProps.isEmpty()) return

        for (clause in extendsClauses) {
            for (typeExpr in clause.types) {
                val baseName = when (val tn = typeExpr.expression) {
                    is Identifier -> tn.text
                    is PropertyAccessExpression -> (tn.name as? Identifier)?.text
                    else -> null
                } ?: continue

                val baseSymbol = globals[baseName] ?: continue
                if (!baseSymbol.flags.hasAny(SymbolFlags.Interface)) continue

                // Get base interface type and resolve members
                val baseType = getDeclaredTypeOfSymbol(baseSymbol)
                if (baseType !is Type.Object) continue
                resolveStructuredTypeMembers(baseType)
                val baseProps = baseType.properties ?: continue

                // Compare each derived property against matching base property
                for (baseProp in baseProps) {
                    val propName = baseProp.name
                    val derivedType = derivedProps[propName] ?: continue

                    // Get base property's type
                    val basePropType = getTypeOfSymbol(baseProp)
                    if (basePropType === anyType || basePropType === errorType) continue

                    // Get the base type name for error message
                    val baseTypeName = typeToString(basePropType)

                    // Get derived type name from AST type node
                    val derivedTypeName = typeNodeToSimpleName(derivedType) ?: continue

                    // Skip if same type name
                    if (derivedTypeName == baseTypeName) continue

                    // Check if clearly incompatible using keyword types
                    if (derivedType is KeywordTypeNode) {
                        val derivedSemanticType = getTypeFromKeyword(derivedType.kind)
                        if (derivedSemanticType !== anyType && derivedSemanticType !== errorType) {
                            // Use structural comparison
                            if (!isTypeAssignableTo(derivedSemanticType, basePropType)) {
                                emitTS2430(ifaceDecl.name, derivedName, baseName, propName,
                                    derivedTypeName, baseTypeName, source, fileName)
                                return // One TS2430 per interface per base
                            }
                        }
                    } else {
                        // For non-keyword types, use string comparison as fallback
                        // Only flag if both are simple known type names that differ
                        val derivedResolvedType = getTypeFromTypeNodeSafe(derivedType)
                        if (derivedResolvedType != null && derivedResolvedType !== anyType && derivedResolvedType !== errorType) {
                            if (!isTypeAssignableTo(derivedResolvedType, basePropType)) {
                                emitTS2430(ifaceDecl.name, derivedName, baseName, propName,
                                    derivedTypeName, baseTypeName, source, fileName)
                                return
                            }
                        }
                    }
                }
            }
        }
    }

    private fun getMemberNameAndType(member: ClassElement): Pair<String, TypeNode?>? {
        return when (member) {
            is PropertyDeclaration -> {
                val name = (member.name as? Identifier)?.text ?: return null
                name to member.type
            }
            is MethodDeclaration -> {
                val name = (member.name as? Identifier)?.text ?: return null
                name to member.type // return type
            }
            else -> null
        }
    }

    private fun typeNodeToSimpleName(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.ObjectKeyword -> "object"
                else -> null
            }
            is TypeReference -> (typeNode.typeName as? Identifier)?.text
            else -> null
        }
    }

    private fun getTypeFromTypeNodeSafe(typeNode: TypeNode): Type? {
        return try {
            getTypeFromTypeNode(typeNode)
        } catch (_: StackOverflowError) {
            null
        }
    }

    private fun emitTS2430(
        nameNode: Identifier, derivedName: String, baseName: String, propName: String,
        derivedTypeName: String, baseTypeName: String, source: String, fileName: String,
    ) {
        val start = nameNode.pos
        val length = derivedName.length
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        diagnostics.add(Diagnostic(
            message = "Interface '$derivedName' incorrectly extends interface '$baseName'.",
            category = DiagnosticCategory.Error,
            code = 2430,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = listOf(
                "  Types of property '$propName' are incompatible.",
                "    Type '$derivedTypeName' is not assignable to type '$baseTypeName'.",
            ),
        ))
    }

    // -----------------------------------------------------------------------
    // TS2416: Property type incompatible with base type
    // -----------------------------------------------------------------------

    private fun checkPropertyOverride() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                for (stmt in result.sourceFile.statements) {
                    checkPropertyOverrideInStatement(stmt, source, fileName)
                }
            } catch (_: StackOverflowError) {
                // Circular type resolution — skip
            }
        }
    }

    private fun checkPropertyOverrideInStatement(stmt: Statement, source: String, fileName: String) {
        when (stmt) {
            is ClassDeclaration -> checkClassPropertyOverrides(stmt, source, fileName)
            is ModuleDeclaration -> {
                val body = stmt.body
                if (body is ModuleBlock) {
                    for (s in body.statements) checkPropertyOverrideInStatement(s, source, fileName)
                }
            }
            else -> {}
        }
    }

    private fun checkClassPropertyOverrides(classDecl: ClassDeclaration, source: String, fileName: String) {
        val heritageClauses = classDecl.heritageClauses ?: return
        val rawClassName = classDecl.name?.text ?: return
        val classTypeParams = classDecl.typeParameters
        val className = if (classTypeParams != null && classTypeParams.isNotEmpty()) {
            "$rawClassName<${classTypeParams.joinToString(", ") { it.name.text }}>"
        } else rawClassName

        for (clause in heritageClauses) {
            for (typeExpr in clause.types) {
                val baseName = when (val tn = typeExpr.expression) {
                    is Identifier -> tn.text
                    is PropertyAccessExpression -> (tn.name as? Identifier)?.text
                    else -> null
                } ?: continue

                val baseSymbol = globals[baseName] ?: continue
                val baseType = getDeclaredTypeOfSymbol(baseSymbol)
                if (baseType !is Type.Object) continue
                resolveStructuredTypeMembers(baseType)
                val baseMembers = baseType.members ?: continue

                val baseTypeName = typeToString(baseType)

                // TS2415: Check private member conflicts (only for extends, not implements)
                if (clause.token == SyntaxKind.ExtendsKeyword) {
                    val ts2415Emitted = checkClassExtendsPrivateConflicts(
                        classDecl, baseName, baseType, baseMembers, source, fileName
                    )
                    if (ts2415Emitted) continue // skip TS2416 checks for this base
                }

                // Collect method names that appear multiple times (overloads) — skip these
                val overloadedMethods = mutableMapOf<String, Int>()
                for (member in classDecl.members) {
                    if (member is MethodDeclaration) {
                        val name = (member.name as? Identifier)?.text ?: continue
                        overloadedMethods[name] = (overloadedMethods[name] ?: 0) + 1
                    }
                }

                for (member in classDecl.members) {
                    // Skip static members
                    val isStatic = when (member) {
                        is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                        is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                        is GetAccessor -> ModifierFlag.Static in member.modifiers
                        is SetAccessor -> ModifierFlag.Static in member.modifiers
                        else -> true
                    }
                    if (isStatic) continue

                    val memberName = when (member) {
                        is PropertyDeclaration -> (member.name as? Identifier)?.text
                        is MethodDeclaration -> (member.name as? Identifier)?.text
                        is GetAccessor -> (member.name as? Identifier)?.text
                        is SetAccessor -> (member.name as? Identifier)?.text
                        else -> null
                    } ?: continue

                    // Skip overloaded methods (need full overload resolution)
                    if (member is MethodDeclaration && (overloadedMethods[memberName] ?: 0) > 1) continue

                    val basePropSymbol = baseMembers[memberName] ?: continue

                    // Skip if base member has multiple declarations (overloads)
                    if (basePropSymbol.declarations.size > 1) continue

                    val derivedType = getTypeOfMemberDecl(member) ?: continue
                    val basePropType = getTypeOfMemberDecl(
                        basePropSymbol.valueDeclaration ?: basePropSymbol.declarations.firstOrNull() ?: continue
                    ) ?: continue

                    if (derivedType === anyType || basePropType === anyType) continue

                    if (!checkTypeRelatedTo(derivedType, basePropType, assignableRelation)) {
                        val nameNode = when (member) {
                            is PropertyDeclaration -> member.name
                            is MethodDeclaration -> member.name
                            is GetAccessor -> member.name
                            is SetAccessor -> member.name
                            else -> null
                        } ?: continue

                        val (line, character) = getLineAndCharacterOfPosition(source, nameNode.pos)
                        val message = "Property '$memberName' in type '$className' is not assignable to the same property in base type '$baseTypeName'."
                        val chain = mutableListOf<String>()
                        chain.add("  Type '${typeToString(derivedType)}' is not assignable to type '${typeToString(basePropType)}'.")

                        // Add signature elaboration for function types
                        addSignatureElaboration(derivedType, basePropType, chain)

                        diagnostics.add(Diagnostic(
                            message = message,
                            category = DiagnosticCategory.Error,
                            code = 2416,
                            fileName = fileName,
                            line = line,
                            character = character,
                            start = nameNode.pos,
                            length = memberName.length,
                            messageChain = chain,
                        ))
                    }
                }
            }
        }
    }

    /**
     * TS2415: Check private member conflicts between derived class and base class.
     * Returns true if a TS2415 diagnostic was emitted (so TS2416 should be skipped).
     */
    private fun checkClassExtendsPrivateConflicts(
        classDecl: ClassDeclaration,
        baseName: String,
        baseType: Type.Object,
        baseMembers: SymbolTable,
        source: String,
        fileName: String,
    ): Boolean {
        val rawClassName = classDecl.name?.text ?: return false
        val classNameNode = classDecl.name ?: return false

        for (member in classDecl.members) {
            // Skip static members
            val isStatic = when (member) {
                is PropertyDeclaration -> ModifierFlag.Static in member.modifiers
                is MethodDeclaration -> ModifierFlag.Static in member.modifiers
                is GetAccessor -> ModifierFlag.Static in member.modifiers
                is SetAccessor -> ModifierFlag.Static in member.modifiers
                else -> true
            }
            if (isStatic) continue

            val memberName = when (member) {
                is PropertyDeclaration -> (member.name as? Identifier)?.text
                is MethodDeclaration -> (member.name as? Identifier)?.text
                is GetAccessor -> (member.name as? Identifier)?.text
                is SetAccessor -> (member.name as? Identifier)?.text
                else -> null
            } ?: continue

            val baseMemberSym = baseMembers[memberName] ?: continue
            val baseDecl = baseMemberSym.valueDeclaration ?: baseMemberSym.declarations.firstOrNull() ?: continue

            val derivedIsPrivate = isMemberPrivate(member)
            val baseIsPrivate = isMemberPrivate(baseDecl)

            if (!derivedIsPrivate && !baseIsPrivate) continue

            val (line, character) = getLineAndCharacterOfPosition(source, classNameNode.pos)
            val chain = mutableListOf<String>()

            if (derivedIsPrivate && baseIsPrivate) {
                // Both private from different classes → separate declarations
                chain.add("  Types have separate declarations of a private property '$memberName'.")
            } else {
                // One is private, other isn't
                // Find the declaring class for the base member (may be grandparent)
                val baseDeclaringClass = if (baseIsPrivate) {
                    findPrivateDeclaringClassName(baseType, memberName) ?: baseName
                } else {
                    findDeclaringClassName(baseType, memberName) ?: baseName
                }
                val privateTypeName = if (baseIsPrivate) baseDeclaringClass else rawClassName
                val publicTypeName = if (baseIsPrivate) rawClassName else baseDeclaringClass
                chain.add("  Property '$memberName' is private in type '$privateTypeName' but not in type '$publicTypeName'.")
            }

            diagnostics.add(Diagnostic(
                message = "Class '$rawClassName' incorrectly extends base class '$baseName'.",
                category = DiagnosticCategory.Error,
                code = 2415,
                fileName = fileName,
                line = line,
                character = character,
                start = classNameNode.pos,
                length = rawClassName.length,
                messageChain = chain,
            ))
            return true // Only report first conflict per class
        }
        return false
    }

    /** Check if a class member (AST node) has the `private` modifier. */
    private fun isMemberPrivate(node: Node): Boolean = when (node) {
        is PropertyDeclaration -> ModifierFlag.Private in node.modifiers
        is MethodDeclaration -> ModifierFlag.Private in node.modifiers
        is GetAccessor -> ModifierFlag.Private in node.modifiers
        is SetAccessor -> ModifierFlag.Private in node.modifiers
        is Parameter -> ModifierFlag.Private in node.modifiers
        else -> false
    }

    /** Walk the base type chain to find the class name where a member is declared as private. */
    private fun findPrivateDeclaringClassName(type: Type.Object, memberName: String): String? {
        if (type is Type.Interface) {
            val symbol = type.symbol
            if (symbol != null) {
                for (decl in symbol.declarations) {
                    val members = when (decl) {
                        is ClassDeclaration -> decl.members
                        else -> continue
                    }
                    for (member in members) {
                        val name = when (member) {
                            is PropertyDeclaration -> (member.name as? Identifier)?.text
                            is MethodDeclaration -> (member.name as? Identifier)?.text
                            is GetAccessor -> (member.name as? Identifier)?.text
                            is SetAccessor -> (member.name as? Identifier)?.text
                            else -> null
                        }
                        if (name == memberName && isMemberPrivate(member)) {
                            return symbol.name
                        }
                    }
                }
            }
            // Walk base types
            type.baseTypes?.forEach { bt ->
                if (bt is Type.Object) {
                    val result = findPrivateDeclaringClassName(bt, memberName)
                    if (result != null) return result
                }
            }
        }
        return null
    }

    /** Walk the base type chain to find the class name where a member is declared (any visibility). */
    private fun findDeclaringClassName(type: Type.Object, memberName: String): String? {
        if (type is Type.Interface) {
            val symbol = type.symbol
            if (symbol != null) {
                for (decl in symbol.declarations) {
                    val members = when (decl) {
                        is ClassDeclaration -> decl.members
                        else -> continue
                    }
                    for (member in members) {
                        val name = when (member) {
                            is PropertyDeclaration -> (member.name as? Identifier)?.text
                            is MethodDeclaration -> (member.name as? Identifier)?.text
                            is GetAccessor -> (member.name as? Identifier)?.text
                            is SetAccessor -> (member.name as? Identifier)?.text
                            else -> null
                        }
                        if (name == memberName) return symbol.name
                    }
                }
            }
            type.baseTypes?.forEach { bt ->
                if (bt is Type.Object) {
                    val result = findDeclaringClassName(bt, memberName)
                    if (result != null) return result
                }
            }
        }
        return null
    }

    /** Get the type of a class member from its AST declaration. */
    private fun getTypeOfMemberDecl(decl: Node): Type? {
        return when (decl) {
            is PropertyDeclaration -> {
                decl.type?.let { return getTypeFromTypeNode(it) }
                // Infer type from initializer if no annotation
                decl.initializer?.let { init ->
                    val t = getTypeOfExpression(init)
                    if (t !== anyType) t else null
                }
            }
            is MethodDeclaration -> {
                // Use void return for methods with body that don't return a value
                val hasBodyNoReturn = decl.body != null && !bodyHasReturnValue(decl.body!!)
                buildMethodType(decl.parameters, decl.type, decl.typeParameters, hasBody = hasBodyNoReturn)
            }
            is GetAccessor -> decl.type?.let { getTypeFromTypeNode(it) }
            is SetAccessor -> decl.parameters.firstOrNull()?.type?.let { getTypeFromTypeNode(it) }
            is Parameter -> decl.type?.let { getTypeFromTypeNode(it) }
            else -> null
        }
    }

    /** Build a function type (Object with call signature) from method parameters and return type. */
    private fun buildMethodType(
        params: List<Parameter>,
        returnTypeNode: TypeNode?,
        typeParams: List<TypeParameter>? = null,
        hasBody: Boolean = false,
    ): Type {
        val fnType = Type.Object()
        val defaultReturn = if (hasBody) voidType else anyType
        val returnType = returnTypeNode?.let { getTypeFromTypeNode(it) } ?: defaultReturn
        val typeParameters = typeParams?.map { tp ->
            val param = Type.TypeParam()
            param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
            tp.constraint?.let { param.constraint = getTypeFromTypeNode(it) }
            tp.default?.let { param.default = getTypeFromTypeNode(it) }
            param
        }
        // Build parameter symbols with initializer type inference
        val paramSymbols = params.mapNotNull { param ->
            val name = when (val n = param.name) {
                is Identifier -> if (n.text == "this") return@mapNotNull null else n.text
                else -> return@mapNotNull null
            }
            val sym = Symbol(SymbolFlags.FunctionScopedVariable, name)
            sym.declarations.add(param)
            sym.valueDeclaration = param
            // If no type annotation, infer from initializer
            if (param.type == null && param.initializer != null) {
                val initType = getTypeOfExpression(param.initializer!!)
                if (initType !== anyType) {
                    symbolTypes[sym.id] = initType
                }
            }
            sym
        }
        val sig = Signature(
            typeParameters = typeParameters,
            parameters = paramSymbols,
            resolvedReturnType = returnType,
            minArgumentCount = params.count {
                !it.questionToken && !it.dotDotDotToken && it.initializer == null
            },
        )
        fnType.callSignatures = listOf(sig)
        return fnType
    }

    /** Check if a function body contains any `return expr` (return with a value). */
    private fun bodyHasReturnValue(body: Node): Boolean {
        return when (body) {
            is ReturnStatement -> body.expression != null
            is Block -> body.statements.any { bodyHasReturnValue(it) }
            is IfStatement -> bodyHasReturnValue(body.thenStatement) ||
                (body.elseStatement?.let { bodyHasReturnValue(it) } ?: false)
            is SwitchStatement -> body.caseBlock.any { node ->
                if (node is CaseClause) node.statements.any { bodyHasReturnValue(it) }
                else if (node is DefaultClause) node.statements.any { bodyHasReturnValue(it) }
                else false
            }
            else -> false
        }
    }

    /** Add signature-level elaboration for function type mismatches in TS2416 chains. */
    private fun addSignatureElaboration(derivedType: Type, basePropType: Type, chain: MutableList<String>) {
        if (derivedType !is Type.Object || basePropType !is Type.Object) return
        val derivedSigs = derivedType.callSignatures
        val baseSigs = basePropType.callSignatures
        if (derivedSigs.isNullOrEmpty() || baseSigs.isNullOrEmpty()) return
        val derivedSig = derivedSigs.first()
        val baseSig = baseSigs.first()
        // Check parameter count mismatch
        if (derivedSig.minArgumentCount > baseSig.parameters.size) {
            chain.add("    Target signature provides too few arguments. Expected ${derivedSig.parameters.size} or more, but got ${baseSig.parameters.size}.")
            return
        }
        // Check return type mismatch
        val sourceReturn = derivedSig.resolvedReturnType ?: anyType
        val targetReturn = baseSig.resolvedReturnType ?: anyType
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, assignableRelation)) {
            chain.add("    Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.")
        }
    }

    // -----------------------------------------------------------------------
    // TS2344: Type does not satisfy the constraint
    // -----------------------------------------------------------------------

    private fun checkTypeArgumentConstraints() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            val source = result.sourceFile.text
            try {
                checkConstraintsInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {
                // Circular type resolution — skip
            }
        }
    }

    private fun checkConstraintsInStatements(stmts: List<Statement>, source: String, fileName: String) {
        for (stmt in stmts) {
            // Visit type nodes in declarations
            when (stmt) {
                is VariableStatement -> {
                    for (decl in stmt.declarationList.declarations) {
                        decl.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                    }
                }
                is FunctionDeclaration -> {
                    stmt.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                    stmt.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
                    stmt.body?.let { checkConstraintsInStatements(it.statements, source, fileName) }
                }
                is ClassDeclaration -> {
                    stmt.heritageClauses?.forEach { clause ->
                        clause.types.forEach { checkConstraintsInExprWithTypeArgs(it, source, fileName) }
                    }
                    for (member in stmt.members) {
                        when (member) {
                            is PropertyDeclaration -> member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                            is MethodDeclaration -> {
                                member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                                member.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
                            }
                            else -> {}
                        }
                    }
                }
                is InterfaceDeclaration -> {
                    stmt.heritageClauses?.forEach { clause ->
                        clause.types.forEach { checkConstraintsInExprWithTypeArgs(it, source, fileName) }
                    }
                    for (member in stmt.members) {
                        when (member) {
                            is PropertyDeclaration -> member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                            is MethodDeclaration -> {
                                member.type?.let { checkConstraintsInTypeNode(it, source, fileName) }
                                member.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
                            }
                            else -> {}
                        }
                    }
                }
                is TypeAliasDeclaration -> checkConstraintsInTypeNode(stmt.type, source, fileName)
                is ModuleDeclaration -> {
                    (stmt.body as? ModuleBlock)?.let { checkConstraintsInStatements(it.statements, source, fileName) }
                }
                else -> {}
            }
        }
    }

    private fun checkConstraintsInExprWithTypeArgs(node: ExpressionWithTypeArguments, source: String, fileName: String) {
        val typeArgs = node.typeArguments ?: return
        val name = when (val expr = node.expression) {
            is Identifier -> expr.text
            else -> return
        }
        // TS2315: check if type is not generic (only for class/interface/type alias/module, not variables)
        if (name !in BUILTIN_GENERICS) {
            val symbol = globals[name]
            if (symbol != null && symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Module)) {
                val typeParams = getTypeParametersOfSymbol(symbol)
                if (typeParams == null || typeParams.isEmpty()) {
                    val start = node.pos
                    val length = node.end - start
                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                    diagnostics.add(Diagnostic(
                        message = "Type '$name' is not generic.",
                        category = DiagnosticCategory.Error,
                        code = 2315,
                        fileName = fileName,
                        line = line,
                        character = character,
                        start = start,
                        length = length,
                    ))
                }
            }
        }
        checkConstraintsForTypeArgs(name, typeArgs, source, fileName)
    }

    private fun checkConstraintsInTypeNode(node: TypeNode, source: String, fileName: String) {
        when (node) {
            is TypeReference -> {
                val typeArgs = node.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    val name = getTypeReferenceLastName(node.typeName)
                    if (name != null) {
                        // TS2315: check if type is not generic (only for type declarations, not variables)
                        if (name !in BUILTIN_GENERICS) {
                            val symbol = resolveTypeNameToSymbol(node.typeName) ?: globals[name]
                            if (symbol != null && symbol.flags.hasAny(SymbolFlags.Class or SymbolFlags.Interface or SymbolFlags.TypeAlias or SymbolFlags.Module)) {
                                val typeParams = getTypeParametersOfSymbol(symbol)
                                if (typeParams == null || typeParams.isEmpty()) {
                                    // Type is not generic but type arguments were provided
                                    val start = node.pos
                                    // node.end overshoots — compute true end from last type arg
                                    // lastArg.end already points past the arg; the '>' is at lastArg.end
                                    val lastArg = typeArgs.last()
                                    val length = lastArg.end - start
                                    val (line, character) = getLineAndCharacterOfPosition(source, start)
                                    diagnostics.add(Diagnostic(
                                        message = "Type '$name' is not generic.",
                                        category = DiagnosticCategory.Error,
                                        code = 2315,
                                        fileName = fileName,
                                        line = line,
                                        character = character,
                                        start = start,
                                        length = length,
                                    ))
                                }
                            }
                        }
                        checkConstraintsForTypeArgs(name, typeArgs, source, fileName)
                    }
                    // Recurse into type arguments
                    typeArgs.forEach { checkConstraintsInTypeNode(it, source, fileName) }
                }
            }
            is UnionType -> node.types.forEach { checkConstraintsInTypeNode(it, source, fileName) }
            is IntersectionType -> node.types.forEach { checkConstraintsInTypeNode(it, source, fileName) }
            is ArrayType -> checkConstraintsInTypeNode(node.elementType, source, fileName)
            is FunctionType -> {
                checkConstraintsInTypeNode(node.type, source, fileName)
                node.parameters.forEach { p -> p.type?.let { checkConstraintsInTypeNode(it, source, fileName) } }
            }
            is ParenthesizedType -> checkConstraintsInTypeNode(node.type, source, fileName)
            else -> {}
        }
    }

    private fun checkConstraintsForTypeArgs(
        typeName: String, typeArgs: List<TypeNode>,
        source: String, fileName: String
    ) {
        // Skip built-in generics (Array, Promise, etc.)
        if (typeName in BUILTIN_GENERICS) return

        val symbol = globals[typeName] ?: return
        // Find type parameters from the declaration
        val typeParams = getTypeParametersOfSymbol(symbol) ?: return
        if (typeParams.isEmpty()) return

        val len = minOf(typeArgs.size, typeParams.size)
        for (i in 0 until len) {
            val typeParam = typeParams[i]
            val constraint = typeParam.constraint ?: continue
            val argType = getTypeFromTypeNode(typeArgs[i])
            if (argType === anyType || argType === errorType) continue
            val constraintType = constraint
            if (constraintType === anyType || constraintType === errorType) continue

            if (!checkTypeRelatedTo(argType, constraintType, assignableRelation)) {
                val argNode = typeArgs[i]
                val argDisplay = formatTypeForDisplay(argNode) ?: typeToString(argType)
                val constraintDisplay = typeToString(constraintType)
                val (line, character) = getLineAndCharacterOfPosition(source, argNode.pos)
                val message = "Type '$argDisplay' does not satisfy the constraint '$constraintDisplay'."
                val chain = mutableListOf<String>()
                val relatedInfo = mutableListOf<Diagnostic>()

                // Add elaboration for missing properties
                if (argType is Type.Object && constraintType is Type.Object) {
                    resolveStructuredTypeMembers(argType)
                    resolveStructuredTypeMembers(constraintType)
                    val constraintProps = constraintType.properties ?: emptyList()
                    val argMembers = argType.members
                    for (cp in constraintProps) {
                        if (isOptionalProperty(cp)) continue
                        if (argMembers == null || cp.name !in argMembers) {
                            chain.add("  Property '${cp.name}' is missing in type '$argDisplay' but required in type '$constraintDisplay'.")
                            // TS2728 related info: point to constraint property declaration
                            cp.valueDeclaration?.let { decl ->
                                val declPos = when (decl) {
                                    is PropertyDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                    is MethodDeclaration -> (decl.name as? Identifier)?.pos ?: decl.pos
                                    else -> decl.pos
                                }
                                val declLength = when (decl) {
                                    is PropertyDeclaration -> (decl.name as? Identifier)?.text?.length ?: cp.name.length
                                    is MethodDeclaration -> (decl.name as? Identifier)?.text?.length ?: cp.name.length
                                    else -> cp.name.length
                                }
                                val (rl, rc) = getLineAndCharacterOfPosition(source, declPos)
                                relatedInfo.add(Diagnostic(
                                    message = "'${cp.name}' is declared here.",
                                    category = DiagnosticCategory.Message,
                                    code = 2728,
                                    fileName = fileName,
                                    line = rl,
                                    character = rc,
                                    start = declPos,
                                    length = declLength,
                                ))
                            }
                            break
                        }
                    }
                }

                diagnostics.add(Diagnostic(
                    message = message,
                    category = DiagnosticCategory.Error,
                    code = 2344,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = argNode.pos,
                    length = argDisplay.length,
                    messageChain = chain,
                    relatedInformation = relatedInfo,
                ))
            }
        }
    }

    /** Get type parameters from a symbol's declarations (class, interface, or type alias). */
    private fun getTypeParametersOfSymbol(symbol: Symbol): List<Type.TypeParam>? {
        // Follow alias if this is an import alias
        val resolved = if (symbol.flags.hasAny(SymbolFlags.Alias)) {
            try { resolveAlias(symbol) } catch (_: StackOverflowError) { symbol }
        } else symbol
        for (decl in resolved.declarations) {
            val typeParamNodes = when (decl) {
                is ClassDeclaration -> decl.typeParameters
                is InterfaceDeclaration -> decl.typeParameters
                is TypeAliasDeclaration -> decl.typeParameters
                is FunctionDeclaration -> decl.typeParameters
                else -> null
            } ?: continue
            if (typeParamNodes.isEmpty()) continue
            return typeParamNodes.map { tp ->
                val param = Type.TypeParam()
                param.symbol = Symbol(SymbolFlags.TypeParameter, tp.name.text)
                tp.constraint?.let { param.constraint = getTypeFromTypeNode(it) }
                tp.default?.let { param.default = getTypeFromTypeNode(it) }
                param
            }
        }
        return null
    }

    // -----------------------------------------------------------------------
    // TS2339: Property does not exist on type (Phase 4 item 5a)
    // -----------------------------------------------------------------------

    private fun checkPropertyAccess() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip .js files — property access patterns differ
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx")) continue
            val source = result.sourceFile.text
            try {
                checkPropertyAccessInStatements(
                    result.sourceFile.statements, source, fileName,
                    enclosingClassType = null
                )
            } catch (_: StackOverflowError) {
                // Circular type resolution in complex files — skip gracefully
            }
        }
    }

    private fun checkPropertyAccessInStatements(
        stmts: List<Statement>, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        for (stmt in stmts) checkPropertyAccessInStatement(stmt, source, fileName, enclosingClassType)
    }

    private fun checkPropertyAccessInStatement(
        stmt: Statement, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        when (stmt) {
            is ClassDeclaration -> {
                // Resolve the class type for "this" inside class body
                val classType = if (stmt.name != null) {
                    val symbol = globals[stmt.name.text]
                    if (symbol != null) getDeclaredTypeOfSymbol(symbol) else null
                } else null
                for (member in stmt.members) {
                    checkPropertyAccessInClassMember(member, source, fileName, classType)
                }
            }
            is InterfaceDeclaration -> { /* No runtime property access in interfaces */ }
            is FunctionDeclaration -> {
                stmt.body?.let {
                    checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType = null)
                }
            }
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let {
                        checkPropertyAccessInExpr(it, source, fileName, enclosingClassType)
                    }
                }
            }
            is ExpressionStatement -> checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
            is ReturnStatement -> stmt.expression?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            is IfStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.thenStatement, source, fileName, enclosingClassType)
                stmt.elseStatement?.let { checkPropertyAccessInStatement(it, source, fileName, enclosingClassType) }
            }
            is Block -> checkPropertyAccessInStatements(stmt.statements, source, fileName, enclosingClassType)
            is ForStatement -> {
                stmt.condition?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
                stmt.incrementor?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is ForInStatement -> checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            is ForOfStatement -> checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            is WhileStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is DoStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is SwitchStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                for (clause in stmt.caseBlock) {
                    when (clause) {
                        is CaseClause -> {
                            checkPropertyAccessInExpr(clause.expression, source, fileName, enclosingClassType)
                            checkPropertyAccessInStatements(clause.statements, source, fileName, enclosingClassType)
                        }
                        is DefaultClause -> {
                            checkPropertyAccessInStatements(clause.statements, source, fileName, enclosingClassType)
                        }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkPropertyAccessInStatements(stmt.tryBlock.statements, source, fileName, enclosingClassType)
                stmt.catchClause?.block?.let { checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType) }
                stmt.finallyBlock?.let { checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType) }
            }
            is ThrowStatement -> stmt.expression?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            is WithStatement -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            }
            is LabeledStatement -> checkPropertyAccessInStatement(stmt.statement, source, fileName, enclosingClassType)
            is ModuleDeclaration -> {
                (stmt.body as? Block)?.let {
                    checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType)
                }
            }
            is ExportAssignment -> {
                checkPropertyAccessInExpr(stmt.expression, source, fileName, enclosingClassType)
            }
            else -> { /* no property access in other statement types */ }
        }
    }

    private fun checkPropertyAccessInClassMember(
        member: ClassElement, source: String, fileName: String,
        classType: Type?,
    ) {
        when (member) {
            is MethodDeclaration -> {
                member.body?.let {
                    checkPropertyAccessInStatements(it.statements, source, fileName, classType)
                }
            }
            is Constructor -> {
                member.body?.let {
                    checkPropertyAccessInStatements(it.statements, source, fileName, classType)
                }
            }
            is GetAccessor -> {
                member.body?.let {
                    checkPropertyAccessInStatements(it.statements, source, fileName, classType)
                }
            }
            is SetAccessor -> {
                member.body?.let {
                    checkPropertyAccessInStatements(it.statements, source, fileName, classType)
                }
            }
            is PropertyDeclaration -> {
                member.initializer?.let {
                    checkPropertyAccessInExpr(it, source, fileName, classType)
                }
            }
            else -> {}
        }
    }

    private fun checkPropertyAccessInExpr(
        expr: Expression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        when (expr) {
            is PropertyAccessExpression -> {
                // First recurse into subexpressions
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                // Now check this property access
                checkSinglePropertyAccess(expr, source, fileName, enclosingClassType)
            }
            is CallExpression -> {
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                expr.arguments?.forEach { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            }
            is BinaryExpression -> {
                checkPropertyAccessInExpr(expr.left, source, fileName, enclosingClassType)
                checkPropertyAccessInExpr(expr.right, source, fileName, enclosingClassType)
            }
            is ConditionalExpression -> {
                checkPropertyAccessInExpr(expr.condition, source, fileName, enclosingClassType)
                checkPropertyAccessInExpr(expr.whenTrue, source, fileName, enclosingClassType)
                checkPropertyAccessInExpr(expr.whenFalse, source, fileName, enclosingClassType)
            }
            is ParenthesizedExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is ArrowFunction -> {
                expr.body.let { body ->
                    when (body) {
                        is Block -> checkPropertyAccessInStatements(body.statements, source, fileName, enclosingClassType)
                        is Expression -> checkPropertyAccessInExpr(body, source, fileName, enclosingClassType)
                        else -> {}
                    }
                }
            }
            is NewExpression -> {
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                expr.arguments?.forEach { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            }
            is ElementAccessExpression -> {
                checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
                checkPropertyAccessInExpr(expr.argumentExpression, source, fileName, enclosingClassType)
            }
            is AsExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is NonNullExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is PrefixUnaryExpression -> checkPropertyAccessInExpr(expr.operand, source, fileName, enclosingClassType)
            is TemplateExpression -> {
                expr.templateSpans.forEach { span ->
                    checkPropertyAccessInExpr(span.expression, source, fileName, enclosingClassType)
                }
            }
            is ArrayLiteralExpression -> {
                expr.elements.forEach { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkPropertyAccessInExpr(prop.initializer, source, fileName, enclosingClassType)
                        is ShorthandPropertyAssignment -> {}
                        is SpreadAssignment -> checkPropertyAccessInExpr(prop.expression, source, fileName, enclosingClassType)
                        else -> {}
                    }
                }
            }
            is TaggedTemplateExpression -> {
                checkPropertyAccessInExpr(expr.tag, source, fileName, enclosingClassType)
            }
            is TypeAssertionExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is SpreadElement -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is AwaitExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is DeleteExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is VoidExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is TypeOfExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is PostfixUnaryExpression -> checkPropertyAccessInExpr(expr.operand, source, fileName, enclosingClassType)
            is SatisfiesExpression -> checkPropertyAccessInExpr(expr.expression, source, fileName, enclosingClassType)
            is YieldExpression -> expr.expression?.let { checkPropertyAccessInExpr(it, source, fileName, enclosingClassType) }
            is FunctionExpression -> {
                expr.body?.let { checkPropertyAccessInStatements(it.statements, source, fileName, enclosingClassType = null) }
            }
            else -> {}
        }
    }

    /**
     * Check a single property access expression for TS2339.
     * Conservative: only check this.X access in class bodies for now.
     */
    private fun checkSinglePropertyAccess(
        expr: PropertyAccessExpression, source: String, fileName: String,
        enclosingClassType: Type?,
    ) {
        // Resolve object type: "this" uses enclosing class type;
        // non-this identifiers use global type resolution.
        val isThisAccess = expr.expression is Identifier && (expr.expression as Identifier).text == "this"
        val objectType = if (isThisAccess) {
            if (enclosingClassType == null) return
            enclosingClassType
        } else {
            if (expr.expression !is Identifier) return
            val identName = (expr.expression as Identifier).text
            val identSymbol = globals[identName] ?: return
            val exprType = getTypeOfSymbol(identSymbol)
            if (exprType === anyType || exprType === errorType || exprType === unknownType) return
            if (exprType !is Type.Object) return
            // For variables, only check property access when the type is an interface
            // (not a class) — class-typed variables may be narrowed via instanceof,
            // causing FPs without control flow analysis.
            if (identSymbol.flags.hasAny(SymbolFlags.Variable or SymbolFlags.Property)) {
                val typeSym = exprType.symbol
                if (typeSym == null || typeSym.flags.hasAny(SymbolFlags.Class)) return
            }
            exprType
        }
        // Only check Interface types
        if (objectType !is Type.Interface) return
        if (objectType.symbol == null) return
        // Skip enum types
        if (objectType.symbol!!.flags.hasAny(SymbolFlags.Enum)) return
        // Resolve members
        resolveStructuredTypeMembers(objectType)
        if (objectType.properties.isNullOrEmpty()) return
        // Skip if class has base types — incomplete inheritance resolution causes FPs
        if (objectType.baseTypes != null && objectType.baseTypes!!.isNotEmpty()) return
        val propName = expr.name.text
        // Skip well-known runtime properties
        if (propName in RUNTIME_PROPERTIES) return
        // Check if property exists in type members
        val prop = getPropertyOfType(objectType, propName)
        if (prop != null) return
        // Check namespace exports (for merged class+namespace symbols like `Observable.someValue`)
        val sym = objectType.symbol
        if (sym != null && sym.flags.hasAny(SymbolFlags.Module) && sym.exports?.containsKey(propName) == true) return
        // Check index signatures
        if (objectType.stringIndexInfo != null || objectType.numberIndexInfo != null) return
        // Try spelling suggestion from known properties
        val memberNames = (objectType.properties ?: emptyList()).map { it.name }.toSet()
        val suggestion = getSpellingSuggestionFromNames(propName, memberNames)
        // Emit TS2339 (or TS2551 with spelling suggestion)
        val start = expr.name.pos
        val length = expr.name.text.length
        // For static access on class/namespace identifiers, use "typeof X" format
        val rawTypeName = typeToString(objectType)
        val typeName = if (!isThisAccess && objectType.symbol?.flags?.hasAny(SymbolFlags.Class) == true) {
            "typeof $rawTypeName"
        } else {
            rawTypeName
        }
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        if (suggestion != null) {
            // Find the declaration of the suggested property for TS2728 related info
            val suggestedProp = objectType.properties?.find { it.name == suggestion }
            val relatedInfo = if (suggestedProp != null) {
                val decl = suggestedProp.valueDeclaration ?: suggestedProp.declarations.firstOrNull()
                if (decl != null) {
                    val declPos = when (decl) {
                        is PropertyDeclaration -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        is MethodDeclaration -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        is Parameter -> {
                            val n = decl.name
                            if (n is Identifier) n.pos else decl.pos
                        }
                        else -> decl.pos
                    }
                    val declLength = suggestion.length
                    val (declLine, declChar) = getLineAndCharacterOfPosition(source, declPos)
                    listOf(Diagnostic(
                        message = "'$suggestion' is declared here.",
                        category = DiagnosticCategory.Message,
                        code = 2728,
                        fileName = fileName,
                        line = declLine,
                        character = declChar,
                        start = declPos,
                        length = declLength,
                    ))
                } else emptyList()
            } else emptyList()
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'. Did you mean '$suggestion'?",
                category = DiagnosticCategory.Error,
                code = 2551,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
                relatedInformation = relatedInfo,
            ))
        } else {
            diagnostics.add(Diagnostic(
                message = "Property '$propName' does not exist on type '$typeName'.",
                category = DiagnosticCategory.Error,
                code = 2339,
                fileName = fileName,
                line = line,
                character = character,
                start = start,
                length = length,
            ))
        }
    }

    /**
     * Resolve the type of a property access's object expression.
     * Enhanced version that handles 'this' with class context.
     */
    private fun resolvePropertyAccessObjectType(expr: Expression, enclosingClassType: Type?): Type {
        if (expr is Identifier && expr.text == "this" && enclosingClassType != null) {
            return enclosingClassType
        }
        return getTypeOfExpression(expr)
    }

    // -----------------------------------------------------------------------
    // TS2345: Argument type checking (Phase 4 item 7a)
    // -----------------------------------------------------------------------

    private fun checkCallExpressionTypes() {
        for (result in binderResults) {
            val fileName = result.sourceFile.fileName
            if (isDtsFile(fileName)) continue
            // Skip .js files
            if (fileName.endsWith(".js") || fileName.endsWith(".jsx") ||
                fileName.endsWith(".mjs") || fileName.endsWith(".cjs")) continue
            val source = result.sourceFile.text
            try {
                checkCallTypesInStatements(result.sourceFile.statements, source, fileName)
            } catch (_: StackOverflowError) {
                // Safety net for deeply nested ASTs
            }
        }
    }

    private fun checkCallTypesInStatements(statements: List<Statement>, source: String, fileName: String) {
        for (stmt in statements) {
            checkCallTypesInStatement(stmt, source, fileName)
        }
    }

    private fun checkCallTypesInStatement(stmt: Statement, source: String, fileName: String) {
        if (++callTypeCheckDepth > maxCheckDepth) { callTypeCheckDepth--; return }
        try {
        when (stmt) {
            is ExpressionStatement -> checkCallTypesInExpr(stmt.expression, source, fileName)
            is VariableStatement -> {
                for (decl in stmt.declarationList.declarations) {
                    decl.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
            }
            is ReturnStatement -> stmt.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is IfStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.thenStatement, source, fileName)
                stmt.elseStatement?.let { checkCallTypesInStatement(it, source, fileName) }
            }
            is Block -> checkCallTypesInStatements(stmt.statements, source, fileName)
            is ForStatement -> {
                when (val init = stmt.initializer) {
                    is VariableDeclarationList -> {
                        for (decl in init.declarations) {
                            decl.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                        }
                    }
                    is Expression -> checkCallTypesInExpr(init, source, fileName)
                    else -> {}
                }
                stmt.condition?.let { checkCallTypesInExpr(it, source, fileName) }
                stmt.incrementor?.let { checkCallTypesInExpr(it, source, fileName) }
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is ForInStatement -> {
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is ForOfStatement -> {
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is WhileStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            is DoStatement -> {
                checkCallTypesInStatement(stmt.statement, source, fileName)
                checkCallTypesInExpr(stmt.expression, source, fileName)
            }
            is SwitchStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                for (clause in stmt.caseBlock) {
                    val clauseStmts = when (clause) {
                        is CaseClause -> clause.statements
                        is DefaultClause -> clause.statements
                        else -> emptyList()
                    }
                    checkCallTypesInStatements(clauseStmts, source, fileName)
                }
            }
            is FunctionDeclaration -> {
                // Check parameter default initializers for call expression type errors
                for (param in stmt.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                stmt.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
            }
            is ClassDeclaration -> {
                for (member in stmt.members) {
                    when (member) {
                        is MethodDeclaration -> {
                            for (param in member.parameters) {
                                param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                            }
                            member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                        }
                        is Constructor -> {
                            for (param in member.parameters) {
                                param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                            }
                            member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                        }
                        is GetAccessor -> member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                        is SetAccessor -> member.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
                        is PropertyDeclaration -> member.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                        else -> {}
                    }
                }
            }
            is TryStatement -> {
                checkCallTypesInStatements(stmt.tryBlock.statements, source, fileName)
                stmt.catchClause?.let { checkCallTypesInStatements(it.block.statements, source, fileName) }
                stmt.finallyBlock?.let { checkCallTypesInStatements(it.statements, source, fileName) }
            }
            is ThrowStatement -> stmt.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is LabeledStatement -> checkCallTypesInStatement(stmt.statement, source, fileName)
            is WithStatement -> {
                checkCallTypesInExpr(stmt.expression, source, fileName)
                checkCallTypesInStatement(stmt.statement, source, fileName)
            }
            else -> {}
        }
        } finally { callTypeCheckDepth-- }
    }

    private fun checkCallTypesInExpr(expr: Expression, source: String, fileName: String) {
        when (expr) {
            is CallExpression -> {
                checkSingleCallExpressionTypes(expr, source, fileName)
                // Recurse into callee and arguments
                checkCallTypesInExpr(expr.expression, source, fileName)
                for (arg in expr.arguments) checkCallTypesInExpr(arg, source, fileName)
            }
            is NewExpression -> {
                checkSingleNewExpressionTypes(expr, source, fileName)
                checkCallTypesInExpr(expr.expression, source, fileName)
                expr.arguments?.forEach { checkCallTypesInExpr(it, source, fileName) }
            }
            is BinaryExpression -> {
                checkCallTypesInExpr(expr.left, source, fileName)
                checkCallTypesInExpr(expr.right, source, fileName)
            }
            is ConditionalExpression -> {
                checkCallTypesInExpr(expr.condition, source, fileName)
                checkCallTypesInExpr(expr.whenTrue, source, fileName)
                checkCallTypesInExpr(expr.whenFalse, source, fileName)
            }
            is ParenthesizedExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is PrefixUnaryExpression -> checkCallTypesInExpr(expr.operand, source, fileName)
            is PostfixUnaryExpression -> checkCallTypesInExpr(expr.operand, source, fileName)
            is PropertyAccessExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is ElementAccessExpression -> {
                checkCallTypesInExpr(expr.expression, source, fileName)
                checkCallTypesInExpr(expr.argumentExpression, source, fileName)
            }
            is ArrayLiteralExpression -> expr.elements.forEach { checkCallTypesInExpr(it, source, fileName) }
            is ObjectLiteralExpression -> {
                for (prop in expr.properties) {
                    when (prop) {
                        is PropertyAssignment -> checkCallTypesInExpr(prop.initializer, source, fileName)
                        is ShorthandPropertyAssignment -> prop.objectAssignmentInitializer?.let { checkCallTypesInExpr(it, source, fileName) }
                        is SpreadAssignment -> checkCallTypesInExpr(prop.expression, source, fileName)
                        else -> {}
                    }
                }
            }
            is ArrowFunction -> {
                for (param in expr.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                expr.body?.let { body ->
                    when (body) {
                        is Block -> checkCallTypesInStatements(body.statements, source, fileName)
                        is Expression -> checkCallTypesInExpr(body, source, fileName)
                        else -> {}
                    }
                }
            }
            is FunctionExpression -> {
                for (param in expr.parameters) {
                    param.initializer?.let { checkCallTypesInExpr(it, source, fileName) }
                }
                expr.body?.let { checkCallTypesInStatements(it.statements, source, fileName) }
            }
            is TemplateExpression -> {
                for (span in expr.templateSpans) checkCallTypesInExpr(span.expression, source, fileName)
            }
            is TaggedTemplateExpression -> checkCallTypesInExpr(expr.tag, source, fileName)
            is AsExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is TypeAssertionExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is SatisfiesExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is NonNullExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is SpreadElement -> checkCallTypesInExpr(expr.expression, source, fileName)
            is AwaitExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is YieldExpression -> expr.expression?.let { checkCallTypesInExpr(it, source, fileName) }
            is DeleteExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is TypeOfExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is VoidExpression -> checkCallTypesInExpr(expr.expression, source, fileName)
            is CommaListExpression -> expr.elements.forEach { checkCallTypesInExpr(it, source, fileName) }
            else -> {}
        }
    }

    /**
     * Check argument types for a single CallExpression against resolved signature(s).
     * For non-overloaded functions: check against the single signature.
     * For overloaded functions: try each overload in order, skip if any matches,
     * report TS2345 against the last overload if none match (TypeScript convention).
     */
    private fun checkSingleCallExpressionTypes(expr: CallExpression, source: String, fileName: String) {
        // Resolve callee to get its type
        val calleeType = getCalleeType(expr.expression)
        if (calleeType === anyType || calleeType === errorType) return
        // Get call signatures
        val signatures = getCallSignaturesOfType(calleeType)
        if (signatures.isEmpty()) return
        if (signatures.size == 1) {
            checkArgumentsAgainstSignature(expr.arguments, signatures[0], source, fileName)
        } else {
            // Overload resolution: try each signature in order
            checkArgumentsAgainstOverloads(expr.arguments, signatures, source, fileName)
        }
    }

    /**
     * Check argument types for a NewExpression against the construct signature.
     */
    private fun checkSingleNewExpressionTypes(expr: NewExpression, source: String, fileName: String) {
        val args = expr.arguments ?: return
        val calleeType = getCalleeType(expr.expression)
        if (calleeType === anyType || calleeType === errorType) return
        // Get construct signatures
        val signatures = getConstructSignaturesOfType(calleeType)
        if (signatures.isEmpty()) return
        if (signatures.size == 1) {
            checkArgumentsAgainstSignature(args, signatures[0], source, fileName)
        } else {
            checkArgumentsAgainstOverloads(args, signatures, source, fileName)
        }
    }

    /**
     * Try each overload signature in order. If any overload accepts all arguments, no error.
     * If none succeed, report TS2345 against the last overload (TypeScript convention).
     */
    private fun checkArgumentsAgainstOverloads(
        args: List<Expression>,
        signatures: List<Signature>,
        source: String,
        fileName: String,
    ) {
        for (sig in signatures) {
            if (allArgumentsMatch(args, sig)) return // found a matching overload
        }
        // None matched — emit TS2769 with errors from each overload
        // Collect the first argument mismatch per overload for the error chain
        val overloadErrors = mutableListOf<Triple<Int, Signature, String>>() // (overloadIndex, sig, errorMsg)
        for ((idx, sig) in signatures.withIndex()) {
            val errorMsg = getFirstArgumentError(args, sig)
            if (errorMsg != null) {
                overloadErrors.add(Triple(idx + 1, sig, errorMsg))
            }
        }
        if (overloadErrors.isNotEmpty()) {
            // Find the error position — use the first failing argument position from any overload
            val firstArgError = getFirstFailingArgPosition(args, signatures.last())
            if (firstArgError != null) {
                val (argStart, argLength) = firstArgError
                val (line, character) = getLineAndCharacterOfPosition(source, argStart)
                val chain = mutableListOf<String>()
                val totalOverloads = signatures.size
                for ((overloadIdx, sig, errorMsg) in overloadErrors) {
                    val sigStr = signatureToString(sig)
                    chain.add("  Overload $overloadIdx of $totalOverloads, '$sigStr', gave the following error.")
                    chain.add("    $errorMsg")
                }
                diagnostics.add(Diagnostic(
                    message = "No overload matches this call.",
                    category = DiagnosticCategory.Error,
                    code = 2769,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = argStart,
                    length = argLength,
                    messageChain = chain,
                ))
                return
            }
        }
        // Fallback: report TS2345 against the last signature
        val lastSig = signatures.last()
        checkArgumentsAgainstSignature(args, lastSig, source, fileName)
    }

    /** Get the first argument type error message for a signature, or null if all match. */
    private fun getFirstArgumentError(args: List<Expression>, sig: Signature): String? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!isSimpleCheckableType(paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                return "Argument of type '${typeToString(argType)}' is not assignable to parameter of type '${typeToString(paramType)}'."
            }
        }
        return null
    }

    /** Get the position and length of the first failing argument for a signature. */
    private fun getFirstFailingArgPosition(args: List<Expression>, sig: Signature): Pair<Int, Int>? {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!isSimpleCheckableType(paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length > 0) return Pair(start, length)
            }
        }
        return null
    }

    /** Format a signature for display in TS2769 messages: (param: type, ...): returnType */
    private fun signatureToString(sig: Signature): String {
        val params = sig.parameters.joinToString(", ") { param ->
            val paramType = getTypeOfSymbol(param)
            val typeStr = if (paramType === anyType) "any" else typeToString(paramType)
            "${param.name}: $typeStr"
        }
        val returnType = sig.resolvedReturnType
        val returnStr = if (returnType != null && returnType !== anyType) typeToString(returnType) else "any"
        return "($params): $returnStr"
    }

    /**
     * Check if all arguments match a signature (no TS2345 errors would fire).
     * Returns true if all args are assignable to their corresponding param types.
     */
    private fun allArgumentsMatch(args: List<Expression>, sig: Signature): Boolean {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            if (!isSimpleCheckableType(paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) return false
        }
        return true
    }

    /**
     * Get the type of a callee expression for call/new checking.
     */
    private fun getCalleeType(expr: Expression): Type {
        return when (expr) {
            is Identifier -> {
                val symbol = globals[expr.text] ?: return anyType
                getTypeOfSymbol(symbol)
            }
            is PropertyAccessExpression -> getTypeOfPropertyAccess(expr)
            is ParenthesizedExpression -> getCalleeType(expr.expression)
            else -> anyType
        }
    }

    /**
     * Get call signatures from a type.
     */
    private fun getCallSignaturesOfType(type: Type): List<Signature> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.callSignatures ?: emptyList()
        }
        if (type is Type.Union) {
            // Collect call signatures from all union constituents
            val allSigs = mutableListOf<Signature>()
            for (constituent in type.types) {
                allSigs.addAll(getCallSignaturesOfType(constituent))
            }
            return allSigs
        }
        return emptyList()
    }

    /**
     * Get construct signatures from a type.
     */
    private fun getConstructSignaturesOfType(type: Type): List<Signature> {
        if (type is Type.Object) {
            resolveStructuredTypeMembers(type)
            return type.constructSignatures ?: emptyList()
        }
        return emptyList()
    }

    /**
     * Check each argument against the corresponding parameter type.
     * Emits TS2345 for type mismatches.
     *
     * Conservative: only checks when both argument and parameter types are
     * well-understood (primitives, literals, intrinsics). Skips complex types
     * (interfaces, objects, unions, intersections) to avoid false positives
     * from incomplete structural comparison and missing generic instantiation.
     */
    private fun checkArgumentsAgainstSignature(
        args: List<Expression>,
        sig: Signature,
        source: String,
        fileName: String,
    ) {
        val params = sig.parameters
        for ((i, arg) in args.withIndex()) {
            if (i >= params.size) break // extra args handled by TS2554
            // Skip spread arguments — complex handling
            if (arg is SpreadElement) continue
            val paramType = getTypeOfSymbol(params[i])
            if (paramType === anyType || paramType === errorType) continue
            val argType = getTypeOfExpression(arg)
            if (argType === anyType || argType === errorType) continue
            // Conservative: only check when parameter type is a well-known type
            // (primitive, void, undefined, null, never). Skip object/interface/union/
            // intersection types which need deeper structural comparison or generics.
            if (!isSimpleCheckableType(paramType)) continue
            if (!checkTypeRelatedTo(argType, paramType, assignableRelation)) {
                // Emit TS2345
                val argTypeStr = typeToString(argType)
                val paramTypeStr = typeToString(paramType)
                val start = arg.pos
                val length = expressionTrueEnd(arg) - start
                if (length <= 0) continue
                val (line, character) = getLineAndCharacterOfPosition(source, start)
                diagnostics.add(Diagnostic(
                    message = "Argument of type '$argTypeStr' is not assignable to parameter of type '$paramTypeStr'.",
                    category = DiagnosticCategory.Error,
                    code = 2345,
                    fileName = fileName,
                    line = line,
                    character = character,
                    start = start,
                    length = length,
                ))
                break // TypeScript reports only the first failing argument per call
            }
        }
    }

    /**
     * Check if a type is "simple" enough that we can safely check TS2345 against it
     * without risking false positives from incomplete structural comparison.
     * Returns true for primitive types (string, number, boolean, void, null, undefined, never,
     * bigint, symbol) and their literal variants.
     */
    private fun isSimpleCheckableType(type: Type): Boolean {
        val f = type.flags
        if (f.hasAny(
            TypeFlags.String or TypeFlags.Number or TypeFlags.Boolean or
            TypeFlags.Void or TypeFlags.Undefined or TypeFlags.Null or
            TypeFlags.Never or TypeFlags.BigInt or TypeFlags.ESSymbol or
            TypeFlags.StringLiteral or TypeFlags.NumberLiteral or
            TypeFlags.BooleanLiteral or TypeFlags.BigIntLiteral or
            TypeFlags.UniqueESSymbol or TypeFlags.EnumLiteral
        )) return true
        // Allow union types where all members are checkable (e.g., string | number)
        if (type is Type.Union) return type.types.all { isSimpleCheckableType(it) }
        return false
    }

    // -----------------------------------------------------------------------
    // Structural typing engine (Phase 4 items 4a-4e)
    // -----------------------------------------------------------------------

    /** Ternary logic for type relations: True, False, or Maybe (for recursive checks). */
    private enum class Ternary { True, False, Maybe }

    /** Relation cache — maps (sourceId, targetId) packed into Long → result. */
    private class Relation {
        private val cache = HashMap<Long, Ternary>()

        fun get(sourceId: Int, targetId: Int): Ternary? {
            return cache[packKey(sourceId, targetId)]
        }

        fun set(sourceId: Int, targetId: Int, result: Ternary) {
            cache[packKey(sourceId, targetId)] = result
        }

        private fun packKey(a: Int, b: Int): Long =
            (a.toLong() shl 32) or (b.toLong() and 0xFFFFFFFFL)
    }

    /**
     * 4a. Fast flag-based type relatedness check (no recursion).
     * Returns true if the relation holds purely from type flags.
     */
    private fun isSimpleTypeRelatedTo(source: Type, target: Type): Boolean {
        val sf = source.flags
        val tf = target.flags
        // Any target accepts everything
        if (tf.hasAny(TypeFlags.Any)) return true
        // Any source is assignable to everything (any is both top and bottom type)
        if (sf.hasAny(TypeFlags.Any)) return true
        // Unknown target accepts everything (for assignability)
        if (tf.hasAny(TypeFlags.Unknown)) return true
        // Never source is assignable to everything
        if (sf.hasAny(TypeFlags.Never)) return true
        // Same type by identity
        if (source === target) return true
        // Literal value comparison (different instances with same value)
        if (source is Type.StringLiteral && target is Type.StringLiteral && source.value == target.value) return true
        if (source is Type.NumberLiteral && target is Type.NumberLiteral && source.value == target.value) return true
        if (source is Type.BigIntLiteral && target is Type.BigIntLiteral && source.value == target.value) return true
        // Primitive widening: string literal → string, number literal → number, etc.
        if (sf.hasAny(TypeFlags.StringLiteral) && tf.hasAny(TypeFlags.String)) return true
        if (sf.hasAny(TypeFlags.NumberLiteral) && tf.hasAny(TypeFlags.Number)) return true
        if (sf.hasAny(TypeFlags.BigIntLiteral) && tf.hasAny(TypeFlags.BigInt)) return true
        if (sf.hasAny(TypeFlags.BooleanLiteral) && tf.hasAny(TypeFlags.Boolean)) return true
        if (sf.hasAny(TypeFlags.EnumLiteral) && tf.hasAny(TypeFlags.Enum)) return true
        if (sf.hasAny(TypeFlags.UniqueESSymbol) && tf.hasAny(TypeFlags.ESSymbol)) return true
        // String-like types to string
        if (sf.hasAny(TypeFlags.StringLike) && tf.hasAny(TypeFlags.String)) return true
        if (sf.hasAny(TypeFlags.NumberLike) && tf.hasAny(TypeFlags.Number)) return true
        if (sf.hasAny(TypeFlags.BigIntLike) && tf.hasAny(TypeFlags.BigInt)) return true
        // undefined → void
        if (sf.hasAny(TypeFlags.Undefined) && tf.hasAny(TypeFlags.Void)) return true
        // void → undefined (void is treated as undefined for assignability)
        if (sf.hasAny(TypeFlags.Void) && tf.hasAny(TypeFlags.Undefined)) return true
        // When strict null checks are off, null/undefined assignable to everything
        if (!strictNullChecks && sf.hasAny(TypeFlags.Null or TypeFlags.Undefined)) return true
        // object type (non-primitive) — primitives are NOT assignable to object
        if (tf.hasAny(TypeFlags.NonPrimitive)) {
            return !sf.hasAny(TypeFlags.Primitive or TypeFlags.Null or TypeFlags.Undefined or TypeFlags.Void)
        }
        return false
    }

    /**
     * 4b. Main entry point for type relation checking with error reporting.
     * Returns true if source is related to target in the given relation.
     */
    private fun checkTypeRelatedTo(
        source: Type,
        target: Type,
        relation: Relation,
    ): Boolean {
        if (source === target) return true
        // Fast check
        if (isSimpleTypeRelatedTo(source, target)) return true
        // Check cache
        val cached = relation.get(source.id, target.id)
        if (cached == Ternary.True) return true
        if (cached == Ternary.False) return false
        // Depth limit
        if (relationDepth >= maxRelationDepth) return false
        relationDepth++
        val result = structuredTypeRelatedTo(source, target, relation)
        relationDepth--
        val ternary = if (result) Ternary.True else Ternary.False
        relation.set(source.id, target.id, ternary)
        return result
    }

    /**
     * 4c. Core structural comparison — handles unions, intersections, and objects.
     */
    private fun structuredTypeRelatedTo(
        source: Type,
        target: Type,
        relation: Relation,
    ): Boolean {
        // Union source: each constituent must be related to the target
        if (source is Type.Union) {
            return source.types.all { checkTypeRelatedTo(it, target, relation) }
        }
        // Union target: source must be related to some constituent
        if (target is Type.Union) {
            return target.types.any { checkTypeRelatedTo(source, it, relation) }
        }
        // Intersection target: source must be related to each constituent
        if (target is Type.Intersection) {
            return target.types.all { checkTypeRelatedTo(source, it, relation) }
        }
        // Intersection source: some constituent must be related to target
        if (source is Type.Intersection) {
            return source.types.any { checkTypeRelatedTo(it, target, relation) }
        }
        // Object types: structural comparison
        if (source is Type.Object && target is Type.Object) {
            return objectTypeRelatedTo(source, target, relation)
        }
        return false
    }

    /**
     * Structural comparison of two object types.
     * Checks properties, call signatures, and construct signatures.
     */
    private fun objectTypeRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
    ): Boolean {
        resolveStructuredTypeMembers(source)
        resolveStructuredTypeMembers(target)
        // Check properties
        if (!propertiesRelatedTo(source, target, relation)) return false
        // Check call signatures
        if (!signaturesRelatedTo(source, target, relation, isConstruct = false)) return false
        // Check construct signatures
        if (!signaturesRelatedTo(source, target, relation, isConstruct = true)) return false
        return true
    }

    /**
     * 4d. Property-by-property structural comparison.
     * For each required property in target, source must have a compatible property.
     */
    private fun propertiesRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
    ): Boolean {
        val targetProps = target.properties ?: return true
        val sourceMembers = source.members ?: return targetProps.isEmpty()
        for (targetProp in targetProps) {
            val targetName = targetProp.name
            // Check if property is optional (question mark in declaration)
            val isOptional = isOptionalProperty(targetProp)
            val sourceProp = sourceMembers[targetName]
            if (sourceProp == null) {
                // Check index signature
                val indexInfo = source.stringIndexInfo
                if (indexInfo != null) {
                    val targetPropType = getTypeOfSymbol(targetProp)
                    if (!checkTypeRelatedTo(indexInfo.type, targetPropType, relation)) return false
                    continue
                }
                if (!isOptional) return false // missing required property
                continue
            }
            // Compare property types
            val sourcePropType = getTypeOfSymbol(sourceProp)
            val targetPropType = getTypeOfSymbol(targetProp)
            if (!checkTypeRelatedTo(sourcePropType, targetPropType, relation)) return false
        }
        return true
    }

    /**
     * 4e. Compare call or construct signatures.
     * Parameter types compared contravariantly, return types covariantly.
     */
    private fun signaturesRelatedTo(
        source: Type.Object,
        target: Type.Object,
        relation: Relation,
        isConstruct: Boolean,
    ): Boolean {
        val targetSigs = if (isConstruct) target.constructSignatures else target.callSignatures
        if (targetSigs.isNullOrEmpty()) return true // no signatures to match
        val sourceSigs = if (isConstruct) source.constructSignatures else source.callSignatures
        if (sourceSigs.isNullOrEmpty()) return false // target has signatures, source doesn't
        // Each target signature must be matched by some source signature
        for (targetSig in targetSigs) {
            val matched = sourceSigs.any { sourceSig ->
                signatureRelatedTo(sourceSig, targetSig, relation)
            }
            if (!matched) return false
        }
        return true
    }

    /** Compare two individual signatures. */
    private fun signatureRelatedTo(
        source: Signature,
        target: Signature,
        relation: Relation,
    ): Boolean {
        // Source requires more args than target provides → incompatible
        val sourceParams = source.parameters
        val targetParams = target.parameters
        if (source.minArgumentCount > targetParams.size) return false
        // Check return types (covariant)
        // Void target return accepts any source return type (void means "don't care about return")
        val sourceReturn = source.resolvedReturnType ?: anyType
        val targetReturn = target.resolvedReturnType ?: anyType
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, relation)) return false
        // Check parameter types (contravariant)
        val len = minOf(sourceParams.size, targetParams.size)
        for (i in 0 until len) {
            val sourceParamType = getTypeOfSymbol(sourceParams[i])
            val targetParamType = getTypeOfSymbol(targetParams[i])
            // Contravariant: target param must be assignable to source param
            if (!checkTypeRelatedTo(targetParamType, sourceParamType, relation)) return false
        }
        return true
    }

    /**
     * Generate elaboration chain for a function→function type mismatch.
     * Returns lines like:
     *   "  Type 'void' is not assignable to type 'boolean'."
     * or:
     *   "  Types of parameters 'x' and 's1' are incompatible."
     *   "    Type 'string' is not assignable to type 'number'."
     */
    private fun getFunctionMismatchElaboration(
        source: Type.Object, target: Type.Object
    ): List<String> {
        val sourceSigs = source.callSignatures
        val targetSigs = target.callSignatures
        if (sourceSigs.isNullOrEmpty() || targetSigs.isNullOrEmpty()) return emptyList()
        val sourceSig = sourceSigs.first()
        val targetSig = targetSigs.first()
        // Check return type mismatch
        val sourceReturn = sourceSig.resolvedReturnType ?: anyType
        val targetReturn = targetSig.resolvedReturnType ?: anyType
        if (!targetReturn.flags.hasAny(TypeFlags.Void) &&
            !checkTypeRelatedTo(sourceReturn, targetReturn, assignableRelation)) {
            return listOf("  Type '${typeToString(sourceReturn)}' is not assignable to type '${typeToString(targetReturn)}'.")
        }
        // Check parameter type mismatch (contravariant)
        val sourceParams = sourceSig.parameters
        val targetParams = targetSig.parameters
        val len = minOf(sourceParams.size, targetParams.size)
        for (i in 0 until len) {
            val sourceParamType = getTypeOfSymbol(sourceParams[i])
            val targetParamType = getTypeOfSymbol(targetParams[i])
            if (!checkTypeRelatedTo(targetParamType, sourceParamType, assignableRelation)) {
                return listOf(
                    "  Types of parameters '${sourceParams[i].name}' and '${targetParams[i].name}' are incompatible.",
                    "    Type '${typeToString(targetParamType)}' is not assignable to type '${typeToString(sourceParamType)}'.",
                )
            }
        }
        return emptyList()
    }

    /** Check if a property symbol is optional (has questionToken in its declaration). */
    private fun isOptionalProperty(symbol: Symbol): Boolean {
        val decl = symbol.valueDeclaration ?: symbol.declarations.firstOrNull() ?: return false
        return when (decl) {
            is PropertyDeclaration -> decl.questionToken
            is Parameter -> decl.questionToken
            is MethodDeclaration -> decl.questionToken
            else -> false
        }
    }

    /**
     * Check if source type is assignable to target type using the new Type-based engine.
     * This is the replacement for the string-based isAssignableTo.
     */
    private fun isTypeAssignableTo(source: Type, target: Type): Boolean {
        return checkTypeRelatedTo(source, target, assignableRelation)
    }

    // -----------------------------------------------------------------------
    // Generic type instantiation (Phase 4 item 8a)
    // -----------------------------------------------------------------------

    /**
     * TypeMapper — maps type parameters to concrete types during generic instantiation.
     */
    private fun interface TypeMapper {
        fun map(typeParam: Type.TypeParam): Type?
    }

    /**
     * Create a TypeMapper from parallel lists of type parameters and type arguments.
     */
    private fun createTypeMapper(typeParams: List<Type.TypeParam>, typeArgs: List<Type>): TypeMapper {
        return TypeMapper { tp ->
            val index = typeParams.indexOf(tp)
            if (index >= 0 && index < typeArgs.size) typeArgs[index] else null
        }
    }

    /**
     * Recursively substitute type parameters in a type according to the given mapper.
     * Returns the same type if no substitution occurs.
     */
    private fun instantiateType(type: Type, mapper: TypeMapper): Type {
        return when (type) {
            is Type.TypeParam -> mapper.map(type) ?: type
            is Type.Union -> {
                val mapped = type.types.map { instantiateType(it, mapper) }
                if (mapped.zip(type.types).all { (a, b) -> a === b }) type
                else getUnionType(mapped)
            }
            is Type.Intersection -> {
                val mapped = type.types.map { instantiateType(it, mapper) }
                if (mapped.zip(type.types).all { (a, b) -> a === b }) type
                else getIntersectionType(mapped)
            }
            is Type.Reference -> {
                val args = type.resolvedTypeArguments ?: return type
                val mapped = args.map { instantiateType(it, mapper) }
                if (mapped.zip(args).all { (a, b) -> a === b }) type
                else {
                    val ref = Type.Reference(type.target)
                    ref.resolvedTypeArguments = mapped
                    ref
                }
            }
            is Type.Object -> {
                // For anonymous object types, we'd need to instantiate members
                // For now, return as-is
                type
            }
            // Intrinsic, literal types don't contain type parameters
            else -> type
        }
    }

    /**
     * Instantiate a signature with type arguments — substitute type params in parameter types
     * and return type.
     */
    private fun instantiateSignature(sig: Signature, mapper: TypeMapper): Signature {
        val newReturnType = sig.resolvedReturnType?.let { instantiateType(it, mapper) }
        // Parameter types are resolved lazily from their declarations, so we need to create
        // new parameter symbols with mapped types if the parameters have type annotations
        // involving type parameters. For now, return the original parameters — the type
        // resolution in getTypeOfSymbol will pick up the original (non-instantiated) types.
        return Signature(
            declaration = sig.declaration,
            typeParameters = null, // instantiated signature has no type parameters
            parameters = sig.parameters,
            resolvedReturnType = newReturnType ?: sig.resolvedReturnType,
            minArgumentCount = sig.minArgumentCount,
        )
    }

    /** Create an array type: `Type.Reference(globalArrayType, [elementType])`. */
    private fun getArrayType(elementType: Type): Type {
        return Type.Reference(globalArrayType, resolvedTypeArguments = listOf(elementType))
    }

    /** Create a tuple type from a TupleType node. */
    private fun getTupleType(node: TupleType): Type {
        // TODO: proper tuple type
        return Type.Object()
    }

    /** Create a Type from a literal type node (e.g., `type X = "hello"` or `type Y = 42`). */
    private fun getTypeFromLiteralTypeNode(node: LiteralType): Type {
        return when (val literal = node.literal) {
            is StringLiteralNode -> Type.StringLiteral(literal.text)
            is NumericLiteralNode -> {
                val value = literal.text.toDoubleOrNull() ?: 0.0
                Type.NumberLiteral(value)
            }
            is BigIntLiteralNode -> Type.BigIntLiteral(literal.text.removeSuffix("n"))
            is Identifier -> when (literal.text) {
                "true" -> trueType
                "false" -> falseType
                else -> errorType
            }
            is PrefixUnaryExpression -> {
                // -42, -1n, etc.
                if (literal.operator == SyntaxKind.Minus) {
                    when (val operand = literal.operand) {
                        is NumericLiteralNode -> {
                            val value = -(operand.text.toDoubleOrNull() ?: 0.0)
                            Type.NumberLiteral(value)
                        }
                        is BigIntLiteralNode -> Type.BigIntLiteral("-${operand.text.removeSuffix("n")}")
                        else -> errorType
                    }
                } else errorType
            }
            else -> errorType
        }
    }

    /** Create a function type from a FunctionType node. */
    private fun getFunctionTypeFromNode(node: FunctionType): Type {
        val fnType = Type.Object()
        val sig = Signature(
            declaration = node,
            parameters = getParameterSymbols(node.parameters),
            resolvedReturnType = getTypeFromTypeNode(node.type),
            minArgumentCount = node.parameters.count { !it.questionToken && !it.dotDotDotToken && it.initializer == null },
        )
        fnType.callSignatures = listOf(sig)
        return fnType
    }

    /** Create a constructor type from a ConstructorType node. */
    private fun getFunctionTypeFromConstructorNode(node: ConstructorType): Type {
        val ctorType = Type.Object()
        val sig = Signature(
            declaration = node,
            parameters = getParameterSymbols(node.parameters),
            resolvedReturnType = getTypeFromTypeNode(node.type),
            minArgumentCount = node.parameters.count { !it.questionToken && !it.dotDotDotToken && it.initializer == null },
        )
        ctorType.constructSignatures = listOf(sig)
        return ctorType
    }

    /** Create an object type from a TypeLiteral node (e.g., `{ x: number; y: string }`). */
    private fun getTypeFromTypeLiteral(node: TypeLiteral): Type {
        val objType = Type.Object()
        // TODO: resolve members from node.members
        return objType
    }

    /** Handle TypeOperator nodes (keyof, unique, readonly). */
    private fun getTypeFromTypeOperator(node: TypeOperator): Type {
        return when (node.operator) {
            SyntaxKind.KeyOfKeyword -> anyType // TODO: keyof type
            SyntaxKind.UniqueKeyword -> esSymbolType // unique symbol
            SyntaxKind.ReadonlyKeyword -> getTypeFromTypeNode(node.type) // readonly just adds modifier
            else -> anyType
        }
    }

    // -----------------------------------------------------------------------
    // Union and Intersection type construction (basic — Phase 4 items 1b/1c)
    // -----------------------------------------------------------------------

    /** Construct a union type from a list of constituent types, with basic normalization. */
    private fun getUnionType(types: List<Type>): Type {
        if (types.isEmpty()) return neverType
        // Flatten nested unions
        val flattened = mutableListOf<Type>()
        for (type in types) {
            if (type is Type.Union) {
                flattened.addAll(type.types)
            } else {
                flattened.add(type)
            }
        }
        // Remove never types
        val filtered = flattened.filter { !it.flags.hasAny(TypeFlags.Never) }
        if (filtered.isEmpty()) return neverType
        // If any constituent is any, the union is any
        filtered.firstOrNull { it.flags.hasAny(TypeFlags.Any) }?.let { return it }
        // Single type — no union needed
        if (filtered.size == 1) return filtered[0]
        // Deduplicate by type identity (by id)
        val seen = mutableSetOf<Int>()
        val deduped = filtered.filter { seen.add(it.id) }
        if (deduped.size == 1) return deduped[0]
        return Type.Union(deduped)
    }

    /** Construct an intersection type from a list of constituent types, with basic normalization. */
    private fun getIntersectionType(types: List<Type>): Type {
        if (types.isEmpty()) return unknownType
        // Flatten nested intersections
        val flattened = mutableListOf<Type>()
        for (type in types) {
            if (type is Type.Intersection) {
                flattened.addAll(type.types)
            } else {
                flattened.add(type)
            }
        }
        // If any constituent is never, the intersection is never
        if (flattened.any { it.flags.hasAny(TypeFlags.Never) }) return neverType
        // Remove unknown types (unknown & X = X)
        val filtered = flattened.filter { !it.flags.hasAny(TypeFlags.Unknown) }
        if (filtered.isEmpty()) return unknownType
        // If any constituent is any, the intersection is any
        filtered.firstOrNull { it.flags.hasAny(TypeFlags.Any) }?.let { return it }
        // Single type — no intersection needed
        if (filtered.size == 1) return filtered[0]
        return Type.Intersection(filtered)
    }

    // -----------------------------------------------------------------------
    // String-based type resolution (legacy — to be replaced by Type-based)
    // -----------------------------------------------------------------------

    /** Resolve a type annotation to a type name string. Returns null for complex types we can't handle.
     *  Named types (from TypeReference) are prefixed with "@" to distinguish from keyword types. */
    private fun resolveSimpleTypeName(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is TypeReference -> {
                val baseName = getTypeReferenceLastName(typeNode.typeName) ?: return null
                val typeArgs = typeNode.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    // Format as Name<Arg1, Arg2> for display in TS2322 messages
                    val argNames = typeArgs.map { formatTypeForDisplay(it) }
                    if (argNames.any { it == null }) return null
                    "@$baseName<${argNames.joinToString(", ")}>"
                } else {
                    // Simple type reference — prefix with "@" to mark as named type
                    "@$baseName"
                }
            }
            is UnionType -> {
                // Format as "type1 | type2 | ..." for display
                val memberTypes = typeNode.types.map { formatTypeForDisplay(it) }
                if (memberTypes.any { it == null }) return null
                // Use "|" prefix to mark as union type for assignability checking
                "|${memberTypes.joinToString(" | ")}"
            }
            is TypePredicate -> "boolean" // Type predicates return boolean
            else -> null
        }
    }

    /** Get the last identifier name from a TypeReference typeName (Identifier or QualifiedName). */
    private fun getTypeReferenceLastName(node: Node): String? {
        return when (node) {
            is Identifier -> node.text
            is QualifiedName -> node.right.text
            else -> null
        }
    }

    /** Resolve a TypeReference typeName (Identifier or QualifiedName) to a Symbol. */
    private fun resolveTypeNameToSymbol(node: Node): Symbol? {
        return when (node) {
            is Identifier -> globals[node.text]
            is QualifiedName -> resolveQualifiedName(node)
            else -> null
        }
    }

    /**
     * Format a TypeNode for display in TS2322 messages (no "@" prefix).
     * Returns null for unsupported types (caller falls back to typeToString).
     */
    private fun formatTypeForDisplay(typeNode: TypeNode): String? {
        return when (typeNode) {
            is KeywordTypeNode -> when (typeNode.kind) {
                SyntaxKind.NumberKeyword -> "number"
                SyntaxKind.StringKeyword -> "string"
                SyntaxKind.BooleanKeyword -> "boolean"
                SyntaxKind.VoidKeyword -> "void"
                SyntaxKind.AnyKeyword -> "any"
                SyntaxKind.UnknownKeyword -> "unknown"
                SyntaxKind.NeverKeyword -> "never"
                SyntaxKind.ObjectKeyword -> "object"
                SyntaxKind.SymbolKeyword -> "symbol"
                SyntaxKind.BigIntKeyword -> "bigint"
                SyntaxKind.UndefinedKeyword -> "undefined"
                SyntaxKind.NullKeyword -> "null"
                else -> null
            }
            is TypeReference -> {
                val baseName = getTypeReferenceLastName(typeNode.typeName) ?: return null
                val typeArgs = typeNode.typeArguments
                if (typeArgs != null && typeArgs.isNotEmpty()) {
                    // TypeScript normalizes Array<T> → T[] in error messages
                    if ((baseName == "Array" || baseName == "ReadonlyArray") && typeArgs.size == 1) {
                        val elementDisplay = formatTypeForDisplay(typeArgs[0]) ?: return null
                        return "${elementDisplay}[]"
                    }
                    val argNames = typeArgs.map { formatTypeForDisplay(it) }
                    if (argNames.any { it == null }) return null
                    "$baseName<${argNames.joinToString(", ")}>"
                } else baseName
            }
            is ArrayType -> {
                val elementType = formatTypeForDisplay(typeNode.elementType) ?: return null
                "$elementType[]"
            }
            is UnionType -> {
                val memberTypes = typeNode.types.map { formatTypeForDisplay(it) }
                if (memberTypes.any { it == null }) return null
                memberTypes.joinToString(" | ")
            }
            is IntersectionType -> {
                val memberTypes = typeNode.types.map { formatTypeForDisplay(it) }
                if (memberTypes.any { it == null }) return null
                memberTypes.joinToString(" & ")
            }
            is FunctionType -> {
                val typeParams = typeNode.typeParameters ?: emptyList()
                val tpStr = if (typeParams.isNotEmpty()) "<${typeParams.joinToString(", ") { it.name.text }}>" else ""
                val params = typeNode.parameters.joinToString(", ") { p ->
                    val pName = (p.name as? Identifier)?.text ?: "_"
                    val pType = p.type?.let { formatTypeForDisplay(it) } ?: "any"
                    "$pName: $pType"
                }
                val retType = formatTypeForDisplay(typeNode.type) ?: return null
                "$tpStr($params) => $retType"
            }
            is ConstructorType -> {
                val typeParams = typeNode.typeParameters ?: emptyList()
                val tpStr = if (typeParams.isNotEmpty()) "<${typeParams.joinToString(", ") { it.name.text }}>" else ""
                val params = typeNode.parameters.joinToString(", ") { p ->
                    val pName = (p.name as? Identifier)?.text ?: "_"
                    val pType = p.type?.let { formatTypeForDisplay(it) } ?: "any"
                    "$pName: $pType"
                }
                val retType = formatTypeForDisplay(typeNode.type) ?: return null
                "new $tpStr($params) => $retType"
            }
            is ParenthesizedType -> {
                val inner = formatTypeForDisplay(typeNode.type) ?: return null
                "($inner)"
            }
            is TupleType -> {
                val elements = typeNode.elements.map { formatTypeForDisplay(it) }
                if (elements.any { it == null }) return null
                "[${elements.joinToString(", ")}]"
            }
            else -> null
        }
    }

    /** Infer the type of a simple expression. Returns null for complex expressions. */
    private fun inferSimpleExprType(expr: Expression, varTypes: Map<String, String>): String? {
        return when (expr) {
            is NumericLiteralNode -> "number"
            is StringLiteralNode -> "string"
            is NoSubstitutionTemplateLiteralNode -> "string"
            is TemplateExpression -> "string"
            is RegularExpressionLiteralNode -> "object" // RegExp
            is Identifier -> when (expr.text) {
                "undefined" -> "undefined"
                "null" -> "null"
                "true", "false" -> "boolean"
                "NaN", "Infinity" -> "number"
                else -> null // Don't look up variable types — causes FPs with enum/union targets
            }
            is TypeOfExpression -> "string" // typeof always returns string
            is PrefixUnaryExpression -> when (expr.operator) {
                SyntaxKind.Exclamation -> "boolean" // !x is boolean
                SyntaxKind.Minus, SyntaxKind.Plus, SyntaxKind.Tilde -> "number"
                else -> null
            }
            is ParenthesizedExpression -> inferSimpleExprType(expr.expression, varTypes)
            is AsExpression -> {
                // Type assertion: return the asserted type, not the inner expression type
                val assertedType = resolveSimpleTypeName(expr.type)
                if (assertedType != null) assertedType
                else inferSimpleExprType(expr.expression, varTypes)
            }
            is ArrayLiteralExpression -> "array" // Used internally for assignability
            is BinaryExpression -> when (expr.operator) {
                SyntaxKind.Equals -> inferSimpleExprType(expr.right, varTypes)
                else -> null
            }
            else -> null
        }
    }

    /** Check if an expression is a simple literal (no elaboration needed in TS2322 chain). */
    private fun isSimpleLiteral(expr: Expression): Boolean {
        return when (expr) {
            is NumericLiteralNode -> true
            is StringLiteralNode -> true
            is NoSubstitutionTemplateLiteralNode -> true
            is Identifier -> true // All identifiers are "simple" (no elaboration chain)
            is ParenthesizedExpression -> isSimpleLiteral(expr.expression)
            is PrefixUnaryExpression -> expr.operand is NumericLiteralNode
            is BinaryExpression -> expr.operator == SyntaxKind.Equals && isSimpleLiteral(expr.right)
            else -> false
        }
    }

    /** Check if sourceType is assignable to targetType.
     *  Named types (from TypeReference) are prefixed with "@".
     *  Union types are prefixed with "|". */
    private fun isAssignableTo(sourceType: String, targetType: String): Boolean {
        if (sourceType == targetType) return true
        if (targetType == "any" || targetType == "unknown") return true
        if (sourceType == "any") return true
        // undefined is assignable to void
        if (sourceType == "undefined" && targetType == "void") return true
        // When strict null checks are off, null and undefined are assignable to everything
        if (!strictNullChecks && (sourceType == "null" || sourceType == "undefined")) return true
        // Union types: source is assignable to union if it matches any member
        if (targetType.startsWith("|")) {
            val members = targetType.removePrefix("|").split(" | ")
            // null/undefined are only assignable to union if a member is null/undefined/void
            if (sourceType == "null" || sourceType == "undefined") {
                return members.any { it == sourceType || it == "any" || it == "unknown" || (sourceType == "undefined" && it == "void") }
            }
            // For other source types, assignable if it matches any member
            return members.any { isAssignableTo(sourceType, it) }
        }
        // For named types (TypeReference, prefixed with "@"), we can only confidently say
        // that null/undefined are NOT assignable. Other source types might actually be
        // assignable via structural typing, type aliases, etc.
        if (targetType.startsWith("@")) {
            // null and undefined are never assignable to named types (with strict null checks)
            return sourceType != "null" && sourceType != "undefined"
        }
        if (sourceType.startsWith("@") || sourceType.startsWith("|")) {
            // Named/union source type vs keyword target — can't determine without full resolution
            return true // safe default: assume assignable to avoid FPs
        }
        // null is assignable to any/unknown (already handled above) but NOT void or other types
        // number literal subtypes
        if (sourceType == "number" && targetType == "object") return false
        if (sourceType == "string" && targetType == "object") return false
        // Otherwise, different primitive types are not assignable
        return false
    }

    private fun emitTS2322(start: Int, length: Int, sourceType: String, targetType: String, source: String, fileName: String, hasElaboration: Boolean = false, typeParams: Set<String> = emptySet()) {
        val (line, character) = getLineAndCharacterOfPosition(source, start)
        // Strip "@"/"@" prefix from named/union types for display
        val displaySource = sourceType.removePrefix("@").removePrefix("|")
        val displayTarget = targetType.removePrefix("@").removePrefix("|")
        val message = "Type '$displaySource' is not assignable to type '$displayTarget'."
        // Check if target type is a type parameter — add elaboration chain
        val chain = mutableListOf<String>()
        if (hasElaboration) chain.add("  $message")
        if (targetType.startsWith("@")) {
            val targetBaseName = displayTarget.substringBefore('<')
            if (targetBaseName in typeParams) {
                chain.add("  '$targetBaseName' could be instantiated with an arbitrary type which could be unrelated to '$displaySource'.")
            }
        }
        diagnostics.add(Diagnostic(
            message = message,
            category = DiagnosticCategory.Error,
            code = 2322,
            fileName = fileName,
            line = line,
            character = character,
            start = start,
            length = length,
            messageChain = chain,
        ))
    }

